INSERT INTO "theory_assertion_links" VALUES(38,'real-singlet-z2',1,23,'vacuum',1,NULL,'competing_minimum_conditions_deferred','qualifies','The printed coexistence inequality conflicts with simultaneous local-minimum conditions; no corrected domain is inserted.');
INSERT INTO "theory_assertion_links" VALUES(39,'real-singlet-z2',1,22,'specification',NULL,NULL,'Higgs_mass_normalization_deferred','qualifies','No canonical lambda_h-to-m_h relation is adopted from the conflicting source expressions.');
INSERT INTO "theory_assertion_links" VALUES(40,'real-singlet-z2',1,28,'specification',NULL,NULL,'cross_paper_field_content','supports','P02 and P01 both specify one real scalar singlet with an inherited Standard Model sector; retain the existing identity provisionally.');
INSERT INTO "theory_assertion_links" VALUES(41,'real-singlet-z2',1,30,'symmetry_action',1,NULL,'sign_action_and_stability','supports','The P02 transformation is the same imposed singlet sign action recorded from P01.');
INSERT INTO "theory_assertion_links" VALUES(42,'real-singlet-z2',1,29,'interaction',4,NULL,'portal_convention_mapping','supports','Comparing P02 V ⊃ lambda_hS S²|H|²/2 with the existing P01 L ⊃ −lambda S²H†H gives lambda_hS(P02) = 2 lambda(P01). No field rescaling or additional operator is needed.');
INSERT INTO "theory_assertion_links" VALUES(43,'real-singlet-z2',1,29,'interaction',2,NULL,'mass_coefficient_mapping','supports','P02 mu_S² equals P01 m_0² when matching the quadratic terms in the potential.');
INSERT INTO "theory_assertion_links" VALUES(44,'real-singlet-z2',1,32,'interaction',3,NULL,'quartic_retained_despite_display_omission','supports','P02 acknowledges the quartic. Its omission from Eq. (1) does not define a two-parameter theory or a zero-quartic restriction.');
INSERT INTO "theory_assertion_links" VALUES(45,'real-singlet-z2',1,45,'parameter',2,NULL,'quartic_convention_mapping','supports','Matching P02''s written lambda_S S⁴ to P01''s lambda_S S⁴/4 gives lambda_S(P01) = 4 lambda_S(P02). This coefficient comparison does not resolve the numerical scan conflict or establish a Higgs-quartic convention mapping.');
INSERT INTO "theory_assertion_links" VALUES(46,'real-singlet-z2',1,31,'interaction',5,NULL,'odd_operator_exclusion','supports','Linear and cubic singlet terms are symmetry-forbidden, distinct from the omitted but acknowledged quartic.');
INSERT INTO "theory_assertion_links" VALUES(47,'real-singlet-z2',1,33,'interaction',1,NULL,'kinetic_term_presence','supports','P02 acknowledges the kinetic term; this assertion alone does not independently specify its coefficient.');
INSERT INTO "theory_assertion_links" VALUES(48,'real-singlet-z2',1,34,'parameter',4,NULL,'mass_relation_agreement','supports','P02 m_S² = mu_S² + lambda_hS v0²/2 agrees with the canonical P01 relation after the portal and quadratic coefficient conversions. The source VEV numerical inputs remain paper-specific.');
INSERT INTO "theory_assertion_links" VALUES(49,'real-singlet-z2',1,36,'vacuum',1,NULL,'present_sign_preserving_phase','supports','P02''s present <S> = 0 interpretation is agent-inferred from the stable-particle treatment, unlike P01''s explicit vacuum assumption. It does not support the full P01 vacuum inequalities.');
