INSERT INTO "theory_assertion_links" VALUES(175,'thdm-type-i-real-z2',1,93,'interaction',13,NULL,'conditional_tree_level_boundedness','qualifies','For this real λ6 = λ7 = 0 potential, the source gives λ1,λ2 ≥ 0, λ3 ≥ −√(λ1λ2), and λ3+λ4−|λ5| ≥ −√(λ1λ2). Quartic-flat directions additionally require a non-negative quadratic potential. These conditions do not select a vacuum.');
