INSERT INTO "theory_assertion_links" VALUES(271,'lr-triplet-charge-conjugation',1,130,'specification',NULL,NULL,'collider_seesaw_scope','qualifies','Small Dirac Yukawas and accessible RH neutrinos are adopted phenomenological choices. No neutrino Dirac operator is declared forbidden or identically zero.');
INSERT INTO "theory_assertion_links" VALUES(272,'lr-triplet-parity',1,118,'vacuum',5,NULL,'manifest_limit_is_optional','qualifies','Real VEVs give equal mixing angles; Eq. (18) writes VR ≃ Su VL Sd. This limit is not imposed on the general P specification.');
INSERT INTO "theory_assertion_links" VALUES(273,'lr-triplet-charge-conjugation',1,125,'specification',NULL,NULL,'right_quark_mixing_constraint','supports','VR = Ku VL* Kd: equal mixing angles and five additional physical phases before phenomenological constraints. No vanishing-phase condition is imposed.');
INSERT INTO "theory_assertion_links" VALUES(274,'lr-triplet-parity',1,117,'specification',NULL,NULL,'mass_Hermiticity_is_vacuum_dependent','qualifies','Hermitian Yukawas do not imply exactly Hermitian quark masses at a general complex bidoublet VEV.');
INSERT INTO "theory_assertion_links" VALUES(275,'lr-triplet-parity',1,120,'specification',NULL,NULL,'numerical_angle_limit_deferred','qualifies','Retain the main-text 20% and Appendix A 25% summaries as conditional source results, without selecting a universal canonical bound.');
INSERT INTO "theory_assertion_links" VALUES(276,'lr-triplet-charge-conjugation',1,123,'symmetry',5,NULL,'gauged_embedding_motivation','qualifies','The source says C can be gauged and is a finite SO(10) transformation. It does not provide an SO(10) model or establish a particular global gauge completion of this specification.');
INSERT INTO "theory_assertion_links" VALUES(277,'lr-triplet-parity',1,138,'model_relation',3,NULL,'restricted_real_symmetric_case','qualifies','Footnote 2 discusses a real-symmetric-Yukawa spontaneous-CP case and its stated viability problem. It does not merge the general P and C constructions or complete their scalar potentials.');
INSERT INTO "theory_assertion_links" VALUES(278,'lr-triplet-parity',1,114,'specification',NULL,NULL,'perturbativity_scope','qualifies','MH < 10 MWR is an adopted estimate, and x ≲ 0.8 is a perturbative-Yukawa analysis restriction. Neither is a symmetry exclusion or a new model identity.');
INSERT INTO "theory_assertion_links" VALUES(279,'lr-triplet-charge-conjugation',1,114,'specification',NULL,NULL,'perturbativity_scope','qualifies','MH < 10 MWR is an adopted estimate, and x ≲ 0.8 is a perturbative-Yukawa analysis restriction. Neither is a symmetry exclusion or a new model identity.');
INSERT INTO "theory_assertion_links" VALUES(280,'lr-triplet-parity',1,129,'specification',NULL,NULL,'strong_CP_analysis_policy','qualifies','The source allows tuning of total neutron-EDM contributions. Its resulting scale bounds are conditional and do not supply a structural strong-CP solution.');
INSERT INTO "theory_assertion_links" VALUES(281,'lr-triplet-charge-conjugation',1,129,'specification',NULL,NULL,'strong_CP_analysis_policy','qualifies','The source allows strong-CP tuning; phase choices removing stronger bounds are not imposed as defining couplings.');
INSERT INTO "theory_assertion_links" VALUES(282,'lr-triplet-parity',1,132,'specification',NULL,NULL,'type_II_seesaw_scope','supports','The source includes a type-II mechanism and same-sign triplet decays. Type-II dominance is optional; a complete triplet Yukawa operator and flavor relation are not reconstructed.');
INSERT INTO "theory_assertion_links" VALUES(283,'lr-triplet-charge-conjugation',1,132,'specification',NULL,NULL,'type_II_seesaw_scope','supports','The source includes a type-II mechanism and same-sign triplet decays. Type-II dominance is optional; a complete triplet Yukawa operator and flavor relation are not reconstructed.');
INSERT INTO "theory_assertion_links" VALUES(284,'lr-triplet-parity',1,134,'specification',NULL,NULL,'no_fixed_light_heavy_neutrino_mass_relation','qualifies','The generic seesaw discussion supplies no a priori light-heavy mass-matrix connection; no type-II-dominant relation is imposed.');
