INSERT INTO "theory_assertion_links" VALUES(387,'nmssm-z3-rpc-cpc',1,163,'model_relation',4,NULL,'coordinate_choice_distinction','qualifies','Removing μ by a shift does not enforce the other five zeros or imply this Z3 action in those coordinates.');
INSERT INTO "theory_assertion_links" VALUES(388,'nmssm-general-rpc-cpc',1,140,'field',30,NULL,'scalar_component','supports','S is complex even though the selected expectation value s is real.');
INSERT INTO "theory_assertion_links" VALUES(389,'nmssm-z3-rpc-cpc',1,140,'field',38,NULL,'scalar_component','supports',NULL);
INSERT INTO "theory_assertion_links" VALUES(390,'nmssm-general-rpc-cpc',1,148,'interaction',26,NULL,'contraction_convention','supports','Ĥu·Ĥd = Ĥu⁺Ĥd⁻ − Ĥu⁰Ĥd⁰. No external convention source was needed.');
INSERT INTO "theory_assertion_links" VALUES(391,'nmssm-z3-rpc-cpc',1,148,'interaction',36,NULL,'contraction_convention','supports','Same Ĥu·Ĥd contraction as Eq. (2.4).');
INSERT INTO "theory_assertion_links" VALUES(392,'nmssm-general-rpc-cpc',1,145,'interaction',27,NULL,'coefficient_dimensions','supports','μ and μ′ have mass dimension one; ξF has mass dimension two. λ and κ in the cubic terms are dimensionless.');
INSERT INTO "theory_assertion_links" VALUES(393,'nmssm-general-rpc-cpc',1,158,'interaction',27,NULL,'explicit_Z3_breaking','supports','Nonzero dimensionful superpotential terms break the stated common-phase Z3; the general specification does not impose that symmetry.');
INSERT INTO "theory_assertion_links" VALUES(394,'nmssm-z3-rpc-cpc',1,157,'interaction',37,NULL,'Z3_noninvariance','supports','Linear and quadratic superfield monomials fail the stated common-phase cubic symmetry. Zero-by-assumption records the source''s explicit defining restriction.');
INSERT INTO "theory_assertion_links" VALUES(395,'nmssm-z3-rpc-cpc',1,157,'interaction',43,NULL,'Z3_noninvariance','supports','The component bilinears acquire exp(4πi/3); their removal is explicit in assertion 156.');
INSERT INTO "theory_assertion_links" VALUES(396,'nmssm-z3-rpc-cpc',1,157,'interaction',44,NULL,'Z3_noninvariance','supports','The scalar tadpole acquires exp(2πi/3); its removal is explicit in assertion 156.');
INSERT INTO "theory_assertion_links" VALUES(397,'nmssm-general-rpc-cpc',1,161,'specification',NULL,NULL,'tree_level_quartics','supports','Higgs quartics follow from supersymmetric gauge interactions and F terms, not independent general two-doublet scalar coefficients.');
INSERT INTO "theory_assertion_links" VALUES(398,'nmssm-z3-rpc-cpc',1,161,'specification',NULL,NULL,'tree_level_quartics','supports','Apply the coefficient restriction to the same supersymmetric construction of the potential.');
INSERT INTO "theory_assertion_links" VALUES(399,'nmssm-z3-rpc-cpc',1,160,'specification',NULL,NULL,'Higgs_Lagrangian_parameters','supports','Seven Higgs-sector parameters before vacuum elimination: λ, κ, mHu², mHd², mS², Aλ, Aκ; this is not a count of all model parameters.');
INSERT INTO "theory_assertion_links" VALUES(400,'nmssm-z3-rpc-cpc',1,168,'specification',NULL,NULL,'fixed_MZ_Higgs_inputs','supports','After minimisation and fixing MZ, six inputs can be λ, κ, Aλ, Aκ, tanβ, μeff. This is a parameterization of the same construction.');
INSERT INTO "theory_assertion_links" VALUES(401,'nmssm-general-rpc-cpc',1,169,'specification',NULL,NULL,'fixed_MZ_Higgs_inputs','supports','In μ = 0 coordinates, add m3², μ′, mS′², ξF, ξS to λ, κ, Aλ, Aκ, tanβ, μeff. This is not a total model-parameter count.');
INSERT INTO "theory_assertion_links" VALUES(402,'nmssm-general-rpc-cpc',1,167,'vacuum',7,NULL,'minimisation_parameter_elimination','supports','The three minimisation equations can replace mHu², mHd² and mS² by vu, vd and s; no automatic global-minimum certification follows.');
INSERT INTO "theory_assertion_links" VALUES(403,'nmssm-z3-rpc-cpc',1,167,'vacuum',8,NULL,'minimisation_parameter_elimination','supports','Same equations after the six-zero restriction.');
INSERT INTO "theory_assertion_links" VALUES(404,'nmssm-general-rpc-cpc',1,164,'specification',NULL,NULL,'sign_conventions','qualifies','The positive λ, ht, hb, hτ, vu and vd convention is a field-redefinition choice. κ, s and dimensionful parameters may have either sign; squared parameter symbols do not impose positivity.');
INSERT INTO "theory_assertion_links" VALUES(405,'nmssm-z3-rpc-cpc',1,164,'specification',NULL,NULL,'sign_conventions','qualifies','Same sign conventions restricted to the surviving parameters; no positive μeff benchmark is imposed.');
INSERT INTO "theory_assertion_links" VALUES(406,'nmssm-general-rpc-cpc',1,166,'specification',NULL,NULL,'derived_Higgs_combinations','supports','In μ = 0 coordinates, Beff = Aλ + κs and m̂3² = m3² + λ(μ′s + ξF). These are derived combinations, not new independent couplings.');
INSERT INTO "theory_assertion_links" VALUES(407,'nmssm-z3-rpc-cpc',1,166,'specification',NULL,NULL,'derived_Higgs_combinations','supports','Beff = Aλ + κs; m̂3² vanishes under the defining restriction.');
INSERT INTO "theory_assertion_links" VALUES(408,'nmssm-general-rpc-cpc',1,170,'vacuum',7,NULL,'physical_scalar_content','supports','Around the assumed CP-conserving neutral vacuum: three CP-even neutral states, two physical CP-odd neutral states and one charged pair after Goldstone removal; these are component eigenstates, not extra multiplets.');
INSERT INTO "theory_assertion_links" VALUES(409,'nmssm-z3-rpc-cpc',1,170,'vacuum',8,NULL,'physical_scalar_content','supports','The restriction retains the same three CP-even, two physical CP-odd and charged-pair component content.');
INSERT INTO "theory_assertion_links" VALUES(410,'nmssm-general-rpc-cpc',1,171,'specification',NULL,NULL,'neutralino_component_basis','supports','ψ⁰ = (−iλ1, −iλ2³, ψd⁰, ψu⁰, ψS) with a symmetric 5 × 5 mass matrix. The component basis does not add independent supermultiplets.');
INSERT INTO "theory_assertion_links" VALUES(411,'nmssm-z3-rpc-cpc',1,171,'specification',NULL,NULL,'neutralino_component_basis','supports','Same five-state neutral component basis under the coefficient restriction.');
INSERT INTO "theory_assertion_links" VALUES(412,'nmssm-general-rpc-cpc',1,172,'specification',NULL,NULL,'singlet_neutralino_matrix_entry','supports','(M0)55 = 2κs + μ′ is a weak-basis diagonal entry, not generally a physical mass eigenvalue.');
INSERT INTO "theory_assertion_links" VALUES(413,'nmssm-z3-rpc-cpc',1,172,'specification',NULL,NULL,'singlet_neutralino_matrix_entry','supports','μ′ = 0 gives (M0)55 = 2κs; no pure-singlino eigenstate assumption is imposed.');
INSERT INTO "theory_assertion_links" VALUES(414,'mchm-spinorial',1,180,'specification',NULL,NULL,'spinorial_identity','supports','The enclosing model and revision identify the composite-key target. Spinorial composite operators are a physical assumption, unlike nondynamical source completion.');
INSERT INTO "theory_assertion_links" VALUES(415,'mchm-spinorial',1,194,'specification',NULL,NULL,'shared_effective_description','supports','Descriptions 12 and 13 are provisionally merged at the effective-construction level; the 5D realization supplies specific form factors.');
INSERT INTO "theory_assertion_links" VALUES(416,'mchm-spinorial',1,195,'specification',NULL,NULL,'microscopic_equivalence_limit','qualifies','No microscopic 4D completion or reliance on the validity of AdS/CFT is asserted.');
