INSERT INTO "theory_assertion_links" VALUES(513,'mchm-spinorial',1,178,'symmetry',11,NULL,'elementary_sector_explicit_breaking','supports','Without explicit SO(5) breaking the Goldstone potential vanishes perturbatively; elementary interactions generate it at one loop.');
INSERT INTO "theory_assertion_links" VALUES(514,'mchm-spinorial',1,189,'field',49,NULL,'Hosotani_potential','supports','5D gauge invariance forbids the tree-level A5 potential; radiative nonlocal finite-volume effects generate it. This is not a symmetry-allowed local potential tuned to zero.');
INSERT INTO "theory_assertion_links" VALUES(515,'mchm-spinorial',1,200,'interaction',53,NULL,'finiteness_scope','qualifies','Finiteness concerns the h-dependent one-loop potential. The 5D breaking form factors fall exponentially; no claim is made about the h-independent constant.');
INSERT INTO "theory_assertion_links" VALUES(516,'mchm-spinorial',1,185,'specification',NULL,NULL,'custodial_protection_scope','qualifies','No tree-level CFT contribution to T, but top interactions can induce it. Section 4 T and Zbb results are NDA estimates; the full calculation is left open by the source.');
INSERT INTO "theory_assertion_links" VALUES(517,'mchm-spinorial',1,181,'regime',10,NULL,'omitted_terms_are_not_forbidden','qualifies','Possible Ψu–Ψd mixing is neglected in the calculation; bare source kinetic and gauge-fixing terms are omitted from the displayed action. These omissions do not define structural exclusions.');
INSERT INTO "theory_assertion_links" VALUES(518,'mchm-spinorial',1,197,'regime_relation',2,NULL,'principal_source_chiralities','supports','The principal matching fixes ξqL and ξuR; ξd is omitted only for simplicity in that matching calculation.');
INSERT INTO "theory_assertion_links" VALUES(519,'mchm-spinorial-scalar14',1,205,'interaction',54,NULL,'SO4_mass_restriction','supports','Independent masses of 9, 4 and 1 preserve SO(4) in the chosen example while breaking SO(5); this is not asserted for every possible source deformation.');
INSERT INTO "theory_assertion_links" VALUES(520,'mchm-spinorial-scalar14',1,206,'specification',NULL,NULL,'source_decoupling_limits','qualifies','Only the 9 source gives a pure sin⁴ term; a positive coefficient requires m9²<0 and therefore an auxiliary source. Only the 4 source gives ξ(sin⁴−sin²). These conditional limits do not fix all source masses or propagation choices.');
INSERT INTO "theory_assertion_links" VALUES(521,'mchm-spinorial',1,208,'regime',11,NULL,'flat_space_comparison_deferred','qualifies','Footnote 9 states a low-energy flat-space alternative with large UV kinetic terms; it supplies no separate full construction or geometry-equivalence proof.');
INSERT INTO "theory_assertion_links" VALUES(522,'mchm-spinorial',1,184,'specification',NULL,NULL,'flavor_and_compositeness_regimes','qualifies','Positive anomalous dimensions suppress light-fermion mixing; the adopted third-generation regime has γu<0 and γq≃0 and a mostly composite physical right-handed top. These are flavor choices within the construction.');
