INSERT INTO "theory_assertion_links" VALUES(573,'georgi-machacek-general',1,220,'specification',NULL,NULL,'potential_parameter_reality','supports','All Eq. (5) coefficients are real because its operators are Hermitian. Supports the reality restrictions on interactions 58–61 and parameters 25–28. Does not establish a statement about spontaneous CP breaking or fermion-sector phases.');
INSERT INTO "theory_assertion_links" VALUES(574,'georgi-machacek-general',1,219,'interaction',60,NULL,'matrix_conventions','supports','τa=σa/2; ta are Eq. (6) generators. U=[[-1/√2,0,1/√2],[-i/√2,0,-i/√2],[0,1,0]]. The same U and generators define interaction 61.');
INSERT INTO "theory_assertion_links" VALUES(575,'georgi-machacek-general',1,221,'vacuum',10,NULL,NULL,'supports',NULL);
INSERT INTO "theory_assertion_links" VALUES(576,'georgi-machacek-general',1,222,'vacuum',10,NULL,'neutral_fluctuation_normalization','supports',NULL);
INSERT INTO "theory_assertion_links" VALUES(577,'georgi-machacek-general',1,224,'vacuum',10,NULL,'stationarity_conditions','supports',NULL);
INSERT INTO "theory_assertion_links" VALUES(578,'georgi-machacek-general',1,233,'vacuum',10,NULL,'global_minimum_selection','qualifies','The source compares triplet orientations Reχ0=sinθ/√2, ξ0=cosθ with magnitudes minimized separately. Aligned orientations are θ=arccos(1/√3) and π+arccos(1/√3). Its geometrical reduction is source-stated, not independently proved here. The desired minimum must also lie below V=0.');
INSERT INTO "theory_assertion_links" VALUES(579,'georgi-machacek-general',1,213,'breaking_step',8,NULL,NULL,'supports',NULL);
INSERT INTO "theory_assertion_links" VALUES(580,'georgi-machacek-general',1,226,'vacuum',10,NULL,'physical_scalar_content','supports','Ten real physical scalar degrees of freedom form a custodial fiveplet, triplet and two singlets, with three Goldstones. Tree-level degeneracy is within each custodial multiplet. These labels are not gauge representations or extra independent scalar multiplets.');
INSERT INTO "theory_assertion_links" VALUES(581,'georgi-machacek-general',1,227,'vacuum',10,NULL,'fiveplet_composition','supports','H5++=χ++; H5+=(χ+−ξ+)/√2; H5⁰=√(2/3)ξ0−χ0,r/√3, with charge conjugates.');
INSERT INTO "theory_assertion_links" VALUES(582,'georgi-machacek-general',1,228,'vacuum',10,NULL,'triplet_composition','supports','H3+=−sHφ++cH(χ++ξ+)/√2, where the sum in parentheses denotes the singly charged χ and ξ components; H3⁰=−sHφ0,i+cHχ0,i. cH=vφ/v; sH=2√2vχ/v.');
INSERT INTO "theory_assertion_links" VALUES(583,'georgi-machacek-general',1,225,'vacuum',10,NULL,'Goldstone_composition','supports','G+ = cH φ+ + sH (χ+ + ξ+)/√2; G0 = cH φ0,i + sH χ0,i; cH=vφ/v and sH=2√2vχ/v.');
INSERT INTO "theory_assertion_links" VALUES(584,'georgi-machacek-general',1,231,'parameter',30,NULL,'singlet_mass_matrix','supports','ℳ11²=8λ1vφ²; ℳ12²=(√3/2)vφ[−M1+4(2λ2−λ5)vχ]; ℳ22²=M1vφ²/(4vχ)−6M2vχ+8(λ3+3λ4)vχ². For nondegenerate singlets, sin2α=2ℳ12²/(mH²−mh²) and cos2α=(ℳ22²−ℳ11²)/(mH²−mh²). The vχ=0 branch requires separate limiting treatment.');
INSERT INTO "theory_assertion_links" VALUES(585,'georgi-machacek-general',1,230,'vacuum',10,NULL,'tree_level_masses','supports','For the nonzero-vχ stationary branch, m5²=M1vφ²/(4vχ)+12M2vχ+(3/2)λ5vφ²+8λ3vχ² and m3²=[M1/(4vχ)+λ5/2]v². Eq. (15) resolves the apparent ratio for finite remaining parameters; no universal bounded M1/vχ assertion along μ3→∞ is adopted.');
INSERT INTO "theory_assertion_links" VALUES(586,'georgi-machacek-general',1,236,'regime',16,NULL,'leading_decoupling_behavior','supports','mH,m3,m5 approach μ3 with fractional corrections O(μ3⁻²). vχ≈M1v²/(4μ3²), vφ→v and sinα≈−√3M1v/(2μ3²); the vev and mixing fall as μ3⁻² in case A and μ3⁻¹ in case B.');
INSERT INTO "theory_assertion_links" VALUES(587,'georgi-machacek-general',1,237,'regime',16,NULL,'light_Higgs_coupling_limits','supports','κV≈1+3M1²v²/(8μ3⁴) and κf≈1−M1²v²/(8μ3⁴). Nonzero leading corrections have the stated signs. Tree-level deviations fall as μ3⁻⁴ in case A and μ3⁻² in case B; new charged-scalar hγγ and hZγ contributions fall as μ3⁻².');
INSERT INTO "theory_assertion_links" VALUES(588,'georgi-machacek-general',1,238,'specification',NULL,NULL,'Z2_branch_scope','qualifies','The introduction''s nondecoupling statement must not be generalized to every M1=M2=0 branch. Footnote 14 discusses an unbroken-Z2 branch with decoupling loop effects. A standalone variant and sufficient vacuum conditions are deferred.');
INSERT INTO "theory_assertion_links" VALUES(589,'threedm-d6',1,252,'specification',NULL,NULL,'defining_D6_constraints','supports','Composite target is the enclosing model and revision. Equations (24)–(26) and Section 6.2.2 distinguish this scalar construction from existing models.');
INSERT INTO "theory_assertion_links" VALUES(590,'threedm-d8',1,261,'specification',NULL,NULL,'defining_D8_constraints','supports','The Z4 operator content and exchange constraints define the specification. Description 22 does not change those coefficients.');
