INSERT INTO "theory_assertion_links" VALUES(624,'threedm-d6',1,253,'symmetry',13,NULL,'generic_exact_unitary_group','supports','Source proof excludes continuous symmetry for generic separated bilinear eigenvalues and larger finite groups by avoiding stronger coefficient restrictions. No universal exact-group claim at every parameter point.');
INSERT INTO "theory_assertion_links" VALUES(625,'threedm-d8',1,262,'symmetry',15,NULL,'generic_exact_unitary_group','supports',NULL);
INSERT INTO "theory_assertion_links" VALUES(626,'threedm-d8',1,263,'specification',NULL,NULL,'merged_unitary_and_antiunitary_descriptions','supports','Description 22 reveals an automatic symmetry of description 21. Neither a new interaction restriction nor a new model revision is required.');
INSERT INTO "theory_assertion_links" VALUES(627,'threedm-d6',1,255,'specification',NULL,NULL,'CP_description_is_scoped_restriction','qualifies','Description 20 selects a phase locus of the registered parameterized potential. Its full symmetry differs from the generic CP-violating branch, and the conditional symmetry/action records preserve that distinction.');
INSERT INTO "theory_assertion_links" VALUES(628,'threedm-d6',1,257,'interaction',64,NULL,'equivalent_rephased_CP_violating_form','supports','Appendix A gives real λ1, λ2=−λ1 and a third coefficient with sin ψ3≠0 in a basis with δ=0. This is a basis representative of the CP-violating branch, not an additional model or a reality condition on all coefficients.');
INSERT INTO "theory_assertion_links" VALUES(629,'threedm-d6',1,258,'specification',NULL,NULL,'abstract_isomorphism_does_not_establish_identity','qualifies','Do not merge with Z3 ⋊ Z2* merely because both abstract groups are D6. The registered construction has unitary D6, including on its CP-conserving locus.');
INSERT INTO "theory_assertion_links" VALUES(630,'threedm-d8',1,264,'specification',NULL,NULL,'distinction_from_antiunitary_D8','qualifies','A generic Z4 potential already conserves generalized CP without the V0 exchange constraints. Its Z4 ⋊ Z2* realization is not the registered unitary-D8 construction.');
INSERT INTO "theory_assertion_links" VALUES(631,'threedm-d8',1,265,'interaction',66,NULL,'excluded_finite_Q8_extension','qualifies','The alternative Q8 generator flips the λ1 operator, forcing λ1=0 and continuous rephasing symmetry. This rejected finite extension is not registered as another model or imposed as a zero in the D8 specification.');
