INSERT INTO "theory_assertion_links" VALUES(705,'sm-octet-doublet-mfv-triplets',1,299,'specification',NULL,NULL,'representation_label_conflicts','qualifies','Page 7 twice prints (8,1)1/2 and page 8 prints (1,2)0. The registered partial extension follows the explicit triplets on pages 2 and 7 and the doublet contractions of Eq. (42); no correction of the paper extraction or validation of the unification numerics is implied.');
INSERT INTO "theory_assertion_links" VALUES(706,'sm-octet-doublet-mfv',1,288,'specification',NULL,NULL,'custodial_restriction_deferred','qualifies','Eq. (11) states 2λ3=λ2, 2λ6=2λ7=λ11 and λ9=λ10. Retain this as a source claim, without certifying sufficiency for the complete Eq. (6), including complex λ4 and λ5.');
INSERT INTO "theory_assertion_links" VALUES(707,'sm-octet-doublet-mfv',1,287,'specification',NULL,NULL,'scoped_custodial_transformation','qualifies','The source organizes S and H into matrices transforming as 𝓢^A→U𝓢^AU† and 𝓗→U𝓗U†, with the Higgs matrix vacuum invariant. No unconditional custodial action on the full registered theory is inserted while potential sufficiency remains unresolved.');
INSERT INTO "theory_assertion_links" VALUES(708,'sm-octet-doublet-mfv',1,289,'parameter',36,NULL,'conditional_mass_degeneracy','supports','The algebraic substitution λ2=2λ3 gives m²_{S_I^0}=m²_{S±}. This conditional equality does not establish full custodial invariance.');
INSERT INTO "theory_assertion_links" VALUES(709,'sm-octet-doublet-mfv',1,274,'specification',NULL,NULL,'potential_notation','supports','For the registered Eq. (6) operators, S=S^A T^A, traces are over color and i,j are weak indices. No unprinted generator trace normalization is inferred.');
INSERT INTO "theory_assertion_links" VALUES(710,'sm-octet-doublet-mfv',1,283,'specification',NULL,NULL,'CP_freedom','supports','General complex η_U, η_D, λ4 and λ5 remain after choosing λ3 real. The heavy-operator calculation''s CP assumption does not remove this freedom.');
INSERT INTO "theory_assertion_links" VALUES(711,'sm-octet-doublet-mfv',1,272,'specification',NULL,NULL,'neutral_Yukawa_alignment','supports','Eq. (14) gives flavor-diagonal neutral couplings proportional to the corresponding quark masses in the mass basis; these are expansions of the registered Yukawa interactions.');
INSERT INTO "theory_assertion_links" VALUES(712,'sm-octet-doublet-mfv',1,273,'specification',NULL,NULL,'charged_Yukawa_mixing','supports','The charged components of the same interactions involve V and V† as displayed in Eq. (14). No independent charged-sector flavor matrices are added.');
INSERT INTO "theory_assertion_links" VALUES(713,'sm-octet-doublet-mfv',1,270,'specification',NULL,NULL,'representation_argument_scope','qualifies','The source''s restriction to (1,2)1/2 and (8,2)1/2 scalars coupling to quarks depends on its flavor assumptions and Appendix A qualification. Background representation surveys do not define additional models.');
