INSERT INTO "theory_assertion_links" VALUES(817,'vlq-xt-doublet',1,327,'specification',NULL,NULL,'derived_mass_relation','supports','Table 1: mX²=mT² cos²θR+mt² sin²θR. Physical masses, not independent bare masses.');
INSERT INTO "theory_assertion_links" VALUES(818,'vlq-tb-doublet',1,327,'specification',NULL,NULL,'derived_mass_relation','supports','mT² cos²θR^u+mt² sin²θR^u=mB² cos²θR^d+mb² sin²θR^d. Shared bare mass constrains physical splittings.');
INSERT INTO "theory_assertion_links" VALUES(819,'vlq-by-doublet',1,327,'specification',NULL,NULL,'derived_mass_relation','supports','Table 1: mY²=mB² cos²θR+mb² sin²θR.');
INSERT INTO "theory_assertion_links" VALUES(820,'vlq-xtb-triplet',1,327,'specification',NULL,NULL,'derived_mass_relations','supports','mX²=mT² cos²θL^u+mt² sin²θL^u=mB² cos²θL^d+mb² sin²θL^d.');
INSERT INTO "theory_assertion_links" VALUES(821,'vlq-tby-triplet',1,327,'specification',NULL,NULL,'derived_mass_relations','supports','mY²=mB² cos²θL^d+mb² sin²θL^d=mT² cos²θL^u+mt² sin²θL^u.');
INSERT INTO "theory_assertion_links" VALUES(822,'vlq-t-singlet',1,326,'specification',NULL,NULL,'parameterisation_scope','qualifies','Source parameterisation uses one angle, one heavy mass and a phase. Ignoring the phase for selected observables does not impose a CP symmetry or independently validate physical phase counting.');
INSERT INTO "theory_assertion_links" VALUES(823,'vlq-b-singlet',1,326,'specification',NULL,NULL,'parameterisation_scope','qualifies','Source parameterisation uses one angle, one heavy mass and a phase; no CP-conservation restriction is imposed. Physical phase counting is not independently established.');
INSERT INTO "theory_assertion_links" VALUES(824,'vlq-xt-doublet',1,326,'specification',NULL,NULL,'parameterisation_scope','qualifies','Source parameterisation uses one angle, one heavy mass and a phase; ignored phase dependence is an observable-level approximation.');
INSERT INTO "theory_assertion_links" VALUES(825,'vlq-tb-doublet',1,326,'specification',NULL,NULL,'parameterisation_scope','qualifies','Two independent angles are retained. The source writes two sector phases; this is not promoted to an independently verified count of rephasing-invariant CP phases.');
INSERT INTO "theory_assertion_links" VALUES(826,'vlq-by-doublet',1,326,'specification',NULL,NULL,'parameterisation_scope','qualifies','One angle, one heavy mass and a phase in the source parameterisation; no fit benchmark or exact CP restriction is defining.');
INSERT INTO "theory_assertion_links" VALUES(827,'vlq-xtb-triplet',1,326,'specification',NULL,NULL,'parameterisation_scope','qualifies','After correlated masses and Yukawas, one independent angle remains. The source phase parameterisation is retained without an independent physical phase-count claim.');
INSERT INTO "theory_assertion_links" VALUES(828,'vlq-tby-triplet',1,326,'specification',NULL,NULL,'parameterisation_scope','qualifies','After correlated masses and Yukawas, one independent angle remains. No CP-conserving restriction follows from ignoring phases in the studied observables.');
