INSERT INTO "theory_assertion_links" VALUES(1356,'u1-ybl-charge-family',1,536,'specification',NULL,NULL,NULL,'supports','Only the family-universal three-neutrino overlap with Fν≠0 is reused. P15''s singlets are right-handed, opposite in charge to P13''s conjugate left-handed singlets.');
INSERT INTO "theory_assertion_links" VALUES(1357,'u1-ybl-charge-family',1,536,'parameter',48,NULL,NULL,'supports','Algebraic conversion of the existing charges: b=−2Fν and z=−1−3FQ/Fν, valid for Fν≠0. It reproduces all six species after singlet conjugation. No extension of the existing b≠0 chart is made.');
INSERT INTO "theory_assertion_links" VALUES(1358,'u1-ybl-charge-family',1,537,'parameter',49,NULL,NULL,'supports','Fν=−3FQ maps to z=0 and b=6FQ. Agreement is confined to fermion charges, not P14''s scalar-completed pure B−L construction.');
