INSERT INTO "theory_assertion_links" VALUES(1752,'so10-45-126-sector',1,675,'regime',62,NULL,NULL,'qualifies','For the source scan with dimensionless couplings in [−1,+1], the reported stable domain has ωBL>0, β′4<0, β4>0, a0>−0.1 and |γ2|<0.6. These are scan findings, not sufficient analytic stability conditions or restrictions on the general specification.');
INSERT INTO "theory_assertion_links" VALUES(1753,'so10-45-126-sector',1,677,'regime',63,NULL,NULL,'qualifies','For dimensionless couplings below one in magnitude, the reported necessary domain has |ωBL|<|ωR|, β′4<0, a0>−0.05, |γ2|<0.6 and |γ2|<−0.8β′4. Only one octet-doublet eigenstate can be lowered in this analysis; no sufficient full-theory stability theorem is inferred.');
