INSERT INTO "theory_assertion_links" VALUES(2510,'smash-down',1,954,'model_relation',30,NULL,NULL,'supports','Target identifies the KSVZ mechanism; relation is limited to that sector and does not assume identity with an earlier external source.');
INSERT INTO "theory_assertion_links" VALUES(2511,'smash-down',1,946,'model_relation',30,NULL,NULL,'supports',NULL);
INSERT INTO "theory_assertion_links" VALUES(2512,'smash-down',1,963,'regime',104,NULL,NULL,'qualifies','Single-field slow roll uses valley attraction, moderate initial velocities, heavy transverse modes and b≈1; detailed matter and graviton loop treatment is not supplied.');
INSERT INTO "theory_assertion_links" VALUES(2513,'smash-down',1,968,'regime',104,NULL,NULL,'supports','Negative-portal absolute stability requires λtildeH,λtildeσ>0 over relevant scales. Typical threshold δ≈10^-3–10^-1 is scale- and SM-input-dependent, not an independent universal interval.');
INSERT INTO "theory_assertion_links" VALUES(2514,'smash-down',1,969,'regime',105,NULL,NULL,'supports','Positive-portal stability imposes the tilde-quartic conditions in the low-field region, and λH,λσ>0 at large fields; high-scale negative λtildeH alone does not establish instability.');
INSERT INTO "theory_assertion_links" VALUES(2515,'smash-down',1,970,'regime',104,NULL,NULL,'qualifies','Singlet Yukawas are constrained by stability; hierarchical estimates and full running must be distinguished.');
INSERT INTO "theory_assertion_links" VALUES(2516,'smash-down',1,973,'regime',104,NULL,NULL,'supports','Nonthermal restoration for fA≲4×10^16 GeV is inferred from scalar simulations neglecting fA during fluctuation growth and other fields; extrapolation to mostly-singlet HHSI is approximate.');
INSERT INTO "theory_assertion_links" VALUES(2517,'smash-down',1,975,'regime',104,NULL,NULL,'supports','Higgs-mediated W/Z production, decays and thermal feedback give typical reheating near 10^10 GeV in the analyzed region.');
INSERT INTO "theory_assertion_links" VALUES(2518,'smash-down',1,977,'regime',104,NULL,NULL,'supports','Source predicts thermal axion temperature 0.907 K and ΔNνeff≈0.0268 for g*s=427/4, with specified entropy scaling; not unconditional values for every spectrum.');
INSERT INTO "theory_assertion_links" VALUES(2519,'smash-down',1,979,'parameter',121,NULL,NULL,'qualifies','Defect-yield extrapolation and separating realignment from string production introduce systematic uncertainty that may move the inferred window beyond quoted errors.');
INSERT INTO "theory_assertion_links" VALUES(2520,'smash-down',1,982,'regime',104,NULL,NULL,'supports','Thermal PQ restoration and subsequent breaking can retain at least N1 in thermal abundance under the stated coupling and stability conditions.');
INSERT INTO "theory_assertion_links" VALUES(2521,'smash-down',1,983,'regime',104,NULL,NULL,'qualifies','Vanilla leptogenesis assumptions and its M1 lower estimate can conflict with hierarchical singlet stability. Eq. (166)''s matrix convention is not repaired here.');
INSERT INTO "theory_assertion_links" VALUES(2522,'smash-down',1,984,'regime',104,NULL,NULL,'supports','Mild degeneracy is offered to enhance CP sources and weaken the stability restriction. The factor-50 estimate is not a final baryon-yield calculation; the source''s 4% convention remains unresolved.');
INSERT INTO "theory_assertion_links" VALUES(2523,'smash-down',1,986,'regime',104,NULL,NULL,'qualifies','Singlet-mediated neutrino annihilations must remain subdominant to decays; the M<4×10^9 GeV illustration uses representative neutrino masses and fA, not a universal bound.');
INSERT INTO "theory_assertion_links" VALUES(2524,'smash-down',1,988,'specification',NULL,NULL,NULL,'qualifies','The construction accepts scale hierarchies and a small cosmological constant; it does not claim to explain their fundamental origin.');
INSERT INTO "theory_assertion_links" VALUES(2525,'smash-down',1,945,'specification',NULL,NULL,NULL,'qualifies','The five-problem solution is an author claim for an appropriate correlated region, not an independently verified property of every parameter point.');
