INSERT INTO "theory_assertion_links" VALUES(4218,'heavy-weak-triplet-proca-current-sector',1,1811,'regime',191,NULL,'four_quark_correlation_denominator','qualifies','The M_B denominator in Eq. (5.14) is not silently corrected.');
INSERT INTO "theory_assumptions" VALUES(1,'real-singlet-z2',1,'S is the only new degree of freedom relevant at the electroweak scale; nonrenormalizable couplings are neglected.','effective_description','source_assumed');
INSERT INTO "theory_assumptions" VALUES(2,'real-singlet-z2',1,'The presented analysis assumes lambda_S is small enough for perturbation theory; no numerical bound is specified.','analysis_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(3,'thdm-type-i-real-z2',1,'The early-chapter treatment assumes CP conservation in the scalar sector and no spontaneous scalar CP violation. This does not impose CP conservation on the CKM sector.','scalar_sector_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(4,'thdm-type-ii-real-z2',1,'The early-chapter treatment assumes CP conservation in the scalar sector and no spontaneous scalar CP violation. This does not impose CP conservation on the CKM sector.','scalar_sector_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(5,'mchm-spinorial',1,'The strong sector has large N, is conformal at high energies and has a mass gap near a TeV.','strong_sector','source_assumed');
INSERT INTO "theory_assumptions" VALUES(6,'mchm-spinorial',1,'The operator responsible for spontaneous SO(5) breaking has large dimension. Its microscopic form is unspecified.','strong_sector_breaking','source_assumed');
INSERT INTO "theory_assumptions" VALUES(7,'georgi-machacek-general',1,'The source selects parameters satisfying strict tree-level large-field conditions: λ1>0, ζλ3+λ4>0 and λ2−ωλ5+2√[λ1(ζλ3+λ4)]>0 for every accessible correlated (ζ,ω). Here ζ=Tr(X†XX†X)/[Tr(X†X)]² and ω=Tr(Φ†τaΦτb)Tr(X†taXtb)/[Tr(Φ†Φ)Tr(X†X)]. The marginal boundaries are not classified by these strict conditions.','vacuum_stability_selection','source_stated_selection');
INSERT INTO "theory_assumptions" VALUES(8,'sm-octet-doublet-mfv',1,'Assume an underlying SU(3)_U×SU(3)_D×SU(3)_Q flavor symmetry broken by G^U and G^D, with each charge sector''s Yukawa matrices proportional to its corresponding breaking matrix. Appendix A makes this stronger than simultaneous diagonalization alone.','flavor_alignment','source_assumed');
INSERT INTO "theory_assumptions" VALUES(9,'sm-octet-doublet-mfv-triplets',1,'Triplet sign breaking by μ1, μ2 and ξ is very small; triplet expectation values are neglected. For the source''s collider discussion the triplets are taken sufficiently heavy for negligible LHC production, without numerical masses.','scoped_triplet_example','source_assumed');
INSERT INTO "theory_assumptions" VALUES(10,'lq-rtilde2-nur',1,'Use three right-chiral neutrinos as explicitly assumed for Eq. (5); the two Yukawa matrices are 3 by 3.','field_content_branch','source_assumed');
INSERT INTO "theory_assumptions" VALUES(11,'lq-u3-effective',1,'Only conditionally, if the current is identified with generation-blind gauge interactions, x3LL=x times the identity in the flavor basis; mass-basis rotations must then be included. This is not imposed on the general current.','conditional_gauge_origin','source_assumed_conditional');
INSERT INTO "theory_assumptions" VALUES(12,'lq-utilde1-effective',1,'Interpret the displayed explicit-mass vector sector as an effective description; a renormalizable gauge-origin theory requires an extended gauge symmetry and its Higgs breaking sector.','completion_scope','source_stated');
INSERT INTO "theory_assumptions" VALUES(13,'lq-u1-effective',1,'No generation-blind extended gauge origin is imposed. Unitary flavor-matrix restrictions apply only if that additional assumption is made; explicit-mass loop predictions remain completion dependent.','completion_scope','source_stated_conditional');
INSERT INTO "theory_assumptions" VALUES(14,'lq-ubar1-nur-effective',1,'The explicit-mass vector description does not specify a renormalizable ultraviolet theory or a Higgs mechanism for its mass.','completion_scope','source_stated');
INSERT INTO "theory_assumptions" VALUES(15,'su5-gg-extra5-two10',1,'Assume a desert spectrum with two total Higgs doublets and two Rtilde2 multiplets light and other non-SM components superheavy. The illustrative common 100 GeV scale is not a defining mass choice.','light_spectrum_selection','source_assumed');
INSERT INTO "theory_assumptions" VALUES(16,'mdm-majorana-quintuplet',1,'Cosmological stability requires sufficiently suppressed higher-dimensional decay operators. The source estimates dimension-6 terms safe for a cutoff of order 10^14 GeV or higher for TeV-scale masses; no ultraviolet completion or exact lifetime guarantee is specified.','higher_dimension_decay_suppression','source_assumed');
INSERT INTO "theory_assumptions" VALUES(17,'mdm-real-septuplet-displayed',1,'The source''s stability conclusion is conditional on its operator analysis and sufficiently suppressed higher-dimensional interactions. Its generic TeV-scale estimates require effective dimension-5 suppression above the Planck scale and dimension-6 suppression at about 10^14 GeV or higher. Completeness of the septuplet operator inventory is unresolved.','higher_dimension_decay_suppression','source_assumed_with_unresolved_operator_scope');
INSERT INTO "theory_assumptions" VALUES(18,'mdm-real-septuplet-displayed',1,'For gauge-dominated numerical predictions, assume |lambda''_H| much smaller than gY² and g2². The source''s generic lambda_H splitting restriction is not promoted to an independent septuplet coupling before checking its real-representation operator identity.','numerical_parameter_regime','source_assumed');
INSERT INTO "theory_assumptions" VALUES(19,'minimal-bl-pure',1,'Choose vanishing Abelian kinetic mixing and no mixed hypercharge coupling to B′μ in the displayed basis. The source supplies no renormalization scale or running boundary condition for this choice.','defining_gauge_mixing_restriction','source_assumed');
INSERT INTO "theory_assumptions" VALUES(20,'minimal-bl-pure',1,'The pure-model implementation assumes no mixing between the Standard Model Z and ZB−L, denoted Z′.','neutral_gauge_boson_mixing','source_assumed');
INSERT INTO "theory_assumptions" VALUES(21,'u1-leptonic-opposite-nur',1,'Select the three-RH-neutrino inventory of Section 2 for the Section 3.2 charge family. b=0 means neutral retained neutrinos; deleting them is a separate field-content branch.','field_content_branch','source_scoped_selection');
INSERT INTO "theory_assumptions" VALUES(22,'u1-sm-top-only-charge',1,'Other fermion masses are presumed to arise from higher-dimensional operators after integrating out unspecified UV physics. No particular vector-like inventory, operator dimension or coefficient is selected.','mass_completion_proposal','source_assumed');
INSERT INTO "theory_assumptions" VALUES(23,'u1-smnur-all-sm-yukawas',1,'The charges satisfy all six ACCs. With q=FQ and r=(n1+n2+n3)/3, substituting the universal charged-fermion assignments into Eq. (2.6) leaves n1³+n2³+n3³=3r³. This is an algebraic rendering of the extracted anomaly equation, not the deferred Section 5.2 parametrization.','anomaly_constraint','source_equation_algebraically_rendered');
INSERT INTO "theory_assumptions" VALUES(24,'pp331-displayed',1,'No independent right-handed neutrinos are introduced. The source assumes massless neutrinos and omits lepton mixing in its displayed Yukawa construction.','neutrino_sector','source_assumed');
INSERT INTO "theory_assumptions" VALUES(25,'pp331-displayed',1,'The source uses psi^c=gamma5 C bar(psi)^T and claims that this permits its diagonal charged-lepton Yukawa mass terms. Its equivalence to a consistent conventional fermionic formulation is unresolved; the claimed mass generation is not independently adopted as an established result.','source_specific_charge_conjugation_prescription','source_stated_with_consistency_question');
INSERT INTO "theory_assumptions" VALUES(26,'pp331-displayed',1,'Eq. (10) sets mixed quark terms aside. The current discussion chooses mixing only in the charge −1/3 and −4/3 sectors; this presentation does not establish a symmetry forbidding every omitted Yukawa.','flavor_presentation_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(27,'so10-45-126-sector',1,'For the numerical stability and unification applications, add the leading universal nonlogarithmic τ² correction to the tree-level scalar spectrum and require positive mass-squares for propagating scalars. This is not a full one-loop effective-potential calculation or comparison of competing global minima; a fully consistent precision treatment requires complete one-loop spectra and two-loop running.','spectrum_and_running_approximation','source_assumed');
INSERT INTO "theory_assumptions" VALUES(28,'trinification-n3-adjoint-l',1,'No permutation symmetry among the three SU(3) factors is imposed; no equality of their gauge couplings is required.','discrete_symmetry_scope','source_stated');
INSERT INTO "theory_assumptions" VALUES(29,'trinification-n3-adjoint-l',1,'The TAF application searches for simultaneous asymptotic freedom of gauge, Yukawa and quartic couplings at one loop. The yes* result requires nonzero asymptotic fixed points for lighter-generation Yukawa couplings. It supplies neither arbitrary-coupling TAF nor a numerical benchmark in the PDF.','conditional_rg_application','source_stated');
INSERT INTO "theory_assumptions" VALUES(30,'mssm-rpv-general',1,'SU(4) rotations of (H_d,L_i) are field-coordinate freedom because these superfields have identical gauge quantum numbers, with Y=-1 in the source convention. They transform couplings and VEVs, leaving lambda-double-prime unchanged. This is not an imposed physical SU(4) symmetry of arbitrary fixed couplings.','basis_convention','source_stated');
INSERT INTO "theory_assumptions" VALUES(31,'mssm-rpv-bilinear',1,'An initial basis exists with only mu_i, B_i and mtilde_di^2 providing RPV. In the phase-neglecting VEV-aligned description of Section 2.3, lambda_ijk=(v_d/v_0)(e_0i lambda^e_jk-e_0j lambda^e_ik) and lambda-prime_ijk=(v_d/v_0)e_0i lambda^d_jk. These induced couplings are not independent; additional initial trilinears invalidate these as complete expressions.','defining_operator_restriction_and_basis_conversion','source_stated');
INSERT INTO "theory_assumptions" VALUES(32,'split-susy',1,'Squarks, sleptons and the orthogonal heavy Higgs sector are much heavier than the electroweak scale. Their common mass mtilde is a simplifying threshold assumption, not a demonstrated supersymmetry-breaking mechanism.','scalar_hierarchy_and_threshold_approximation','source_assumed');
INSERT INTO "theory_assumptions" VALUES(33,'split-susy',1,'Fine-tune H=-cos(beta) epsilon Hd*+sin(beta) Hu to have a small quadratic term. At matching project Hu to sin(beta)H and Hd to cos(beta)epsilon H*. The EFT contains only this one scalar doublet.','light_Higgs_projection','source_assumed');
INSERT INTO "theory_assumptions" VALUES(34,'gem-supersoft',1,'The basic framework assumes only supersoft supersymmetry-breaking terms. Later discussions of competing mediation effects are conditional departures.','supersymmetry_breaking_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(35,'gem-supersoft',1,'Vector and adjoint chiral multiplets form an N=2 gauge-sector inventory; Q,U,D,L,E remain N=1. Higgs assignment is unselected. N=2 Higgs assignment mandates Higgs–ESP trilinears; general N=1 adjoint interactions can instead break N=2.','sector_supersymmetry_assignment','source_stated');
INSERT INTO "theory_assumptions" VALUES(36,'gem-supersoft',1,'Hidden–hypercharge kinetic mixing must be controlled. A non-Abelian hypercharge embedding is proposed as a way to make its absence natural and radiatively stable; no unique GUT embedding is imposed.','conditional_kinetic_mixing_control','source_stated_conditional');
INSERT INTO "theory_assumptions" VALUES(37,'gem-supersoft-messengers',1,'Messenger loops generate both supersoft operators. The adjoint scalar bilinear has the problematic relative loop hierarchy described in Section 3.1. An independent cancelling contribution is an optional approximately one-percent tuning, not part of the displayed minimal messenger action.','matching_and_optional_cancellation','source_stated');
INSERT INTO "theory_assumptions" VALUES(38,'gem-supersoft-su5-bachelors',1,'For the illustrative Section 3.2 construction neglect Eq. (2.9), permit only soft N=2 violations through ESP and bachelor masses, and omit ESP/bachelor self-trilinears and Higgs–ESP/bachelor trilinears. These omissions are simplifying assumptions, not an approximate protecting symmetry.','benchmark_operator_restrictions','source_assumed');
INSERT INTO "theory_assumptions" VALUES(39,'gem-supersoft-su3cubed-bachelors',1,'For the illustrative Section 3.2 construction neglect Eq. (2.9), permit only soft N=2 violations through ESP and bachelor masses, and omit ESP/bachelor self-trilinears and Higgs–ESP/bachelor trilinears. These omissions are simplifying assumptions, not an approximate protecting symmetry.','benchmark_operator_restrictions','source_assumed');
INSERT INTO "theory_assumptions" VALUES(40,'general-gauge-mediation',1,'As all MSSM gauge couplings tend to zero, the theory decouples into the MSSM and a separate spontaneously supersymmetry-breaking hidden sector. Messengers, when present, are included in that hidden sector.','defining_decoupling_condition','source_stated');
INSERT INTO "theory_assumptions" VALUES(41,'general-gauge-mediation',1,'The hidden global symmetry that is weakly gauged is not spontaneously broken. Nontrivial unified-group gauge-messenger embeddings are excluded from this framework; independent-coupling hidden gauge sectors are possible but unselected.','framework_domain','source_stated');
INSERT INTO "theory_assumptions" VALUES(42,'u1-minimal-gauge-messenger-toy',1,'Treat X through its prescribed expectation value. No potential or dynamical sector generating its scalar and auxiliary background is supplied.','spurion_approximation','source_scope_inference');
INSERT INTO "theory_assumptions" VALUES(43,'general-gauge-mediation-higgs-operators',1,'Assume composite chiral operators O_u,d have short-distance dimension two. Expand in lambda_u,d and visible gauge couplings; decoupling requires both sets of couplings to vanish. A satisfactory correlator hierarchy is not established.','operator_dimension_and_decoupling','source_assumed');
INSERT INTO "theory_assumptions" VALUES(44,'ksvz-neutral-triplet',1,'The benchmark does not supply a sufficiently protected accidental PQ symmetry. SM gauge invariance alone permits the omitted bare Q mass. Footnote 20''s discrete mass-forbidding transformation is an optional mechanism, not a complete PQ-quality solution incorporated here.','PQ_quality_limitation','source_stated');
INSERT INTO "theory_assumptions" VALUES(45,'dfsz-i-quartic',1,'The common DFSZ benchmark assumes PQ-invariant operator selection without supplying a quality-protection completion. Gauge invariance permits mu_H² H_u H_d, which would break PQ and is not included in the displayed benchmark potential. This limitation applies to both lepton variants.','PQ_quality_limitation','source_stated');
INSERT INTO "theory_assumptions" VALUES(46,'smash-down',1,'Assume the infrared gravitational action approaches Eq. (22), with other operator coefficients negligible. The preferred background energy scales are argued to remain below MP; Planckian field values and a quantum-gravity completion remain unresolved.','gravitational_EFT_truncation','source_assumed');
INSERT INTO "theory_assumptions" VALUES(47,'smash-down',1,'The main stability analysis requires a positive effective potential away from its zero-energy absolute minimum, checked to approximately 30MP. This is a conservative analysis selection; metastable alternatives are not excluded from the general construction.','analysis_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(48,'smash-down',1,'PQ-invariant operator selection is assumed. An accidental origin from an exact discrete symmetry is suggested, but no discrete charge assignment or explicit quantum-gravity-compatible completion is supplied.','PQ_quality_completion_scope','source_stated_limitation');
INSERT INTO "theory_assumptions" VALUES(49,'lns-two-singlet-quarks',1,'Use the supersymmetric example and neglect soft supersymmetry-breaking terms. Superfield inventory below organizes the source''s quark and scalar component labels; no separate component copies are counted.','supersymmetric_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(50,'lns-two-singlet-quarks',1,'Nonzero texture entries specify orders of magnitude with generic coefficients. Equal powers do not require equal coefficients; hierarchy estimates assume no cancellations changing leading masses or ranks.','texture_interpretation','agent_inferred');
INSERT INTO "theory_assumptions" VALUES(51,'lns-two-singlet-quarks',1,'The continuous-charge description is not a completed discrete gauge theory. The example Z3 × Z3 × Z5 subgroup has a source-claimed absence of QCD anomalies, but lepton assignments, SU(2) anomalies and an R versus non-R realization remain unresolved.','completion_scope','source_stated_limitation');
INSERT INTO "theory_assumptions" VALUES(52,'lns-single-singlet-quarks',1,'Replace the two singlets by one S with H(S)=-1 and replace the horizontal action by H=2H1+3H2. The inherited neutral Higgs horizontal charges remain zero. The former two-charge zeros are no longer required; this is not just a numerical epsilon choice.','defining_field_and_symmetry_replacement','source_stated');
INSERT INTO "theory_assumptions" VALUES(53,'lns-reduced-quarks',1,'Select the combined reduced realization with mu=0 and the effective texture of (9.3). The removed heavy multiplets restrict generated operators beyond horizontal permission alone; do not infer that every zero of (9.3) is enforced by the continuous horizontal charges.','defining_heavy_inventory_and_rank_restriction','source_stated_with_scope_qualification');
INSERT INTO "theory_assumptions" VALUES(54,'af-a4-susy-effective',1,'Soft masses are much smaller than the scales in w_d. First solve the supersymmetric F-term equations, then include soft effects. The potential also contains gauge D terms and possible additional soft terms that are not fully enumerated.','alignment_approximation','source_assumed');
INSERT INTO "theory_assumptions" VALUES(55,'af-a4-susy-effective',1,'For the selected alignment choose positive xi_tilde and driving-field soft squared masses, and negative phiS and xi soft squared masses. Negative phiT soft squared mass can eliminate its trivial solution. These are vacuum-selection choices, not universal restrictions on the operator specification.','soft_vacuum_selection','source_assumed');
INSERT INTO "theory_assumptions" VALUES(56,'af-a4-susy-effective',1,'Assume one-loop stabilization of the undetermined large-u direction. Additional fields, exemplified by sigma with a coupling g_sigma theta sigma², are implicitly assumed to stabilize theta near the cutoff. Their full charges, inventory and potential are unspecified; no unique sigma completion is instantiated.','radiative_completion','source_assumed');
INSERT INTO "theory_assumptions" VALUES(57,'af-a4-susy-effective',1,'Assume v_u,d much smaller than Lambda and an unspecified electroweak-breaking mechanism, possibly radiative after supersymmetry breaking. The leading driving sector contains no Higgs terms; suppressed Higgs factors remain present in the lepton interactions.','electroweak_completion','source_assumed');
INSERT INTO "theory_assumptions" VALUES(58,'af-a4-susy-effective',1,'Choose coordinates among the two identically transforming singlets so that xi_tilde is the combination coupling to (phiS0 phiS) in w_d. Absence of the corresponding xi coupling in this basis is not a symmetry prohibition or removal of a physical singlet.','singlet_basis_convention','source_stated');
INSERT INTO "theory_assumptions" VALUES(59,'modular-a4-flavonfree-seesaw',1,'Assume K=-h log(-iτ+iτbar)+ΣI(-iτ+iτbar)^(-kI)|ϕI|² with h>0. This is a selected Kähler potential, not the unique modular-invariant kinetic structure. At fixed τ the canonical rescalings can be absorbed into α,β,γ,g1,g2,Λ.','kahler_structure','source_assumed');
INSERT INTO "theory_assumptions" VALUES(60,'modular-a4-flavonfree-seesaw',1,'Treat the modulus vacuum value as a scanned spurion. No stabilization potential or dynamically selected minimum is supplied. No flavon other than τ is introduced.','vacuum_dynamics_scope','source_stated');
INSERT INTO "theory_assumptions" VALUES(61,'grv-quark-flavor-u3',1,'Assume a realistic flavor-breaking vacuum. The authors state that two bifundamentals cannot realize the SM Yukawa pattern with a renormalizable potential. Higher-dimensional potential terms are a proposed remedy, perturbative if their cutoff exceeds the largest flavon VEV; no such potential is specified.','scalar_completion_scope','source_stated_limitation');
INSERT INTO "theory_assumptions" VALUES(62,'grv-quark-flavor-u3',1,'The authors'' anomaly-cancellation argument motivates the four exotic chiral flavor multiplets. For full classical U(3)^3 they identify residual U(1)QL × SU(2)L² and U(1)QL × U(1)Y² anomalies; the selected gauging excludes U(1)QL. This records their argument without an independent anomaly calculation.','anomaly_cancellation_argument','source_stated');
INSERT INTO "theory_assumptions" VALUES(63,'numsm',1,'Assume Eq. (1) remains the low-energy theory up to a Planck or grand-unified scale. This motivates avoiding a new mass scale above the electroweak scale; it does not establish an ultraviolet completion.','range_of_validity','source_assumed');
INSERT INTO "theory_assumptions" VALUES(64,'numsm',1,'For regime 122 impose zero initial sterile population and zero initial active lepton-flavor asymmetry. These are cosmological initial conditions, not a vacuum or a defining absence of sterile fields.','cosmological_initial_conditions','source_assumed');
INSERT INTO "theory_assumptions" VALUES(65,'numsm',1,'In regime 122 neglect lepton-number-changing and sterile helicity-flip processes suppressed by small Yukawas and M_I/T. Conservation of active lepton number plus sterile helicity applies to this kinetic approximation; no exact lepton-number symmetry of the Majorana Lagrangian is imposed.','relativistic_kinetic_approximation','source_stated');
INSERT INTO "theory_assumptions" VALUES(66,'weinberg-t1i-first-row',1,'This record retains necessary diagrammatic field assignments only. A scalar with Higgs-doublet quantum numbers is not assigned an electroweak-breaking VEV without a potential analysis.','specification_scope','source_stated_limitation');
INSERT INTO "theory_assumptions" VALUES(67,'weinberg-t41ii-first-row',1,'The scalar-only loop cannot implement the paper''s Majorana-mass-only lepton-number-violation mechanism. Generic charge assignments allowing the required finite T4 interactions also allow the associated tree-level seesaw vertex.','leading_contribution_limitation','source_stated');
INSERT INTO "theory_assumptions" VALUES(68,'su4-hypercolor-partial-compositeness',1,'The anomalous dimensions needed for realistic partial-compositeness masses are not demonstrated. The higher-scale origin of elementary–hypercolor four-fermion interactions is unspecified.','dynamical_and_ultraviolet_completion_gap','source_stated_limitation');
INSERT INTO "theory_assumptions" VALUES(69,'su4-hypercolor-partial-compositeness',1,'Assume one linear combination of the spin-1/2 color-triplet channels creates a Dirac (5,3)2/3 resonance of mass M below the generic resonance scale Lambda. Other channels, color sextets and spin-3/2 resonances are not retained as light states.','light_resonance_truncation','source_assumed');
INSERT INTO "theory_assumptions" VALUES(70,'su4-hypercolor-partial-compositeness',1,'In the explicit third-family mass analysis neglect subleading quadratic top operators. Their omission is an approximation, not a symmetry prohibition. Remaining fermion masses are assigned to quadratic elementary-fermion couplings.','mass_analysis_truncation','source_assumed');
INSERT INTO "theory_assumptions" VALUES(71,'littlest-higgs-minimal',1,'Fermion charges must make the displayed interactions gauge invariant and reproduce diagonal Standard Model charges. Individual U(1) assignments are unselected. Only Standard Model anomaly cancellation is required within the retained EFT; additional cutoff-scale fermions may cancel broken-subgroup anomalies.','charge_and_ultraviolet_completion_scope','source_stated_limitation');
INSERT INTO "theory_assumptions" VALUES(72,'littlest-higgs-minimal',1,'Remaining Standard Model Yukawa couplings are small. Their one-loop quadratic Higgs corrections are neglected for a cutoff of order 10 TeV; they are not claimed to vanish identically.','radiative_approximation','source_assumed');
INSERT INTO "theory_assumptions" VALUES(73,'twin-higgs-unextended',1,'Assume the nonlinearly realized symmetry is O(8), rather than only SU(4), to restrict custodial-SU(2)-violating effective operators.','custodial_protection','source_assumed');
INSERT INTO "theory_assumptions" VALUES(74,'twin-higgs-unextended',1,'Dominant electroweak and top interactions respect sector interchange. Smaller Yukawa couplings need not obey it because their contributions to the Higgs potential are small.','discrete_symmetry_breaking_scope','source_stated');
INSERT INTO "theory_assumptions" VALUES(75,'twin-higgs-unextended',1,'The unextended branch has no particles charged under both gauge sectors. The reported absence of nonzero kinetic mixing through three loops is preliminary. A massless twin photon is considered potentially viable if kinetic mixing is absent at the cutoff; no all-orders prohibition is asserted.','matter_branch_and_conditional_portal_boundary','source_stated_conditional');
INSERT INTO "theory_assumptions" VALUES(76,'twin-higgs-extended-top',1,'The cross-sector exotic quarks carry both U(1) charges and generate kinetic mixing at one loop. The source concludes that its experimental constraints require a heavy twin photon in this class. This is a source-era phenomenological condition; its microscopic mass origin is unspecified.','conditional_photon_mass_requirement','source_stated');
INSERT INTO "theory_assumptions" VALUES(77,'fraternal-twin-higgs',1,'The effective construction addresses a cutoff of order 5–10 TeV; numerical estimates use 5 TeV. Further ultraviolet protection is unspecified.','ultraviolet_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(78,'fraternal-twin-higgs',1,'Twin hypercharge is absent below the cutoff: it was either never gauged or broken near the cutoff. No ultraviolet breaking sector is selected.','defining_gauge_inventory','source_assumed');
INSERT INTO "theory_assumptions" VALUES(79,'fraternal-twin-higgs',1,'First- and second-generation twin fermions are absent. The three species indexed by a in the twin quark sector become color components, not three twin generations.','defining_fermion_inventory','source_stated');
INSERT INTO "theory_assumptions" VALUES(80,'fraternal-twin-higgs',1,'Use perturbative lambda approximately at most one, f a few times v, and sigma below lambda. Neglect the technically small rho coupling in the working approximation; this is not a symmetry prohibition or an exact all-scale zero.','scalar_analysis_approximation','source_assumed');
INSERT INTO "theory_assumptions" VALUES(81,'fraternal-twin-higgs',1,'The neutrino within the twin lepton doublet is sufficiently light in the minimal summary and may have a Majorana mass. Neither its mass-generation mechanism nor an additional right-handed neutrino inventory is fixed.','neutrino_completion_scope','source_stated');
INSERT INTO "theory_assumptions" VALUES(82,'large-extra-dimensions-framework',1,'The higher-dimensional Planck scale and ultraviolet cutoff are of order m_EW, taken as the only fundamental short-distance scale.','fundamental_scale','source_assumed');
INSERT INTO "theory_assumptions" VALUES(83,'large-extra-dimensions-framework',1,'Assume ultraviolet physics does not induce weak-scale-suppressed operators causing dangerous proton decay or neutral-meson mixing. No protecting mechanism is specified.','ultraviolet_operator_suppression','source_assumed');
INSERT INTO "theory_assumptions" VALUES(84,'large-extra-dimensions-framework',1,'Low-energy supersymmetry is not required for hierarchy stabilization. Supersymmetry or a superstring theory above the weak cutoff remains possible but unconstructed.','ultraviolet_completion_scope','source_stated');
INSERT INTO "theory_assumptions" VALUES(85,'six-dimensional-pati-salam-vortex',1,'Postulate a bulk gauge mass gap of order Λ. The proposed conditions are nonabelian enlargement of the SM gauge group, absence of symmetry-enforced light bulk matter and a tree-level gauge coupling that diverges away from the vortex. Higher-dimensional confinement is explicitly not established.','gauge_localization_dynamics','source_assumed');
INSERT INTO "theory_assumptions" VALUES(86,'six-dimensional-pati-salam-vortex',1,'Vortex mass Yukawas are flavor-universal; flavor violation is confined to ordinary core Higgs Yukawas. A flavor symmetry is suggested but no group or action is specified.','flavor_restriction','source_assumed');
INSERT INTO "theory_assumptions" VALUES(87,'rs-two-brane-warped',1,'Assume k < M to trust the classical bulk gravitational solution.','classical_curvature_validity','source_assumed');
INSERT INTO "theory_assumptions" VALUES(88,'rs-two-brane-warped',1,'The classical radius is undetermined. Subsequent effective calculations replace T(x) by r_c, assuming an unresolved stabilization mechanism with modulus mass at least 10^(-4) eV. No stabilizing potential or added field is specified.','unresolved_stabilization_and_fixed_radius_approximation','source_assumed_with_explicit_completion_gap');
INSERT INTO "theory_assumptions" VALUES(89,'ued-orbifold-framework',1,'Treat the higher-dimensional action as an EFT below Ms with 1/R < Ms. The source expects Ms not to exceed the upper end of the perturbative range.','effective_theory_cutoff','source_assumed');
INSERT INTO "theory_assumptions" VALUES(90,'ued-orbifold-framework',1,'The paper attributes exact KK-number conservation to the displayed bulk action and orbifold projection, without added violating interactions. Retain this as the source''s working prescription; no all-orders closure under quantum-generated localized operators is established here.','source_selection_rule_scope','source_stated_with_consistency_question');
INSERT INTO "theory_assumptions" VALUES(91,'ued-orbifold-framework',1,'For even delta the source proposes gauge-singlet fermions and Green–Schwarz cancellation. Neither their multiplicities nor their fields and couplings are supplied; the enumerated Standard Model bulk sector is not a completed anomaly-cancelling theory.','anomaly_completion_gap','source_stated_with_unspecified_completion');
INSERT INTO "theory_assumptions" VALUES(92,'holographic-su3-brane-scalar-mediator',1,'Ultraviolet dynamics breaks SU(3)L × U(1)X and removes the unwanted fermion zero modes, leaving QL^(D), DR^(S) and the infrared UR before infrared mixing. No particular ultraviolet field completion is selected.','ultraviolet_completion_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(93,'holographic-su3-brane-scalar-mediator',1,'The mediator''s boundary masses must admit a stable scalar sector. The source does not supply ultraviolet dynamics enforcing the desirable doublet-singlet mass equality; quantum corrections generally spoil it.','scalar_completion_gap','source_stated_limitation');
INSERT INTO "theory_assumptions" VALUES(94,'hidden-valley-chi-two-flavor',1,'Use the baseline without the additional hidden flavor-changing interactions of Unstable C; its terminal C-containing mesons are stable. The proposed flavor-violating completions are not inherited.','interaction_scope','source_stated');
INSERT INTO "theory_assumptions" VALUES(95,'hidden-valley-x-adjoint-prompt',1,'Assume X immediately decays to a hidden gluon and one or more SM quarks or gluons. No microscopic decay operator or spin assignment is specified.','constituent_decay','source_assumed');
INSERT INTO "theory_assumptions" VALUES(96,'hidden-valley-x-adjoint-stable',1,'Assume X is stable. A hidden gluon screens its hidden-adjoint charge to form a color-charged composite Xgv. No protecting symmetry or operator restriction is supplied.','constituent_stability','source_assumed');
INSERT INTO "theory_assumptions" VALUES(97,'hidden-valley-x-fundamental-stable',1,'Assume X is stable as a constituent. The X–Xbar system is linked by a confining hidden flux tube, loses energy by ordinary-gluon or hidden-glueball emission, and eventually annihilates.','constituent_stability_and_confinement','source_assumed');
INSERT INTO "theory_assumptions" VALUES(98,'secluded-dirac-u1-higgsed',1,'ψ stability is only supported within the displayed mass and gauge interactions. A symmetry protecting it against all higher-dimensional decay operators is not specified.','stability_completion_scope','source_scope_inference');
INSERT INTO "theory_assumptions" VALUES(99,'secluded-dirac-u1-higgsed',1,'The thermal relic calculation assumes initial thermal and chemical equilibrium. Requiring V decays to maintain contact near T=0.05mψ gives Eq. (15), a stronger condition than decay before BBN. Alternative early UV contact is a separate, unconstructed completion.','conditional_thermal_history','source_assumed');
INSERT INTO "theory_assumptions" VALUES(100,'secluded-fermion-scalar-portal',1,'No discrete stabilizing symmetry or ultraviolet protection for ψ is specified. The prepared phase-invariance interpretation is not promoted to a full symmetry before resolving the fermion''s Dirac/Majorana character.','stability_completion_scope','source_scope_inference');
INSERT INTO "theory_assumptions" VALUES(101,'simp-sp-pions',1,'For the relic calculation, 3 to 2 freeze-out sets the abundance while scattering maintains kinetic equilibrium with the SM bath. Annihilation into the SM is subdominant; the required portal is unspecified.','conditional_thermal_application','source_assumed');
INSERT INTO "theory_assumptions" VALUES(102,'simp-su-pions',1,'For the relic calculation, 3 to 2 freeze-out sets the abundance while scattering maintains kinetic equilibrium with the SM bath. Annihilation into the SM is subdominant; the required portal is unspecified.','conditional_thermal_application','source_assumed');
INSERT INTO "theory_assumptions" VALUES(103,'simp-o-pions',1,'For the relic calculation, 3 to 2 freeze-out sets the abundance while scattering maintains kinetic equilibrium with the SM bath. Annihilation into the SM is subdominant; the required portal is unspecified.','conditional_thermal_application','source_assumed');
INSERT INTO "theory_assumptions" VALUES(104,'vector-higgs-portal-z2-eft',1,'Vector stability requires no kinematically open hidden decay channels, only the stated communication with the SM, and xi1=xi2=0.','stability_conditions','source_assumed');
INSERT INTO "theory_assumptions" VALUES(105,'vector-portal-stueckelberg-higgs',1,'No additional hidden-U(1)-charged fields beyond the absorbed axion. The hidden U(1) is orthogonal to the SM. The source states xi1=xi2=0 and no tree-level or radiatively induced hypercharge mixing.','minimal_inventory_and_mixing_restriction','source_stated');
INSERT INTO "theory_assumptions" VALUES(106,'vector-portal-stueckelberg-scalar',1,'No additional hidden-U(1)-charged fields beyond the absorbed axion. The mass-controlling S does not add charged matter in this example. The source states xi1=xi2=0 and no tree-level or radiatively induced hypercharge mixing for the orthogonal hidden U(1).','minimal_inventory_and_mixing_restriction','source_stated');
INSERT INTO "theory_assumptions" VALUES(107,'vector-portal-stueckelberg-scalar',1,'Eliminate S only when m_h²,m_X² are much smaller than m_S². The source accepts an approximate order-of-magnitude hierarchy for its illustrative estimates; this is not an exact decoupling-error bound.','conditional_heavy_field_elimination','source_assumed');
INSERT INTO "theory_assumptions" VALUES(108,'vector-higgs-portal-z2-eft',1,'In regime 182 set the symmetry-allowed vector quartic lambda to zero for simplicity and scan lambda_hv and m_X without specifying a microscopic origin.','conditional_scan_restriction','source_assumed');
INSERT INTO "theory_assumptions" VALUES(109,'vector-higgs-portal-z2-eft',1,'Regime 182 assumes thermal WIMP production. Invisible h -> XX decay is open for m_X<m_h/2, with enhanced longitudinal-vector contributions. Experimental comparisons refer to the source-era constraints.','conditional_thermal_and_collider_application','source_assumed');
INSERT INTO "theory_assumptions" VALUES(110,'smeft-d6-b-conserving',1,'Retain three generations and all flavor assignments. No flavor-universal, flavor-diagonal or CP-conserving restriction is imposed on the general operator space. Hermitian conjugation and flavor-index permutations must be respected when specifying coefficient tensors; 59 is not a generation-resolved coefficient count.','flavor_and_coefficient_scope','source_stated');
INSERT INTO "theory_assumptions" VALUES(111,'general-heavy-field-tree-matching',1,'Assume a local four-dimensional Poincare-invariant EFT below a cutoff, linearly invariant under the SM gauge group, containing the SM fields and particles of spin at most one. Extra fermions are vector-like under the SM group or Majorana.','framework_domain','source_assumed');
INSERT INTO "theory_assumptions" VALUES(112,'general-heavy-field-tree-matching',1,'General Proca vectors are admitted without imposing gauge invariance beyond the SM. Extended spontaneously broken gauge theories form a possible special case.','vector_completion_scope','source_assumed');
INSERT INTO "theory_assumptions" VALUES(113,'general-heavy-field-tree-matching',1,'Use diagonal canonical kinetic terms and diagonal masses in the electroweak-symmetric phase, apart from the stated L1 mixing exception. Shift gauge-invariant singlet VEVs away before using the dictionary; this is a field-coordinate prescription, not a singlet sign symmetry.','matching_basis','source_assumed');
INSERT INTO "theory_assumptions" VALUES(114,'general-heavy-field-tree-matching',1,'The identified SM Higgs is the unique scalar eigenstate with a nondegenerate negative squared-mass eigenvalue; all other scalar squared-mass eigenvalues are positive in the chosen symmetric-phase basis.','matching_spectrum','source_assumed');
INSERT INTO "theory_boundaries" VALUES(1,'mchm-spinorial',1,11,'UV','z=L0=1/k','SU(3)c×SU(2)L×U(1)Y',NULL);
INSERT INTO "theory_boundaries" VALUES(2,'mchm-spinorial',1,11,'IR','z=L1','SU(3)c×SO(4)×U(1)B−L',NULL);
INSERT INTO "theory_boundaries" VALUES(3,'mchm-spinorial-scalar14',1,14,'UV','z=L0',NULL,'Inherited UV boundary; scalar component conditions encode whether the corresponding external source propagates.');
INSERT INTO "theory_boundaries" VALUES(4,'mchm-spinorial-scalar14',1,14,'IR','z=L1',NULL,'Inherited IR boundary; the added scalar has an SO(4)-singlet tadpole here.');
INSERT INTO "theory_boundaries" VALUES(5,'rs-two-brane-warped',1,144,'Hidden brane','phi=0',NULL,'Orbifold fixed-point 3-brane extending along x^mu. Positive vacuum energy in the selected k>0 flat background; internal residual gauge symmetry unspecified.');
INSERT INTO "theory_boundaries" VALUES(6,'rs-two-brane-warped',1,144,'Visible brane','phi=pi',NULL,'Orbifold fixed-point 3-brane supporting the Standard Model. Negative vacuum energy in the selected k>0 flat background; no internal gauge projection specified.');
INSERT INTO "theory_boundaries" VALUES(7,'ued-orbifold-framework',1,147,'First orbifold endpoint','y=0','SU(3)C x SU(2)W x U(1)Y before Higgs breaking','Five-dimensional specialization only. The projection retains all Standard Model gauge zero modes; no independent brane matter sector is added.');
INSERT INTO "theory_boundaries" VALUES(8,'ued-orbifold-framework',1,147,'Second orbifold endpoint','y=pi R','SU(3)C x SU(2)W x U(1)Y before Higgs breaking','Same parity assignments as the first endpoint. No boundary gauge-group reduction is selected.');
INSERT INTO "theory_boundaries" VALUES(9,'holographic-su3-brane-scalar-mediator',1,151,'UV','z=L0=1/k','SU(2)L × U(1)Y','Scalar/dynamical ultraviolet breaking; bare Neumann gauge assignments precede boundary mass effects.');
INSERT INTO "theory_boundaries" VALUES(10,'holographic-su3-brane-scalar-mediator',1,151,'IR','z=L1','SU(2)L × U(1)Y in the aligned Sigma vacuum','Supports Sigma, UR and the displayed Yukawa and mediator interactions.');
INSERT INTO "theory_boundaries" VALUES(11,'holographic-boundary-pgb-framework',1,152,'UV','z=L0','H0',NULL);
INSERT INTO "theory_boundaries" VALUES(12,'holographic-boundary-pgb-framework',1,152,'IR','z=L1','H1',NULL);
INSERT INTO "theory_boundaries" VALUES(13,'holographic-boundary-pgb-framework',1,154,'UV','z=L0','H',NULL);
INSERT INTO "theory_boundaries" VALUES(14,'holographic-boundary-pgb-framework',1,154,'IR','z=L1','H',NULL);
INSERT INTO "theory_breaking_steps" VALUES(1,'real-singlet-z2',1,2,NULL,'<S> = Sc at the critical temperature','Z2: S → −S','Singlet sign symmetry broken','Source-stated temporary breaking; chronological position within a full thermal phase sequence is unspecified.');
INSERT INTO "theory_breaking_steps" VALUES(2,'lr-triplet-parity',1,5,1,'⟨ΔR⟩ = [[0,0],[vR,0]]; ⟨ΔL⟩ = 0 at this stage','GLR','Standard Model gauge symmetry, with color suppressed in the notation','Source-stated first-stage pattern; scalar-potential derivation not reproduced.');
INSERT INTO "theory_breaking_steps" VALUES(3,'lr-triplet-parity',1,5,2,'⟨Φ⟩ = diag(v1,v2 exp(iα))','Standard Model electroweak symmetry','U(1)em','Source-stated second-stage pattern; suppressed color is unaffected by this notation.');
INSERT INTO "theory_breaking_steps" VALUES(4,'lr-triplet-charge-conjugation',1,6,1,'⟨ΔR⟩ = [[0,0],[vR,0]]; ⟨ΔL⟩ = 0 at this stage','GLR','Standard Model gauge symmetry, with color suppressed in the notation','Source-stated first-stage pattern; scalar-potential derivation not reproduced.');
INSERT INTO "theory_breaking_steps" VALUES(5,'lr-triplet-charge-conjugation',1,6,2,'⟨Φ⟩ = diag(v1,v2 exp(iα))','Standard Model electroweak symmetry','U(1)em','Source-stated second-stage pattern; suppressed color is unaffected by this notation.');
INSERT INTO "theory_breaking_steps" VALUES(6,'mchm-spinorial',1,9,1,'Unspecified high-dimension strong-sector operator; scale fπ∼(√N/4π)mρ','SU(3)c×SO(5)×U(1)B−L','SU(3)c×SO(4)×U(1)B−L','Source-assumed spontaneous strong-sector breaking; microscopic dynamics unspecified.');
INSERT INTO "theory_breaking_steps" VALUES(7,'mchm-spinorial',1,9,2,'Nonzero Higgs VEV with v=ϵfπ','SO(4)','Custodial SO(3)','Source-stated conditional Higgs-vacuum pattern; top loops can generate the required misalignment.');
INSERT INTO "theory_breaking_steps" VALUES(8,'georgi-machacek-general',1,10,1,'Identity-proportional aligned Φ and X vevs','Scalar-sector SU(2)L × SU(2)R','Diagonal custodial SU(2)','Source-stated custodial preservation; diagonal identification follows the explicitly marked inference in assertion 213. Hypercharge breaks custodial symmetry in the full theory.');
INSERT INTO "theory_breaking_steps" VALUES(9,'su5-georgi-glashow-review',1,13,1,'Scalar 24 expectation value','SU(5)','SU(3) × SU(2) × U(1)','Source-stated pattern; no explicit alignment or minimum calculation extracted.');
INSERT INTO "theory_breaking_steps" VALUES(10,'su5-georgi-glashow-review',1,13,2,'Electroweak component of scalar 5 expectation value','SU(3) × SU(2) × U(1)','SU(3) × U(1)em','Source-stated pattern.');
INSERT INTO "theory_breaking_steps" VALUES(11,'minimal-bl-pure',1,18,NULL,'Nonzero χ and neutral H vacuum expectation values','SU(3)C × SU(2)L × U(1)Y × U(1)B−L','Continuous subgroup SU(3)C × U(1)em','Prepared assertion 502 inference from scalar charges and VEV-dependent masses. No chronological sequence, residual discrete group or global-minimum result is asserted.');
INSERT INTO "theory_breaking_steps" VALUES(12,'pp331-displayed',1,19,1,'<chi>','SU(3)L × U(1)N','SU(2)L × U(1)Y','Source-stated hierarchical breaking in Eq. (9); color is outside this displayed electroweak chain.');
INSERT INTO "theory_breaking_steps" VALUES(13,'pp331-displayed',1,19,2,'<rho>,<eta>','SU(2)L × U(1)Y','U(1)em','Source-stated second stage; no transition-temperature calculation or global-minimum proof is inferred.');
INSERT INTO "theory_breaking_steps" VALUES(14,'ql421-dirac',1,20,1,'⟨χ_R^0⟩=vχ/√2 in the fourth component','SU(4)C × SU(2)L × U(1)R','SU(3)C × SU(2)L × U(1)Y','Source-stated pattern; assumed viable vacuum.');
