INSERT INTO "theory_fields" VALUES(49,'mchm-spinorial',1,11,'AM','bulk gauge connection',NULL,NULL,NULL,NULL,NULL,'Boundary-condition rows concern Aμ. In gauge ∂z(A5/z)=0, physical A5 survives only in SO(5)/SO(4), with A5(x,z)=z√[2/(L1²−L0²)]h(x). The Higgs is this component, not an independent added bulk scalar.');
INSERT INTO "theory_fields" VALUES(50,'mchm-spinorial',1,11,'ξq','bulk Dirac spinor','1/2',NULL,'One per quark family',NULL,NULL,'q and Q denote SU(2)L and SU(2)R doublets; L and R denote 4D Lorentz chirality.');
