INSERT INTO "theory_fields" VALUES(54,'mchm-spinorial-scalar14',1,13,'ϕi','external scalar source collection','0',NULL,NULL,NULL,NULL,'Sources in 14_0 of SO(5)×U(1)B−L; may be dynamical or auxiliary. Under SO(4), 14=9+4+1=(3,3)+(2,2)+(1,1). This is a global/spurion embedding, not a new gauged SO(5) in four dimensions.');
