INSERT INTO "theory_fields" VALUES(57,'georgi-machacek-general',1,15,'φ','scalar doublet','0',NULL,'1','complex','Standard Model Higgs doublet','φ=(φ+,φ0)T; supplies fermion masses as in the SM. It is not an additional doublet beyond the one encoded by Φ.');
