INSERT INTO "theory_fields" VALUES(162,'minimal-bl-pure',1,47,'χ','scalar singlet under the Standard Model','0',NULL,'1','complex',NULL,'Charged under U(1)B−L. Its radial excitation mixes with the Higgs excitation; the two scalar mass eigenstates are not additional independent multiplets.');
