INSERT INTO "theory_fields" VALUES(194,'pp331-displayed',1,53,'Q1L=(u,d,J1)L','quark multiplet',NULL,'left-handed','1 family, with color counted separately',NULL,NULL,'J1 has electric charge +5/3. This is a chiral SU(3)L multiplet, not one of the existing vector-like SM quark additions.');
INSERT INTO "theory_fields" VALUES(195,'pp331-displayed',1,53,'QaL: Q2L=(J2,c,s)L; Q3L=(J3,t,b)L','quark antitriplet collection',NULL,'left-handed','2 families; a=2,3',NULL,NULL,'Preserve the printed component order. J2 and J3 have electric charge −4/3; an explicit antitriplet-generator basis remains unresolved.');
