INSERT INTO "theory_fields" VALUES(201,'pp331-displayed',1,53,'rho','scalar triplet','0',NULL,'1',NULL,NULL,'rho=(rho+,rho0,rho++).');
INSERT INTO "theory_fields" VALUES(202,'pp331-displayed',1,53,'chi','scalar triplet','0',NULL,'1',NULL,NULL,'chi=(chi−,chi−−,chi0).');
INSERT INTO "theory_fields" VALUES(203,'pp331-displayed',1,53,'W_mu^a','SU(3)L gauge connection','1',NULL,'8 components',NULL,NULL,'sqrt(2)W+=−(W1−iW2), sqrt(2)V−=−(W4−iW5), sqrt(2)U−−=−(W6−iW7). Physical combinations do not add independent gauge fields.');
INSERT INTO "theory_fields" VALUES(204,'pp331-displayed',1,53,'B_mu','U(1)N gauge connection','1',NULL,'1',NULL,NULL,'Together with W3 and W8 supplies A, Z and Zprime; massive neutral-state expressions use the hierarchical approximation.');
INSERT INTO "theory_fields" VALUES(205,'pp331-sigma-omega',1,54,'sigma','additional scalar triplet','0',NULL,'1',NULL,NULL,'Same quantum numbers as eta; no extended vacuum is specified.');
INSERT INTO "theory_fields" VALUES(206,'pp331-sigma-omega',1,54,'omega','additional scalar triplet','0',NULL,'1',NULL,NULL,'Same quantum numbers as eta; independent of sigma.');
INSERT INTO "theory_fields" VALUES(207,'pp331-sigma-omega',1,54,'eta','inherited scalar triplet',NULL,NULL,NULL,NULL,'pp331-displayed revision 1','Participant in the new epsilon contraction; this record does not add another eta beyond the inherited baseline.');
INSERT INTO "theory_fields" VALUES(208,'ql421-dirac',1,55,'FQL','fermion multiplet',NULL,'left-handed',NULL,NULL,NULL,'Contains QL and ℓL, displayed as rows (u,ν) and (d,e). Family indices are suppressed.');
INSERT INTO "theory_fields" VALUES(209,'ql421-dirac',1,55,'Fu','fermion multiplet',NULL,'left-handed',NULL,NULL,NULL,'Fu=(u^c,ν^c); includes the conjugate right-handed neutrino. No Majorana condition is imposed on the unified multiplet.');
INSERT INTO "theory_fields" VALUES(210,'ql421-dirac',1,55,'Fd','fermion multiplet',NULL,'left-handed',NULL,NULL,NULL,'Fd=(d^c,e^c).');
INSERT INTO "theory_fields" VALUES(211,'ql421-dirac',1,55,'χ','scalar multiplet','0',NULL,'1',NULL,NULL,'χ=(χu,χ_R^0); its fourth component supplies unified symmetry breaking.');
INSERT INTO "theory_fields" VALUES(212,'ql421-dirac',1,55,'H','scalar doublet','0',NULL,'1',NULL,NULL,'H^T=(H+,H0).');
INSERT INTO "theory_fields" VALUES(213,'ql421-dirac',1,55,'Φ','scalar adjoint weak doublet','0',NULL,'1',NULL,NULL,'Φ=[[Φ8,Φ3],[Φ4,0]]+T4 H2. The adjoint representation does not impose a real-field condition. Source convention: Φ→U*ΦU^T under SU(4)C.');
INSERT INTO "theory_fields" VALUES(214,'ql421-dirac',1,55,'Aμ','SU(4)C gauge connection','1',NULL,NULL,NULL,NULL,'Aμ=[[Gμ,Xμ/√2],[Xμ*/√2,0]]+T4 B′μ. Homogeneous transformation Aμ→UAμU†; the source explicitly suppresses spacetime dependence in that statement.');
INSERT INTO "theory_fields" VALUES(215,'ql421-dirac',1,56,'Φ8','scalar component multiplet','0',NULL,NULL,NULL,NULL,'Color-octet weak doublet inside Φ; not an extra multiplet beyond Φ. No MFV proportionality assumption is inherited from the cited octet model.');
INSERT INTO "theory_fields" VALUES(216,'ql421-dirac',1,56,'Φ3','scalar leptoquark component multiplet','0',NULL,NULL,NULL,NULL,'Upper-right block of Φ in the source''s conjugate-adjoint convention.');
INSERT INTO "theory_fields" VALUES(217,'ql421-dirac',1,56,'Φ4','scalar leptoquark component multiplet','0',NULL,NULL,NULL,NULL,'Lower-left block of Φ; not an independent addition to the unified inventory.');
INSERT INTO "theory_fields" VALUES(218,'ql421-dirac',1,56,'H2','scalar Higgs-doublet component','0',NULL,NULL,NULL,NULL,'Second Higgs doublet in T4 H2 within Φ. Its neutral component has VEV v2/√2.');
INSERT INTO "theory_fields" VALUES(219,'ql421-dirac',1,56,'Xμ','vector leptoquark gauge component','1',NULL,NULL,NULL,NULL,'Massive off-diagonal component of Aμ after unified breaking; not an independently added explicit-mass vector.');
INSERT INTO "theory_fields" VALUES(220,'ql421-inverse-seesaw',1,57,'N','singlet fermion collection',NULL,'left-handed','3',NULL,NULL,'Independent added Weyl fields. A Majorana mass term does not impose a Majorana reality condition on this chiral field record.');
INSERT INTO "theory_fields" VALUES(221,'ql421-inverse-seesaw',1,57,'Fu','inherited fermion multiplet',NULL,'left-handed',NULL,NULL,'ql421-dirac revision 1','Participant in the added Yukawa; not an additional Fu multiplet.');
INSERT INTO "theory_fields" VALUES(222,'ql421-inverse-seesaw',1,57,'χ','inherited scalar multiplet',NULL,NULL,NULL,NULL,'ql421-dirac revision 1','Participant in the added Yukawa; not an additional χ.');
INSERT INTO "theory_fields" VALUES(223,'su5-adjoint-renormalizable',1,59,'5̄_i','ordinary matter fermion multiplet',NULL,NULL,'3 families',NULL,NULL,'Anti-fundamental orientation is explicit in the page-2 inventory. The three-family Yukawa matrices support the family count. Ordinary SM component decomposition is not reconstructed.');
INSERT INTO "theory_fields" VALUES(224,'su5-adjoint-renormalizable',1,59,'10_i','ordinary matter fermion multiplet',NULL,NULL,'3 families',NULL,NULL,'Family-indexed ordinary matter; detailed SM component assignments are not supplied in the prepared scope.');
INSERT INTO "theory_fields" VALUES(225,'su5-adjoint-renormalizable',1,59,'24','adjoint matter fermion multiplet',NULL,NULL,'1',NULL,NULL,'Contains ρ8, ρ3, ρ(3,2), ρ(3̄,2) and ρ0. The triplet ρ3 and singlet ρ0 mediate type III and type I seesaw respectively. These are components of one added multiplet. No field reality condition is inferred solely from the adjoint representation.');
INSERT INTO "theory_fields" VALUES(226,'su5-adjoint-renormalizable',1,59,'5H','scalar multiplet','0',NULL,'1',NULL,NULL,'Contains H1 and T; participates in charged-fermion and neutrino masses. Its conjugate in Eq. (1) is not another independent multiplet.');
INSERT INTO "theory_fields" VALUES(227,'su5-adjoint-renormalizable',1,59,'24H','scalar adjoint','0',NULL,'1',NULL,NULL,'Supplies the unified symmetry-breaking VEV and adjoint-fermion mass splitting. It is retained in addition to the two scalar multiplets used for fermion masses. Field reality is left unspecified.');
INSERT INTO "theory_fields" VALUES(228,'su5-adjoint-renormalizable',1,59,'45H','scalar multiplet','0',NULL,'1',NULL,NULL,'Supplies independent charged-fermion and neutrino Yukawa structures and contains H2 and Φ1–Φ6. Exact component color conjugations and tensor-VEV index placement remain deferred; conjugate occurrences do not add independent multiplets.');
INSERT INTO "theory_fields" VALUES(229,'so10-45-126-sector',1,61,'φ = 45H','scalar adjoint','0',NULL,'1','real',NULL,'Rank-two antisymmetric tensor φij. Its 45 real components are consistent with the potential''s O(45) limit; component states do not add independent multiplets.');
INSERT INTO "theory_fields" VALUES(230,'so10-45-126-sector',1,61,'Σ = 126H','scalar tensor multiplet','0',NULL,'1 complex multiplet','complex self-dual rank-five antisymmetric tensor',NULL,'Appendix A defines Σ=(φ5+φ̃5)/√2 with φ̃ijklm=−i εijklmnopqr φnopqr/5!. Σ* is the conjugate anti-self-dual tensor, not a second independent scalar multiplet.');
INSERT INTO "theory_fields" VALUES(231,'so10-45-126-complex10',1,64,'45H','inherited scalar adjoint','0',NULL,'1 inherited',NULL,'so10-45-126-sector revision 1','Participant in the extended scalar mixing interaction; this does not add another adjoint.');
INSERT INTO "theory_fields" VALUES(232,'so10-45-126-complex10',1,64,'126H','inherited scalar tensor multiplet','0',NULL,'1 inherited complex multiplet',NULL,'so10-45-126-sector revision 1','Its conjugate participates in the Yukawa and scalar mixing operators. No second independent conjugate multiplet is added.');
INSERT INTO "theory_fields" VALUES(233,'so10-45-126-complex10',1,64,'10H','scalar multiplet','0',NULL,'1 complex multiplet','complex',NULL,'The gauge representation is equivalent to its conjugate, but the field is complex in Eq. (17). Thus the 10H and 10H* Yukawa structures are independent. The rejected real-component specialization is not imposed.');
INSERT INTO "theory_fields" VALUES(234,'so10-45-126-complex10',1,64,'16F','matter spinor multiplet collection',NULL,NULL,'Family indices implicit in the Yukawa matrices',NULL,NULL,'Unified fermion participant in Eq. (17). No detailed SM decomposition, extra singlet fermions or Majorana reality condition on the unified multiplet is inferred.');
INSERT INTO "theory_fields" VALUES(235,'trinification-n3-adjoint-l',1,65,'QLi','chiral fermion multiplet collection','1/2',NULL,'3 families',NULL,NULL,'Complete trinification multiplets. Their exotic down-quark components are not additional independent vector-like multiplets.');
INSERT INTO "theory_fields" VALUES(236,'trinification-n3-adjoint-l',1,65,'QRi','chiral fermion multiplet collection','1/2',NULL,'3 families',NULL,NULL,'Retain the source QR label and conjugate-color representation; the label alone is not used to impose a four-component chirality convention.');
INSERT INTO "theory_fields" VALUES(237,'trinification-n3-adjoint-l',1,65,'Li','chiral fermion bi-triplet collection','1/2',NULL,'3 families',NULL,NULL,'Contains ordinary leptons, vector-like doublet components and two sterile components per family. These are components of L, not additional complete Table 2 multiplets.');
INSERT INTO "theory_fields" VALUES(238,'trinification-n3-adjoint-l',1,65,'Hn','scalar bi-triplet collection','0',NULL,'3; n=1,2,3',NULL,NULL,'Each independent bi-triplet contains three Higgs doublets. Hn* and Hn† are conjugates of these same fields.');
INSERT INTO "theory_fields" VALUES(239,'trinification-n3-adjoint-l',1,65,'8L','adjoint fermion','1/2',NULL,'1','Majorana',NULL,'Additional complete SU(3)L adjoint from the first Table 4 row; distinct from components of the three chiral families.');
INSERT INTO "theory_fields" VALUES(240,'trinification-singlet-neutrino-sector',1,66,'Ni','gauge-singlet fermion collection',NULL,NULL,'3; one per generation',NULL,NULL,'Independent added fermions with a Majorana mass matrix. No additional independent charge-conjugate inventory is introduced.');
INSERT INTO "theory_fields" VALUES(241,'trinification-singlet-neutrino-sector',1,66,'Lj','chiral fermion bi-triplet collection','1/2',NULL,'3 families',NULL,'Common trinification sector','Inherited participant in Eq. (2.18), not three further lepton families.');
INSERT INTO "theory_fields" VALUES(242,'trinification-singlet-neutrino-sector',1,66,'Hn','scalar bi-triplet collection','0',NULL,'Unselected scalar index n',NULL,'Common trinification scalar sector','Participant in Eq. (2.18); this mechanism record does not fix the total number of bi-triplets.');
INSERT INTO "theory_fields" VALUES(243,'mssm-rpc-conventional-soft',1,67,'H_u','chiral superfield',NULL,NULL,'1',NULL,NULL,'Scalar components are (H_u^+,H_u^0); higgsinos and auxiliary F belong to this same multiplet. H_u in the component potential denotes its scalar, not another field.');
INSERT INTO "theory_fields" VALUES(244,'mssm-rpc-conventional-soft',1,67,'H_d','chiral superfield',NULL,NULL,'1',NULL,NULL,'Scalar components are (H_d^0,H_d^-); higgsinos and auxiliary F belong to this same multiplet. H_d in the component potential denotes its scalar.');
INSERT INTO "theory_fields" VALUES(245,'mssm-rpc-conventional-soft',1,67,'Q','chiral superfield collection',NULL,NULL,'3 families',NULL,NULL,'Quark-doublet supermultiplets. Tilde Q denotes their scalar components; a complete component and hypercharge inventory is not reconstructed.');
INSERT INTO "theory_fields" VALUES(246,'mssm-rpc-conventional-soft',1,67,'L','chiral superfield collection',NULL,NULL,'3 families',NULL,NULL,'Lepton-doublet supermultiplets. Tilde L denotes their scalar components.');
INSERT INTO "theory_fields" VALUES(247,'mssm-rpc-conventional-soft',1,67,'\bar u','chiral superfield collection',NULL,NULL,'3 families',NULL,NULL,'Bar denotes the source''s conjugate-quark multiplet label, not an anti-chiral superfield. Its scalar is tilde bar-u.');
INSERT INTO "theory_fields" VALUES(248,'mssm-rpc-conventional-soft',1,67,'\bar d','chiral superfield collection',NULL,NULL,'3 families',NULL,NULL,'Bar denotes the source''s conjugate-quark multiplet label. Its scalar is tilde bar-d.');
INSERT INTO "theory_fields" VALUES(249,'mssm-rpc-conventional-soft',1,67,'\bar e','chiral superfield collection',NULL,NULL,'3 families',NULL,NULL,'Bar denotes the source''s conjugate-charged-lepton multiplet label. Its scalar is tilde bar-e.');
INSERT INTO "theory_fields" VALUES(250,'mssm-rpc-conventional-soft',1,67,'V_C, V_L, V_Y','gauge vector superfield collection',NULL,NULL,NULL,'Real vector superfields',NULL,'One vector superfield per gauge generator. Their gaugino components are gluino, winos and bino; gluino and wino indices are adjoint indices. In Wess-Zumino gauge each contains gauge boson, gaugino and auxiliary D. These component labels do not add independent multiplets.');
INSERT INTO "theory_fields" VALUES(251,'mssm-minimal-gauge-messengers',1,72,'S','chiral superfield',NULL,NULL,'1',NULL,NULL,'Gauge singlet coupled to the messengers. <S> is its scalar VEV and <F_S> its auxiliary VEV; no S H_u H_d interaction or NMSSM identification is inferred.');
INSERT INTO "theory_fields" VALUES(252,'mssm-minimal-gauge-messengers',1,72,'q','chiral messenger superfield',NULL,NULL,'1',NULL,NULL,'Additional colored messenger; independent of the inherited MSSM Q and barred quark multiplets.');
INSERT INTO "theory_fields" VALUES(253,'mssm-minimal-gauge-messengers',1,72,'\bar q','chiral messenger superfield',NULL,NULL,'1',NULL,NULL,'Independent conjugate-representation partner of q; the bar does not mean its anti-chiral complex conjugate.');
INSERT INTO "theory_fields" VALUES(254,'mssm-minimal-gauge-messengers',1,72,'ell','chiral messenger superfield',NULL,NULL,'1',NULL,NULL,'Additional weak-doublet messenger, independent of the three MSSM L multiplets.');
INSERT INTO "theory_fields" VALUES(255,'mssm-minimal-gauge-messengers',1,72,'\bar ell','chiral messenger superfield',NULL,NULL,'1',NULL,NULL,'Independent conjugate-representation messenger partner.');
