INSERT INTO "theory_fields" VALUES(376,'af-a4-susy-seesaw',1,114,'xi','inherited flavon chiral superfield',NULL,NULL,NULL,NULL,'af-a4-susy-effective revision 1','Same A4 singlet and R charge zero; replaces its Z3 phase by omega².');
INSERT INTO "theory_fields" VALUES(377,'af-a4-susy-seesaw',1,114,'xi_tilde','inherited flavon chiral superfield',NULL,NULL,NULL,NULL,'af-a4-susy-effective revision 1','Same independent A4 singlet and R charge zero; replaces its Z3 phase by omega².');
INSERT INTO "theory_fields" VALUES(378,'af-a4-susy-seesaw',1,114,'phiS0','inherited driving chiral superfield',NULL,NULL,NULL,NULL,'af-a4-susy-effective revision 1','Same A4 triplet and R charge two; replaces its Z3 phase by omega².');
INSERT INTO "theory_fields" VALUES(379,'af-a4-susy-seesaw',1,114,'xi0','inherited driving chiral superfield',NULL,NULL,NULL,NULL,'af-a4-susy-effective revision 1','Same A4 singlet and R charge two; replaces its Z3 phase by omega².');
INSERT INTO "theory_fields" VALUES(380,'modular-a4-flavonfree-seesaw',1,115,'E1^c','chiral superfield',NULL,NULL,'1',NULL,NULL,'Conjugate charged-lepton multiplet; component scalars and fermions are not separately counted.');
