INSERT INTO "theory_fields" VALUES(388,'grv-quark-flavor-u3',1,116,'QL','quark doublet collection',NULL,'left-handed','One flavor triplet of three SM families',NULL,'Standard Model quark inventory',NULL);
INSERT INTO "theory_fields" VALUES(389,'grv-quark-flavor-u3',1,116,'UR','up-quark collection',NULL,'right-handed','One flavor triplet of three SM families',NULL,'Standard Model quark inventory',NULL);
