INSERT INTO "theory_fields" VALUES(391,'grv-quark-flavor-u3',1,116,'ΨuR','exotic quark chiral multiplet','1/2','right-handed','One SU(3)QL triplet',NULL,NULL,'Independent fermion field, not a superfield or a mass eigenstate.');
INSERT INTO "theory_fields" VALUES(392,'grv-quark-flavor-u3',1,116,'ΨdR','exotic quark chiral multiplet','1/2','right-handed','One SU(3)QL triplet',NULL,NULL,NULL);
