INSERT INTO "theory_fields" VALUES(394,'grv-quark-flavor-u3',1,116,'Ψd','exotic quark chiral multiplet','1/2','left-handed','One SU(3)DR triplet',NULL,NULL,NULL);
INSERT INTO "theory_fields" VALUES(395,'grv-quark-flavor-u3',1,116,'Yu','bifundamental flavon scalar','0',NULL,'1 complex 3 × 3 matrix','complex',NULL,'The same symbol denotes its VEV in mass formulas. Goldstone and radial coordinates are components of this field, not added multiplets.');
INSERT INTO "theory_fields" VALUES(396,'grv-quark-flavor-u3',1,116,'Yd','bifundamental flavon scalar','0',NULL,'1 complex 3 × 3 matrix','complex',NULL,'Independent of Yu. Together the two fields have 36 real components before gauge removal.');
INSERT INTO "theory_fields" VALUES(397,'grv-quark-flavor-u3',1,116,'H','Higgs scalar doublet','0',NULL,'1',NULL,'Standard Model Higgs','H̃ in the up interaction is the conjugate doublet constructed from H, not an independent field.');
INSERT INTO "theory_fields" VALUES(398,'sm-singlet-neutrino-framework',1,119,'N_I','chiral neutrino fermion collection','1/2','right-handed','N; I=1,...,N',NULL,NULL,'Independent chiral fields with Majorana mass bilinears. N_I^c is a constructed charge conjugate, not an added independent field; no Majorana reality condition is imposed on the chiral collection.');
INSERT INTO "theory_fields" VALUES(399,'sm-singlet-neutrino-framework',1,119,'L_alpha','lepton doublet fermion collection',NULL,NULL,'3; alpha=e,mu,tau',NULL,'Standard Model','Inherited participants in the neutrino Yukawa operator; not a separately reconstructed complete SM inventory.');
INSERT INTO "theory_fields" VALUES(400,'sm-singlet-neutrino-framework',1,119,'Phi','Higgs scalar doublet',NULL,NULL,'1',NULL,'Standard Model','Retain Eq. (1)''s Phi notation. No extra conjugate Higgs doublet or unstated hypercharge convention is introduced.');
INSERT INTO "theory_fields" VALUES(401,'numsm',1,120,'N_I','chiral neutrino fermion collection','1/2','right-handed','3; I=1,2,3',NULL,'Three-member replacement of the parent N_I collection','Replaces field 398 under the explicit specialization. Inherit kinetic, Yukawa and Majorana operators with this collection and inherited L_alpha and Phi. No additional independent conjugate or mass-eigenstate fields are counted.');
INSERT INTO "theory_fields" VALUES(402,'ma-radiative-seesaw-z2',1,123,'N_i','neutral singlet fermion collection','1/2',NULL,'3; i=1,2,3',NULL,NULL,'Independent singlet fermions with the displayed Majorana bilinear. No additional independent conjugate fields are counted, and no real-component condition is imposed on the two-component notation.');
INSERT INTO "theory_fields" VALUES(403,'ma-radiative-seesaw-z2',1,123,'η=(η+,η0)','scalar doublet','0',NULL,'1','complex',NULL,'Additional doublet. sqrt(2)Reη0 and sqrt(2)Imη0 are real component coordinates, not additional independent doublets.');
INSERT INTO "theory_fields" VALUES(404,'ma-radiative-seesaw-z2',1,123,'Φ=(φ+,φ0)','scalar Higgs doublet','0',NULL,'1','complex','Standard Model',NULL);
INSERT INTO "theory_fields" VALUES(405,'ma-radiative-seesaw-z2',1,123,'L_i=(ν_i,l_i)','lepton doublet collection','1/2','left-handed','SM families indexed by i',NULL,'Standard Model',NULL);
INSERT INTO "theory_fields" VALUES(406,'ma-radiative-seesaw-z2',1,123,'l_i^c','conjugate charged-lepton singlet collection','1/2',NULL,'SM families indexed by i',NULL,'Standard Model','Retain the source''s conjugate-field notation and positive hypercharge; not an additional lepton family.');
INSERT INTO "theory_fields" VALUES(407,'weinberg-t1i-first-row',1,126,'ϕ','scalar mediator','0',NULL,NULL,NULL,NULL,'Table 2 first-row label; reality and generation multiplicity unselected.');
INSERT INTO "theory_fields" VALUES(408,'weinberg-t1i-first-row',1,126,'φ′','scalar mediator','0',NULL,NULL,NULL,NULL,'Separate table label; no special-alpha identification with another field is imposed.');
INSERT INTO "theory_fields" VALUES(409,'weinberg-t1i-first-row',1,126,'ψ','fermion mediator','1/2',NULL,NULL,NULL,NULL,'No Majorana condition or generation count is inferred from this generic representation row.');
INSERT INTO "theory_fields" VALUES(410,'weinberg-t1i-first-row',1,126,'φ','scalar mediator','0',NULL,NULL,NULL,NULL,'Higgs-like quantum numbers at a selected alpha would not establish a VEV.');
INSERT INTO "theory_fields" VALUES(411,'weinberg-t41ii-first-row',1,127,'Δ','scalar triplet mediator','0',NULL,NULL,NULL,NULL,NULL);
