INSERT INTO "theory_fields" VALUES(415,'weinberg-t41i-doublet-fermions',1,128,'Δ','scalar triplet mediator','0',NULL,NULL,NULL,NULL,'Delta0 in Eq. (3) is a component; it is not an additional multiplet.');
INSERT INTO "theory_fields" VALUES(416,'weinberg-t41i-doublet-fermions',1,128,'ψ′','fermion doublet mediator','1/2',NULL,NULL,NULL,NULL,'Four-component notation and displayed mass term retained; exact flavor multiplicity unselected.');
INSERT INTO "theory_fields" VALUES(417,'weinberg-t41i-doublet-fermions',1,128,'ψ','fermion doublet mediator','1/2',NULL,NULL,NULL,NULL,'Independent table label, distinct from ψ′.');
INSERT INTO "theory_fields" VALUES(418,'weinberg-t41i-doublet-fermions',1,128,'Ψ','fermion singlet mediator','1/2',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "theory_fields" VALUES(419,'weinberg-t41i-doublet-fermions',1,128,'L','lepton doublet collection',NULL,NULL,NULL,NULL,'Standard Model','νL in Eq. (3) is the neutrino component. Flavor structure is not reconstructed.');
INSERT INTO "theory_fields" VALUES(420,'weinberg-t41i-doublet-fermions',1,128,'H','Higgs scalar doublet',NULL,NULL,NULL,NULL,'Standard Model','H0 in Eq. (3) is a component of the inherited doublet.');
INSERT INTO "theory_fields" VALUES(421,'su4-hypercolor-partial-compositeness',1,129,'psi','two-component hyperfermion collection','1/2','left-handed','5',NULL,NULL,'The SU(4) representation is real; no independent real-field condition is imposed on the Weyl fields.');
INSERT INTO "theory_fields" VALUES(422,'su4-hypercolor-partial-compositeness',1,129,'chi','two-component hyperfermion collection','1/2','left-handed','3',NULL,NULL,NULL);
INSERT INTO "theory_fields" VALUES(423,'su4-hypercolor-partial-compositeness',1,129,'chi_tilde','two-component hyperfermion collection','1/2','left-handed','3',NULL,NULL,'Independent antifundamental Weyl fields, not merely the conjugate variables of chi.');
INSERT INTO "theory_fields" VALUES(424,'su4-hypercolor-partial-compositeness',1,130,'H','composite pNGB Higgs doublet','0',NULL,'1','complex',NULL,'Four real SU(5)/SO(5) coordinates; H-dagger is not a second doublet.');
INSERT INTO "theory_fields" VALUES(425,'su4-hypercolor-partial-compositeness',1,130,'Phi0','composite pNGB weak triplet','0',NULL,'1','real triplet, with conjugate charged components',NULL,NULL);
INSERT INTO "theory_fields" VALUES(426,'su4-hypercolor-partial-compositeness',1,130,'Phi+','composite pNGB weak triplet','0',NULL,'1','complex',NULL,'Phi- is its conjugate, not another independent complex multiplet.');
INSERT INTO "theory_fields" VALUES(427,'su4-hypercolor-partial-compositeness',1,130,'eta','SU(5)/SO(5) singlet pNGB','0',NULL,'1','real',NULL,'Identified in the coset inventory, then omitted from the explicit effective analysis.');
INSERT INTO "theory_fields" VALUES(428,'su4-hypercolor-partial-compositeness',1,130,'pi','color-octet pNGB coordinates','0',NULL,'8 real Goldstone coordinates',NULL,NULL,'pi = pi^a lambda^a/2 from SU(3) × SU(3)''/SU(3)c.');
INSERT INTO "theory_fields" VALUES(429,'su4-hypercolor-partial-compositeness',1,130,'eta-prime','broken-U(1)'' Goldstone coordinate','0',NULL,'1',NULL,NULL,'SM neutral and massless in the stated approximation; omitted from subsequent analysis, without a cosmological completion.');
INSERT INTO "theory_fields" VALUES(430,'su4-hypercolor-partial-compositeness',1,130,'Sigma; U','nonlinear pNGB matrix organization',NULL,NULL,NULL,NULL,NULL,'Sigma=exp(iPi/f), U=Sigma Sigma^T=exp(2iPi/f), with Pi=H+H-dagger+Phi0+Phi++Phi+-dagger in the singlet-omitted treatment. These matrices organize fields 424–426 and do not add independent scalar degrees of freedom.');
INSERT INTO "theory_fields" VALUES(431,'su4-hypercolor-partial-compositeness',1,130,'Psi','composite Dirac fermion multiplet','1/2',NULL,'One (5,3)2/3 of HF',NULL,NULL,'Assumed light resonance, not an added microscopic hyperfermion. Components (X,Y), (T,B), R form two weak doublets and one singlet; electric charges are 5/3, three times 2/3, and -1/3.');
INSERT INTO "theory_fields" VALUES(432,'su4-hypercolor-partial-compositeness',1,130,'qLi','elementary quark doublet collection',NULL,'left-handed','3 families',NULL,'Standard Model fermions','qL without a family index denotes qL3. Its 5 and 24 spurion embeddings contain the same physical third-family fields, not additional fermions.');
INSERT INTO "theory_fields" VALUES(433,'su4-hypercolor-partial-compositeness',1,130,'uRi','elementary up-quark collection',NULL,'right-handed','3 families',NULL,'Standard Model fermions','tR=uR3 participates in linear mixing through a 5-bar embedding; the quadratic prescription uses a 10 embedding. Auxiliary spurion components are not physical additions.');
INSERT INTO "theory_fields" VALUES(434,'su4-hypercolor-partial-compositeness',1,130,'dRi','elementary down-quark collection',NULL,'right-handed','3 families',NULL,'Standard Model fermions','bR=dR3 receives the displayed quadratic mass coupling; no bR partial-compositeness partner is supplied.');
INSERT INTO "theory_fields" VALUES(435,'littlest-higgs-minimal',1,131,'Sigma; Pi','nonlinear Goldstone matrix organization',NULL,NULL,NULL,NULL,NULL,'Pi=pi^a X^a; Sigma=exp(i Pi/f) Sigma0 exp(i Pi^T/f)=exp(2i Pi/f) Sigma0. Organizes fourteen Goldstone coordinates, not an extra independent linear scalar multiplet. The illustrative Phi of Section 3 is not added as a propagating field.');
INSERT INTO "theory_fields" VALUES(436,'littlest-higgs-minimal',1,131,'h','pseudo-Goldstone Higgs doublet','0',NULL,'1','complex',NULL,'h=(h+,h0). Its conjugate is not a second doublet. In the eaten-field-suppressed Pi matrix, h occurs in the off-diagonal blocks with the source''s 1/sqrt(2) factors.');
INSERT INTO "theory_fields" VALUES(437,'littlest-higgs-minimal',1,131,'phi','pseudo-Goldstone scalar triplet','0',NULL,'1','complex',NULL,'Symmetric 2 × 2 matrix in Pi; phi-dagger is its conjugate, not another independent triplet.');
INSERT INTO "theory_fields" VALUES(438,'littlest-higgs-minimal',1,131,'Eaten singlet Goldstone','Goldstone coordinate','0',NULL,'1 real coordinate',NULL,NULL,'Removed by the Higgs mechanism for doubled electroweak gauging; omitted from Eq. (3.7). Not a physical additional light scalar.');
INSERT INTO "theory_fields" VALUES(439,'littlest-higgs-minimal',1,131,'Eaten triplet Goldstones','Goldstone coordinate multiplet','0',NULL,'1 triplet','real triplet',NULL,'Three coordinates removed by the Higgs mechanism; omitted from Eq. (3.7).');
INSERT INTO "theory_fields" VALUES(440,'littlest-higgs-minimal',1,131,'W-prime','massive gauge-boson combination','1',NULL,'1 electroweak triplet',NULL,NULL,'Three massive combinations from the broken doubled gauge sector, not an independent Proca extension.');
INSERT INTO "theory_fields" VALUES(441,'littlest-higgs-minimal',1,131,'B-prime','massive gauge-boson combination','1',NULL,'1',NULL,NULL,'Neutral massive combination from the broken Abelian gauge sector.');
INSERT INTO "theory_fields" VALUES(442,'littlest-higgs-minimal',1,131,'q3=(t3,b3)','third-family quark doublet',NULL,NULL,NULL,NULL,'Standard Model ordinary fermions','The first two entries of chi=(b3,t3,t-tilde) reorganize this doublet. Chi is not an additional independent fermion.');
INSERT INTO "theory_fields" VALUES(443,'littlest-higgs-minimal',1,131,'t-tilde','colored Weyl fermion','1/2',NULL,'1',NULL,NULL,'Added third entry of chi. Pairs with a combination of u3-prime-c and t-tilde-c to form the heavy charge-2/3 electroweak-singlet quark.');
INSERT INTO "theory_fields" VALUES(444,'littlest-higgs-minimal',1,131,'t-tilde-c','colored Weyl fermion','1/2',NULL,'1',NULL,NULL,'Independent conjugate partner field in the mass term, not merely the complex-conjugate variable of t-tilde. Individual doubled-U(1) charges are unspecified.');
INSERT INTO "theory_fields" VALUES(445,'littlest-higgs-minimal',1,131,'u3-prime-c','conjugate up-quark weak singlet',NULL,NULL,NULL,NULL,'Standard Model ordinary fermion context','Gauge-basis participant. The surviving light u3-c is a mixture with t-tilde-c, not an additional independent ultraviolet field.');
INSERT INTO "theory_fields" VALUES(446,'littlest-higgs-minimal',1,131,'Remaining up-sector fermion participants','indexed inherited fermion collection',NULL,NULL,NULL,NULL,'Standard Model light up-sector Yukawa participants','Collective record for L_psi assignment; no extra t-tilde partners are added for these small Yukawas. Detailed flavor matrices and doubled-group charges are unselected.');
INSERT INTO "theory_fields" VALUES(447,'littlest-higgs-minimal',1,131,'Down-sector fermion participants','indexed inherited fermion collection',NULL,NULL,NULL,NULL,'Standard Model down-sector Yukawa participants','Collective L_psi participant record; overlaps with the ordinary quark-doublet inventory and does not add independent copies of those doublets.');
INSERT INTO "theory_fields" VALUES(448,'littlest-higgs-minimal',1,131,'Charged-lepton Yukawa participants','indexed inherited fermion collection',NULL,NULL,NULL,NULL,'Standard Model charged-lepton sector','Collective assignment record; no additional neutrino-mass sector is specified.');
INSERT INTO "theory_fields" VALUES(449,'littlest-higgs-minimal',1,132,'h','surviving light Higgs doublet',NULL,NULL,NULL,NULL,NULL,'Low-energy continuation of field 436 after heavy-state elimination, not another independent doublet.');
INSERT INTO "theory_fields" VALUES(450,'twin-higgs-linear-scalar-sector',1,133,'H=(H_A,H_B)','linear scalar multiplet','0',NULL,'One complex four-component multiplet','complex',NULL,'H_A and H_B are the two doublet blocks of the same H. The radial mode is retained; the seven angular modes are not additional independent fields.');
INSERT INTO "theory_fields" VALUES(451,'twin-higgs-unextended',1,134,'H=(H_A,H_B)','nonlinear scalar coordinate organization',NULL,NULL,NULL,NULL,NULL,'Radial mode removed. H organizes h1,h2,h3 complex and h0 real about (0,0,0,f)^T. The constraint fixes H-dagger H=f²; H is not an additional unconstrained complex multiplet.');
INSERT INTO "theory_fields" VALUES(452,'twin-higgs-unextended',1,134,'h=(h1,h2)','uneaten pseudo-Goldstone Higgs doublet','0',NULL,'One SU(2)_A doublet','complex',NULL,'Subset of the coordinates organized by field 451, identified with the visible Higgs. This record does not add independent scalar degrees of freedom.');
INSERT INTO "theory_fields" VALUES(453,'twin-higgs-unextended',1,134,'Ordinary SM_A and corresponding SM_B particles','indexed inherited particle collection',NULL,NULL,NULL,NULL,'Two ordinary Standard Model inventories','Collective record for the explicitly stated interchange of every particle. Higgs coordinates are recorded separately and overlap with this bookkeeping collection. It is not an exhaustive representation table; ordinary B partners carry no A-sector gauge charges.');
INSERT INTO "theory_fields" VALUES(454,'twin-higgs-extended-top',1,135,'H','inherited nonlinear scalar organization',NULL,NULL,NULL,NULL,'Nonlinear twin Higgs','Local participant in yHQ_LT_R. Same nonlinear Higgs degrees of freedom as the baseline, not an added radial scalar.');
INSERT INTO "theory_fields" VALUES(455,'twin-higgs-extended-top',1,135,'Q_L=(q_A,q_B,qtilde_A,qtilde_B)','chiral fermion collection','1/2',NULL,NULL,NULL,NULL,'Eq. (4) organization into (6,4-bar) of global SU(6) × SU(4). q_A,q_B are ordinary top-sector doublets; qtilde_A,qtilde_B are added cross-sector quarks. This organization does not add copies of its components.');
INSERT INTO "theory_fields" VALUES(456,'twin-higgs-extended-top',1,135,'T_R=(t_A,t_B)','source-labeled chiral fermion collection','1/2',NULL,NULL,NULL,NULL,'Retain the source''s T_R label and antifundamental gauge representations without silently converting its chiral notation. No numerical hypercharge assignment is supplied.');
INSERT INTO "theory_fields" VALUES(457,'twin-higgs-extended-top',1,135,'qtilde_A,qtilde_B','exotic component collection within Q_L','1/2','left-handed',NULL,NULL,NULL,'The (3,1;1,2) and (1,2;3,1) components of field 455, recorded separately as mass participants. They are not further independent copies.');
INSERT INTO "theory_fields" VALUES(458,'twin-higgs-extended-top',1,135,'qtilde_A^c,qtilde_B^c','additional conjugate-charge fermion collection','1/2',NULL,NULL,NULL,NULL,'Independent additional fermions with charges opposite to the respective exotic components, permitting the displayed mass M. They are not merely conjugate variables of field 457; numerical hypercharges remain unspecified.');
INSERT INTO "theory_fields" VALUES(459,'mirror-higgs-unextended',1,136,'Ordinary SM_A particles and their mirror counterparts in SM_B','indexed particle collection',NULL,NULL,NULL,NULL,'Doubled ordinary Standard Model inventory','Replaces the baseline''s direct-interchange correspondence. The transformation pairs each A particle with its CP conjugate in B and includes spatial inversion; no cross-sector top exotics are added.');
INSERT INTO "theory_fields" VALUES(460,'fraternal-twin-higgs',1,137,'A','scalar Higgs doublet','0',NULL,'1','complex','Standard Model Higgs doublet',NULL);
INSERT INTO "theory_fields" VALUES(461,'fraternal-twin-higgs',1,137,'B','twin scalar Higgs doublet','0',NULL,'1','complex',NULL,NULL);
INSERT INTO "theory_fields" VALUES(462,'fraternal-twin-higgs',1,137,'Qhat_a','twin quark doublet','1/2',NULL,'One twin generation; a=1,2,3 is the twin-color index',NULL,NULL,'Contains the twin top and bottom left components. Source Yukawa notation is schematic; no conjugation convention is reconstructed.');
INSERT INTO "theory_fields" VALUES(463,'fraternal-twin-higgs',1,137,'uhat_a','twin top singlet','1/2','source-labeled right-handed','One twin generation with three color components',NULL,NULL,'The flattened Yukawa does not determine whether its printed spinor symbol denotes a conjugated two-component field.');
INSERT INTO "theory_fields" VALUES(464,'fraternal-twin-higgs',1,137,'bhat','twin bottom singlet','1/2','source-labeled right-handed','One twin generation with twin-color components',NULL,NULL,'Included to cancel the twin-color anomaly. This is the singlet partner of the bottom component in Qhat, not an additional bottom flavor.');
INSERT INTO "theory_fields" VALUES(465,'fraternal-twin-higgs',1,137,'Lhat','twin lepton doublet','1/2','left-handed','1',NULL,NULL,'Twin-color neutral; includes the twin tau neutrino. Required by the source''s twin SU(2) anomaly-cancellation argument.');
INSERT INTO "theory_fields" VALUES(466,'fraternal-twin-higgs',1,137,'tauhat_R','twin tau singlet','1/2','right-handed','1',NULL,NULL,'Included to permit a twin tau mass; not required by the source''s anomaly argument.');
INSERT INTO "theory_fields" VALUES(467,'fraternal-twin-higgs',1,137,'H=(A,B)','scalar multiplet organization',NULL,NULL,NULL,NULL,NULL,'Complex SU(4) fundamental organizing fields 460 and 461. This is not an additional independent scalar multiplet.');
INSERT INTO "theory_fields" VALUES(468,'fraternal-twin-higgs',1,139,'G0+','composite twin glueball','0',NULL,NULL,NULL,NULL,'Lightest pure-glue state with JPC=0++; a bound state of microscopic twin color, not an added elementary scalar.');
INSERT INTO "theory_fields" VALUES(469,'fraternal-twin-higgs',1,140,'chihat','scalar twin-bottomonium bound-state tower','0',NULL,NULL,NULL,NULL,'The 0++ members of the twin bottom–antibottom spectrum. No elementary scalar is added.');
INSERT INTO "theory_fields" VALUES(470,'fraternal-twin-higgs',1,140,'Upsilonhat','vector twin-bottomonium bound-state tower','1',NULL,NULL,NULL,NULL,'JPC=1−−; bound states of the existing twin bottom.');
INSERT INTO "theory_fields" VALUES(471,'large-extra-dimensions-framework',1,141,'Standard Model fields','inherited particle collection',NULL,NULL,NULL,NULL,'Standard Model','Localized on a four-dimensional submanifold of thickness of order m_EW^−1 at sub-cutoff energies. This collective record does not independently enumerate baseline fields.');
INSERT INTO "theory_fields" VALUES(472,'large-extra-dimensions-framework',1,141,'Bulk graviton','higher-dimensional gravitational field',NULL,NULL,NULL,NULL,NULL,'Propagates in all 4+n dimensions; the KK description reorganizes this same field.');
INSERT INTO "theory_fields" VALUES(473,'six-dimensional-pati-salam-vortex',1,143,'Φ','vortex scalar','0',NULL,'1','complex',NULL,'Pati–Salam singlet charged under U(1)V. Its phase winds; the absolute U(1)V charge is unspecified.');
INSERT INTO "theory_fields" VALUES(474,'six-dimensional-pati-salam-vortex',1,143,'χ','six-dimensional scalar','0',NULL,'1',NULL,NULL,'Core-breaking scalar. No field reality condition is inferred from its adjoint representation.');
INSERT INTO "theory_fields" VALUES(475,'six-dimensional-pati-salam-vortex',1,143,'χ′','six-dimensional scalar','0',NULL,'1',NULL,NULL,'Independent core-breaking scalar; full interactions with Φ are not enumerated.');
INSERT INTO "theory_fields" VALUES(476,'six-dimensional-pati-salam-vortex',1,143,'H','six-dimensional Higgs scalar','0',NULL,'1 bidoublet',NULL,NULL,'Core-condensing Higgs in the explicit Pati–Salam construction. Its localized modes are not additional independent bulk fields; no bidoublet reality restriction is inferred.');
INSERT INTO "theory_fields" VALUES(477,'six-dimensional-pati-salam-vortex',1,143,'Q','six-dimensional chiral spinor','1/2','six-dimensional chiral; explicit sign not reconstructed','One per generation',NULL,NULL,'Independent member of a vortex-mass pair; four-dimensional zero-mode chirality is a separate property.');
INSERT INTO "theory_fields" VALUES(478,'six-dimensional-pati-salam-vortex',1,143,'Qbar','six-dimensional chiral spinor','1/2','six-dimensional chiral; explicit sign not reconstructed','One per generation',NULL,NULL,'Independent conjugate-gauge-representation partner of Q, not simply its conjugate variable.');
INSERT INTO "theory_fields" VALUES(479,'six-dimensional-pati-salam-vortex',1,143,'Q_c','six-dimensional chiral spinor','1/2','six-dimensional chiral; explicit sign not reconstructed','One per generation',NULL,NULL,'Independent second vortex-mass pair member.');
INSERT INTO "theory_fields" VALUES(480,'six-dimensional-pati-salam-vortex',1,143,'Qbar_c','six-dimensional chiral spinor','1/2','six-dimensional chiral; explicit sign not reconstructed','One per generation',NULL,NULL,'Independent partner of Q_c. Bars and c subscripts retain the source''s field labels.');
INSERT INTO "theory_fields" VALUES(481,'six-dimensional-pati-salam-vortex',1,143,'Six-dimensional graviton','bulk gravitational field',NULL,NULL,NULL,NULL,NULL,'Only light bulk particle in the source''s assumed gapped realization.');
