INSERT INTO "theory_interactions" VALUES(13,'thdm-type-i-real-z2',1,4,'Z2-even scalar potential','scalar_potential','V_even = m11² Φ1†Φ1 + m22² Φ2†Φ2 + (λ1/2)(Φ1†Φ1)² + (λ2/2)(Φ2†Φ2)² + λ3(Φ1†Φ1)(Φ2†Φ2) + λ4(Φ1†Φ2)(Φ2†Φ1) + (λ5/2)[(Φ1†Φ2)² + (Φ2†Φ1)²]','Eq. (2), excluding the separately recorded soft term',1,1,0,'All coefficients real in this basis; λ5 is not required to vanish.',NULL);
INSERT INTO "theory_interactions" VALUES(14,'thdm-type-i-real-z2',1,4,'Permitted quadratic soft Z2 breaking','soft_scalar_mixing','V_soft = −m12²(Φ1†Φ2 + Φ2†Φ1)','Eq. (2)',0,1,0,'m12² real and free, including zero.','Not invariant under the defining Z2; explicitly permitted as soft breaking. Inclusion does not require a nonzero coefficient.');
INSERT INTO "theory_interactions" VALUES(15,'thdm-type-i-real-z2',1,4,'Excluded Z2-odd quartics','excluded_scalar_operators','λ6(Φ1†Φ1)(Φ1†Φ2) + λ7(Φ2†Φ2)(Φ1†Φ2) + H.c.','Eq. (98) notation for terms excluded from Eq. (2)',0,0,0,'λ6 = λ7 = 0','Excluded by the imposed dimension-four Z2 restriction in its manifest basis, not independently tuned symmetry-allowed terms.');
INSERT INTO "theory_interactions" VALUES(16,'thdm-type-ii-real-z2',1,5,'Up-quark Yukawa assignment to Φ2','Yukawa_assignment',NULL,'Table 1: u_R^i → Φ2',1,1,0,'Only Φ2 supplies this sector''s Yukawa couplings in the stated symmetry basis.','Assignment record, not a complete operator formula; inherited left-handed partners are not independently enumerated.');
INSERT INTO "theory_interactions" VALUES(17,'thdm-type-ii-real-z2',1,5,'Down-quark Yukawa assignment to Φ1','Yukawa_assignment',NULL,'Table 1: d_R^i → Φ1',1,1,0,'Only Φ1 supplies this sector''s Yukawa couplings in the stated symmetry basis.',NULL);
INSERT INTO "theory_interactions" VALUES(18,'thdm-type-ii-real-z2',1,5,'Charged-lepton Yukawa assignment to Φ1','Yukawa_assignment',NULL,'Table 1: e_R^i → Φ1',1,1,0,'Only Φ1 supplies charged-lepton Yukawa couplings in the conventional lepton extension.',NULL);
INSERT INTO "theory_interactions" VALUES(19,'thdm-type-ii-real-z2',1,5,'Z2-even scalar potential','scalar_potential','V_even = m11² Φ1†Φ1 + m22² Φ2†Φ2 + (λ1/2)(Φ1†Φ1)² + (λ2/2)(Φ2†Φ2)² + λ3(Φ1†Φ1)(Φ2†Φ2) + λ4(Φ1†Φ2)(Φ2†Φ1) + (λ5/2)[(Φ1†Φ2)² + (Φ2†Φ1)²]','Eq. (2), excluding the separately recorded soft term',1,1,0,'All coefficients real in this basis; λ5 is not required to vanish.',NULL);
INSERT INTO "theory_interactions" VALUES(20,'thdm-type-ii-real-z2',1,5,'Permitted quadratic soft Z2 breaking','soft_scalar_mixing','V_soft = −m12²(Φ1†Φ2 + Φ2†Φ1)','Eq. (2)',0,1,0,'m12² real and free, including zero.','Not invariant under the defining Z2; explicitly permitted as soft breaking. Inclusion does not require a nonzero coefficient.');
INSERT INTO "theory_interactions" VALUES(21,'thdm-type-ii-real-z2',1,5,'Excluded Z2-odd quartics','excluded_scalar_operators','λ6(Φ1†Φ1)(Φ1†Φ2) + λ7(Φ2†Φ2)(Φ1†Φ2) + H.c.','Eq. (98) notation for terms excluded from Eq. (2)',0,0,0,'λ6 = λ7 = 0','Excluded by the imposed dimension-four Z2 restriction in its manifest basis, not independently tuned symmetry-allowed terms.');
INSERT INTO "theory_interactions" VALUES(22,'lr-triplet-parity',1,6,'Quark Yukawa coupling to Φ','Yukawa','L ⊃ Q̄L Y Φ QR + h.c.','Eq. (8), first term',1,1,0,'Y = Y†',NULL);
INSERT INTO "theory_interactions" VALUES(23,'lr-triplet-parity',1,6,'Quark Yukawa coupling to Φ̃','Yukawa','L ⊃ Q̄L Ỹ (σ2 Φ* σ2) QR + h.c.','Eq. (8), second term; Φ̃ = σ2 Φ* σ2',1,1,0,'Ỹ = Ỹ†',NULL);
INSERT INTO "theory_interactions" VALUES(24,'lr-triplet-charge-conjugation',1,7,'Quark Yukawa coupling to Φ','Yukawa','L ⊃ Q̄L Y Φ QR + h.c.','Eq. (8), first term',1,1,0,'Y = YT',NULL);
INSERT INTO "theory_interactions" VALUES(25,'lr-triplet-charge-conjugation',1,7,'Quark Yukawa coupling to Φ̃','Yukawa','L ⊃ Q̄L Ỹ (σ2 Φ* σ2) QR + h.c.','Eq. (8), second term; Φ̃ = σ2 Φ* σ2',1,1,0,'Ỹ = ỸT',NULL);
INSERT INTO "theory_interactions" VALUES(26,'nmssm-general-rpc-cpc',1,8,'Cubic Higgs superpotential','superpotential','W ⊃ λŜ Ĥu·Ĥd + (κ/3)Ŝ³','Eq. (2.1)',NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(27,'nmssm-general-rpc-cpc',1,8,'Dimensionful Higgs superpotential terms','superpotential','W ⊃ μ Ĥu·Ĥd + ξF Ŝ + (μ′/2)Ŝ²',NULL,NULL,1,0,NULL,'Eq. (2.1) before shifting the singlet origin. Inclusion permits zero parameter values without requiring them. A later μ = 0 convention does not remove the general structural freedom.');
INSERT INTO "theory_interactions" VALUES(28,'nmssm-general-rpc-cpc',1,8,'Up-type matter Yukawa','superpotential_Yukawa','W ⊃ hu Q̂·Ĥu ÛRᶜ',NULL,NULL,1,NULL,'hu is a matrix in family space; Eq. (2.2).',NULL);
INSERT INTO "theory_interactions" VALUES(29,'nmssm-general-rpc-cpc',1,8,'Down-type matter Yukawa','superpotential_Yukawa','W ⊃ hd Ĥd·Q̂ D̂Rᶜ',NULL,NULL,1,NULL,'hd is a matrix in family space; Eq. (2.2).',NULL);
INSERT INTO "theory_interactions" VALUES(30,'nmssm-general-rpc-cpc',1,8,'Charged-lepton matter Yukawa','superpotential_Yukawa','W ⊃ he Ĥd·L̂ ÊRᶜ',NULL,NULL,1,NULL,'he is a matrix in family space; Eq. (2.2).',NULL);
INSERT INTO "theory_interactions" VALUES(31,'nmssm-general-rpc-cpc',1,8,'Scalar soft masses','soft_scalar_mass','−Lsoft ⊃ mHu²|Hu|² + mHd²|Hd|² + mS²|S|² + mQ²|Q|² + mU²|UR|² + mD²|DR|² + mL²|L|² + mE²|ER|²',NULL,NULL,1,NULL,NULL,'Unhatted symbols are component scalars, not superfields; Eq. (2.5).');
INSERT INTO "theory_interactions" VALUES(32,'nmssm-general-rpc-cpc',1,8,'Scalar soft trilinears','soft_scalar_trilinear','−Lsoft ⊃ (hu Au Q·Hu URᶜ − hd Ad Q·Hd DRᶜ − he Ae L·Hd ERᶜ + λAλ Hu·Hd S + (κAκ/3)S³ + h.c.)',NULL,NULL,1,NULL,NULL,'Component operators; contraction order and signs follow Eq. (2.5).');
INSERT INTO "theory_interactions" VALUES(33,'nmssm-general-rpc-cpc',1,8,'Holomorphic scalar soft bilinears','soft_scalar_bilinear','−Lsoft ⊃ (m3² Hu·Hd + (mS′²/2)S² + h.c.)',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(34,'nmssm-general-rpc-cpc',1,8,'Scalar soft tadpole','soft_scalar_tadpole','−Lsoft ⊃ ξS S + h.c.',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(35,'nmssm-general-rpc-cpc',1,8,'MSSM-like gaugino soft masses','soft_gaugino_mass','L = (M1/2)λ1λ1 + (M2/2)λ2ⁱλ2ⁱ + (M3/2)λ3ᵃλ3ᵃ',NULL,NULL,1,NULL,NULL,'Eq. (2.30) displayed sign retained. λ1, λ2ⁱ and λ3ᵃ are component gauginos for U(1)Y, SU(2) and SU(3); i = 1,2,3 and a = 1,…,8. Supplied separately from Eq. (2.5).');
INSERT INTO "theory_interactions" VALUES(36,'nmssm-z3-rpc-cpc',1,9,'Cubic Higgs superpotential','superpotential','W ⊃ λŜ Ĥu·Ĥd + (κ/3)Ŝ³',NULL,1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(37,'nmssm-z3-rpc-cpc',1,9,'Removed dimensionful superpotential terms','excluded_superpotential_operators','μ Ĥu·Ĥd + ξF Ŝ + (μ′/2)Ŝ²',NULL,0,0,1,'μ = μ′ = ξF = 0','Source defines this restriction first and identifies accidental Z3 afterward; these operators violate that common-phase symmetry.');
INSERT INTO "theory_interactions" VALUES(38,'nmssm-z3-rpc-cpc',1,9,'Up-type matter Yukawa','superpotential_Yukawa','W ⊃ hu Q̂·Ĥu ÛRᶜ',NULL,1,1,NULL,'Family-space matrix hu retained from Eq. (2.2).',NULL);
INSERT INTO "theory_interactions" VALUES(39,'nmssm-z3-rpc-cpc',1,9,'Down-type matter Yukawa','superpotential_Yukawa','W ⊃ hd Ĥd·Q̂ D̂Rᶜ',NULL,1,1,NULL,'Family-space matrix hd retained from Eq. (2.2).',NULL);
INSERT INTO "theory_interactions" VALUES(40,'nmssm-z3-rpc-cpc',1,9,'Charged-lepton matter Yukawa','superpotential_Yukawa','W ⊃ he Ĥd·L̂ ÊRᶜ',NULL,1,1,NULL,'Family-space matrix he retained from Eq. (2.2).',NULL);
INSERT INTO "theory_interactions" VALUES(41,'nmssm-z3-rpc-cpc',1,9,'Surviving scalar soft masses','soft_scalar_mass','−Lsoft ⊃ mHu²|Hu|² + mHd²|Hd|² + mS²|S|² + mQ²|Q|² + mU²|UR|² + mD²|DR|² + mL²|L|² + mE²|ER|²',NULL,NULL,1,0,NULL,'Component scalars; the cubic-superpotential restriction does not remove these dimensionful soft terms.');
INSERT INTO "theory_interactions" VALUES(42,'nmssm-z3-rpc-cpc',1,9,'Surviving scalar soft trilinears','soft_scalar_trilinear','−Lsoft ⊃ (hu Au Q·Hu URᶜ − hd Ad Q·Hd DRᶜ − he Ae L·Hd ERᶜ + λAλ Hu·Hd S + (κAκ/3)S³ + h.c.)',NULL,NULL,1,0,NULL,'Component operators retained from Eq. (2.5).');
INSERT INTO "theory_interactions" VALUES(43,'nmssm-z3-rpc-cpc',1,9,'Removed holomorphic scalar soft bilinears','excluded_soft_scalar_operators','m3² Hu·Hd + (mS′²/2)S² + h.c.',NULL,0,0,1,'m3² = mS′² = 0; mS²|S|² remains.',NULL);
INSERT INTO "theory_interactions" VALUES(44,'nmssm-z3-rpc-cpc',1,9,'Removed scalar soft tadpole','excluded_soft_scalar_operators','ξS S + h.c.',NULL,0,0,1,'ξS = 0',NULL);
INSERT INTO "theory_interactions" VALUES(45,'nmssm-z3-rpc-cpc',1,9,'Surviving MSSM-like gaugino soft masses','soft_gaugino_mass','L = (M1/2)λ1λ1 + (M2/2)λ2ⁱλ2ⁱ + (M3/2)λ3ᵃλ3ᵃ',NULL,NULL,1,0,NULL,'Eq. (2.30) displayed sign retained. Component gauginos belong to U(1)Y, SU(2), SU(3); the six-zero restriction does not remove their masses.');
INSERT INTO "theory_interactions" VALUES(46,'mchm-spinorial',1,10,'Elementary–composite fermion mixing','linear_operator_coupling','Σr λr ψ̄r Or + h.c.',NULL,NULL,1,NULL,NULL,'r runs over qL,uR,dR,lL,eR with a family index. These interactions explicitly break SO(5); completed nondynamical source multiplets are bookkeeping devices.');
INSERT INTO "theory_interactions" VALUES(47,'mchm-spinorial',1,11,'A5 coupling within ξq','gauge_origin_Yukawa',NULL,NULL,1,1,NULL,NULL,'A5 in the bulk covariant derivative connects SU(2)L and SU(2)R doublets of opposite 4D chirality within ξq. Physical zero-mode Yukawas depend on multiplet mixing; no separately normalized vertex is inferred.');
INSERT INTO "theory_interactions" VALUES(48,'mchm-spinorial',1,11,'A5 coupling within ξu','gauge_origin_Yukawa',NULL,NULL,1,1,NULL,NULL,'Connects SU(2)L and SU(2)R doublets of opposite 4D chirality within ξu through the bulk covariant derivative.');
INSERT INTO "theory_interactions" VALUES(49,'mchm-spinorial',1,11,'A5 coupling within ξd','gauge_origin_Yukawa',NULL,NULL,1,1,NULL,NULL,'Connects SU(2)L and SU(2)R doublets of opposite 4D chirality within ξd through the bulk covariant derivative.');
INSERT INTO "theory_interactions" VALUES(50,'mchm-spinorial',1,11,'SO(4)-invariant IR mass mixing','boundary_mass_mixing','[M̃u Q̄L^u+M̃d Q̄L^d]QR + q̄L[m̃u qR^u+m̃d qR^d] + h.c.',NULL,1,1,NULL,NULL,'Located on the IR boundary. Bulk kinetic and mass matrices are first diagonalized by field redefinitions. Eq. (28) boundary assignments precede this mixing.');
INSERT INTO "theory_interactions" VALUES(51,'mchm-spinorial',1,11,'Removal of unwanted zero modes','boundary_fermion_pairing','[Q̄L^u+Q̄L^d]Q̃R',NULL,NULL,1,NULL,NULL,'IR-brane pairing written by the source to remove dcL′ and ucL″; no coefficient normalization is supplied.');
INSERT INTO "theory_interactions" VALUES(52,'mchm-spinorial',1,11,'SO(4) IR gauge kinetic term','boundary_gauge_kinetic',NULL,NULL,NULL,1,NULL,'Coefficient 1/gIR²','Included in the form factors. UV boundary kinetic terms can also be added; omission from the displayed matching formula does not forbid them.');
INSERT INTO "theory_interactions" VALUES(53,'mchm-spinorial',1,10,'Approximate radiative Higgs potential','effective_scalar_potential','V(h)≃α cos(h/fπ)−β sin²(h/fπ)',NULL,NULL,1,NULL,NULL,'One-loop approximation. Gauge loops align the vacuum; top loops can misalign it. A subleading top logarithm is omitted here; the 5D numerical calculation uses the full Eq. (19).');
INSERT INTO "theory_interactions" VALUES(54,'mchm-spinorial-scalar14',1,13,'Scalar sources and their masses','source_operator_coupling','ΔL=kϕi Oϕi−m_i²ϕ_i²/2',NULL,NULL,1,NULL,'Independent m9²,m4²,m1² for the SO(4) components in the chosen example.','Dimension-two Oϕi; k∼MPl and mi∼k. Source-dependent masses explicitly break SO(5); SO(4)-invariant masses are a simplifying choice.');
INSERT INTO "theory_interactions" VALUES(55,'mchm-spinorial-scalar14',1,13,'Induced marginal deformation','effective_double_trace','ΔL=λi Oϕi²',NULL,NULL,1,NULL,'λi(k)=k²/(2m_i²); logarithmic running.','Obtained by integrating out ϕi; this is an alternative effective expression for the source mechanism, not an independent additional coupling.');
INSERT INTO "theory_interactions" VALUES(56,'mchm-spinorial-scalar14',1,14,'IR tadpole for the SO(4) singlet in Φ','boundary_scalar_tadpole',NULL,NULL,NULL,1,NULL,NULL,'Located at the IR boundary. Generates the stated tree-level Higgs-potential deformation. Coefficient and complete scalar boundary conditions are unspecified.');
INSERT INTO "theory_interactions" VALUES(57,'georgi-machacek-general',1,15,'Scalar gauge kinetics','gauge_kinetic','L ⊃ (Dμφ)†Dμφ + (1/2)(Dμξ)†Dμξ + (Dμχ)†Dμχ = (1/2)Tr[(DμΦ)†DμΦ] + (1/2)Tr[(DμX)†DμX]','Eqs. (A4), (A6), (A7)',NULL,1,0,NULL,'DμΦ=∂μΦ−igWμaτaΦ+ig′BμΦτ3; DμX=∂μX−igWμataX+ig′BμXt3. The two displayed forms are equivalent descriptions, not additive kinetic sectors.');
INSERT INTO "theory_interactions" VALUES(58,'georgi-machacek-general',1,15,'Quadratic scalar potential','scalar_mass','V2=(μ2²/2)Tr(Φ†Φ)+(μ3²/2)Tr(X†X)','Eq. (5)',1,1,0,'Real coefficients; superscript notation does not impose positivity throughout the general parameter space.',NULL);
INSERT INTO "theory_interactions" VALUES(59,'georgi-machacek-general',1,15,'Quartic scalar potential','scalar_quartic','V4=λ1[Tr(Φ†Φ)]²+λ2Tr(Φ†Φ)Tr(X†X)+λ3Tr(X†XX†X)+λ4[Tr(X†X)]²−λ5Tr(Φ†τaΦτb)Tr(X†taXtb)','Eq. (5); repeated a,b contracted',1,1,0,'Five real quartic coefficients; no additional zero restriction imposed.',NULL);
INSERT INTO "theory_interactions" VALUES(60,'georgi-machacek-general',1,15,'Doublet–triplet cubic','scalar_cubic','V ⊃ −M1Tr(Φ†τaΦτb)(UXU†)ab','Eq. (5)',1,1,0,'M1 real and free, including zero.','Allowed by the defining gauge and custodial symmetries. X→−X is not imposed; this operator would violate that extra restriction.');
INSERT INTO "theory_interactions" VALUES(61,'georgi-machacek-general',1,15,'Triplet cubic','scalar_cubic','V ⊃ −M2Tr(X†taXtb)(UXU†)ab','Eq. (5)',1,1,0,'M2 real and free, including zero.','Allowed by the defining gauge and custodial symmetries. X→−X is not imposed.');
INSERT INTO "theory_interactions" VALUES(62,'georgi-machacek-general',1,15,'SM fermion mass assignment to φ','Yukawa_assignment',NULL,NULL,NULL,1,NULL,NULL,'The usual doublet supplies fermion masses as in the SM. This assignment record does not reconstruct unsupplied chiral operator formulas or additional triplet Yukawa exclusions.');
INSERT INTO "theory_interactions" VALUES(63,'threedm-d6',1,17,'Exchange-constrained phase-invariant potential','scalar_potential','V0=−Σ_i m_i²(φ_i†φ_i)+Σ_{i≤j}λ_ij(φ_i†φ_i)(φ_j†φ_j)+Σ_{i<j}λ''_ij(φ_i†φ_j)(φ_j†φ_i), with i,j=1,2,3.','Section 6.2.1, V0 and equation (25)',1,1,0,'Real V0 coefficients; m_1²=m_2², λ11=λ22, λ13=λ23, λ''13=λ''23. Equation (25) denotes the same quadratic coefficients by m_11² and m_22². Remaining coefficients are free; no positivity or vacuum restriction is inferred.',NULL);
INSERT INTO "theory_interactions" VALUES(64,'threedm-d6',1,17,'Z3-based phase-sensitive quartics','scalar_quartic','V_Z3=λ1(φ2†φ1)(φ3†φ1)+λ2(φ1†φ2)(φ3†φ2)+λ3(φ1†φ3)(φ2†φ3)+h.c.','Equation (24); V=V0+V_Z3',1,1,0,'|λ1|=|λ2|, with λ1 and λ2 nonzero for the selected finite D6 construction. λ3 is complex and may vanish; CP restrictions are conditional parameter loci.','Generic remaining coefficients avoid stronger restrictions giving larger finite groups. The λ3=0 locus retains this operator basis with its third coefficient zero; that zero is not imposed throughout the specification.');
INSERT INTO "theory_interactions" VALUES(65,'threedm-d8',1,18,'Exchange-constrained phase-invariant potential','scalar_potential','V0=−Σ_i m_i²(φ_i†φ_i)+Σ_{i≤j}λ_ij(φ_i†φ_i)(φ_j†φ_j)+Σ_{i<j}λ''_ij(φ_i†φ_j)(φ_j†φ_i), with i,j=1,2,3.','V0 of Section 6.2.1 with equation (25), reused in Section 6.3.1',1,1,0,'Real V0 coefficients; m_1²=m_2², λ11=λ22, λ13=λ23, λ''13=λ''23. The source also writes the quadratic equality as m_11²=m_22². Remaining coefficients are free.',NULL);
INSERT INTO "theory_interactions" VALUES(66,'threedm-d8',1,18,'Z4-based phase-sensitive quartics','scalar_quartic','V_Z4=λ1(φ3†φ1)(φ3†φ2)+λ2(φ1†φ2)²+h.c.','Equation (31); V=V0+V_Z4',1,1,0,'Two potentially complex coefficients; no equality between their magnitudes. Their labels are local to this construction and do not identify them with the D6 couplings.','Exact finite-group conclusions concern generic coefficients. Choosing δ=arg(λ2)/2 makes the second term invariant under b; the first is unchanged. No extra CP restriction is needed.');
INSERT INTO "theory_interactions" VALUES(67,'sm-octet-doublet-mfv',1,19,'Up-quark octet Yukawa','Yukawa','L ⊃ −η_U g^U_ij ū_Ri T^A Q_j S^A + h.c.',NULL,NULL,1,0,'g^U is the Standard Model Yukawa matrix; η_U is a complex constant.','Eq. (4); gauge contractions suppressed as in the source.');
INSERT INTO "theory_interactions" VALUES(68,'sm-octet-doublet-mfv',1,19,'Down-quark octet Yukawa','Yukawa','L ⊃ −η_D g^D_ij d̄_Ri T^A Q_j S^{A†} + h.c.',NULL,NULL,1,0,'g^D is the Standard Model Yukawa matrix; η_D is a complex constant.','Eq. (4); the conjugate scalar is not an independent multiplet.');
INSERT INTO "theory_interactions" VALUES(69,'sm-octet-doublet-mfv',1,19,'Pure Higgs potential','scalar_potential','V ⊃ (λ/4)(H†i H_i−v²/2)²',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(70,'sm-octet-doublet-mfv',1,19,'Octet quadratic term','scalar_mass','V ⊃ 2m_S² Tr(S†i S_i)',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(71,'sm-octet-doublet-mfv',1,19,'λ1 and λ2 Higgs–octet terms','scalar_quartic','V ⊃ λ1 H†i H_i Tr(S†j S_j)+λ2 H†i H_j Tr(S†j S_i)',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(72,'sm-octet-doublet-mfv',1,19,'λ3 Higgs–octet term','scalar_quartic','V ⊃ λ3 H†i H†j Tr(S_i S_j)+h.c.',NULL,NULL,1,0,'λ3 chosen real by rephasing S; this is a coordinate convention.',NULL);
INSERT INTO "theory_interactions" VALUES(73,'sm-octet-doublet-mfv',1,19,'One-Higgs three-octet terms','scalar_quartic','V ⊃ λ4 H†i Tr(S†j S_j S_i)+λ5 H†i Tr(S†j S_i S_j)+h.c.',NULL,NULL,1,0,'λ4 and λ5 may be complex. Color-matrix ordering is retained; no custodial coefficient relation is imposed.',NULL);
INSERT INTO "theory_interactions" VALUES(74,'sm-octet-doublet-mfv',1,19,'λ6 and λ7 octet quartics','scalar_quartic','V ⊃ λ6 Tr(S†i S_i S†j S_j)+λ7 Tr(S†i S_j S†j S_i)',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(75,'sm-octet-doublet-mfv',1,19,'Double-trace octet quartics','scalar_quartic','V ⊃ λ8 Tr(S†i S_i)Tr(S†j S_j)+λ9 Tr(S†i S_j)Tr(S†j S_i)+λ10 Tr(S_i S_j)Tr(S†i S†j)',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(76,'sm-octet-doublet-mfv',1,19,'λ11 octet quartic','scalar_quartic','V ⊃ λ11 Tr(S_i S_j S†j S†i)',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(77,'sm-octet-doublet-mfv-triplets',1,21,'Displayed triplet-sign-even potential','scalar_potential','ΔV_even=m²_{T_j}T_j^aT_j^a+λ_jklm T_j^aT_k^aT_l^bT_m^b+g_jk H†H T_j^aT_k^a',NULL,1,1,0,NULL,'Eq. (42) normalization and operator set. No inference that unlisted even operators are forbidden or vanish.');
INSERT INTO "theory_interactions" VALUES(78,'sm-octet-doublet-mfv-triplets',1,21,'Small triplet-sign-breaking cubic terms','scalar_cubic','ΔV_odd=ξ ε_ijk ε_abc T_i^aT_j^bT_k^c+μ_1j(S^{A†}σ^aS^A)T_j^a+μ_2j(H†σ^aH)T_j^a',NULL,0,1,0,'μ1, μ2 and ξ are dimensionful and very small in the adopted example.','Not invariant under T→−T, but explicitly included as its small breaking. They are not set identically to zero.');
INSERT INTO "theory_interactions" VALUES(79,'vlq-t-singlet',1,22,'Up-sector mixing','VEV_inserted_Yukawa','L ⊃ -y34^u v/sqrt(2) bar(t_L^0) T_R^0 + H.c.',NULL,NULL,1,0,'y43^u=0 in Eq. (4); no B partner','Weak-basis convention; v=246 GeV. The zero is not asserted as a basis-independent prohibition of every same-representation mass bilinear.');
INSERT INTO "theory_interactions" VALUES(80,'vlq-b-singlet',1,23,'Down-sector mixing','VEV_inserted_Yukawa','L ⊃ -y34^d v/sqrt(2) bar(b_L^0) B_R^0 + H.c.',NULL,NULL,1,0,'y43^d=0 in Eq. (4); no T partner','Weak-basis convention; v=246 GeV. No basis-independent exclusion of every same-representation mass bilinear is inferred.');
INSERT INTO "theory_interactions" VALUES(81,'vlq-xt-doublet',1,24,'Up-sector mixing','VEV_inserted_Yukawa','L ⊃ -y43^u v/sqrt(2) bar(T_L^0) t_R^0 + H.c.',NULL,NULL,1,0,'y34^u=0 in Eq. (4); no B partner','Weak-basis convention; v=246 GeV. T is a component of the doublet.');
INSERT INTO "theory_interactions" VALUES(82,'vlq-tb-doublet',1,25,'Up-sector mixing','VEV_inserted_Yukawa','L ⊃ -y43^u v/sqrt(2) bar(T_L^0) t_R^0 + H.c.',NULL,NULL,1,0,'y43^u independent of y43^d; y34^u=0','Eq. (4) weak-basis convention; v=246 GeV.');
INSERT INTO "theory_interactions" VALUES(83,'vlq-tb-doublet',1,25,'Down-sector mixing','VEV_inserted_Yukawa','L ⊃ -y43^d v/sqrt(2) bar(B_L^0) b_R^0 + H.c.',NULL,NULL,1,0,'y43^d independent of y43^u; y34^d=0','Eq. (4) weak-basis convention; v=246 GeV.');
INSERT INTO "theory_interactions" VALUES(84,'vlq-by-doublet',1,26,'Down-sector mixing','VEV_inserted_Yukawa','L ⊃ -y43^d v/sqrt(2) bar(B_L^0) b_R^0 + H.c.',NULL,NULL,1,0,'y34^d=0 in Eq. (4); no T partner','Weak-basis convention; v=246 GeV. B is a component of the doublet.');
INSERT INTO "theory_interactions" VALUES(85,'vlq-xtb-triplet',1,27,'Up-sector mixing','VEV_inserted_Yukawa','L ⊃ -y34^u v/sqrt(2) bar(t_L^0) T_R^0 + H.c.',NULL,NULL,1,0,'y34^d=sqrt(2)y34^u; y43^u=y43^d=0','Eq. (4), spherical triplet basis; v=246 GeV. Up/down entries are correlated components of the triplet coupling.');
INSERT INTO "theory_interactions" VALUES(86,'vlq-xtb-triplet',1,27,'Down-sector mixing','VEV_inserted_Yukawa','L ⊃ -y34^d v/sqrt(2) bar(b_L^0) B_R^0 + H.c.',NULL,NULL,1,0,'y34^d=sqrt(2)y34^u; y43^u=y43^d=0','Spherical triplet basis; this coefficient is not independent of the up-sector one.');
INSERT INTO "theory_interactions" VALUES(87,'vlq-tby-triplet',1,28,'Up-sector mixing','VEV_inserted_Yukawa','L ⊃ -y34^u v/sqrt(2) bar(t_L^0) T_R^0 + H.c.',NULL,NULL,1,0,'y34^u=sqrt(2)y34^d; y43^u=y43^d=0','Eq. (4), spherical triplet basis; v=246 GeV. Up/down entries are correlated components of the triplet coupling.');
INSERT INTO "theory_interactions" VALUES(88,'vlq-tby-triplet',1,28,'Down-sector mixing','VEV_inserted_Yukawa','L ⊃ -y34^d v/sqrt(2) bar(b_L^0) B_R^0 + H.c.',NULL,NULL,1,0,'y34^u=sqrt(2)y34^d; y43^u=y43^d=0','Spherical triplet basis; this coefficient is not independent of the up-sector one.');
INSERT INTO "theory_interactions" VALUES(89,'vlq-t-singlet',1,22,'Gauge-invariant vector-like mass','fermion_mass','L ⊃ -M^0 bar(T_L^0) T_R^0 + H.c.',NULL,1,1,0,NULL,'Bare mass, distinct from the heavy physical eigenvalue after mixing. No scalar-singlet mass origin is required.');
INSERT INTO "theory_interactions" VALUES(90,'vlq-b-singlet',1,23,'Gauge-invariant vector-like mass','fermion_mass','L ⊃ -M^0 bar(B_L^0) B_R^0 + H.c.',NULL,1,1,0,NULL,'Bare mass, distinct from the physical heavy eigenvalue after mixing.');
INSERT INTO "theory_interactions" VALUES(91,'vlq-xt-doublet',1,24,'Gauge-invariant vector-like mass','fermion_mass','L ⊃ -M^0 [bar(X_L)X_R + bar(T_L^0)T_R^0] + H.c.',NULL,1,1,0,NULL,'Common doublet mass. Component expression renders the gauge-invariant multiplet mass; mixing shifts the physical T mass.');
INSERT INTO "theory_interactions" VALUES(92,'vlq-tb-doublet',1,25,'Gauge-invariant vector-like mass','fermion_mass','L ⊃ -M^0 [bar(T_L^0)T_R^0 + bar(B_L^0)B_R^0] + H.c.',NULL,1,1,0,NULL,'Same M^0 in the two matrices of Eq. (4); physical heavy masses need not be equal.');
