INSERT INTO "theory_interactions" VALUES(98,'lq-r2-general',1,29,'Displayed R2 bosonic terms','kinetic_mass_and_Higgs_operators','(D_mu R2)†(D^mu R2) - (m_R2²+lambda_R2 H†H)(R2†R2) - lambda''_R2 H†a R2^a R2†b H^b','Eqs. (A.1), (A.2), (B.2)',NULL,1,0,NULL,'Appendix A Higgs convention. This collection is not a complete scalar self-interaction potential.');
