INSERT INTO "theory_interactions" VALUES(111,'mdm-majorana-quintuplet',1,39,'Minimal fermion gauge kinetics and mass','gauge_kinetic_and_mass','L-L_SM = (1/2) Xbar(iDslash+M)X','Equation (1), c=1/2',1,1,0,NULL,'Source mass sign retained. Prefactor follows the inferred Majorana realization; D is the inherited gauge-covariant derivative.');
