INSERT INTO "theory_interactions" VALUES(136,'pp331-displayed',1,53,'Source-prescribed diagonal lepton–eta Yukawa','source_stated_Yukawa','-L_Y contains (1/2) sum_l G_l epsilon_ijk bar(psi_li^c) psi_lj eta_k + h.c.',NULL,NULL,1,NULL,NULL,'Eq. (10) as written, interpreted with the appendix''s nonstandard conjugation. This records the proposed operator and assignment, not an independently established nonzero diagonal coupling or consistent charged-lepton mass mechanism.');
