INSERT INTO "theory_interactions" VALUES(150,'ql421-dirac',1,55,'Reliably extracted scalar quadratic terms','scalar_mass','V ⊃ m_H² H†H + m_χ² χ†χ + m_Φ² Tr(Φ†Φ)',NULL,NULL,1,0,NULL,'Eq. (24) also displays quartics λ1 through λ10. Their full invariant transcription is deferred, not omitted by a defining zero assumption. Trace acts in SU(4)C space.');
INSERT INTO "theory_interactions" VALUES(151,'ql421-dirac',1,56,'Absent scalar-leptoquark diquark Yukawas','excluded_Yukawa_operators',NULL,NULL,NULL,0,0,NULL,'The source states that Φ3 and Φ4 do not couple to a quark pair at renormalizable level. No explicit higher-dimensional proton-decay operator is reconstructed.');
INSERT INTO "theory_interactions" VALUES(152,'ql421-dirac',1,56,'Vector leptoquark gauge currents','gauge_fermion_current','(g4/√2) Xμ (Q̄L γμ ℓL + ūR γμ νR + d̄R γμ eR) + h.c.',NULL,NULL,1,NULL,NULL,'Eq. (25) uses four-component notation for components of the unified fermions. g4 equals the strong coupling evaluated at the SU(4)C scale; these are not arbitrary independent current coefficients.');
INSERT INTO "theory_interactions" VALUES(153,'ql421-inverse-seesaw',1,57,'Singlet–unified-fermion Yukawa','Yukawa','Y5 Fu χ N + h.c.',NULL,1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(154,'ql421-inverse-seesaw',1,57,'Singlet Majorana term','fermion_mass','(1/2) µ N N + h.c.',NULL,0,1,0,NULL,'Gauge invariant but explicitly breaks U(1)F. The symmetry flag refers to U(1)F; µ is allowed as a small breaking parameter, including its zero limit.');
INSERT INTO "theory_interactions" VALUES(155,'su5-adjoint-renormalizable',1,59,'Y1 charged-fermion Yukawa','Yukawa','10 5̄ Y1 5H* + h.c.','Eq. (1)',NULL,1,0,'Y1 is an arbitrary 3 × 3 matrix.','Schematic source contraction; matter overbar restored from the explicit inventory, without reconstructing tensor contractions.');
