INSERT INTO "theory_interactions" VALUES(158,'su5-adjoint-renormalizable',1,59,'Y4 two-10 Yukawa','Yukawa','10 10 Y4 45H + h.c.','Eq. (1)',NULL,1,0,NULL,'The optional proton-decay suppression discussed on page 4 is not imposed on the defining operator. Its matrix-symmetry interpretation requires checking the explicit fermionic contraction.');
