INSERT INTO "theory_interactions" VALUES(161,'su5-adjoint-renormalizable',1,59,'Bare adjoint-fermion mass','fermion_mass','V24 ⊃ m Tr(24²)','Eq. (8)',NULL,1,0,NULL,'Displayed normalization retained; no additional prefactor or hermitian-completion convention is inferred.');
INSERT INTO "theory_interactions" VALUES(162,'su5-adjoint-renormalizable',1,59,'Adjoint-fermion coupling to the breaking scalar','Yukawa','V24 ⊃ λ Tr(24² 24H)','Eq. (8)',NULL,1,0,NULL,'Generates correlated component mass splittings after the stated 24H VEV.');
INSERT INTO "theory_interactions" VALUES(163,'so10-45-126-sector',1,61,'Adjoint scalar potential V45','scalar_potential','V45=−(μ²/2)φijφij+(a0/4)φijφijφklφkl+(a2/4)φijφikφljφlk','Eqs. (2), (A4)-(A5); repeated indices contracted',1,1,0,'μ², a0 and a2 are real; no numerical restriction or compulsory nonzero value imposed.',NULL);
INSERT INTO "theory_interactions" VALUES(164,'so10-45-126-sector',1,61,'126 scalar potential V126','scalar_potential','V126=−ν² ΣijklmΣ*ijklm/5!+λ0 ΣijklmΣ*ijklmΣnopqrΣ*nopqr/(5!)²+λ2 ΣijklmΣ*ijklnΣopqrmΣ*opqrn/(4!)²+λ4 ΣijklmΣ*ijknoΣpqrlmΣ*pqrno/[(3!)²(2!)²]+λ′4 ΣijklmΣ*ijknoΣpqrlnΣ*pqrmo/(3!)²+[η2 ΣijklmΣijklnΣopqrmΣopqrn/(4!)²+h.c.]','Eqs. (3), (A4), (A6); repeated indices contracted',1,1,0,'ν², λ0, λ2, λ4 and λ′4 are real; η2 is complex.','η2 is retained. Its absence from the restricted SM vacuum potential, stationarity equations and tree-level spectrum does not remove the invariant from the theory.');
INSERT INTO "theory_interactions" VALUES(165,'so10-45-126-sector',1,61,'Mixed scalar potential Vmix','scalar_potential','Vmix=iτ φijΣklmniΣ*klmnj/4!+α φijφijΣklmnoΣ*klmno/(2·5!)+β4 φijφklΣmnoijΣ*mnokl/(4·3!)+β′4 φijφklΣmnoikΣ*mnojl/3!+[γ2 φijφikΣlmnojΣlmnok/4!+h.c.]','Eqs. (4), (A7); repeated indices contracted',1,1,0,'τ, α, β4 and β′4 are real; γ2 is complex. No general zero restriction imposed.',NULL);
INSERT INTO "theory_interactions" VALUES(166,'so10-45-126-complex10',1,64,'10H Yukawa','Yukawa','L ⊃ 16F f1^10 10H 16F+h.c.','Eq. (17); schematic source contraction',1,1,0,'f1^10 is a complex symmetric flavor matrix, independent of f2^10 and f126.',NULL);
INSERT INTO "theory_interactions" VALUES(167,'so10-45-126-complex10',1,64,'Conjugate-10H Yukawa','Yukawa','L ⊃ 16F f2^10 10H* 16F+h.c.','Eq. (17)',1,1,0,'f2^10 is a complex symmetric flavor matrix. No optional PQ selection forbidding this or the other 10H coupling is imposed.',NULL);
INSERT INTO "theory_interactions" VALUES(168,'so10-45-126-complex10',1,64,'Conjugate-126H Yukawa','Yukawa','L ⊃ 16F f126 126H* 16F+h.c.','Eq. (17)',1,1,0,'f126 is a complex symmetric flavor matrix.',NULL);
INSERT INTO "theory_interactions" VALUES(169,'so10-45-126-complex10',1,64,'Direct 10H-126H scalar mixing','scalar_quartic','10H 126H* 45H 45H','Section IV A schematic contraction',1,1,0,NULL,'Source-stated mixing interaction permitting an admixture of 10H and 126H electroweak doublets. Coefficient normalization and explicit tensor contraction are not supplied; this is not a complete extended potential.');
INSERT INTO "theory_interactions" VALUES(170,'trinification-n3-adjoint-l',1,65,'Common quark Yukawa','Yukawa','−LY ⊃ yQn^{ij} QLi QRj Hn + h.c.','Eq. (2.10)',1,1,0,'i,j=1,2,3 and n=1,2,3; no numerical texture imposed.',NULL);
INSERT INTO "theory_interactions" VALUES(171,'trinification-n3-adjoint-l',1,65,'Common lepton Yukawa','Yukawa','−LY ⊃ (yLn^{ij}/2) Li Lj Hn + h.c.','Eq. (2.10)',1,1,0,'yLn^{ij}=yLn^{ji}; i,j=1,2,3 and n=1,2,3.','Follow the explicit common-sector equation. Appendix A instead displays Hn*, an unresolved source conflict rather than an additional operator.');
INSERT INTO "theory_interactions" VALUES(172,'trinification-n3-adjoint-l',1,65,'Adjoint–lepton–scalar Yukawa','Yukawa','8L L H*','Tables 2 and 4; schematic source contraction',1,1,0,NULL,'Included operator family in the selected extension. Overall normalization, explicit gauge-index contraction and numerical flavor coefficients are not supplied; no requirement that every flavor entry be nonzero is inferred.');
INSERT INTO "theory_interactions" VALUES(173,'trinification-n3-adjoint-l',1,65,'Adjoint Majorana mass','fermion_mass',NULL,'Section 2.5 massive Majorana 8L discussion',NULL,1,0,NULL,'Source states a massive Majorana adjoint. No explicit coefficient normalization is reconstructed. Its nonzero mass is required for the discussed integration-out mechanism; M∼V is a contextual scale choice.');
INSERT INTO "theory_interactions" VALUES(174,'trinification-n3-adjoint-l',1,65,'Single-bi-triplet quartics','scalar_quartic','Σi=1..3 {λai [Tr(Hi†Hi)]² + λbi Tr(Hi†HiHi†Hi)}','Eq. (2.3a)',1,1,0,NULL,'Only the reliably prepared one-field trace structures are transcribed explicitly.');
INSERT INTO "theory_interactions" VALUES(175,'trinification-n3-adjoint-l',1,65,'Mixed-bi-triplet quartic sector','scalar_quartic_collection',NULL,'Viiij, Viijj and Viijk of Eqs. (2.3b–d)',NULL,1,0,NULL,'The general mixed quartics are included, not assumed zero. Exact dagger placements and trace powers are deferred. Together with the single-field terms, the source counts 54 real quartics plus 36 phases.');
INSERT INTO "theory_interactions" VALUES(176,'trinification-singlet-neutrino-sector',1,66,'Singlet-neutrino Yukawa','Yukawa','Lextra ⊃ −yNn^{ij} Ni Lj Hn*','Eq. (2.18)',1,1,0,'Generation-indexed coupling; scalar index n remains unselected. No arbitrary-coupling TAF claim.',NULL);
INSERT INTO "theory_interactions" VALUES(177,'trinification-singlet-neutrino-sector',1,66,'Singlet Majorana mass matrix','fermion_mass','Lextra ⊃ −(MN^{ij}/2) Ni Nj','Eq. (2.18)',1,1,0,NULL,'Displayed normalization retained. A nonsingular heavy-sector restriction is needed when integrating out the relevant singlet combinations.');
INSERT INTO "theory_interactions" VALUES(178,'mssm-rpc-conventional-soft',1,67,'Up-type superpotential Yukawa','superpotential_Yukawa','W ⊃ \bar u y_u Q H_u',NULL,NULL,1,0,'General dimensionless 3×3 family matrix y_u.','Weak doublets contract with epsilon. Third-family dominance is an optional approximation.');
INSERT INTO "theory_interactions" VALUES(179,'mssm-rpc-conventional-soft',1,67,'Down-type superpotential Yukawa','superpotential_Yukawa','W ⊃ −\bar d y_d Q H_d',NULL,NULL,1,0,'General dimensionless 3×3 family matrix y_d.','The displayed minus sign is a source convention; doublets contract with epsilon.');
INSERT INTO "theory_interactions" VALUES(180,'mssm-rpc-conventional-soft',1,67,'Charged-lepton superpotential Yukawa','superpotential_Yukawa','W ⊃ −\bar e y_e L H_d',NULL,NULL,1,0,'General dimensionless 3×3 family matrix y_e.','The minus sign is conventional. Holomorphy prevents replacing H_d by H_u* in this superpotential.');
INSERT INTO "theory_interactions" VALUES(181,'mssm-rpc-conventional-soft',1,67,'Supersymmetric Higgs mass','superpotential','W ⊃ μ H_u H_d',NULL,NULL,1,0,NULL,'H_u H_d=H_u^+H_d^-−H_u^0H_d^0 in the source component convention. μ is independent; no generation mechanism is selected.');
INSERT INTO "theory_interactions" VALUES(182,'mssm-rpc-conventional-soft',1,67,'Majorana gaugino soft masses','soft_gaugino_mass','L_soft ⊃ −(M3 tilde-g tilde-g + M2 tilde-W tilde-W + M1 tilde-B tilde-B + c.c.)/2',NULL,NULL,1,0,'Independent M1,M2,M3; no unification imposed.','These are fermion components of gauge vector multiplets, not superfield mass operators.');
INSERT INTO "theory_interactions" VALUES(183,'mssm-rpc-conventional-soft',1,67,'Conventional scalar soft cubics','soft_scalar_trilinear','L_soft ⊃ −(tilde-bar-u a_u tilde-Q H_u − tilde-bar-d a_d tilde-Q H_d − tilde-bar-e a_e tilde-L H_d + c.c.)',NULL,NULL,1,0,'a_u,a_d,a_e are independent complex 3×3 family matrices of mass dimension one.','All field factors here are scalar components. Yukawa proportionality is not imposed.');
INSERT INTO "theory_interactions" VALUES(184,'mssm-rpc-conventional-soft',1,67,'Sfermion soft squared masses','soft_scalar_mass','L_soft ⊃ −tilde-Q† m_Q² tilde-Q − tilde-L† m_L² tilde-L − tilde-bar-u m_bar-u² tilde-bar-u† − tilde-bar-d m_bar-d² tilde-bar-d† − tilde-bar-e m_bar-e² tilde-bar-e†',NULL,NULL,1,0,'Five independent Hermitian 3×3 family matrices, permitting complex off-diagonal entries.','Component notation and matrix ordering follow Eq. (6.3.1). No flavor diagonality or positivity for every parameter choice is imposed.');
INSERT INTO "theory_interactions" VALUES(185,'mssm-rpc-conventional-soft',1,67,'Higgs soft masses and bilinear','soft_scalar_mass_and_bilinear','L_soft ⊃ −m_Hu² H_u*H_u −m_Hd² H_d*H_d −(b H_u H_d+c.c.)',NULL,NULL,1,0,'Independent real squared-mass coefficients and generally complex b of mass dimension two.','Higgs symbols denote scalar components. A convention with b positive is attached to the neutral vacuum, not imposed as full-theory CP conservation.');
INSERT INTO "theory_interactions" VALUES(186,'mssm-rpc-conventional-soft',1,67,'Matter-parity-excluded superpotential terms','excluded_superpotential_operators','W_deltaL=λ^ijk L_i L_j \bar e_k/2 + λ''^ijk L_i Q_j \bar d_k + μ''^i L_i H_u; W_deltaB=λ''''^ijk \bar u_i \bar d_j \bar d_k/2',NULL,0,0,0,NULL,'Gauge invariant but forbidden by exact matter parity. λ'''' is antisymmetric in the final two family indices. Displaying these exclusions does not reconstruct an R-parity-violating model.');
INSERT INTO "theory_interactions" VALUES(187,'mssm-rpc-conventional-soft',1,67,'Conventionally omitted nonholomorphic soft cubics','excluded_operator_class','L_maybe_soft=−c_i^{jk} phi^{*i} phi_j phi_k/2+c.c.',NULL,NULL,0,1,NULL,'Schematic general class from Eq. (5.2); only gauge- and parity-compatible instances would be candidates. Omission is conventional, not a general gauge prohibition. No individual MSSM coefficient basis is reconstructed.');
INSERT INTO "theory_interactions" VALUES(188,'mssm-rpc-conventional-soft',1,67,'Derived classical Higgs scalar potential','component_scalar_potential','V=(|μ|²+m_Hu²)(|H_u^0|²+|H_u^+|²)+(|μ|²+m_Hd²)(|H_d^0|²+|H_d^-|²)+[b(H_u^+H_d^-−H_u^0H_d^0)+c.c.]+(g²+g''²)(|H_u^0|²+|H_u^+|²−|H_d^0|²−|H_d^-|²)²/8+g²|H_u^+H_d^{0*}+H_u^0H_d^{-*}|²/2',NULL,NULL,1,0,NULL,'Derived from the μ superpotential, Higgs soft terms and gauge D-terms; not an additional independent potential. Sfermion directions are omitted only for the stated vacuum analysis.');
INSERT INTO "theory_interactions" VALUES(189,'mssm-minimal-gauge-messengers',1,72,'Weak-doublet messenger coupling','superpotential_Yukawa','W_mess ⊃ y2 S ell \bar ell',NULL,NULL,1,0,NULL,'Displayed messenger superpotential; W_breaking is separately unspecified.');
INSERT INTO "theory_interactions" VALUES(190,'mssm-minimal-gauge-messengers',1,72,'Colored messenger coupling','superpotential_Yukawa','W_mess ⊃ y3 S q \bar q',NULL,NULL,1,0,NULL,NULL);
