INSERT INTO "theory_interactions" VALUES(194,'mssm-rpv-general',1,74,'Up-quark Yukawa','superpotential_Yukawa','-lambda^u_ij H_u Q_i U_j^c',NULL,NULL,1,0,NULL,'Source contraction order and relative sign retained.');
INSERT INTO "theory_interactions" VALUES(195,'mssm-rpv-general',1,74,'Lepton-number-violating bilinear','superpotential','mu_i H_u L_i',NULL,1,1,0,NULL,'Allowed by gauge symmetry; R-parity is not imposed. Family indices are summed.');
INSERT INTO "theory_interactions" VALUES(196,'mssm-rpv-general',1,74,'Lepton-number-violating LLE^c','superpotential_Yukawa','(1/2) lambda_ijk L_i L_j E_k^c',NULL,1,1,0,'lambda_ijk=-lambda_jik','Gauge invariant; weak-doublet contraction uses epsilon_ab. R-parity is explicitly violated.');
INSERT INTO "theory_interactions" VALUES(197,'mssm-rpv-general',1,74,'Lepton-number-violating LQD^c','superpotential_Yukawa','lambda-prime_ijk L_i Q_j D_k^c',NULL,1,1,0,NULL,'Gauge invariant; R-parity is explicitly violated.');
INSERT INTO "theory_interactions" VALUES(198,'mssm-rpv-general',1,74,'Baryon-number-violating U^cD^cD^c','superpotential_Yukawa','(1/2) lambda-double-prime_ijk U_i^c D_j^c D_k^c',NULL,1,1,0,'lambda-double-prime_ijk=-lambda-double-prime_ikj','Gauge invariant with epsilon color contraction; R-parity is explicitly violated.');
INSERT INTO "theory_interactions" VALUES(199,'mssm-rpv-general',1,74,'Displayed RPV soft scalar operators','soft_scalar_potential','V_soft,RPV=(1/2) A_ijk Ltilde_i Ltilde_j ltilde_k^c+A-prime_ijk Ltilde_i Qtilde_j dtilde_k^c+(1/2) A-double-prime_ijk utilde_i^c dtilde_j^c dtilde_k^c+B_i h_u Ltilde_i+mtilde_di^2 h_d† Ltilde_i+h.c.',NULL,NULL,1,0,'A coefficients are written directly, without factoring out superpotential couplings.','Eq. (2.16). All factors are scalar components of the listed superfields.');
INSERT INTO "theory_interactions" VALUES(200,'mssm-rpv-general',1,74,'Inherited displayed RPC soft sector','soft_operator_collection',NULL,'Eq. (2.15)',NULL,1,0,NULL,'Matter scalar mass matrices, charged-lepton/down/up scalar A-terms, both Higgs squared masses, B h_u h_d and Majorana masses M1,M2,M3. No universal masses or Yukawa proportionality is imposed. Component operators are not superfield mass terms.');
INSERT INTO "theory_interactions" VALUES(201,'mssm-rpv-bilinear',1,75,'Retained independent bilinear RPV sources','superpotential_and_soft_operator_collection','W_RPV=mu_i H_u L_i; V_soft,RPV=B_i h_u Ltilde_i+mtilde_di^2 h_d† Ltilde_i+h.c.',NULL,NULL,1,0,NULL,'Superfield W and component V are separate contributions. All RPC interactions are retained from the parent.');
INSERT INTO "theory_interactions" VALUES(202,'mssm-rpv-bilinear',1,75,'Absent independent trilinear RPV sources','excluded_operator_collection',NULL,NULL,NULL,0,1,'lambda=lambda-prime=lambda-double-prime=A=A-prime=A-double-prime=0 in the defining basis','Overrides parent trilinear inclusion. Rotated lepton-violating trilinears can be nonzero and dependent. The review states that bilinear superpotential sources do not radiatively generate RPV dimension-three A-terms.');
INSERT INTO "theory_interactions" VALUES(203,'mssm-rpv-dim23',1,76,'Retained bilinear superpotential and all displayed RPV soft terms','operator_collection',NULL,NULL,NULL,1,0,NULL,'Retain parent interaction 195 and every class in 199, including independent A, A-prime and A-double-prime. RPC interactions are unchanged.');
INSERT INTO "theory_interactions" VALUES(204,'mssm-rpv-dim23',1,76,'Removed trilinear RPV superpotential','excluded_superpotential_operators',NULL,NULL,NULL,0,1,'lambda=lambda-prime=lambda-double-prime=0 in the specified basis; overrides parent interactions 196-198.',NULL);
INSERT INTO "theory_interactions" VALUES(205,'mssm-rpv-soft-bilinear',1,77,'Only independent RPV soft sources','soft_scalar_bilinear','V_soft,RPV=B_i h_u Ltilde_i+mtilde_di^2 h_d† Ltilde_i+h.c.',NULL,NULL,1,0,NULL,'RPC interactions inherited; factors are scalar components.');
INSERT INTO "theory_interactions" VALUES(206,'mssm-rpv-soft-bilinear',1,77,'Removed independent RPV superpotential and soft triscalars','excluded_operator_collection',NULL,NULL,NULL,0,1,'mu_i=lambda=lambda-prime=lambda-double-prime=A=A-prime=A-double-prime=0 in the defining basis','Overrides parent interactions 195-198 and the triscalar classes of 199; this is not a claim about every rotated basis.');
INSERT INTO "theory_interactions" VALUES(207,'rpv-singlet-spontaneous-sector',1,80,'Singlet-generated Higgs mass coupling','superpotential','h_0 H_u H_d Phi',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(208,'rpv-singlet-spontaneous-sector',1,80,'Phi cubic','superpotential','lambda_Phi Phi^3',NULL,NULL,1,0,NULL,'Eq. (2.49) has no displayed factor 1/3; no NMSSM coefficient conversion imposed.');
INSERT INTO "theory_interactions" VALUES(209,'rpv-singlet-spontaneous-sector',1,80,'Neutrino Yukawa','superpotential_Yukawa','h^nu_ij H_u L_i N_j^c',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(210,'rpv-singlet-spontaneous-sector',1,80,'Singlet neutrino coupling','superpotential_Yukawa','h_ij S_i N_j^c Phi',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(211,'su5-rpv-trilinear-sector',1,81,'Unified RPV trilinear','superpotential_Yukawa','(1/2) Lambda_ijk bar5_i bar5_j 10_k',NULL,1,1,0,'Antisymmetric under exchange of the first two family indices.','Gauge invariant; R-parity is not imposed on this operator sector. No claim that every independent coefficient is nonzero.');
INSERT INTO "theory_interactions" VALUES(212,'split-susy',1,82,'Light Higgs quadratic and quartic terms','scalar_potential','L contains m² H†H - (lambda/2)(H†H)²',NULL,1,1,0,NULL,'Eq. (20) normalization. The quartic threshold is specified separately; the tuned quadratic coefficient is not determined by the fermion mass parameters.');
INSERT INTO "theory_interactions" VALUES(213,'split-susy',1,82,'Up-quark Yukawa','Yukawa','L contains -h^u_ij bar(q_j) u_i epsilon H* + h.c.; epsilon=i sigma2',NULL,1,1,0,'At mtilde, h^u_ij=lambda^{u*}_ij sin(beta); no numerical flavor texture imposed.',NULL);
INSERT INTO "theory_interactions" VALUES(214,'split-susy',1,82,'Down-quark Yukawa','Yukawa','L contains -h^d_ij bar(q_j) d_i H + h.c.',NULL,1,1,0,'At mtilde, h^d_ij=lambda^{d*}_ij cos(beta); threshold relation only.',NULL);
INSERT INTO "theory_interactions" VALUES(215,'split-susy',1,82,'Charged-lepton Yukawa','Yukawa','L contains -h^e_ij bar(ell_j) e_i H + h.c.',NULL,1,1,0,'At mtilde, h^e_ij=lambda^{e*}_ij cos(beta), following unambiguous Eq. (23). The H_e notation in Eq. (21) is not treated as an additional parent Higgs.',NULL);
INSERT INTO "theory_interactions" VALUES(216,'split-susy',1,82,'Gaugino and higgsino mass bilinears','fermion_mass_collection','L contains -[(M3/2)gtilde^A gtilde^A+(M2/2)Wtilde^a Wtilde^a+(M1/2)Btilde Btilde+mu Htilde_u^T epsilon Htilde_d+h.c.]',NULL,1,1,0,NULL,'Allowed by the defining gauge and matter-parity symmetries. These masses break the conditional U(1); no unified, anomaly-mediated or zero-mu input condition is required generally.');
INSERT INTO "theory_interactions" VALUES(217,'split-susy',1,82,'Up-higgsino Higgs–gaugino couplings','Yukawa','L contains -H†(gtilde_u sigma^a Wtilde^a+gtilde_u_prime Btilde)Htilde_u/sqrt(2)+h.c.',NULL,1,1,0,'At mtilde, gtilde_u=g sin(beta) and gtilde_u_prime=g_prime sin(beta). Below matching these run independently of the gauge couplings.',NULL);
INSERT INTO "theory_interactions" VALUES(218,'split-susy',1,82,'Down-higgsino Higgs–gaugino couplings','Yukawa','L contains -H^T epsilon(-gtilde_d sigma^a Wtilde^a+gtilde_d_prime Btilde)Htilde_d/sqrt(2)+h.c.',NULL,1,1,0,'At mtilde, gtilde_d=g cos(beta) and gtilde_d_prime=g_prime cos(beta). The relative wino sign follows Eq. (20).',NULL);
INSERT INTO "theory_interactions" VALUES(219,'split-susy',1,82,'Gauge-invariant kinetic terms','kinetic_operator_collection',NULL,NULL,NULL,1,0,NULL,'Explicitly additional to Eq. (20); includes inherited SM gauge interactions and covariant kinetics of the retained fields. No unsupplied component formula is reconstructed.');
INSERT INTO "theory_interactions" VALUES(220,'gem-supersoft',1,87,'Dirac supersoft operator','superspace_effective_operator','Integral d^2 theta sqrt(2) W''_alpha W_j^alpha A_j/M',NULL,1,1,0,NULL,'For each visible gauge factor, W_j contracts with its corresponding adjoint. Eq. (2.4) normalization; hidden D background generates the linked component operators.');
INSERT INTO "theory_interactions" VALUES(221,'gem-supersoft',1,87,'Linked supersoft component terms','derived_component_mass_and_scalar_trilinear','L contains -m_D lambda_j tilde a_j - m_D^2(a_j+a_j*)^2 - sqrt(2)m_D(a_j+a_j*) J_j',NULL,NULL,1,NULL,NULL,'Component consequences of interaction 220, not independent coefficients. J_j denotes the gauge scalar current summed over charged q_i; ambiguous extracted gauge/generator subscripts are not repaired. Only the real adjoint receives a tree mass from this operator alone.');
INSERT INTO "theory_interactions" VALUES(222,'gem-supersoft',1,87,'Independent second supersoft operator','superspace_effective_operator','Integral d^2 theta (W''_alpha W''^alpha/M^2) A_j^2',NULL,1,1,0,'Independent coefficient, permitted to vanish; Eq. (2.9) does not specify its numerical value.','Included as optional operator freedom. Opposite scalar/pseudoscalar mass-squared contributions do not alone establish a stable vacuum. No symmetry allowing Eq. (2.4) forbids this term, but neither operator generates the other.');
INSERT INTO "theory_interactions" VALUES(223,'gem-supersoft',1,87,'Optional supersymmetric ESP mass','superpotential_mass','W contains M_A A^2',NULL,NULL,1,0,'Free supersymmetric adjoint mass, including zero; schematic normalization follows Eq. (3.22).','Preserves N=1 supersymmetry. The scalar and ESP-fermion masses from this term are distinct from a direct visible-gaugino Majorana soft mass. Electroweak masses M_1,M_2 in Eq. (2.8) use that equation''s convention.');
INSERT INTO "theory_interactions" VALUES(224,'gem-supersoft',1,87,'Optional adjoint and Higgs–adjoint trilinears','superpotential_operator_class',NULL,NULL,1,NULL,0,NULL,'General N=1 interactions among adjoints and with Higgs fields are allowed. Exact gauge contractions and coefficients are not reconstructed. Higgs–ESP trilinears are mandatory only with the N=2 Higgs assignment; permission is not a universal nonzero coupling.');
INSERT INTO "theory_interactions" VALUES(225,'gem-supersoft',1,87,'Optional D-spurion Higgs bilinear','superspace_effective_operator','Integral d^2 theta (W''_alpha W''^alpha/M^2) H_u H_d',NULL,1,NULL,NULL,NULL,'Generation requires PQ-sensitive physics. The paper denotes the resulting scalar coefficient by mu B_mu, of order D^2/M^2. No exact PQ action, coefficient or mu-generation completion is imposed.');
INSERT INTO "theory_interactions" VALUES(226,'gem-supersoft-messengers',1,90,'Supersymmetric messenger mass','superpotential_mass','W contains M T_i bar T^i',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(227,'gem-supersoft-messengers',1,90,'Messenger–adjoint coupling','superpotential_Yukawa','W contains lambda T_i A^i_j bar T^j',NULL,NULL,1,0,NULL,'Displayed schematic contraction of Eq. (3.1); no full messenger charge table is inferred.');
INSERT INTO "theory_interactions" VALUES(228,'gem-supersoft-su5-bachelors',1,91,'Neglected second supersoft operator and omitted trilinear classes','scoped_operator_restrictions',NULL,NULL,NULL,0,1,NULL,'Overrides the core''s optional operator freedom for the Section 3.2 benchmark treatment: neglect Eq. (2.9), omit ESP/bachelor trilinears and Higgs–ESP/bachelor trilinears. Neglect of Eq. (2.9) is an approximation, not a symmetry prohibition. ESP and bachelor masses are allowed.');
INSERT INTO "theory_interactions" VALUES(229,'gem-supersoft-su3cubed-bachelors',1,92,'Neglected second supersoft operator and omitted trilinear classes','scoped_operator_restrictions',NULL,NULL,NULL,0,1,NULL,'Overrides the core''s optional operator freedom for the Section 3.2 benchmark treatment: neglect Eq. (2.9), omit ESP/bachelor trilinears and Higgs–ESP/bachelor trilinears. Neglect is not a protecting symmetry. ESP and bachelor masses are allowed.');
INSERT INTO "theory_interactions" VALUES(230,'general-gauge-mediation',1,94,'Weak gauging of the hidden current','superspace_current_coupling','L_int=2g integral d^4 theta mathcal J V + ...',NULL,NULL,1,NULL,NULL,'The ellipsis includes order-g² two-gauge-field terms required by gauge invariance. This is not a complete microscopic hidden-sector action.');
INSERT INTO "theory_interactions" VALUES(231,'u1-minimal-gauge-messenger-toy',1,95,'Canonical messenger gauge kinetics','superspace_kinetic','integral d^4 theta [phi† exp(2gV) phi + phi_tilde† exp(-2gV) phi_tilde]',NULL,1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(232,'u1-minimal-gauge-messenger-toy',1,95,'Spurion–messenger coupling','superpotential_Yukawa','W=lambda X phi phi_tilde',NULL,1,1,0,'lambda=1 in the Appendix A convention.','The superspace Lagrangian includes the Hermitian conjugate. X is evaluated on its prescribed background.');
INSERT INTO "theory_interactions" VALUES(233,'general-gauge-mediation-higgs-operators',1,96,'Up-Higgs direct hidden coupling','superpotential_operator_coupling','integral d^2 theta lambda_u O_u H_u',NULL,1,1,0,NULL,'Gauge-singlet contraction as specified in Eq. (5.4); hidden operator is composite, with assumed ultraviolet dimension two.');
INSERT INTO "theory_interactions" VALUES(234,'general-gauge-mediation-higgs-operators',1,96,'Down-Higgs direct hidden coupling','superpotential_operator_coupling','integral d^2 theta lambda_d O_d H_d',NULL,1,1,0,NULL,'Gauge-singlet contraction as specified in Eq. (5.4). This is not a complete constituent-level Yukawa sector.');
INSERT INTO "theory_interactions" VALUES(235,'ksvz-neutral-triplet',1,97,'Heavy-quark singlet Yukawa','Yukawa','L contains -y_Q bar(Q_L) Q_R Phi + h.c.',NULL,1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(236,'ksvz-neutral-triplet',1,97,'PQ-breaking singlet potential','scalar_potential','V(Phi)=lambda_Phi (|Phi|²-v_a²/2)²',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(237,'ksvz-neutral-triplet',1,97,'Absent bare heavy-quark mass','excluded_fermion_mass','mu_Q bar(Q_L) Q_R + h.c.',NULL,0,0,1,NULL,'Gauge invariant but incompatible with the displayed PQ action. Absence is assumed; the optional discrete enforcement mechanism is not imposed.');
INSERT INTO "theory_interactions" VALUES(238,'ksvz-neutral-triplet',1,98,'Anomaly-induced axion-gluon interaction','effective_anomalous_interaction','delta L=g_s² a G G_tilde/(32 pi² v_a)',NULL,NULL,1,NULL,NULL,'Generated by the anomalous axial Q redefinition and heavy-Q removal. f_a=v_a; not a new independent ultraviolet coefficient.');
INSERT INTO "theory_interactions" VALUES(239,'ksvz-representation-framework',1,99,'Signed singlet Yukawa assignment','Yukawa_assignment','-y_Q bar(Q_L) Q_R Phi + h.c., or -y_Q bar(Q_L) Q_R Phi-dagger + h.c.',NULL,1,1,NULL,NULL,'Alternative for each heavy pair according to its PQ charges, not two simultaneously included couplings for one fixed pair. No full cross-species Yukawa matrix is reconstructed.');
INSERT INTO "theory_interactions" VALUES(240,'dfsz-i-quartic',1,100,'Common quartic DFSZ potential','scalar_potential','V=V_moduli(|H_u|,|H_d|,|Phi|,|H_u H_d|)+(lambda H_u H_d Phi-dagger²+h.c.)',NULL,1,1,0,NULL,'V_moduli contains the gauge-allowed moduli terms; coefficients are not individually expanded. The phase-sensitive operator preserves PQ while reducing the larger scalar rephasing group.');
INSERT INTO "theory_interactions" VALUES(241,'dfsz-i-quartic',1,100,'Up-quark Yukawa','Yukawa','L contains -Y_U bar(q_L) u_R H_u+h.c.',NULL,1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(242,'dfsz-i-quartic',1,100,'Down-quark Yukawa','Yukawa','L contains -Y_D bar(q_L) d_R H_d+h.c.',NULL,1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(243,'dfsz-i-quartic',1,100,'DFSZ-I charged-lepton Yukawa','Yukawa','L contains -Y_E bar(ell_L) e_R H_d+h.c.',NULL,1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(244,'dfsz-ii-quartic',1,101,'DFSZ-II charged-lepton Yukawa replacement','Yukawa','L contains -Y_E bar(ell_L) e_R (i sigma_2 H_u*)+h.c.',NULL,1,1,0,NULL,'Replaces interaction 243 of the comparison baseline. Quark assignments remain unchanged; H_d charged-lepton coupling is not simultaneously retained.');
INSERT INTO "theory_interactions" VALUES(245,'smash-down',1,102,'SM up-quark Yukawa','Yukawa','L contains -Yu_ij qi εH uj + h.c.','Eq. (1)',1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(246,'smash-down',1,102,'SM down-quark Yukawa','Yukawa','L contains -Yd_ij qi H† dj + h.c.','Eq. (1)',1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(247,'smash-down',1,102,'Charged-lepton Yukawa','Yukawa','L contains -G_ij Li H† Ej + h.c.','Eq. (1)',1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(248,'smash-down',1,102,'Neutrino Dirac Yukawa','Yukawa','L contains -F_ij Li εH Nj + h.c.',NULL,1,1,0,'General family matrix; no scan ansatz or CP-conservation restriction imposed.',NULL);
INSERT INTO "theory_interactions" VALUES(249,'smash-down',1,102,'Singlet-neutrino Majorana Yukawa','Yukawa','L contains -(1/2)Y_ij σ Ni Nj + h.c.','Eq. (1); retain the explicit factor 1/2.',1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(250,'smash-down',1,102,'Colored-pair singlet Yukawa','Yukawa','L contains -y Qtilde σ Q + h.c.',NULL,1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(251,'smash-down',1,102,'Decay-enabling down-quark mixing','Yukawa','L contains -yQd_i σ Q di + h.c.',NULL,1,1,0,NULL,'Appropriate nonzero mixing permits Q decay. Its omission in stability scans is confined to regime 107, not imposed here.');
INSERT INTO "theory_interactions" VALUES(252,'smash-down',1,102,'PQ-invariant scalar potential','scalar_potential','V=λH(H†H-v²/2)²+λσ(|σ|²-vσ²/2)²+2λHσ(H†H-v²/2)(|σ|²-vσ²/2)','Eq. (4); L contains -V.',1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(253,'smash-down',1,102,'Jordan-frame gravitational contribution','nonminimal_gravitational_coupling','S contains -∫d^4x sqrt(-g)[M²/2+ξH H†H+ξσ σ*σ]R',NULL,NULL,1,0,NULL,'Eqs. (22)-(23); MP²=M²+ξH v²+ξσ vσ². Positive ξH,ξσ assumed for the analysis; other gravitational operators are subject to assumption 46.');
INSERT INTO "theory_interactions" VALUES(254,'smash-down',1,103,'Axion-gluon anomaly coupling','effective_anomalous_interaction','L contains -(αs/8π)(A/fA) G^c_mu_nu Gtilde^{c,mu_nu}',NULL,NULL,1,NULL,NULL,'Eq. (8); derived heavy-sector anomaly, not an independent ultraviolet coefficient.');
INSERT INTO "theory_interactions" VALUES(255,'smash-down',1,103,'Axion-photon anomaly coupling above QCD','effective_anomalous_interaction','L contains -(α/8π)(2/3)(A/fA) F_mu_nu Ftilde^{mu_nu}',NULL,NULL,1,NULL,NULL,'Eq. (8), above ΛQCD and below electroweak breaking; low-energy QCD matching changes the photon coefficient.');
INSERT INTO "theory_interactions" VALUES(256,'smash-down',1,103,'Axion/majoron active-neutrino coupling','effective_derivative_interaction','L contains -(∂mu A/4fA) bar(νi) gamma^mu gamma5 νi',NULL,NULL,1,NULL,NULL,'Eq. (8); active Majorana mass eigenstates. No tree-level axion interaction with SM quarks or charged leptons in this description; loop-induced interactions are not excluded.');
INSERT INTO "theory_interactions" VALUES(257,'lns-two-singlet-quarks',1,108,'Holomorphic effective up Yukawas','effective_superpotential_Yukawa','W contains sum_ij lambda_uij Q_i phi_u ubar_j (S1/M)^n1ij (S2/M)^n2ij, for nonnegative n1ij,n2ij',NULL,1,1,0,'naij=Ha(Q_i)+Ha(ubar_j), a=1,2. Leading Yu orders [[epsilon2^2,0,epsilon2],[epsilon1 epsilon2,epsilon2,epsilon1],[epsilon2,0,1]]. Independent order-one coefficients on nonzero entries.','The two-singlet formula is the prepared charge-conservation inference. Entries (1,2),(3,2) require negative S1 powers and are absent in this continuous holomorphic description; no discrete all-orders zero theorem is asserted.');
INSERT INTO "theory_interactions" VALUES(258,'lns-two-singlet-quarks',1,108,'Holomorphic effective down Yukawas','effective_superpotential_Yukawa','W contains sum_ij lambda_dij Q_i phi_d dbar_j (S1/M)^m1ij (S2/M)^m2ij',NULL,1,1,0,'maij=Ha(Q_i)+Ha(dbar_j), a=1,2. Leading Yd orders [[epsilon2^2,epsilon1 epsilon2,epsilon1 epsilon2],[epsilon1 epsilon2,epsilon1^2,epsilon1^2],[epsilon2,epsilon1,epsilon1]].','Nonnegative integer insertion powers; independent coefficients. The source''s component Yukawa Lagrangian includes h.c.; no superpotential normalization beyond the schematic operator is inferred.');
INSERT INTO "theory_interactions" VALUES(259,'af-a4-susy-effective',1,113,'Displayed charged-lepton operator collection','effective_superpotential_Yukawa','[ye e^c(phiT l)+ymu mu^c(phiT l)''+ytau tau^c(phiT l)''''] h_d/Lambda','Equations (12), (23)',NULL,1,0,NULL,'Three independent terms with field-dependent hierarchy coefficients y_f(theta). The printed contractions are retained, but their consistency with the conflicting table assignments is unresolved. The source prints h.c.; it is not treated as an antiholomorphic term inside a holomorphic superpotential.');
INSERT INTO "theory_interactions" VALUES(260,'af-a4-susy-effective',1,113,'xi effective neutrino operator','effective_superpotential','xa xi(l h_u l h_u)/Lambda²',NULL,NULL,1,0,NULL,'A4 invariant singlet contraction (ab)=a1b1+a2b3+a3b2; electroweak contractions follow the source''s suppressed notation.');
INSERT INTO "theory_interactions" VALUES(261,'af-a4-susy-effective',1,113,'xi_tilde effective neutrino operator','effective_superpotential','xa_tilde xi_tilde(l h_u l h_u)/Lambda²',NULL,NULL,1,0,NULL,'Retained explicitly in equation (23); its leading vacuum contribution vanishes because the selected xi_tilde VEV is zero, not because the coefficient is removed.');
INSERT INTO "theory_interactions" VALUES(262,'af-a4-susy-effective',1,113,'Triplet-flavon effective neutrino operator','effective_superpotential','xb (phiS l l) h_u h_u/Lambda²',NULL,NULL,1,0,NULL,'Source A4 contractions and normalization of equations (7)–(9), (23); no additional independent mass-texture coefficient is introduced.');
INSERT INTO "theory_interactions" VALUES(263,'af-a4-susy-effective',1,113,'Leading driving superpotential','superpotential','w_d=M(phiT0 phiT)+g(phiT0 phiT phiT)+g1(phiS0 phiS phiS)+g2 xi_tilde(phiS0 phiS)+g3 xi0(phiS phiS)+g4 xi0 xi²+g5 xi0 xi xi_tilde+g6 xi0 xi_tilde²','Equation (25)',1,1,0,NULL,'Linear in driving superfields. Original g3,g4 convention retained; no Appendix B tilde-coupling redefinition is imposed.');
INSERT INTO "theory_interactions" VALUES(264,'af-a4-susy-effective',1,113,'Undressed neutrino operator excluded by Z3','excluded_effective_superpotential','(l h_u l h_u)/Lambda',NULL,0,0,0,NULL,'Transforms as omega² under the specified auxiliary Z3; exclusion is a selection rule, not an independently tuned coefficient.');
INSERT INTO "theory_interactions" VALUES(265,'af-a4-susy-effective',1,113,'Three independent next-order neutrino structures','effective_superpotential_collection','[xc(phiT phiS)''(ll)''''+xd(phiT phiS)''''(ll)''+xe xi(phiT ll)] h_u h_u/Lambda³','Equation (32)',NULL,1,0,NULL,'Three separate terms with independent coefficients. Their effects cannot be absorbed into xa,xb in the stated analysis; this is not the full higher-order action.');
INSERT INTO "theory_interactions" VALUES(266,'af-a4-susy-effective',1,113,'Next-order charged-lepton operator class','effective_superpotential_Yukawa','(f^c l phiT phiT) h_d/Lambda², f^c=e^c,mu^c,tau^c','Equation (30)',NULL,1,0,NULL,'Schematic source operator class with coefficients and charged-singlet contractions suppressed. At the leading aligned vacuum it reproduces the leading texture; this does not exclude alignment-induced corrections at the preceding relative order.');
INSERT INTO "theory_interactions" VALUES(267,'af-a4-susy-seesaw',1,114,'Neutrino Dirac superpotential','superpotential_Yukawa','y(nu^c l) h_u','Equation (45)',NULL,1,0,NULL,'Retain the printed singlet contraction. No identity Dirac matrix is canonicalized: the common-basis contraction and equation (46) disagree without a stated basis change.');
INSERT INTO "theory_interactions" VALUES(268,'af-a4-susy-seesaw',1,114,'Singlet-flavon Majorana operator collection','superpotential_Yukawa','(xA xi+xA_tilde xi_tilde)(nu^c nu^c)','Equation (45)',NULL,1,0,NULL,'Two independent terms. No factor 1/2 is inserted into the displayed superpotential convention. Both singlets remain present although xi_tilde has zero leading VEV.');
INSERT INTO "theory_interactions" VALUES(269,'af-a4-susy-seesaw',1,114,'Triplet-flavon Majorana operator','superpotential_Yukawa','xB(phiS nu^c nu^c)','Equation (45)',NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(270,'modular-a4-flavonfree-seesaw',1,115,'E1 charged-lepton coupling','superpotential_Yukawa','w ⊃ α E1^c Hd(LY)1 = α E1^c Hd(Y1 L1+Y3 L2+Y2 L3)',NULL,1,1,0,'Linear in the weight-2 modular triplet, with constant coefficient α.',NULL);
INSERT INTO "theory_interactions" VALUES(271,'modular-a4-flavonfree-seesaw',1,115,'E2 charged-lepton coupling','superpotential_Yukawa','w ⊃ β E2^c Hd(LY)1'' = β E2^c Hd(Y2 L1+Y1 L2+Y3 L3)',NULL,1,1,0,'Linear in the same modular triplet, with independent constant β.',NULL);
INSERT INTO "theory_interactions" VALUES(272,'modular-a4-flavonfree-seesaw',1,115,'E3 charged-lepton coupling','superpotential_Yukawa','w ⊃ γ E3^c Hd(LY)1'''' = γ E3^c Hd(Y3 L1+Y2 L2+Y1 L3)',NULL,1,1,0,'Linear in the same modular triplet, with independent constant γ.',NULL);
INSERT INTO "theory_interactions" VALUES(273,'modular-a4-flavonfree-seesaw',1,115,'Two independent neutrino Dirac contractions','superpotential_Yukawa','w ⊃ N^{cT} Yν Hu L; Yν=[[2g1Y1,(-g1+g2)Y3,(-g1-g2)Y2],[(-g1-g2)Y3,2g1Y2,(-g1+g2)Y1],[(-g1+g2)Y2,(-g1-g2)Y1,2g1Y3]]',NULL,1,1,0,'Two independent constants g1,g2; all entries use the same constrained Yi(τ).','Equation (51) fixes the contraction normalization. The shorthand g(N^c Hu L Y)1 denotes both invariant contributions.');
INSERT INTO "theory_interactions" VALUES(274,'modular-a4-flavonfree-seesaw',1,115,'Modular Majorana term','superpotential_mass','w ⊃ Λ(N^c N^c Y)1 = N^{cT} MR N^c; MR=Λ[[2Y1,-Y3,-Y2],[-Y3,2Y2,-Y1],[-Y2,-Y1,2Y3]]',NULL,1,1,0,NULL,'Equation (51) as printed, without inserting a factor 1/2. Permission flag refers to modular and gauge symmetry; fixed nonzero Λ breaks lepton number. Conversion to a canonically normalized physical Majorana mass remains unresolved.');
INSERT INTO "theory_interactions" VALUES(275,'grv-quark-flavor-u3',1,116,'Up-sector Higgs coupling','Yukawa','λu bar(QL) H̃ ΨuR + h.c.',NULL,NULL,1,NULL,'Flavor-universal λu; a real convention is available.',NULL);
