INSERT INTO "theory_interactions" VALUES(278,'grv-quark-flavor-u3',1,116,'Down-sector Higgs coupling','Yukawa','λd bar(QL) H ΨdR + h.c.',NULL,NULL,1,NULL,'Flavor-universal λd; a real convention is available.',NULL);
