INSERT INTO "theory_interactions" VALUES(281,'grv-quark-flavor-u3',1,116,'Unspecified scalar potential','scalar_potential','L contains -V(Yu,Yd,H)',NULL,NULL,1,NULL,NULL,'The symbol does not specify an operator basis or coefficients. No realistic renormalizable two-flavon potential is asserted; see assumption 61.');
INSERT INTO "theory_interactions" VALUES(282,'grv-quark-flavor-u3',1,116,'Flavon-induced flavor-vector mass terms','derived_gauge_boson_mass','Lmass=Tr|gU AU Yu-gQ Yu AQ|²+Tr|gD AD Yd-gQ Yd AQ|²',NULL,NULL,1,NULL,NULL,'Yu,Yd denote VEVs here. This follows from covariant scalar kinetics, not independent explicit vector masses. AQ is traceless; AU,AD include their Abelian generators. Nonabelian generators are λa/2; the identity-generator normalization is not fixed in the prepared claim.');
INSERT INTO "theory_interactions" VALUES(283,'grv-quark-flavor-u3',1,116,'Hypercharge mixing with the two flavor U(1) fields','abelian_kinetic_mixing',NULL,NULL,1,1,0,NULL,'Two independently parameterized hypercharge-mixing contributions are retained without a supplied coefficient normalization. Zero mixing is a conditional analysis choice. The 5% statement applies only to the second example; it is not a general structural bound.');
INSERT INTO "theory_interactions" VALUES(284,'sm-singlet-neutrino-framework',1,119,'Sterile kinetic term','kinetic','L contains bar(N_I) i partial_mu gamma^mu N_I','Eq. (1)',NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(285,'sm-singlet-neutrino-framework',1,119,'Neutrino Higgs–lepton Yukawa','Yukawa','L contains -F_alphaI bar(L_alpha) N_I Phi + h.c.','Eq. (1)',1,1,0,'General matrix F_alphaI; alpha=e,mu,tau and I=1,...,N.','Phi notation follows the source without adding a Higgs conjugation convention.');
