INSERT INTO "theory_interactions" VALUES(287,'ma-radiative-seesaw-z2',1,123,'Charged-lepton Yukawa','Yukawa','L_Y contains f_ij(φ−ν_i + φbar0 l_i)l_j^c + H.c.','Eq. (5), first term',1,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(288,'ma-radiative-seesaw-z2',1,123,'Lepton–η–N Yukawa assignment','Yukawa_assignment',NULL,'Eq. (5) prints h_ij(ν_iη0 − l_jη+)N_j + H.c.',NULL,1,0,NULL,'The participant assignment and existence of h_ij are supported. A canonical indexed expression is deferred because the printed l_j and ν_i do not form a consistently indexed doublet contraction. No replacement by l_i or flavor texture is imposed.');
INSERT INTO "theory_interactions" VALUES(289,'ma-radiative-seesaw-z2',1,123,'Singlet Majorana masses','fermion_mass','(1/2) M_i N_i N_i + H.c.',NULL,1,1,0,'Displayed diagonal mass notation; no numerical masses or hierarchy imposed generally.',NULL);
INSERT INTO "theory_interactions" VALUES(290,'ma-radiative-seesaw-z2',1,123,'Exact-parity scalar potential','scalar_potential','V=m_1²Φ†Φ+m_2²η†η+(λ1/2)(Φ†Φ)²+(λ2/2)(η†η)²+λ3(Φ†Φ)(η†η)+λ4(Φ†η)(η†Φ)+(λ5/2)[(Φ†η)²+H.c.]','Eq. (6)',1,1,0,'λ5 chosen real by a phase convention. Its operator is retained; no compulsory zero or numerical quartic value is imposed.',NULL);
INSERT INTO "theory_interactions" VALUES(291,'ma-radiative-seesaw-z2',1,123,'Forbidden scalar mixing bilinear','excluded_scalar_operator','μ²Φ†η + H.c.',NULL,0,0,0,NULL,'Forbidden by exact Z2, rather than a symmetry-allowed coefficient tuned to zero. The softly broken global-lepton-number comparator is not inherited.');
INSERT INTO "theory_interactions" VALUES(292,'weinberg-t41i-doublet-fermions',1,128,'Triplet coupling between loop doublet fermions','component_Yukawa','yL bar(ψ′) PL ψ Δ0 + h.c.',NULL,NULL,1,NULL,NULL,'Eq. (3) component term within the Eq. (4) gauge embedding. Symbols for the fermions here denote the participating components; no full tensor transcription is claimed.');
INSERT INTO "theory_interactions" VALUES(293,'weinberg-t41i-doublet-fermions',1,128,'First Higgs coupling in the fermion loop','component_Yukawa','YL bar(ψ) PL Ψ H0 + h.c.',NULL,NULL,1,NULL,NULL,'Eq. (3) component term, embedded by Eq. (4); not an independently complete gauge-invariant expression.');
INSERT INTO "theory_interactions" VALUES(294,'weinberg-t41i-doublet-fermions',1,128,'Second Higgs coupling in the fermion loop','component_Yukawa','YR′ bar(Ψ) PR ψ′ H0 + h.c.',NULL,NULL,1,NULL,NULL,'Eq. (3) component term, embedded by Eq. (4); no additional conjugate multiplet is introduced.');
INSERT INTO "theory_interactions" VALUES(295,'weinberg-t41i-doublet-fermions',1,128,'Type-II lepton coupling','component_Yukawa','YΔ bar(νL^C) νL Δ0* + h.c.',NULL,NULL,1,NULL,NULL,'Displayed Eq. (3) neutrino component of the Eq. (4) lepton-doublet coupling. No flavor texture is imposed.');
INSERT INTO "theory_interactions" VALUES(296,'weinberg-t41i-doublet-fermions',1,128,'Displayed mediator mass terms','mass_operator_collection','Mψ bar(ψ)ψ + Mψ′ bar(ψ′)ψ′ + MΨ bar(Ψ)Ψ + mΔ² Δ†Δ',NULL,NULL,1,NULL,NULL,'Signs follow the displayed Lagrangian. These terms do not provide a scalar potential or certify a vacuum.');
INSERT INTO "theory_interactions" VALUES(297,'weinberg-t41i-doublet-fermions',1,128,'Required type-II scalar vertex mu_Delta','scalar_trilinear_and_counterterm',NULL,NULL,NULL,1,NULL,NULL,'The ordinary Delta–H–H vertex must be present in the renormalized sector to absorb the loop divergence. Exact contraction and counterterm normalization are not reconstructed.');
INSERT INTO "theory_interactions" VALUES(298,'su4-hypercolor-partial-compositeness',1,130,'Nonlinear pNGB gauge kinetics','gauge_kinetic','L contains (f^2/16) tr[(D_mu U)-dagger D^mu U]; D_mu U=partial_mu U-i g W_mu^a[TL^a,U]-i g'' B_mu[TR3,U]',NULL,NULL,1,NULL,NULL,'Displayed SU(5)/SO(5) sector with singlets omitted; this is not a complete derivative operator basis.');
INSERT INTO "theory_interactions" VALUES(299,'su4-hypercolor-partial-compositeness',1,130,'Left-quark partial-compositeness mixing','linear_elementary_composite_mixing','lambda_q f bar(q-hat-L) Sigma Psi_R + h.c.',NULL,NULL,1,NULL,'lambda_q dimensionless','Third family only; q-hat-L is a 5 spurion. The right-handed (T,B) projection supplies the matching SM doublet.');
INSERT INTO "theory_interactions" VALUES(300,'su4-hypercolor-partial-compositeness',1,130,'Right-top partial-compositeness mixing','linear_elementary_composite_mixing','lambda_t f bar(t-hat-R) Sigma* Psi_L + h.c.',NULL,NULL,1,NULL,'lambda_t dimensionless; expected of similar order to lambda_q, not fixed equal','t-hat-R is a 5-bar spurion. The left-handed R component supplies the matching SM singlet.');
INSERT INTO "theory_interactions" VALUES(301,'su4-hypercolor-partial-compositeness',1,130,'Composite Dirac mass','fermion_mass','(M/2) bar(Psi) Psi + h.c.',NULL,NULL,1,NULL,NULL,'Retain the source''s pre-h.c. normalization; the component mass matrices contain M.');
INSERT INTO "theory_interactions" VALUES(302,'su4-hypercolor-partial-compositeness',1,130,'Quadratic up-quark mass assignment','effective_Yukawa_assignment','bar(q-hat-Li) U* u-hat-Rj with appropriate SU(5) contraction and coefficients',NULL,NULL,1,NULL,NULL,'Uses 24 and 10 spurions. Exact general flavor coefficients are not specified. Quadratic top contributions are neglected in the explicit third-family mass analysis.');
INSERT INTO "theory_interactions" VALUES(303,'su4-hypercolor-partial-compositeness',1,130,'Quadratic down-quark mass assignment','effective_Yukawa_assignment','bar(q-hat-Li) U d-hat-Rj; displayed bottom term sqrt(2) mu_b tr[bar(q-hat-L3) U d-hat-R3] + h.c.',NULL,NULL,1,NULL,NULL,'Uses 24 and 10-bar spurions. The bottom term is a specified member of this class, not an additional independent duplicate interaction.');
INSERT INTO "theory_interactions" VALUES(304,'su4-hypercolor-partial-compositeness',1,130,'Leading radiative Higgs-background potential','effective_scalar_potential','V(h) proportional to alpha cos(2h/f) - beta sin^2(2h/f)',NULL,NULL,1,NULL,NULL,'Leading Coleman–Weinberg description along the neutral-Higgs background. Strong-sector integrals and the overall dimensionful normalization are not calculated. This is not a full potential for all pNGB directions.');
INSERT INTO "theory_interactions" VALUES(305,'littlest-higgs-minimal',1,131,'Leading sigma covariant kinetic term','gauge_kinetic','(f^2/4) tr|D_mu Sigma|^2; D Sigma=partial Sigma-sum_j[i g_j W_j^a(Q_j^a Sigma+Sigma Q_j^{aT})+i g''_j B_j(Y_j Sigma+Sigma Y_j^T)]',NULL,NULL,1,NULL,NULL,'Source normalization of Eqs. (3.9)–(3.10), not converted to another decay-constant convention. Conventional gauge and fermion kinetic terms are also retained.');
INSERT INTO "theory_interactions" VALUES(306,'littlest-higgs-minimal',1,131,'Collective nonlinear lambda1 top assignment','nonlinear_Yukawa_assignment',NULL,'Eq. (3.11): lambda1 f epsilon_ijk epsilon_xy chi_i Sigma_jx Sigma_ky u3-prime-c + h.c.; chi=(b3,t3,t-tilde)',NULL,1,NULL,'Exact overall normalization relative to Eq. (3.12) is deferred; the extracted expression has no explicit 1/2.','i,j,k=1,2,3 and x,y=4,5. The operator structure and participants are retained. Section 3 states that lambda1 preserves SU(3)1 and breaks SU(3)2; no reconciliation of the separate gauge-label conflict is implied.');
INSERT INTO "theory_interactions" VALUES(307,'littlest-higgs-minimal',1,131,'Lambda2 partner mass','fermion_mass','lambda2 f t-tilde t-tilde-c + h.c.',NULL,NULL,1,NULL,NULL,'Together with the lambda1 term this generates the top Yukawa. Section 3 states the complementary protecting-SU(3) breaking pattern.');
INSERT INTO "theory_interactions" VALUES(308,'littlest-higgs-minimal',1,131,'Omitted tree-level Abelian kinetic mixing','abelian_kinetic_mixing',NULL,NULL,NULL,0,1,NULL,'No tree-level mixing of the two nonorthogonal U(1) factors is included. Loop-generated mixing in this EFT is treated as sufficiently small. This is not a symmetry prohibition or a demonstrated property of every strong ultraviolet realization.');
INSERT INTO "theory_interactions" VALUES(309,'littlest-higgs-minimal',1,131,'Leading gauge radiative potential','scalar_potential_counterterm','V_g=sum_j[c g_j^2 f^4 sum_a tr((Q_j^a Sigma)(Q_j^a Sigma)*)+c g_j''^2 f^4 tr((Y_j Sigma)(Y_j Sigma)*)]',NULL,NULL,1,NULL,'c is an ultraviolet-sensitive coefficient of order one; c>0 is the source''s alignment assumption.','Using Lambda approximately 4pi f. Its displayed expansion is c(g1^2+g1''^2)f^2|phi_ij+i(h_i h_j+h_j h_i)/(2f)|^2+c(g2^2+g2''^2)f^2|phi_ij-i(h_i h_j+h_j h_i)/(2f)|^2. The expansion is the same interaction, not an independent potential.');
INSERT INTO "theory_interactions" VALUES(310,'littlest-higgs-minimal',1,131,'Fermion-induced scalar counterterm structure','scalar_potential_counterterm',NULL,'Eq. (4.8): -c'' lambda1^2 epsilon_wx epsilon_yz epsilon_ijk epsilon_kmn Sigma_iw Sigma_jx Sigma*_my Sigma*_nz + h.c.',NULL,1,NULL,'Dimensionful overall normalization is unresolved and is not silently restored.','The source states that this contributes the same scalar structure as the first term of Eq. (4.7), with coefficient -c'' lambda1^2, and preserves the Section 3 top-sector SU(3)1. Only that structural assignment is canonicalized.');
INSERT INTO "theory_interactions" VALUES(311,'littlest-higgs-minimal',1,131,'Remaining up-sector Yukawa assignment','nonlinear_Yukawa_assignment',NULL,NULL,NULL,1,NULL,NULL,'The source permits the L_t form using Sigma without additional t-tilde or t-tilde-c fields. No exact light-flavor coefficient matrices or normalization beyond that assignment are supplied.');
INSERT INTO "theory_interactions" VALUES(312,'littlest-higgs-minimal',1,131,'Down-sector Yukawa assignment','nonlinear_Yukawa_assignment',NULL,NULL,NULL,1,NULL,NULL,'Use the corresponding small-Yukawa construction with Sigma replaced by Sigma*. Detailed gauge charges and contractions beyond the source assignment are not reconstructed.');
INSERT INTO "theory_interactions" VALUES(313,'littlest-higgs-minimal',1,131,'Charged-lepton Yukawa assignment','nonlinear_Yukawa_assignment',NULL,NULL,NULL,1,NULL,NULL,'Use Sigma* in the corresponding small-Yukawa construction. No neutrino-mass operator is inferred.');
INSERT INTO "theory_interactions" VALUES(314,'littlest-higgs-minimal',1,132,'Triplet-matched Higgs quartic','effective_scalar_quartic','V contains lambda(h-dagger h)^2',NULL,NULL,1,NULL,'lambda=c[(g1^2+g1''^2-(c''/c)lambda1^2)(g2^2+g2''^2)]/[g1^2+g1''^2-(c''/c)lambda1^2+g2^2+g2''^2]','Source Eq. (4.9), conditional on integrating out a massive triplet. This leading potential produces no Higgs mass term; separate logarithmic contributions do. The expression is retained as source-stated matching without resolving the normalization questions in Eqs. (3.11) and (4.8).');
INSERT INTO "theory_interactions" VALUES(315,'twin-higgs-linear-scalar-sector',1,133,'SU(4)-invariant linear scalar potential','scalar_potential','V(H)=-m² H-dagger H + lambda(H-dagger H)²',NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(316,'twin-higgs-linear-scalar-sector',1,133,'Gauge-induced interchange-even quartic','radiative_scalar_quartic','kappa(|H_A|^4+|H_B|^4)',NULL,NULL,1,NULL,'kappa of order g^4 log(Lambda/(gf))/(16pi²)','Generated correction that violates SU(4); not an independently specified tree-level addition to Eq. (1).');
INSERT INTO "theory_interactions" VALUES(317,'twin-higgs-unextended',1,134,'Intersector Higgs quartic boundary condition','scalar_portal',NULL,NULL,1,1,NULL,'Assumed SU(4)-invariant form at Lambda.','Gauge-allowed portal in the common construction. After radial removal its invariant part is constant on the Goldstone manifold; no independent additional nonlinear potential coefficient is inferred.');
INSERT INTO "theory_interactions" VALUES(318,'twin-higgs-unextended',1,134,'Hypercharge kinetic mixing','abelian_kinetic_mixing',NULL,NULL,1,1,0,NULL,'Gauge allowed and retained as a possible operator. Neglected in the initial potential calculation; absence at Lambda is an additional condition of the potentially massless-photon scenario, not a universal symmetry prohibition.');
INSERT INTO "theory_interactions" VALUES(319,'twin-higgs-unextended',1,134,'Soft twin-interchange breaking','soft_scalar_mass','V contains mu² H_A-dagger H_A',NULL,NULL,1,NULL,NULL,'Generates a mild hierarchy <h><f and contributes to both quadratic and quartic Higgs terms through the nonlinear expansion. It is not invariant under exact twin interchange.');
INSERT INTO "theory_interactions" VALUES(320,'twin-higgs-extended-top',1,135,'Extended invariant top Yukawa','Yukawa','y H Q_L T_R + h.c.',NULL,NULL,1,NULL,NULL,'SU(4) × SU(6) invariant in the source''s notation. Expanding the inherited nonlinear H supplies the Higgs couplings; this replaces the ordinary unextended top assignment.');
INSERT INTO "theory_interactions" VALUES(321,'twin-higgs-extended-top',1,135,'Twin-symmetric exotic mass','fermion_mass','M(qtilde_A^c qtilde_A + qtilde_B^c qtilde_B)',NULL,NULL,1,NULL,'Same M for the two interchange-related terms.','Only SU(4)-breaking source within the displayed top sector; soft breaking gives a source-stated finite one-loop top contribution.');
INSERT INTO "theory_interactions" VALUES(322,'fraternal-twin-higgs',1,137,'Dominant SU(4)-invariant potential','scalar_potential','V contains lambda(|A|²+|B|²−f²/2)²',NULL,NULL,1,NULL,NULL,'Includes the cross quartic 2lambda|A|²|B|²; it is not a second independent portal coefficient.');
INSERT INTO "theory_interactions" VALUES(323,'fraternal-twin-higgs',1,137,'Exchange-even SU(4)-breaking quartic','scalar_quartic','V contains kappa(|A|⁴+|B|⁴)',NULL,NULL,1,NULL,NULL,'Preserves scalar exchange but breaks SU(4).');
INSERT INTO "theory_interactions" VALUES(324,'fraternal-twin-higgs',1,137,'Gauge-allowed hard exchange breaking','scalar_quartic','V contains rho|A|⁴',NULL,1,1,NULL,'Technically small rho is neglected in the working analysis.','Allowed by gauge symmetry, not by exact exchange. Retained in the general tree-level inventory; its neglect is an approximation rather than a symmetry-enforced zero.');
INSERT INTO "theory_interactions" VALUES(325,'fraternal-twin-higgs',1,137,'Soft exchange breaking','scalar_mass','V contains sigma f²|A|²',NULL,NULL,1,NULL,'sigma<lambda in the working hierarchy; adjusted for visible vacuum misalignment.',NULL);
INSERT INTO "theory_interactions" VALUES(326,'fraternal-twin-higgs',1,137,'Twin top Yukawa assignment','Yukawa_assignment',NULL,'L contains yhat_t B Qhat_a uhat_a',NULL,1,NULL,NULL,'Schematic Eq. (2); conjugations and spinor contractions are not inferred from flattened notation.');
INSERT INTO "theory_interactions" VALUES(327,'fraternal-twin-higgs',1,137,'Twin bottom Yukawa assignment','Yukawa_assignment',NULL,'L contains yhat_b B Qhat bhat',1,1,NULL,NULL,'Schematic Eq. (9); exact conjugation convention remains unresolved.');
INSERT INTO "theory_interactions" VALUES(328,'fraternal-twin-higgs',1,137,'Twin tau Yukawa assignment','Yukawa_assignment',NULL,'L contains yhat_tau B Lhat tauhat_R',NULL,1,NULL,NULL,'Schematic Eq. (10); no unprinted conjugation convention is imposed.');
INSERT INTO "theory_interactions" VALUES(329,'fraternal-twin-higgs',1,138,'Radial-matched twin-bottom portal','effective_fermionic_portal','L5=−yhat_b(A†A)(twin-bottom scalar bilinear)/(sqrt(2) f)',NULL,NULL,1,NULL,NULL,'Leading expansion of the microscopic bottom Yukawa using the radial constraint; after electroweak breaking it gives a v/f-suppressed Higgs coupling. Not an independent ultraviolet Yukawa.');
INSERT INTO "theory_interactions" VALUES(330,'fraternal-twin-higgs',1,138,'Twin-top-induced gluonic Higgs portal','loop_generated_effective_portal','L contains −alpha_hat_3 v h Ghat^a_mu_nu Ghat_a^mu_nu/(6 pi f²)',NULL,NULL,1,NULL,NULL,'Eq. (38), obtained from (alpha_hat_3/(12 pi)) Ghat² ln(B†B/f²) and the radial constraint. Leading heavy-top and v/f expansion; h is the surviving SM-like Higgs.');
INSERT INTO "theory_interactions" VALUES(331,'six-dimensional-pati-salam-vortex',1,143,'First vortex-mass Yukawa','Yukawa','h Φ Q Qbar',NULL,NULL,1,NULL,'h of order Λ^−1; flavor-universal.','Equation (24), with suppressed spinor and gauge contractions. One localized chiral mode per pair is the source''s index-theorem claim; detailed spinor wavefunctions are not reconstructed.');
INSERT INTO "theory_interactions" VALUES(332,'six-dimensional-pati-salam-vortex',1,143,'Second vortex-mass Yukawa','Yukawa','h′ Φ* Q_c Qbar_c',NULL,NULL,1,NULL,'h′ of order Λ^−1; flavor-universal, not fixed equal to h.','Equation (24); Φ* is the conjugate of the existing scalar. This h′ is not identified with the prototype scalar-portal coefficient bearing the same label.');
INSERT INTO "theory_interactions" VALUES(333,'six-dimensional-pati-salam-vortex',1,143,'Core Higgs Yukawa','Yukawa','g H Q Q_c',NULL,NULL,1,NULL,'Ordinary flavor-dependent Yukawa coefficients; no numerical texture supplied.','Equation (25), with contractions suppressed. H condenses only in the core.');
INSERT INTO "theory_interactions" VALUES(334,'six-dimensional-pati-salam-vortex',1,143,'Partner core Higgs Yukawa','Yukawa','gbar H Qbar Qbar_c',NULL,NULL,1,NULL,'No equality or complex-conjugacy relation between gbar and g is inferred.','Equation (25); retains the schematic source notation without reconstructing spinor contractions.');
INSERT INTO "theory_interactions" VALUES(335,'rs-two-brane-warped',1,144,'Bulk Einstein and cosmological action','gravitational_action','S_gravity=integral d^4x integral_(-pi)^pi dphi sqrt(-G)[-Lambda+2M^3 R_5]','Eq. (4); full covering interval',NULL,1,NULL,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(336,'rs-two-brane-warped',1,144,'Visible brane action','boundary_matter_and_vacuum_energy','S_vis=integral d^4x sqrt(-g_vis)[L_vis-V_vis]',NULL,NULL,1,NULL,NULL,'Located at phi=pi; detailed Standard Model Lagrangian is inherited, not enumerated.');
INSERT INTO "theory_interactions" VALUES(337,'rs-two-brane-warped',1,144,'Hidden brane action','boundary_matter_and_vacuum_energy','S_hid=integral d^4x sqrt(-g_hid)[L_hid-V_hid]',NULL,NULL,1,NULL,NULL,'Located at phi=0. L_hid is left unspecified; no hidden particle inventory is inferred.');
INSERT INTO "theory_interactions" VALUES(338,'rs-two-brane-warped',1,144,'Illustrative visible Higgs action','boundary_scalar_kinetic_and_potential','S_vis contains integral d^4x sqrt(-g_vis)[g_vis^mu_nu D_mu H-dagger D_nu H-lambda(|H|^2-v_0^2)^2]',NULL,NULL,1,NULL,NULL,'A displayed component of L_vis, not an additional copy of its Higgs action. Covariant-derivative generators are not enumerated.');
INSERT INTO "theory_interactions" VALUES(339,'rs-two-brane-warped',1,145,'Reduced Einstein curvature term','effective_gravitational_action','S_eff contains integral d^4x sqrt(-gbar) 2(M^3/k)[1-exp(-2 k r_c pi)] Rbar',NULL,NULL,1,NULL,NULL,'Direct phi integration of Eq. (15), at fixed T=r_c. Preserve the source curvature normalization without importing another reduced-Planck convention.');
INSERT INTO "theory_interactions" VALUES(340,'ued-orbifold-framework',1,146,'Bulk up-quark Yukawa','Yukawa','bar(Q) lambda_hat_U U i sigma2 H* + h.c.',NULL,NULL,1,NULL,'lambda_hat_U is a 3 x 3 generation matrix with mass dimension -delta/2.',NULL);
INSERT INTO "theory_interactions" VALUES(341,'ued-orbifold-framework',1,146,'Bulk down-quark Yukawa','Yukawa','bar(Q) lambda_hat_D D H + h.c.',NULL,NULL,1,NULL,'lambda_hat_D is an independent 3 x 3 generation matrix with mass dimension -delta/2.',NULL);
INSERT INTO "theory_interactions" VALUES(342,'ued-orbifold-framework',1,146,'Bulk charged-lepton Yukawa assignment','Yukawa_assignment',NULL,NULL,NULL,1,NULL,NULL,'The source explicitly retains analogous L,E,H lepton Yukawas but does not display their normalized expression.');
INSERT INTO "theory_interactions" VALUES(343,'ued-orbifold-framework',1,146,'Bulk covariant kinetics and Higgs sector','kinetic_and_scalar_potential_collection',NULL,'Eq. (2.1): gauge field strengths, covariant fermion kinetic terms and L_Higgs',NULL,1,NULL,NULL,'L_Higgs contains the Higgs kinetic term and potential. No independently expanded potential coefficients are inferred; omitted displayed lepton kinetics are present.');
INSERT INTO "theory_interactions" VALUES(344,'holographic-su3-brane-scalar-mediator',1,151,'Bulk quark masses','fermion_mass','-MQ bar(QL) QR - MD bar(DL) DR',NULL,NULL,1,NULL,NULL,'Equation (3), with its bulk metric measure; source chiral notation retained.');
INSERT INTO "theory_interactions" VALUES(345,'holographic-su3-brane-scalar-mediator',1,151,'Infrared top Yukawa operator','boundary_Yukawa','lambda_U Sigma-dagger bar(QL) UR + h.c.',NULL,1,1,NULL,NULL,'Localized at z=L1 with delta(z-L1) sqrt(-g_ind). Physical top Yukawa follows after bulk-mode mixing and canonical normalization.');
INSERT INTO "theory_interactions" VALUES(346,'holographic-su3-brane-scalar-mediator',1,151,'Infrared bottom Yukawa operator','boundary_Yukawa','lambda_D Sigma_i bar(QL)^j DR^k epsilon_ijk + h.c.',NULL,1,1,NULL,NULL,'Localized at z=L1 with the induced metric measure; equation (4).');
INSERT INTO "theory_interactions" VALUES(347,'holographic-su3-brane-scalar-mediator',1,151,'Infrared mediator coupling','boundary_scalar_trilinear','lambda_Phi Sigma Phi-dagger Sigma + h.c.',NULL,1,1,NULL,'lambda_Phi has mass dimension 1/2.','Equation (20), localized at z=L1; symmetric-tensor contraction in source notation.');
INSERT INTO "theory_interactions" VALUES(348,'holographic-su3-brane-scalar-mediator',1,151,'Mediator bulk and boundary masses','scalar_mass_collection',NULL,NULL,NULL,1,NULL,NULL,'Bulk squared mass approximately -4k²; common infrared mass parameter m1; ultraviolet parameters m0,S, m0,D and m0,T for the SU(2)L singlet, doublet and triplet. No unextracted delta-function sign or Robin-condition normalization is supplied.');
INSERT INTO "theory_interactions" VALUES(349,'holographic-boundary-pgb-framework',1,152,'Absent basic tree-level A5 potential','excluded_local_scalar_potential','V_tree(A5)',NULL,0,0,0,NULL,'Absence in the basic gauge theory follows from gauge invariance. This does not exclude a radiative nonlocal Wilson-line potential or added mediator mechanisms.');
INSERT INTO "theory_interactions" VALUES(350,'holographic-boundary-pgb-framework',1,154,'Gauge-origin A5 fermion coupling','gauge_origin_Yukawa',NULL,NULL,NULL,1,NULL,NULL,'A5 enters the covariant derivative D_M=partial_M+(1/8)omega_MAB[Gamma^A,Gamma^B]-iA_M. The distorted kinetic expression (37) and an independently normalized component vertex are not reconstructed.');
INSERT INTO "theory_interactions" VALUES(351,'hidden-valley-framework',1,155,'Heavy mediator portals','effective_operator_class',NULL,NULL,NULL,1,NULL,NULL,'Higher-dimension interactions connect SM and hidden fields; suggested origins are Z′ exchange or loops of jointly charged heavy matter. No unique mediator is selected.');
INSERT INTO "theory_interactions" VALUES(352,'hidden-valley-chi-two-flavor',1,156,'U-flavor scalar mass-generating assignment','Yukawa_assignment',NULL,NULL,NULL,1,NULL,NULL,'U and Ubar become massive by coupling to φ. Exact conjugations, contractions and coefficient normalization are not reconstructed from the prose.');
INSERT INTO "theory_interactions" VALUES(353,'hidden-valley-chi-two-flavor',1,156,'C-flavor scalar mass-generating assignment','Yukawa_assignment',NULL,NULL,NULL,1,NULL,NULL,'C and Cbar become massive through the φ sector. The scalar''s conjugation must be distinguished from the U assignment; no unprinted operator formula is imposed.');
