INSERT INTO "theory_interactions" VALUES(355,'hidden-valley-chi-two-flavor',1,156,'Hypercharge–χ kinetic mixing','abelian_kinetic_mixing','(1/2) k F′μν FYμν',NULL,1,1,0,NULL,'k is free; k=0 is a numerical example, not a defining absence.');
INSERT INTO "theory_interactions" VALUES(356,'hidden-valley-chi-two-flavor',1,156,'Higgs–breaking-scalar portal','scalar_portal','|H|²|φ|²',NULL,1,1,0,NULL,'Retained with unspecified coefficient, which may vanish at a parameter point. Nonzero mixing enables Higgs-mediated hidden production; the full potential is not supplied.');
INSERT INTO "theory_interactions" VALUES(357,'hidden-valley-chi-two-flavor',1,156,'Excluded Dirac neutrino masses','excluded_Yukawa_assignment',NULL,NULL,0,0,NULL,NULL,'Forbidden by the imposed baseline Z2, rather than zeroed solely for numerical convenience. Exact field transformation table is unspecified.');
INSERT INTO "theory_interactions" VALUES(358,'hidden-valley-colored-x-framework',1,161,'Displayed dimension-eight gluonic portal','loop_induced_effective_operator','O8 = tr G² tr Gv²',NULL,NULL,1,NULL,NULL,'One member of an induced operator set. The source attributes decay of all glueball states to the set, not to this scalar contraction alone. Wilson coefficient and other contractions remain unspecified.');
INSERT INTO "theory_interactions" VALUES(359,'secluded-dirac-u1-higgsed',1,166,'Hypercharge kinetic mixing','abelian_kinetic_mixing','L contains −(κ/2)VμνBμν',NULL,NULL,1,0,NULL,'κ may vanish in regime 167. Eq. (3) writes the portal as κVν∂μBμν.');
INSERT INTO "theory_interactions" VALUES(360,'secluded-dirac-u1-higgsed',1,166,'Dirac gauge kinetics and mass','gauge_kinetic_and_mass','ψbar(iDμγμ−mψ)ψ; Dμ=∂μ+ie''Vμ',NULL,NULL,1,NULL,NULL,'Displayed vector coupling; no Yukawa mass generation for ψ is inferred.');
INSERT INTO "theory_interactions" VALUES(361,'secluded-dirac-u1-higgsed',1,166,'Unspecified breaking-scalar potential','scalar_potential','L contains −U(φφ*)',NULL,NULL,1,NULL,NULL,'No polynomial coefficients or Higgs portal completion are supplied. Charged scalar covariant interactions are specified through Dμ; its printed kinetic sign is left unresolved.');
