INSERT INTO "theory_interactions" VALUES(363,'secluded-fermion-scalar-portal',1,168,'Linear Higgs portal','scalar_portal','L contains −λ1 v φ(H†H−v²/2)',NULL,NULL,1,NULL,NULL,'In the chosen broken-phase expansion the mixing term is −λ1 v² φh.');
INSERT INTO "theory_interactions" VALUES(364,'secluded-fermion-scalar-portal',1,168,'Quadratic Higgs portal','scalar_portal','L contains −λ2 φ²(H†H−v²/2)',NULL,1,1,0,'λ2→0 is the illustrative analysis limit; the displayed general operator is retained.',NULL);
INSERT INTO "theory_interactions" VALUES(365,'secluded-fermion-scalar-portal',1,168,'Displayed masses and unspecified scalar self-potential','mass_and_scalar_potential','L contains −mψ ψbar ψ −mφ²φ²/2 −V(φ)',NULL,NULL,1,NULL,NULL,'No explicit polynomial V(φ) or complete vacuum-stability conditions are supplied.');
INSERT INTO "theory_interactions" VALUES(366,'secluded-neutrino-portal-z2',1,169,'Lepton–Higgs–neutrino Yukawa assignment','Yukawa_assignment',NULL,'−Yν Lbar H NR; h.c. indicated in Eq. (19)',NULL,1,NULL,NULL,'Retain the field assignment. Exact Higgs conjugation, spinor contractions and h.c. placement are not repaired.');
INSERT INTO "theory_interactions" VALUES(367,'secluded-neutrino-portal-z2',1,169,'Dark scalar–fermion–neutrino Yukawa assignment','Yukawa_assignment',NULL,'−YN'' S NR^T N''; h.c. indicated in Eq. (19)',NULL,1,NULL,NULL,'Spinor contraction remains schematic. The vertex respects joint odd parity.');
INSERT INTO "theory_interactions" VALUES(368,'secluded-neutrino-portal-z2',1,169,'Even scalar Higgs portal','scalar_portal','L contains −(λ/2)S²H†H',NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(369,'secluded-neutrino-portal-z2',1,169,'Displayed Majorana-type and scalar masses','mass_operator_collection',NULL,'−(mN''/2)N''^T N'' −(mNR/2)NR^T NR −(mS²/2)S²',NULL,1,NULL,NULL,'Source schematic spinor notation; no unsupplied contraction or flavor multiplicity is imposed.');
INSERT INTO "theory_interactions" VALUES(370,'simp-sp-pions',1,172,'Flavor-preserving quark mass','fermion_mass','Lmass=-(1/2)Mij qi qj+c.c.',NULL,NULL,1,NULL,'Mij=mQ Jij; J=i sigma2 tensor 1_Nf.',NULL);
INSERT INTO "theory_interactions" VALUES(371,'simp-sp-pions',1,173,'Leading non-WZW pion terms','chiral_kinetic_mass_and_four_pion','(1/4)Tr(partial_mu pi partial^mu pi)-(mpi^2/4)Tr(pi^2)+mpi^2 Tr(pi^4)/(12fpi^2)-Tr(pi^2 partial^mu pi partial_mu pi-pi partial^mu pi pi partial_mu pi)/(6fpi^2)',NULL,NULL,1,NULL,NULL,'Displayed leading expansion; omitted higher-order operators are not declared forbidden or exactly zero.');
INSERT INTO "theory_interactions" VALUES(372,'simp-sp-pions',1,173,'Leading five-pion WZW interaction','anomalous_chiral_interaction','2Nc epsilon^{mu nu rho sigma} Tr(pi partial_mu pi partial_nu pi partial_rho pi partial_sigma pi)/(15pi^2 fpi^5)',NULL,NULL,1,NULL,NULL,'Eq. (8), conditional on the stated coset and Nf>=2. Generates 3 to 2 number changing.');
INSERT INTO "theory_interactions" VALUES(373,'simp-su-pions',1,175,'Leading non-WZW pion terms','chiral_kinetic_mass_and_four_pion','(1/4)Tr(partial_mu pi partial^mu pi)-(mpi^2/4)Tr(pi^2)+mpi^2 Tr(pi^4)/(12fpi^2)-Tr(pi^2 partial^mu pi partial_mu pi-pi partial^mu pi pi partial_mu pi)/(6fpi^2)',NULL,NULL,1,NULL,NULL,'Source retains Eq. (12) after J is replaced by the identity and the condensate is interpreted as q qbar. The sign convention of the microscopic mass matching is not independently repaired.');
INSERT INTO "theory_interactions" VALUES(374,'simp-su-pions',1,175,'Leading five-pion WZW interaction','anomalous_chiral_interaction','2Nc epsilon^{mu nu rho sigma} Tr(pi partial_mu pi partial_nu pi partial_rho pi partial_sigma pi)/(15pi^2 fpi^5)',NULL,NULL,1,NULL,NULL,'Source extends Eq. (8) to this coset for Nf>=3.');
INSERT INTO "theory_interactions" VALUES(375,'simp-o-pions',1,177,'Leading non-WZW pion terms','chiral_kinetic_mass_and_four_pion','(1/4)Tr(partial_mu pi partial^mu pi)-(mpi^2/4)Tr(pi^2)+mpi^2 Tr(pi^4)/(12fpi^2)-Tr(pi^2 partial^mu pi partial_mu pi-pi partial^mu pi pi partial_mu pi)/(6fpi^2)',NULL,NULL,1,NULL,NULL,'Source retains Eq. (12) under its J-to-identity prescription. No microscopic spinor convention is inferred.');
INSERT INTO "theory_interactions" VALUES(376,'simp-o-pions',1,177,'Leading five-pion WZW interaction','anomalous_chiral_interaction','2Nc epsilon^{mu nu rho sigma} Tr(pi partial_mu pi partial_nu pi partial_rho pi partial_sigma pi)/(15pi^2 fpi^5)',NULL,NULL,1,NULL,NULL,'Source extends Eq. (8) to this coset with the stated Nf>=3 threshold. Homotopy details are retained as source claims.');
INSERT INTO "theory_interactions" VALUES(377,'vector-higgs-portal-z2-eft',1,178,'Vector mass','mass','L contains (m²/2) X_mu X^mu',NULL,1,1,NULL,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(378,'vector-higgs-portal-z2-eft',1,178,'Vector Higgs portal','vector_Higgs_portal','L contains (lambda_hv/4) H†H X_mu X^mu',NULL,1,1,NULL,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(379,'vector-higgs-portal-z2-eft',1,178,'Allowed vector quartic','vector_self_interaction','L contains (lambda/4)(X_mu X^mu)²',NULL,1,1,0,NULL,'Retained in the general displayed EFT; lambda=0 is imposed only for regime 182.');
INSERT INTO "theory_interactions" VALUES(380,'vector-higgs-portal-z2-eft',1,178,'Excluded linear-vector portals','excluded_portal_operators','xi1 H† iD_mu H X^mu + xi2 H†H i partial_mu X^mu + h.c.',NULL,0,0,0,'xi1=xi2=0 in the selected vector-parity sector; D_mu is the SM covariant derivative.',NULL);
INSERT INTO "theory_interactions" VALUES(381,'vector-portal-stueckelberg-higgs',1,179,'Direct Higgs-dependent Stückelberg action','gauge_kinetic_and_field_dependent_mass','L contains -F_mu_nu F^mu_nu/4 + (mu²/2)(1+zeta H†H/M²)(X''_mu+partial_mu phi/mu)(X''^mu+partial^mu phi/mu)',NULL,NULL,1,NULL,NULL,'Algebraic substitution of Eqs. (4) and (6) into Eq. (3). The resulting Higgs-vector portal is part of this term, not an additional independent interaction.');
INSERT INTO "theory_interactions" VALUES(382,'vector-portal-stueckelberg-scalar',1,180,'Scalar-dependent Stückelberg action','gauge_kinetic_and_field_dependent_mass','L contains -F_mu_nu F^mu_nu/4 + mu² S² (X''_mu+partial_mu phi/mu)(X''^mu+partial^mu phi/mu)/(2M²)',NULL,NULL,1,NULL,NULL,'Eq. (8) inserted into the shared Stückelberg action. S remains an independent retained scalar.');
INSERT INTO "theory_interactions" VALUES(383,'vector-portal-stueckelberg-scalar',1,180,'Scalar mediator portal and potential','scalar_portal_and_potential','L contains (lambda_hs/4)H†H S² - V(S)',NULL,NULL,1,NULL,NULL,'The potential is symbolic; no polynomial coefficients or minimum conditions are inferred.');
INSERT INTO "theory_interactions" VALUES(384,'vector-portal-abelian-higgs',1,181,'Displayed hidden Abelian Higgs action','gauge_scalar_kinetic_portal_and_potential','L_hidden = -F_mu_nu F^mu_nu/4 + (D_mu S)*D^mu S - V(S) + (lambda_hs/4)H†H S*S',NULL,NULL,1,NULL,NULL,'Eq. (14); numerical charge and explicit V(S) are unspecified. The vector mass and its hidden-Higgs couplings arise from covariant scalar kinetics.');
INSERT INTO "theory_interactions" VALUES(385,'silh-hww-operator-sector',1,183,'cH Higgs derivative operator','dimension_six_operator','L contains cH/(2 f²) ∂^μ(H†H) ∂_μ(H†H)','Eq. (5.1)',NULL,1,0,NULL,'One selected non-SM contribution; not a complete scalar or SILH operator basis.');
INSERT INTO "theory_interactions" VALUES(386,'silh-hww-operator-sector',1,183,'cW Higgs-current weak-field operator','dimension_six_operator','L contains i cW g/(2 gρ² f²) (H† σ^i ↔D^μ H)(D^ν W_μν)^i','Eq. (5.1)',NULL,1,0,NULL,'Retain the printed bidirectional derivative; its detailed sign convention is not independently defined in the supplied passage.');
INSERT INTO "theory_interactions" VALUES(387,'silh-hww-operator-sector',1,183,'cHW Higgs-derivative weak-field operator','dimension_six_operator','L contains i cHW g/(16 π² f²) (D^μ H)† σ^i (D^ν H) W_μν^i','Eq. (5.1)',NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(388,'smeft-d6-b-conserving',1,184,'Complete bosonic dimension-six inventory','dimension_six_operator_collection',NULL,'X^3: QG,QGtilde,QW,QWtilde; X^2 phi^2: QphiG,QphiGtilde,QphiW,QphiWtilde,QphiB,QphiBtilde,QphiWB,QphiWtildeB; phi^6: Qphi; phi^4 D^2: QphiBox,QphiD',1,1,0,NULL,'Fifteen separate basis elements with independent Wilson coefficients, not one summed operator with a shared coefficient. Dual tensors use the Section 2 definition. All bosonic entries are Hermitian. This inventory row does not claim individual expressions have all been transcribed.');
INSERT INTO "theory_interactions" VALUES(389,'smeft-d6-b-conserving',1,184,'Two-fermion dimension-six inventory other than separately recorded Qu_phi','dimension_six_operator_collection',NULL,'psi^2 phi^3: Qephi,Qdphi; psi^2 X phi: QeW,QeB,QuG,QuW,QuB,QdG,QdW,QdB; psi^2 phi^2 D: Qphil^(1),Qphil^(3),Qphie,Qphiq^(1),Qphiq^(3),Qphiu,Qphid,Qphiud',1,1,0,NULL,'Eighteen separate operator types; Qu_phi below completes the nineteen-entry sector. General generation labels and required Hermitian conjugates are understood. This is an inventory, not a complete explicit tensor transcription. The page-5 D^2 class-label typo is resolved by Table 2 and Section 6.');
INSERT INTO "theory_interactions" VALUES(390,'smeft-d6-b-conserving',1,184,'Qu_phi','dimension_six_Yukawa_like','(phi†phi)(bar(q_p) u_r phi_tilde)',NULL,1,1,0,'General generation coefficient C_u_phi^(pr)/Lambda^2; independent Hermitian conjugate included.','This is the separately transcribed member of the nineteen-entry two-fermion inventory, not an extra twentieth operator.');
INSERT INTO "theory_interactions" VALUES(391,'smeft-d6-b-conserving',1,184,'Complete baryon-conserving four-fermion dimension-six inventory','dimension_six_operator_collection',NULL,'Qll,Qqq^(1),Qqq^(3),Qlq^(1),Qlq^(3); Qee,Quu,Qdd,Qeu,Qed,Qud^(1),Qud^(8); Qle,Qlu,Qld,Qqe,Qqu^(1),Qqu^(8),Qqd^(1),Qqd^(8); Qledq,Qquqd^(1),Qquqd^(8),Qlequ^(1),Qlequ^(3)',1,1,0,NULL,'Twenty-five separate operator types with general flavor labels. Their coefficients are not equated. Fierz identities and gauge-generator identities remove redundant contractions. Hermitian conjugates are supplied as required; the count is not a count of generation-resolved coefficients.');
INSERT INTO "theory_interactions" VALUES(392,'smeft-d6-b-conserving',1,184,'Qnu_nu','dimension_five_neutrino_operator','epsilon_jk epsilon_mn phi^j phi^m (l_p^k)^T C l_r^n','Eq. (3.1)',1,1,0,'Coefficient C_nu_nu^(pr)/Lambda with flavor assignments and Hermitian conjugation understood.','Unique dimension-five operator type for this field content. Violates lepton number. The source describes neutrino masses after electroweak breaking but does not analyze a vacuum.');
INSERT INTO "theory_interactions" VALUES(393,'smeft-d6-b-violating',1,185,'Qduq','dimension_six_baryon_violating_four_fermion','epsilon_alpha_beta_gamma epsilon_jk [(d_p^alpha)^T C u_r^beta][(q_s^(gamma j))^T C l_t^k]','Table 3 lower-right block',1,1,0,'General generation labels p,r,s,t and coefficient divided by Lambda^2; add Hermitian conjugate.',NULL);
INSERT INTO "theory_interactions" VALUES(394,'smeft-d6-b-violating',1,185,'Qqqu','dimension_six_baryon_violating_four_fermion','epsilon_alpha_beta_gamma epsilon_jk [(q_p^(alpha j))^T C q_r^(beta k)][(u_s^gamma)^T C e_t]','Table 3 lower-right block',1,1,0,'General generation labels p,r,s,t and coefficient divided by Lambda^2; add Hermitian conjugate.',NULL);
INSERT INTO "theory_interactions" VALUES(395,'smeft-d6-b-violating',1,185,'Qqqq','dimension_six_baryon_violating_four_fermion','epsilon_alpha_beta_gamma epsilon_jn epsilon_km [(q_p^(alpha j))^T C q_r^(beta k)][(q_s^(gamma m))^T C l_t^n]','Table 3 lower-right block',1,1,0,'General generation labels p,r,s,t and coefficient divided by Lambda^2; add Hermitian conjugate.','No flavor-diagonal zero is imposed. The source''s associated statement depends on an external identity and requires checking the precise contraction and meaning of flavor-diagonal.');
INSERT INTO "theory_interactions" VALUES(396,'smeft-d6-b-violating',1,185,'Qduu','dimension_six_baryon_violating_four_fermion','epsilon_alpha_beta_gamma [(d_p^alpha)^T C u_r^beta][(u_s^gamma)^T C e_t]','Table 3 lower-right block',1,1,0,'General generation labels p,r,s,t and coefficient divided by Lambda^2; add Hermitian conjugate.',NULL);
INSERT INTO "theory_interactions" VALUES(397,'real-singlet-linear-portal-gluon-sector',1,188,'Canonical singlet quadratic action','kinetic_and_mass','L contains sum_r [(partial_mu S_r)(partial^mu S_r)-M_Sr^2 S_r^2]/2',NULL,NULL,1,NULL,NULL,'Source real-scalar normalization and diagonal matching basis.');
INSERT INTO "theory_interactions" VALUES(398,'real-singlet-linear-portal-gluon-sector',1,188,'Linear Higgs portal','scalar_portal','-L contains (kappa_S)_r S_r phi†phi',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(399,'real-singlet-linear-portal-gluon-sector',1,188,'Quadratic Higgs portal','scalar_portal','-L contains (lambda_S)_rs S_r S_s phi†phi',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(400,'real-singlet-linear-portal-gluon-sector',1,188,'Singlet cubic','scalar_self_interaction','-L contains (kappa_S3)_rst S_r S_s S_t',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(401,'real-singlet-linear-portal-gluon-sector',1,188,'Dimension-five singlet gluonic interaction','dimension_five_operator','-L contains (ktilde_S^G)_r S_r G_mu_nu^A G^{A mu nu}/f',NULL,1,1,0,'ktilde is dimensionless; f parameterizes the nonrenormalizable coefficient. No numerical value selected.',NULL);
INSERT INTO "theory_interactions" VALUES(402,'scalar-zeta-ql-qq-sector',1,190,'ζ leptoquark Yukawa','Yukawa','-L contains (y_zeta^ql)_ij zeta^{a†} overline(q_Li^c) i sigma2 sigma^a l_Lj + h.c.',NULL,NULL,1,0,NULL,'Single-multiplet restriction of Eq. (A.7); color contraction implicit.');
INSERT INTO "theory_interactions" VALUES(403,'scalar-zeta-ql-qq-sector',1,190,'ζ diquark Yukawa','Yukawa','-L contains (y_zeta^qq)_ij zeta^{aA†} epsilon_ABC bar(q_Li^B) sigma^a i sigma2 q_Lj^{cC} + h.c.',NULL,NULL,1,0,NULL,'No imposed baryon-conservation restriction. Flavor-tensor symmetry and conversion to another leptoquark convention are not independently canonicalized.');
INSERT INTO "theory_interactions" VALUES(404,'heavy-weak-triplet-proca-current-sector',1,191,'Covariant Proca quadratic action','gauge_kinetic_and_mass','L contains [(D_mu W_nu^a)(D^nu W^{a mu})-(D_mu W_nu^a)(D^mu W^{a nu})+M_W^2 W_mu^a W^{a mu}]/2',NULL,NULL,1,NULL,NULL,'Eq. (A.17) with eta_W=1/2; D is covariant only under the SM group.');
INSERT INTO "theory_interactions" VALUES(405,'heavy-weak-triplet-proca-current-sector',1,191,'Left-handed lepton current','vector_fermion_current','-L contains (g_W^l)_ij W^{mu a} bar(l_Li) sigma^a gamma_mu l_Lj/2',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(406,'heavy-weak-triplet-proca-current-sector',1,191,'Left-handed quark current','vector_fermion_current','-L contains (g_W^q)_ij W^{mu a} bar(q_Li) sigma^a gamma_mu q_Lj/2',NULL,NULL,1,0,NULL,NULL);
INSERT INTO "theory_interactions" VALUES(407,'heavy-weak-triplet-proca-current-sector',1,191,'Higgs current','vector_scalar_current','-L contains [(g_W^phi) W^{mu a} phi† sigma^a i D_mu phi/2 + h.c.]',NULL,NULL,1,0,NULL,'Retain the source complex coefficient and Hermitian conjugate; no real-coupling restriction is imposed.');
INSERT INTO "theory_parameters" VALUES(1,'real-singlet-z2',1,2,'m_0','Independent singlet quadratic parameter before electroweak symmetry breaking; not generally the physical singlet mass','L ⊃ −m_0²S²/2','Do not impose m_0² ≥ 0; the source considers negative quadratic coefficients.','specified');
INSERT INTO "theory_parameters" VALUES(2,'real-singlet-z2',1,3,'lambda_S','Independent dimensionless singlet self-coupling','L ⊃ −lambda_S S⁴/4',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(3,'real-singlet-z2',1,4,'lambda','Independent dimensionless singlet-Higgs coupling','L ⊃ −lambda S²H†H; no extra factor of 1/2',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(4,'real-singlet-z2',1,NULL,'m_S','Derived physical singlet mass in the chosen vacuum','m_S² = m_0² + lambda v_EW²','m_S² > 0 in the chosen local minimum. The preferred few-to-few-hundred-GeV range is an analysis choice.','specified');
INSERT INTO "theory_parameters" VALUES(5,'real-singlet-z2',1,NULL,'v_EW','Inherited electroweak vacuum parameter; source value 246 GeV','Unshifted sqrt(2) H† = (h,0), with h_ext² = v_EW²',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(6,'complex-singlet-portal',1,7,'mu_S²','Common quadratic coefficient of the two real components before electroweak symmetry breaking','V ⊃ mu_S²|S|²',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(7,'complex-singlet-portal',1,8,'lambda_hS','Common Higgs portal coefficient for the two real components','V ⊃ lambda_hS|S|²|H|²; each canonical real component has portal coefficient lambda_hS/2',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(8,'thdm-type-i-real-z2',1,NULL,'tan β','Ratio v2/v1 in the Chapter 2 symmetry basis','v = √(v1² + v2²); v1 = v cos β; v2 = v sin β','No benchmark value imposed; the ratio requires v1 ≠ 0 and endpoint cases require separate limiting treatment.','specified');
INSERT INTO "theory_parameters" VALUES(9,'thdm-type-ii-real-z2',1,NULL,'tan β','Ratio v2/v1 in the Chapter 2 symmetry basis','v = √(v1² + v2²); v1 = v cos β; v2 = v sin β','No benchmark value imposed; the ratio requires v1 ≠ 0 and endpoint cases require separate limiting treatment.','specified');
INSERT INTO "theory_parameters" VALUES(10,'thdm-type-i-real-z2',1,14,'m12²','Quadratic scalar mixing coefficient permitting soft Z2 breaking','V ⊃ −m12²(Φ1†Φ2 + Φ2†Φ1)','Real; may vanish. No positivity restriction follows from the superscript notation.','specified');
INSERT INTO "theory_parameters" VALUES(11,'thdm-type-ii-real-z2',1,20,'m12²','Quadratic scalar mixing coefficient permitting soft Z2 breaking','V ⊃ −m12²(Φ1†Φ2 + Φ2†Φ1)','Real; may vanish. No positivity restriction follows from the superscript notation.','specified');
INSERT INTO "theory_parameters" VALUES(12,'lr-triplet-parity',1,NULL,'g','Common SU(2) gauge coupling gL = gR','Source writes MW² = g²(v1²+v2²) and gY⁻² = g⁻² + gB−L⁻²; gY and gB−L couple to Y/2 and (B−L)/2. Retained as source conventions pending the normalization question.',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(13,'lr-triplet-parity',1,NULL,'x','Bidoublet VEV ratio v2/v1','Section 2 and Appendix A convention; s = v2/v, c = v1/v','0 < x < 1 in the analysis; not a separate structural identity. Page 18 reverses the ratio in a later sentence.','specified');
INSERT INTO "theory_parameters" VALUES(14,'lr-triplet-charge-conjugation',1,NULL,'g','Common SU(2) gauge coupling gL = gR','Source writes MW² = g²(v1²+v2²) and gY⁻² = g⁻² + gB−L⁻²; gY and gB−L couple to Y/2 and (B−L)/2. Retained as source conventions pending the normalization question.',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(15,'lr-triplet-charge-conjugation',1,NULL,'x','Bidoublet VEV ratio v2/v1','Section 2 convention; s = v2/v, c = v1/v','0 < x < 1 in the analysis; not a separate structural identity. Page 18 reverses the ratio in a later sentence.','specified');
INSERT INTO "theory_parameters" VALUES(16,'nmssm-general-rpc-cpc',1,27,'μ','Explicit supersymmetric Higgs mass before choosing the singlet origin',NULL,'For λ ≠ 0 the source uses s → s − μ/λ and compensating dimensionful-parameter redefinitions to choose μ = 0. This is not the Z3 restriction and does not imply m3² = 0.','specified');
INSERT INTO "theory_parameters" VALUES(17,'nmssm-general-rpc-cpc',1,NULL,'μeff','λs in the subsequently adopted μ = 0 coordinates','s = ⟨S⟩ is a scalar expectation value. Before that coordinate choice the doublet supersymmetric mass involves μ + λs.',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(18,'nmssm-general-rpc-cpc',1,NULL,'tanβ','vu/vd','v² = vu² + vd² ≃ (174 GeV)²; MZ² = (g1² + g2²)v²/2','Positive in the source convention.','specified');
INSERT INTO "theory_parameters" VALUES(19,'nmssm-z3-rpc-cpc',1,NULL,'μeff','Effective supersymmetric mass generated by the singlet scalar expectation value','μeff = λs; s = ⟨S⟩',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(20,'nmssm-z3-rpc-cpc',1,NULL,'tanβ','vu/vd','v² = vu² + vd² ≃ (174 GeV)²; MZ² = (g1² + g2²)v²/2','Positive in the source convention.','specified');
INSERT INTO "theory_parameters" VALUES(21,'mchm-spinorial',1,NULL,'ϵ','Vacuum misalignment parameter','ϵ=sin(⟨h⟩/fπ); v=ϵfπ=246 GeV','0≤ϵ≤1 in the source parameterization; no phenomenological benchmark is imposed.','specified');
INSERT INTO "theory_parameters" VALUES(22,'mchm-spinorial',1,NULL,'ci','Dimensionless bulk fermion masses','M5i=ci k','For the principal source choices, light fermions use cq>1/2 and cu,d<−1/2; top mixing uses cq≃1/2 and |cu|<1/2. These are flavor regimes, not additional identities.','specified');
INSERT INTO "theory_parameters" VALUES(23,'mchm-spinorial',1,NULL,'N','Large-N parameter identified with the 5D perturbative expansion','1/N≡g5²k/(16π²)','5D NDA requires g5²k/(24π²)≪1. The approximate 1≪N≲10 range depends on the source''s weak-coupling matching and brane terms.','specified');
INSERT INTO "theory_parameters" VALUES(24,'mchm-spinorial-scalar14',1,NULL,'MΦ²','Bulk mass squared of the added scalar','MΦ²=−4k²',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(25,'georgi-machacek-general',1,60,'M1','Dimensionful doublet–triplet cubic coefficient','V ⊃ −M1Tr(Φ†τaΦτb)(UXU†)ab','Real; no compulsory nonzero value.','specified');
INSERT INTO "theory_parameters" VALUES(26,'georgi-machacek-general',1,61,'M2','Dimensionful triplet cubic coefficient','V ⊃ −M2Tr(X†taXtb)(UXU†)ab','Real; no compulsory nonzero value.','specified');
INSERT INTO "theory_parameters" VALUES(27,'georgi-machacek-general',1,58,'μ2², μ3²','Quadratic scalar coefficients','V2=(μ2²/2)Tr(Φ†Φ)+(μ3²/2)Tr(X†X)','Real. Large positive μ3² is a decoupling choice, not a defining restriction of the general potential.','specified');
INSERT INTO "theory_parameters" VALUES(28,'georgi-machacek-general',1,59,'λ1,…,λ5','Five quartic scalar coefficients','Exactly the trace-operator normalization and minus sign on λ5 in Eq. (5).','Real; stability selections are recorded separately.','specified');
INSERT INTO "theory_parameters" VALUES(29,'georgi-machacek-general',1,NULL,'vφ, vχ, v','Aligned doublet and triplet vevs and electroweak scale','⟨Φ⟩=(vφ/√2)I2; ⟨X⟩=vχI3; vφ²+8vχ²=v²=4MW²/g²≈(246 GeV)².',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(30,'georgi-machacek-general',1,NULL,'α','Custodial-singlet mixing angle','H1⁰=φ0,r; H1⁰′=ξ0/√3+√(2/3)χ0,r; h=cosα H1⁰−sinα H1⁰′; H=sinα H1⁰+cosα H1⁰′; mh<mH.',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(31,'threedm-d6',1,64,'ψ1, ψ2, ψ3','Phases of the three coefficients in V_Z3','ψi=arg λi only for nonzero λi; equalities follow equations (26) and (30) in the source phase convention.','With all three coefficients nonzero, the generic CP-conserving locus satisfies 2(ψ1+ψ2+ψ3)=0; failure of this condition gives the generic explicitly CP-violating branch. λ3=0 has automatic CP and no defined ψ3. Neither locus selects a vacuum.','specified');
INSERT INTO "theory_parameters" VALUES(32,'threedm-d8',1,66,'ψ1, ψ2','Phases of the two coefficients in V_Z4','ψi=arg λi for nonzero λi; δ=ψ2/2 and 6γ=2ψ1 choose compatible unitary and generalized-CP generators.','These generator choices do not impose an additional relation between independent coefficient phases or magnitudes. Zero-coefficient enhanced-symmetry loci require separate treatment.','specified');
INSERT INTO "theory_parameters" VALUES(33,'sm-octet-doublet-mfv',1,67,'η_U','Overall coefficient multiplying the Standard Model up-type Yukawa matrix in the octet interaction',NULL,'Complex constant; no benchmark value imposed.','specified');
INSERT INTO "theory_parameters" VALUES(34,'sm-octet-doublet-mfv',1,68,'η_D','Overall coefficient multiplying the Standard Model down-type Yukawa matrix in the octet interaction',NULL,'Complex constant; no benchmark value imposed.','specified');
INSERT INTO "theory_parameters" VALUES(35,'sm-octet-doublet-mfv',1,72,'λ3','Coefficient of the two-Higgs two-octet operator and its hermitian conjugate',NULL,'Chosen real by a phase rotation of S. Phases of η_U, η_D, λ4 and λ5 can still provide additional CP violation.','specified');
INSERT INTO "theory_parameters" VALUES(36,'sm-octet-doublet-mfv',1,NULL,'m²_{S±}, m²_{S_R^0}, m²_{S_I^0}','Tree-level octet component masses after electroweak breaking','m²_{S±}=m_S²+λ1v²/4; m²_{S_R^0}=m_S²+(λ1+λ2+2λ3)v²/4; m²_{S_I^0}=m_S²+(λ1+λ2−2λ3)v²/4.','λ3 real convention. These are derived masses, not additional independent parameters or a selected mass ordering.','specified');
INSERT INTO "theory_parameters" VALUES(37,'vlq-t-singlet',1,NULL,'θL, θR','Up-sector mixing angles','Eq. (2) rotation; tan θR=(mt/mT)tan θL','One independent angle; no fit value imposed.','specified');
INSERT INTO "theory_parameters" VALUES(38,'vlq-b-singlet',1,NULL,'θL, θR','Down-sector mixing angles','Eq. (3) rotation; tan θR=(mb/mB)tan θL','One independent angle; no fit value imposed.','specified');
INSERT INTO "theory_parameters" VALUES(39,'vlq-xt-doublet',1,NULL,'θR, θL','Up-sector mixing angles','Eq. (2) rotation; tan θL=(mt/mT)tan θR','One independent angle; no fit value imposed.','specified');
INSERT INTO "theory_parameters" VALUES(40,'vlq-tb-doublet',1,NULL,'θR^u, θR^d, θL^u, θL^d','Up/down mixing angles','tan θL^u=(mt/mT)tan θR^u; tan θL^d=(mb/mB)tan θR^d','Two independent right-handed angles. Neither sector''s mixing is universally set to zero.','specified');
INSERT INTO "theory_parameters" VALUES(41,'vlq-by-doublet',1,NULL,'θR, θL','Down-sector mixing angles','Eq. (3) rotation; tan θL=(mb/mB)tan θR','One independent angle; neither bottom-asymmetry fit value is defining.','specified');
INSERT INTO "theory_parameters" VALUES(42,'vlq-xtb-triplet',1,NULL,'θL^u, θL^d, θR^u, θR^d','Correlated up/down mixing angles','tan θR^u=(mt/mT)tan θL^u; tan θR^d=(mb/mB)tan θL^d','One independent angle; sin(2θL^d)=sqrt(2)(mT²-mt²)/(mB²-mb²) sin(2θL^u), in the source convention and where the ratio is defined.','specified');
INSERT INTO "theory_parameters" VALUES(43,'vlq-tby-triplet',1,NULL,'θL^u, θL^d, θR^u, θR^d','Correlated up/down mixing angles','tan θR^u=(mt/mT)tan θL^u; tan θR^d=(mb/mB)tan θL^d','One independent angle; sin(2θL^d)=(mT²-mt²)/(sqrt(2)(mB²-mb²)) sin(2θL^u), in the source convention and where the ratio is defined.','specified');
INSERT INTO "theory_parameters" VALUES(44,'su5-gg-scalar15',1,NULL,'y; ytilde2RL','Unified neutrino-mass and Rtilde2 Yukawa matrices','ytilde2RL is proportional to y; multiplicative normalization is unspecified.','y is symmetric, hence the stated unified-basis ytilde2RL is symmetric. No unrestricted mass-basis symmetry is inferred.','specified');
INSERT INTO "theory_parameters" VALUES(45,'mdm-majorana-quintuplet',1,111,'M','Common tree-level multiplet mass','Equation (1), with Majorana prefactor c=1/2','Free structural parameter. The quoted 4.4 ± 0.1 TeV value assumes one thermal multiplet saturating dark matter in the paper''s perturbative calculation; footnote 5 warns of substantial nonperturbative corrections.','specified');
INSERT INTO "theory_parameters" VALUES(46,'mdm-real-septuplet-displayed',1,112,'M','Common tree-level multiplet mass in the minimal starting Lagrangian','Equation (1), with real-scalar prefactor c=1/2','Free structural parameter. The quoted 8.5 ± 0.2 TeV value assumes one thermal multiplet, negligible portal annihilation and perturbative coannihilation; it is not a universal mass or a corrected nonperturbative result.','specified');
INSERT INTO "theory_parameters" VALUES(47,'mdm-real-septuplet-displayed',1,113,'lambda''_H','Allowed scalar norm Higgs-portal coefficient','L ⊃ -(1/2) lambda''_H |X|² |H|²','Not forbidden or set identically to zero; the numerical gauge-dominated limit assumes |lambda''_H| much smaller than gY² and g2².','specified');
INSERT INTO "theory_parameters" VALUES(48,'u1-ybl-charge-family',1,NULL,'b,z','Normalization and hypercharge-admixture parameters','Q2=b(zY+TBL), TBL=(B−L)/2','b≠0. Fix b with Eq. (44), or choose b=1 and leave g2 arbitrary.','specified');
INSERT INTO "theory_parameters" VALUES(49,'u1-ybl-charge-family',1,NULL,'z=0','Pure B−L specialization','(Q,ucL,dcL,LL,e+L,νcL) carry b(1/6,−1/6,−1/6,−1/2,1/2,1/2)','Scoped benchmark with the same fermion content. No U(1)′-breaking scalar sector selected.','specified');
INSERT INTO "theory_parameters" VALUES(50,'u1-ybl-charge-family',1,NULL,'α,κ','Conditional left-right-motivated charge parametrization','QLR=sqrt(3/5)(αT3R−TBL/α); α=gR/gBL=sqrt(κ²cot²θW−1); κ=gR/g; g2=sqrt(5/3)g tanθW','Canonical kinetic terms without kinetic mixing in this derivation; no scalar or discrete left-right completion is imposed.','specified');
INSERT INTO "theory_parameters" VALUES(51,'e6-full27-charge-template',1,NULL,'θE6,ε,λg','Charge-family angle, optional effective hypercharge shift and coupling normalization','Q2=cosθE6 Qχ+sinθE6 Qψ−εY; g2=sqrt(5/3)g tanθW sqrt(λg)','0≤θE6<π before the optional shift. λg is usually of order unity, not fixed. No kinetic operator completion is inferred from ε.','specified');
INSERT INTO "theory_parameters" VALUES(52,'e6-full27-charge-template',1,NULL,'θE6=π/2, ε=0','Unshifted ψ specialization','On fields 139–144 respectively, 2 sqrt(6) Qψ=(1,1,1,−2,−2,4)','Retains three full 27 inventories; no optional incomplete Higgs vector pair or scalar completion added.','specified');
INSERT INTO "theory_parameters" VALUES(53,'umssm-single-s-higgs-sector',1,NULL,'μeff,(Bμ)eff','Derived Higgs parameters after singlet scalar breaking','μeff=λS⟨S⟩; (Bμ)eff=λS AS⟨S⟩',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(54,'abelian-stueckelberg-sector',1,NULL,'m','Mass parameter in the gauge-invariant combination mCμ+∂μσ',NULL,'No numerical value or matter coupling selected.','specified');
INSERT INTO "theory_parameters" VALUES(55,'minimal-bl-pure',1,130,'g1′','Additional Abelian gauge coupling','Multiplies YB−L=B−L in Eq. (5).','No benchmark value or reported historical constraint is imposed on the structural specification.','specified');
INSERT INTO "theory_parameters" VALUES(56,'minimal-bl-pure',1,128,'mD','Single-generation Dirac entry in the neutrino mass matrix','mD=yνv/√2; Eq. (12).','This is the source''s independent-generation mass convention, not a restriction to one neutrino generation.','specified');
INSERT INTO "theory_parameters" VALUES(57,'minimal-bl-pure',1,129,'M','Single-generation right-right Majorana mass-matrix entry','M=√2 yM x; the source calls x the χ VEV. The displayed Yukawa has no factor 1/2.','Do not identify M exactly with the heavy physical mass Mνh. An explicit scalar vacuum expansion defining x is not supplied.','specified');
INSERT INTO "theory_parameters" VALUES(58,'minimal-bl-pure',1,NULL,'αν','Single-generation neutrino diagonalization angle','tan(2αν)=−2mD/M; (νL,νR)^T=[[cosαν,−sinαν],[sinαν,cosαν]](νl,νh)^T.','νL,R here denote the Majorana components of Eq. (10), not unconjugated chiral gauge multiplets. Positive-mass rephasings and Appendix substitutions are unresolved.','specified');
INSERT INTO "theory_parameters" VALUES(59,'u1-leptonic-opposite-nur',1,NULL,'a,b','Opposite charged-lepton-family and RH-neutrino charges','FL=Fe=(0,a,−a); Fν=(0,b,−b).','Integer representatives of rational charges. Nonzero common rescaling is a classification equivalence. b=a gives the stated Lµ−Lτ charge action with neutrinos; b=0 does not itself delete fields.','specified');
INSERT INTO "theory_parameters" VALUES(60,'u1-smnur-all-sm-yukawas',1,NULL,'q,n1,n2,n3;r','q is the universal Q charge; ni are individual RH-neutrino charges; r is their mean','r=(n1+n2+n3)/3; FQ+=3q; Fν+=3r; FH=−3q−r.','Rational charge scope with an overall integer normalization available. ni need not be equal and must satisfy the cubic ACC. No finite Qmax is imposed as a physical restriction.','specified');
INSERT INTO "theory_parameters" VALUES(61,'pp331-displayed',1,143,'f','Dimension-one scalar trilinear coefficient','V contains epsilon_ijk(f eta_i rho_j chi_k+h.c.), with no additional prefactor in Eq. (36).','Im(f)=0 is the source''s tree-level no-tadpole condition under its phase-free nonzero-VEV assumptions; it is not imposed independently on all possible vacua.','specified');
INSERT INTO "theory_parameters" VALUES(62,'ql421-dirac',1,NULL,'Y1,Y2,Y3,Y4','Four independent unified Yukawa matrices in Eq. (11).',NULL,'No numerical texture, alignment or MFV condition selected. Small Dirac neutrino masses require the source''s cancellation between the two Mν^D contributions.','specified');
INSERT INTO "theory_parameters" VALUES(63,'ql421-dirac',1,NULL,'Mu,Mν^D','Derived up-quark and Dirac-neutrino matrices.','Mu=Y1 v1/√2+Y2 v2/(2√6√2); Mν^D=Y1 v1/√2-3Y2 v2/(2√6√2).',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(64,'ql421-dirac',1,NULL,'Md,Me','Derived down-quark and charged-lepton matrices.','Md=Y3 v1/√2+Y4 v2/(2√6√2); Me=Y3 v1/√2-3Y4 v2/(2√6√2).',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(65,'ql421-inverse-seesaw',1,153,'Mχ^D','Neutrino-sector Dirac mass entry generated by χ breaking.','Mχ^D=Y5 vχ/√2. It is not the vector-leptoquark mass or the vacuum parameter vχ itself.',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(66,'ql421-inverse-seesaw',1,154,'µ','Matter-symmetry-breaking singlet Majorana mass parameter.','L ⊃ (1/2)µNN+h.c.','Small relative to the Dirac entries in the inverse-seesaw regime; µ=0 restores the displayed matter symmetry. The numerical 0.1 GeV statement is confined to the illustrative benchmark.','specified');
INSERT INTO "theory_parameters" VALUES(67,'ql421-inverse-seesaw',1,NULL,'M_neutral','Displayed mass matrix in the (ν,ν^c,N) basis.','[[0,Mν^D,0],[(Mν^D)^T,0,Mχ^D],[0,(Mχ^D)^T,µ]].','The explicit diagonalization discussion is for one generation; no three-generation fit or flavor texture is supplied.','specified');
INSERT INTO "theory_parameters" VALUES(68,'ql421-inverse-seesaw',1,NULL,'mν','Leading one-generation light Majorana mass.','mν=µ(Mν^D)^2/(Mχ^D)^2.','Requires µ ≪ Mν^D ≪ Mχ^D; not an exact general matrix formula.','specified');
INSERT INTO "theory_parameters" VALUES(69,'su5-adjoint-renormalizable',1,161,'m','Bare adjoint-fermion mass coefficient.','V24 ⊃ m Tr(24²); distinct from the split component masses.',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(70,'su5-adjoint-renormalizable',1,162,'λ; λ̃','Adjoint-fermion coupling to 24H and its rescaled notation.','λ̃=λ/√(50π).','No small-λ restriction is imposed on the construction.','specified');
INSERT INTO "theory_parameters" VALUES(71,'su5-adjoint-renormalizable',1,NULL,'MD, ME','Derived down-quark and charged-lepton mass matrices.','MD=Y1 v5*+2Y2 v45*; ME=Y1^T v5*−6Y2^T v45*; ⟨5H⟩=v5.','Source VEV conventions retained; exact 45H tensor alignment is not canonicalized.','specified');
INSERT INTO "theory_parameters" VALUES(72,'su5-adjoint-renormalizable',1,NULL,'Mν_ij; a_i,b_i','Tree-level sum of triplet and singlet seesaw mass contributions.','Mν_ij=a_i a_j/Mρ3+b_i b_j/Mρ0; a_i=c_i v5−3p_i v45; b_i=(√15/2)(c_i v5/5+p_i v45).','Applies in the stated tree-level seesaw treatment. Eq. (7) follows the prepared fraction reconstruction, also consistent with the supplied page-3 text; no image verification is claimed.','specified');
INSERT INTO "theory_parameters" VALUES(73,'su5-adjoint-renormalizable',1,NULL,'Mρ0,Mρ3,Mρ8,Mρ(3,2),Mρ(3̄,2)','Correlated adjoint-fermion component mass expressions.','Mρ0=m−λ̃MGUT/√αGUT; Mρ3=m−3λ̃MGUT/√αGUT; Mρ8=m+2λ̃MGUT/√αGUT; Mρ(3,2)=Mρ(3̄,2)=m−λ̃MGUT/(2√αGUT).','Eqs. (9)–(12) as displayed, with MV=MGUT. No unsupplied phase or absolute-value prescription is added. These masses are not independent threshold parameters.','specified');
INSERT INTO "theory_parameters" VALUES(74,'su5-adjoint-renormalizable',1,NULL,'v; MV; MGUT','Adjoint VEV scale, superheavy gauge-boson mass and chosen unification scale.','⟨24H⟩=v diag(2,2,2,−3,−3)/√30; MV=v√(5παGUT/3); MV≡MGUT.','MGUT identification is the source''s unification convention, not a fixed numerical scale.','specified');
INSERT INTO "theory_parameters" VALUES(75,'so10-45-126-sector',1,NULL,'μ²,ν²,a0,a2,λ0,λ2,λ4,λ′4,η2,τ,α,β4,β′4,γ2','Coefficients of the displayed general scalar potential.','Eqs. (2)-(4), with the Appendix A contractions retained in interactions 163-165.','All real except η2 and γ2. Numerical scan ranges and symmetry-enhancement limits are scoped choices, not defining restrictions.','specified');
INSERT INTO "theory_parameters" VALUES(76,'so10-45-126-sector',1,NULL,'ωBL,ωR,σ','Three SM-preserving scalar VEV coordinates.','Under SU(3)c × SU(2)L × SU(2)R × U(1)BL: ωBL=⟨(1,1,1,0)45⟩, ωR=⟨(1,1,3,0)45⟩, σ=⟨(1,1,3,+1)126⟩; BL=(B−L)/2.','ωBL and ωR are real. A 126H phase redefinition can make σ real; this does not make all potential couplings real.','specified');
INSERT INTO "theory_parameters" VALUES(77,'so10-45-126-sector',1,NULL,'M²(1,3,0),M²(8,1,0)','Derived tree-level masses of the two adjoint pseudo-Goldstone multiplets.','M²(1,3,0)=−2a2(ωBL−ωR)(ωBL+2ωR); M²(8,1,0)=−2a2(ωR−ωBL)(ωR+2ωBL).','No σ contribution at tree level. The quoted ratio interval [−2,−1/2] describes the pair''s obstruction to hierarchical VEVs, not sufficient stability conditions for the full spectrum; signs, enhanced alignments, vanishing a2 and endpoint zero modes require their own treatment.','specified');
INSERT INTO "theory_parameters" VALUES(78,'so10-45-126-sector',1,NULL,'ΔM²_(1-loop-τ²)','Source-calculated universal nonlogarithmic scalar mass correction used for minimal spectrum regularization.','ΔM²=35τ²/(32π²)+logs; associated with stationarity renormalization through 45H tadpoles.','The numerical prescription retains the displayed positive nonlogarithmic shift. It is a derived approximate correction, not an independent tree-level coupling or a complete one-loop spectrum.','specified');
INSERT INTO "theory_parameters" VALUES(79,'so10-45-126-complex10',1,NULL,'Mu,Md,Mℓ,MνD,MνM,I,MνM,II','General tree-level fermion mass relations of the proposed extension.','Mu=Y1^10 vu^10+Y2^10 vd^10*+Y126 vu^126; Md=Y1^10 vd^10+Y2^10 vu^10*+Y126 vd^126; Mℓ=Y1^10 vd^10+Y2^10 vu^10*−3Y126 vd^126; MνD=Y1^10 vu^10+Y2^10 vd^10*−3Y126 vu^126; MνM,I=cI Y126 σ; MνM,II=cII Y126 w126.','Y matrices are proportional to the f matrices of Eq. (17); cI and cII contain numerical factors. These are mass-matrix segments, not themselves the integrated-out type-I light-neutrino mass formula. VEV projections depend on the unspecified full scalar potential; no fitted values or one-doublet reduction imposed.','specified');
INSERT INTO "theory_parameters" VALUES(80,'trinification-n3-adjoint-l',1,NULL,'gL,gR,gc','Trinification gauge couplings and source matching to SM couplings','gL=g2; gR=2g2gY/sqrt(3g2²−gY²); gc=g3; gY=sqrt(3/5)g1.','No common-coupling permutation restriction or numerical benchmark imposed. Threshold corrections are unspecified.','specified');
INSERT INTO "theory_parameters" VALUES(81,'trinification-singlet-neutrino-sector',1,177,'MN^{ij}','Added singlet Majorana mass matrix','Lextra ⊃ −MN^{ij}NiNj/2.','No numerical matrix supplied. M∼V belongs to the illustrative neutrino mechanism, not a universal defining value.','specified');
INSERT INTO "theory_parameters" VALUES(82,'mssm-rpc-conventional-soft',1,181,'μ','Independent supersymmetric Higgs mass parameter','W contains μ H_u H_d; its component contributions include the higgsino bilinear and |μ|² times both Higgs scalar norms.','No μ-generation mechanism, real-μ restriction or naturalness mass range imposed.','specified');
INSERT INTO "theory_parameters" VALUES(83,'mssm-rpc-conventional-soft',1,NULL,'y_u,y_d,y_e','Dimensionless 3×3 family matrices in the superpotential',NULL,'General matrices; the third-family truncation is not defining.','specified');
INSERT INTO "theory_parameters" VALUES(84,'mssm-rpc-conventional-soft',1,182,'M1,M2,M3','Bino, wino and gluino Majorana soft mass coefficients, respectively',NULL,'Independent parameters; no common phase, unification or fixed spectrum imposed.','specified');
INSERT INTO "theory_parameters" VALUES(85,'mssm-rpc-conventional-soft',1,183,'a_u,a_d,a_e','Mass-dimension-one scalar cubic coefficient matrices',NULL,'Independent complex 3×3 matrices, not intrinsically proportional to Yukawas.','specified');
INSERT INTO "theory_parameters" VALUES(86,'mssm-rpc-conventional-soft',1,184,'m_Q²,m_bar-u²,m_bar-d²,m_L²,m_bar-e²','Five sfermion squared-mass matrices',NULL,'Hermitian 3×3 matrices; off-diagonal complex entries allowed. The superscript does not require every eigenvalue to be positive throughout parameter space.','specified');
INSERT INTO "theory_parameters" VALUES(87,'mssm-rpc-conventional-soft',1,185,'m_Hu²,m_Hd²,b','Higgs soft squared-mass coefficients and holomorphic bilinear coefficient','L_soft contains −m_Hu²|H_u|²−m_Hd²|H_d|²−(b H_u H_d+c.c.); b is also called Bμ in the cited convention comparison.','No positivity or high-scale equality imposed on m_Hu²,m_Hd². b is not itself a mass-dimension-one B parameter.','specified');
INSERT INTO "theory_parameters" VALUES(88,'mssm-rpc-conventional-soft',1,NULL,'v_u,v_d,v,tanβ','Neutral Higgs VEVs and their ratio in the selected vacuum','v_u=<H_u^0>, v_d=<H_d^0>; v²=v_u²+v_d²=2m_Z²/(g²+g''²) approximately (174 GeV)²; tanβ=v_u/v_d.','0<β<π/2 in the positive-VEV convention. No conversion to the 246 GeV VEV convention.','specified');
INSERT INTO "theory_parameters" VALUES(89,'mssm-minimal-gauge-messengers',1,NULL,'Λ','Ratio of singlet auxiliary and scalar expectation values','Λ=<F_S>/<S>.','Leading matching assumes small messenger splitting. The source prints Λ² in scalar masses; extending that expression to general complex VEV conventions remains deferred.','specified');
INSERT INTO "theory_parameters" VALUES(90,'rpv-singlet-spontaneous-sector',1,209,'mu_i','Derived effective bilinear after singlet sneutrino breaking','mu_i=h^nu_i3 v_R/sqrt(2)','One-family VEV illustration; not an independent explicit RPV parameter of the unbroken superpotential.','specified');
INSERT INTO "theory_parameters" VALUES(91,'su5-rpv-trilinear-sector',1,211,'Lambda; lambda, lambda-prime, lambda-double-prime','Unified coefficient and its MSSM operator components','lambda_ijk=(1/2)lambda-prime_ikj=lambda-double-prime_kij; lambda-prime_ijk=-lambda-prime_kji','Source relations for field-independent renormalizable coefficients. Nine independent superpotential coefficients and nine corresponding A-terms with the same relations; not a generic GUT-breaking-induced texture.','specified');
INSERT INTO "theory_parameters" VALUES(92,'split-susy',1,212,'lambda','Light-Higgs quartic coefficient','L contains -(lambda/2)(H†H)²','lambda(mtilde)=[g²(mtilde)+g_prime²(mtilde)] cos²(2beta)/4. Displayed supersymmetric matching only; unknown scalar-threshold corrections remain unspecified.','specified');
INSERT INTO "theory_parameters" VALUES(93,'split-susy',1,NULL,'beta','Parent Higgs projection angle','H=-cos(beta)epsilon Hd*+sin(beta)Hu','Not a ratio of two independent low-energy scalar-doublet VEVs. No benchmark value imposed.','specified');
INSERT INTO "theory_parameters" VALUES(94,'split-susy',1,216,'M1,M2,M3,mu','Independent bino, wino, gluino and higgsino mass coefficients before optional boundary restrictions','Gaugino bilinears have coefficient Mi/2; higgsino bilinear has coefficient mu in Eq. (20).','No fixed numerical spectrum. In this treatment mu is not fixed by electroweak symmetry breaking; relic-abundance constraints require additional assumptions.','specified');
INSERT INTO "theory_parameters" VALUES(95,'split-susy',1,NULL,'mtilde','Common heavy-scalar threshold in the simplifying degenerate approximation',NULL,'Much above the electroweak scale; no fixed value. The approximate cosmological upper-scale discussion is mass dependent and does not supply a universal defining bound.','specified');
INSERT INTO "theory_parameters" VALUES(96,'gem-supersoft',1,220,'m_D','D-spurion mass scale','m_D=D''/M; W''_alpha/M=theta_alpha m_D','Source local normalization; no common low-energy mass across all three gauge factors is imposed.','specified');
INSERT INTO "theory_parameters" VALUES(97,'gem-supersoft',1,NULL,'M_1,M_2; m_1,m_2','Electroweak supersymmetric ESP masses and Dirac gaugino masses in Eq. (2.8)','Tree Higgs D-quartic coefficient becomes [M_1^2 g''^2/(M_1^2+4m_1^2)+M_2^2 g^2/(M_2^2+4m_2^2)]/8.','Eq. (2.8) setup only; these M_i are ESP masses, whereas Eq. (3.21) reuses M_i for effective visible-gaugino masses. No phase-general formula inferred.','specified');
INSERT INTO "theory_parameters" VALUES(98,'gem-supersoft',1,NULL,'delta_i^2; m_scalar^2','Real-adjoint breaking mass squared and derived one-loop gauge scalar contribution','m_scalar^2=C_i(r) alpha_i m_i^2 log(delta_i^2/m_i^2)/pi; delta_i=2m_i without Eq. (2.9).','Eq. (2.12), without a supersymmetric ESP mass. Positivity requires delta_i^2>m_i^2; minimal limit satisfies it. Gauge flavor blindness does not establish universality after arbitrary additional interactions.','specified');
INSERT INTO "theory_parameters" VALUES(99,'general-gauge-mediation',1,NULL,'zeta','Real current one-point function <J>=zeta.',NULL,'Vanishes for nonabelian currents. Hypercharge zeta is not set to zero by the general definition.','specified');
INSERT INTO "theory_parameters" VALUES(100,'general-gauge-mediation',1,NULL,'Ctilde_0, Ctilde_1/2, Ctilde_1','Real momentum-dependent hidden current two-point functions, independently indexed by visible gauge factor.','<JJ>=Ctilde_0; <j_alpha jbar_alphadot>=-sigma^mu p_mu Ctilde_1/2; <j_mu j_nu>=-(p² eta_munu-p_mu p_nu) Ctilde_1.','Contact terms enforce current conservation. Hidden dynamics are not fixed by this parameterization.','specified');
INSERT INTO "theory_parameters" VALUES(101,'general-gauge-mediation',1,NULL,'Btilde_1/2','Potentially complex chirality-changing current correlator function for each gauge factor.','<j_alpha(p) j_beta(-p)>=epsilon_alphabeta M Btilde_1/2(p²/M²).','No common phase or equality among gauge factors is imposed.','specified');
INSERT INTO "theory_parameters" VALUES(102,'general-gauge-mediation',1,NULL,'A_r','Three real scalar soft-mass correlator integrals.','A_r=-integral d^4p/(2pi)^4 [3Ctilde_1^(r)-4Ctilde_1/2^(r)+Ctilde_0^(r)]/p².','Full momentum dependence is required. General ultraviolet convergence is expected by the authors but explicitly not proved.','specified');
INSERT INTO "theory_parameters" VALUES(103,'general-gauge-mediation',1,NULL,'M_r','Leading visible gaugino mass coefficients.','M_r=g_r² M Btilde_1/2^(r)(0), r=3,2,1.','Leading visible gauge order. No gaugino mass unification follows merely from gauge coupling unification.','specified');
INSERT INTO "theory_parameters" VALUES(104,'general-gauge-mediation',1,NULL,'m_f_tilde²','Leading gauge-mediated MSSM sfermion squared masses at M.','m_f_tilde²=g1² Y_f zeta+sum_r g_r^4 c2(f;r) A_r.','Depends on gauge quantum numbers, not generation. Positivity is not automatic; the hypercharge term can have either sign. Subsequent running and extra Higgs effects require separate treatment.','specified');
INSERT INTO "theory_parameters" VALUES(105,'u1-minimal-gauge-messenger-toy',1,NULL,'M,F','Prescribed scalar and auxiliary components of X.','<X>=M+theta²F.','M and F are real in the chosen convention; no numerical values or dynamical origin are specified.','specified');
INSERT INTO "theory_parameters" VALUES(106,'u1-minimal-gauge-messenger-toy',1,232,'lambda','Coefficient of X phi phi_tilde.',NULL,'Set to one in the source convention; this does not define an additional model identity.','specified');
INSERT INTO "theory_parameters" VALUES(107,'u1-minimal-gauge-messenger-toy',1,NULL,'m_plus²,m_minus²,m0','Derived messenger component masses.','phi_plus,minus=(phi plus or minus phi_tilde*)/sqrt(2); m_plus,minus²=M² plus or minus F; m0=M for psi and psi_tilde.','Real M,F and lambda=1. These eigenstates do not add independent superfields; no global vacuum-stability certification is supplied.','specified');
INSERT INTO "theory_parameters" VALUES(108,'general-gauge-mediation-higgs-operators',1,NULL,'lambda_u,lambda_d','Dimensionless coefficients of the direct hidden-operator Higgs couplings when the operators have short-distance dimension two.',NULL,'Perturbative expansion parameters; both must vanish, along with visible gauge couplings, in the extended decoupling limit. The single-scale estimate lambda_u lambda_d approximately alpha/(4pi) is not imposed generally.','specified');
INSERT INTO "theory_parameters" VALUES(109,'ksvz-neutral-triplet',1,NULL,'N,E/N,N_DW,f_a','Benchmark anomaly and decay-constant data','N=1/2; E/N=0; N_DW=1; f_a=v_a','X_Phi=1 and the single stated pair. N is the prepared inference from N_DW=2N. Ultraviolet c_i^0=0 does not imply vanishing physical low-energy couplings.','specified');
INSERT INTO "theory_parameters" VALUES(110,'ksvz-neutral-triplet',1,NULL,'m_Q,m_rho,m_a(tree)','Derived PQ-broken tree-level masses','m_Q=y_Q v_a/sqrt(2); m_rho=sqrt(2 lambda_Phi) v_a; m_a(tree)=0','Tree-level angular masslessness does not exclude the QCD-induced axion mass.','specified');
INSERT INTO "theory_parameters" VALUES(111,'ksvz-representation-framework',1,NULL,'N,E','Spectrum-dependent QCD and electromagnetic anomalies','N=sum_Q X_Q d(I_Q) T(C_Q); E=sum_Q X_Q d(C_Q)d(I_Q)[(d(I_Q)²-1)/12+Y_Q²]','Sum over left-handed irreducible fields, including Q_R^c with X_QRc=-X_QR. X_Q is not silently replaced by a Dirac-pair charge difference. T(3)=1/2. No numerical E/N selected.','specified');
INSERT INTO "theory_parameters" VALUES(112,'dfsz-i-quartic',1,NULL,'a,v_a,f_a','Physical axion direction and normalization','a=sum_i X_i v_i a_i/v_a; v_a²=sum_i X_i² v_i²=v_Phi²+v² sin²(2 beta); f_a=v_a/6','i=Phi,u,d. v_a approximately v_Phi only for v_Phi much larger than v; the singlet phase alone is not exactly the physical axion. Common direction and scale relations apply also to quartic DFSZ-II.','specified');
INSERT INTO "theory_parameters" VALUES(113,'dfsz-i-quartic',1,NULL,'N,E,N_DW,c_ui^0,c_di^0,c_ei^0','DFSZ-I anomaly and ultraviolet fermion coefficients','N=3; E=8; E/N=8/3; N_DW=6; c_ui^0=cos²(beta)/3; c_di^0=c_ei^0=sin²(beta)/3','Three generations; X_Phi=1; quartic scalar operator. c_f^0 multiplies (partial_mu a)/(2f_a) bar(f) gamma^mu gamma_5 f. DFSZ-I lepton and EM values are replaced in DFSZ-II.','specified');
INSERT INTO "theory_parameters" VALUES(114,'dfsz-i-quartic',1,NULL,'tan(beta)','Doublet VEV ratio shared by the quartic DFSZ benchmarks','tan(beta)=v_u/v_d; v_u=v sin(beta), v_d=v cos(beta); v approximately 246 GeV','The source''s conditional tree-level perturbative range is [0.25,170] for both lepton variants, from y_t,b<sqrt(16pi/3), neglecting running and using m_t=173.1 GeV and m_b=4.18 GeV. It is not an unconditional defining parameter bound.','specified');
INSERT INTO "theory_parameters" VALUES(115,'dfsz-ii-quartic',1,NULL,'N,E,E/N,N_DW,f_a','DFSZ-II anomaly and decay-constant data','N=3; E=2; E/N=2/3; N_DW=6; f_a=v_a/6','E and E/N replace DFSZ-I values. N, f_a and N_DW follow the unchanged quark/scalar sectors as explicitly marked in prepared inference 937; X_Phi=1.','specified');
INSERT INTO "theory_parameters" VALUES(116,'dfsz-ii-quartic',1,NULL,'c_ui^0,c_di^0,c_ei^0','DFSZ-II ultraviolet derivative axial coefficients','c_ui^0=cos²(beta)/3; c_di^0=sin²(beta)/3; c_ei^0=-cos²(beta)/3','i=1,2,3; coefficients multiply (partial_mu a)/(2f_a) bar(f) gamma^mu gamma_5 f. Lepton value replaces the DFSZ-I coefficient.','specified');
INSERT INTO "theory_parameters" VALUES(117,'dfsz-i-quartic',1,NULL,'X_fL-X_fR','Generation-universal chiral PQ charge differences','X_uL-X_uR=X_Hu; X_dL-X_dR=X_Hd; X_eL-X_eR=X_Hd','These relations do not fix separate absolute charges for q_L or ell_L. Do not interpret them as a numerical charge table for each chiral multiplet.','specified');
INSERT INTO "theory_parameters" VALUES(118,'dfsz-ii-quartic',1,NULL,'X_eL-X_eR','Replacement lepton PQ charge difference','X_eL-X_eR=-X_Hu','Only the lepton difference changes; absolute chiral charges remain unselected and quark differences remain those of the common sector.','specified');
INSERT INTO "theory_parameters" VALUES(119,'smash-down',1,NULL,'Mij,mQ,mρ','Leading PQ-breaking masses','Mij=Yij vσ/sqrt(2); mQ=y vσ/sqrt(2); mρ=sqrt(2λσ)vσ','Leading hierarchy approximation of Eq. (7), not exact mixed mass eigenvalues for arbitrary quark mixing; no numerical spectrum imposed.','specified');
INSERT INTO "theory_parameters" VALUES(120,'smash-down',1,NULL,'MD,MM,mν','Neutrino mass blocks and leading type-I seesaw result','MD=Fv/sqrt(2); MM=Yvσ/sqrt(2); mν=-MD MM^-1 MD^T=-FY^-1F^T v²/(sqrt(2)vσ)','Seesaw hierarchy and invertibility of the integrated-out mass block; illustrative 0.04 eV estimate does not fix a flavor matrix.','specified');
INSERT INTO "theory_parameters" VALUES(121,'smash-down',1,NULL,'fA','Axion decay constant and singlet vacuum scale','fA=vσ; σ=(vσ+ρ)exp(iA/vσ)/sqrt(2)','Free structural scale. Eq. (151)''s all-dark-matter window is 3×10^10–1.2×10^11 GeV; page 72 instead gives upper limit 5×10^11 GeV. No unique cosmological upper limit is canonicalized.','ambiguous_conflicting');
INSERT INTO "theory_parameters" VALUES(122,'smash-down',1,NULL,'δ,λbarH','Tree-level radial-threshold matching quantities','δ=λHσ²/λσ; λbarH=λH-δ','For threshold stabilization require mρ below the SM instability scale. λbarH runs in the low-energy theory; the identically formed λtildeH runs with full-theory couplings and is not interchangeable at all scales.','specified');
INSERT INTO "theory_parameters" VALUES(123,'smash-down',1,NULL,'λtildeσ,λ,ξσ','Effective inflationary quartic and non-minimal coupling','λtildeσ=λσ-λHσ²/λH; λ=λtildeσ for HHSI and λ=λσ for HSI','In the source''s preferred small-coupling inflation window, 6×10^-3≲ξσ≲1 and 5×10^-13≲λ≲5×10^-10 at inflationary scales. These conditional ranges do not bound λσ identically in HHSI with cancellation.','specified');
INSERT INTO "theory_parameters" VALUES(124,'smash-down',1,NULL,'mA,CAγ,CAp,CAn','Quoted zero-temperature axion mass and below-QCD effective coefficients','mA=57.0(7)(10^11 GeV/fA) μeV; CAγ=2/3-1.92(4); CAp=-0.47(3); CAn=-0.02(3)','Source-era QCD inputs quoted by the paper; no independent recalculation or current update.','specified');
INSERT INTO "theory_parameters" VALUES(125,'lns-two-singlet-quarks',1,NULL,'epsilon1','First horizontal expansion parameter','epsilon1=<S1>/M; typical singlet Yukawa absorbed into the stated VEV convention','Approximately 0.04 in the illustrative hierarchy; no absolute scale fixed.','specified');
INSERT INTO "theory_parameters" VALUES(126,'lns-two-singlet-quarks',1,NULL,'epsilon2','Second horizontal expansion parameter','epsilon2=<S2>/M; epsilon2/epsilon1 approximately 0.2','Approximately 0.008 in the illustrative hierarchy; scalar minimization is not supplied.','specified');
INSERT INTO "theory_parameters" VALUES(127,'lns-two-singlet-quarks',1,NULL,'M','Characteristic mass scale of the added vectorlike pairs',NULL,'Mass entries are of order M, not necessarily identical exact eigenvalues. The eight-pair source-era perturbativity bound is conditional on the running assumptions of section 8.','specified');
INSERT INTO "theory_parameters" VALUES(128,'lns-single-singlet-quarks',1,NULL,'epsilon','Single horizontal expansion parameter','epsilon=<S>/M; epsilon1=epsilon^2 and epsilon2=epsilon^3 for comparison','Approximately 0.2. Replacement charges allow Mu12 of order <phi_u> epsilon^4 and Mu32 of order <phi_u> epsilon; permission alone does not fix exact coefficients.','specified');
INSERT INTO "theory_parameters" VALUES(129,'lns-reduced-quarks',1,NULL,'Mu','Leading effective up-quark mass texture of the reduced realization','Mu approximately <phi_u> [[0,0,0],[0,epsilon2,epsilon1],[0,0,1]]','mu=0 in this selected realization. Generic nonzero entries; zeros include restrictions from missing heavy paths and are not all horizontal prohibitions.','specified');
INSERT INTO "theory_parameters" VALUES(130,'lns-reduced-quarks',1,NULL,'Md','Leading effective down-quark mass texture with modified charges','Md approximately <phi_d> [[0,epsilon2,epsilon2],[epsilon2,epsilon1,epsilon1],[0,1,1]]','Independent coefficients on nonzero entries; <phi_d> approximately epsilon1 <phi_u> in the combined example.','specified');
INSERT INTO "theory_parameters" VALUES(131,'af-a4-susy-effective',1,NULL,'lambda; q','U(1)F expansion parameter and charged-lepton charge spacing','lambda=<theta>/Lambda; F(e^c,mu^c,tau^c)=(2q,q,0); ytau~O(1), ymu~O(lambda^q), ye~O(lambda^(2q))','lambda<1; q is not numerically fixed. Order estimates do not equate independent coefficients.','specified');
INSERT INTO "theory_parameters" VALUES(132,'af-a4-susy-effective',1,NULL,'vS/Lambda, vT/Lambda, u/Lambda','Flavour-breaking expansion ratios','Source VEV convention has no inserted sqrt(2).','Conditional source-era interval 0.0022<vS/Lambda approximately vT/Lambda approximately u/Lambda<0.05, assuming comparable VEVs. Lower limit uses ytau<4pi and tan(beta)=2.5; tan(beta)=30 instead gives vT/Lambda>0.024. This does not restrict <theta>/Lambda or define another model.','specified');
INSERT INTO "theory_parameters" VALUES(133,'af-a4-susy-effective',1,NULL,'a,b','Leading effective neutrino texture coefficients','a=2xa u/Lambda; b=2xb vS/Lambda; mnu=(v_u²/Lambda)[[a+2b/3,-b/3,-b/3],[-b/3,2b/3,a-b/3],[-b/3,a-b/3,2b/3]]','Leading aligned vacuum with xi_tilde=0. No real-parameter or CP-conservation restriction; the texture is more restrictive than general S-invariance.','specified');
INSERT INTO "theory_parameters" VALUES(134,'af-a4-susy-seesaw',1,NULL,'A,B','Leading heavy-neutrino Majorana texture coefficients','A=2xA; B=2xB vS/u; M=u[[A+2B/3,-B/3,-B/3],[-B/3,2B/3,A-B/3],[-B/3,A-B/3,2B/3]]','Leading aligned vacuum and nonzero u. The associated identity Dirac matrix is not adopted. Complex A,B and normal/inverted spectrum examples are parameter choices.','specified');
INSERT INTO "theory_parameters" VALUES(135,'modular-a4-flavonfree-seesaw',1,NULL,'Y=(Y1,Y2,Y3)','Weight-2 level-3 holomorphic modular coupling functions of τ, not independent fields or freely variable triplet coefficients','Let F(A,B,C,D;τ)=d/dτ[A log η(τ/3)+B log η((τ+1)/3)+C log η((τ+2)/3)+D log η(3τ)], A+B+C+D=0. With c0=i/(2π), Y1=3c0 F(1,1,1,-3;τ), Y2=-6c0 F(1,ω²,ω,0;τ), Y3=-6c0 F(1,ω,ω²,0;τ). η(τ)=q^(1/24)∏n≥1(1-q^n), q=exp(2πiτ), ω=exp(2πi/3).','Y2²+2Y1Y3=0. Y(-1/τ)=τ²ρ(S)Y(τ), Y(τ+1)=ρ(T)Y(τ), with ρ(S)=[[-1,2,2],[2,-1,2],[2,2,-1]]/3 and ρ(T)=diag(1,ω,ω²). The exact functions, not a finite q-series truncation, enter the interactions.','specified');
INSERT INTO "theory_parameters" VALUES(136,'modular-a4-flavonfree-seesaw',1,NULL,'α,β,γ,g1,g2,Λ','Six constant coefficients of the selected lepton superpotential','Equations (50)–(51); field rescalings for the assumed kinetic terms are absorbed into these coefficients.','Field redefinitions permit real α,β,γ,g1; this does not impose CP conservation. At fixed τ, neutrino ratios and mixing depend on g2/g1 and charged-lepton ratios on α/γ,β/γ. Λ=1 is only a convention for the mass-ratio analysis, not a physical heavy-scale assignment.','specified');
INSERT INTO "theory_parameters" VALUES(137,'modular-a4-flavonfree-seesaw',1,NULL,'mν, me','Source-stated seesaw and charged-lepton mass matrices','mν=-Yν^T MR^(-1)Yν⟨Hu⟩²; me=Ye⟨Hd⟩, with Ye rows α(Y1,Y3,Y2), β(Y2,Y1,Y3), γ(Y3,Y2,Y1).','Equation (52) retained alongside equation (51), without independently resolving the quadratic-superpotential factor convention. No exact full neutral-spectrum diagonalization or absolute mass scale is inferred.','specified');
INSERT INTO "theory_parameters" VALUES(138,'grv-quark-flavor-u3',1,NULL,'Mu,Md,λu,λd,λ′u,λ′d','Universal mass insertions and dimensionless coefficients in equation (2.3).',NULL,'Universal in flavor space, independent between the displayed operator classes; field rotations permit real coefficients. This is not a real-CKM or full-theory CP-conservation assumption.','specified');
INSERT INTO "theory_parameters" VALUES(139,'grv-quark-flavor-u3',1,NULL,'yu,yd','Leading effective SM Yukawa matrices in regime 117.','yu=V† λu Mu/(λ′u Ŷu); yd=λd Md/(λ′d Ŷd)','Diagonal denominators mean matrix inverses. Valid in the source''s heavy-exotic expansion; not exact for the top sector. These are derived couplings, not additional independent UV matrices.','specified');
INSERT INTO "theory_parameters" VALUES(140,'grv-quark-flavor-u3',1,NULL,'xi,yi,mu′i,λ′u Ŷui','Exact up-sector physical mass relations; analogous down-sector relations.','xi=Mu/mui; yi=λu v/(sqrt(2) mui); mu′i/mui=xi yi; λ′u Ŷui/mui=sqrt[(xi²-1)(yi²-1)]','Source convention of equations (3.3)–(3.6). Physical branches have xi,yi≥1 or xi,yi<1; partners need not always be heavier. Equation (3.2)''s inconsistent labels are not used.','specified');
INSERT INTO "theory_parameters" VALUES(141,'sm-singlet-neutrino-framework',1,285,'F; M_D','Neutrino Yukawa matrix and associated Dirac mass matrix','M_D=F<Phi>','Charged-lepton and sterile mass matrices real and diagonal in the displayed basis. This does not require F to be real or diagonal.','specified');
INSERT INTO "theory_parameters" VALUES(142,'numsm',1,NULL,'M1,M2,M3','Three Majorana mass parameters inherited from Eq. (1)',NULL,'Electroweak-scale-or-lighter source domain, with conclusions specifying masses below that scale. A keV M1 and near-degenerate approximately 10 GeV M2,3 are scoped cosmological selections, not fixed masses of the specification.','specified');
INSERT INTO "theory_parameters" VALUES(143,'numsm',1,NULL,'f1,f2,f3; theta_Lij,theta_Rij; delta_L,delta_R,alpha1,alpha2,beta1,beta2','F parameterization comprising three diagonal Yukawa couplings, six mixing angles and six CP phases; with three Majorana masses, 18 new parameters',NULL,'No universal texture or CP-conservation condition. Absence of beta phases from the limiting kinetic equations does not remove them from the Lagrangian.','specified');
INSERT INTO "theory_parameters" VALUES(144,'numsm',1,NULL,'m0','Adopted dark-matter abundance parameter in regime 121','(M_D dagger M_D)_11 approximately m0²; m0 of order 0.1 eV','Conditional imported abundance relation for N1 as sole sterile dark matter. Production details from reference [12] are unresolved here; this is not a generic restriction on F.','specified');
INSERT INTO "theory_parameters" VALUES(145,'numsm',1,NULL,'Delta M32²/M3²','Heavier-sterile mass-squared splitting ratio in the perturbative normal-hierarchy example',NULL,'Eq. (34) uses a reference ratio 1e-6 with M3 approximately 10 GeV and suitable delta_CP. The prose describes degeneracy to one part in 1e6. No exact linear splitting is inferred, and the suggested |M3-M2| approximately M1 is not imposed.','specified');
INSERT INTO "theory_parameters" VALUES(146,'ma-radiative-seesaw-z2',1,290,'λ5','Phase-sensitive scalar quartic coefficient','V contains (λ5/2)[(Φ†η)²+H.c.]','Chosen real without loss of generality; this is not full-theory CP conservation. Small splitting is an optional approximation.','specified');
INSERT INTO "theory_parameters" VALUES(147,'ma-radiative-seesaw-z2',1,NULL,'v','Neutral SM Higgs expectation value','<φ0>=v; <η0>=0','Source convention without an inserted 1/sqrt(2); no numerical value imposed.','specified');
INSERT INTO "theory_parameters" VALUES(148,'ma-radiative-seesaw-z2',1,NULL,'m_η±²','Derived charged-scalar squared mass','m_η±²=m_2²+λ3 v²','Assumed vacuum of Eq. (6); not an independent mass input.','specified');
INSERT INTO "theory_parameters" VALUES(149,'ma-radiative-seesaw-z2',1,NULL,'m_R²,m_I²','Derived squared masses of sqrt(2)Reη0 and sqrt(2)Imη0','m_R²=m_2²+(λ3+λ4+λ5)v²; m_I²=m_2²+(λ3+λ4−λ5)v²','Real λ5 convention and assumed parity-preserving vacuum. No universal ordering selected.','specified');
INSERT INTO "theory_parameters" VALUES(150,'ma-radiative-seesaw-z2',1,NULL,'(M_ν)_ij','Source-calculated one-loop Majorana neutrino mass matrix','Σ_k h_ik h_jk M_k/(16π²) {m_R² ln(m_R²/M_k²)/(m_R²−M_k²) − m_I² ln(m_I²/M_k²)/(m_I²−M_k²)}','Eq. (11) as reconstructed from supplied text; no image verification. Derived from existing interactions, not an additional tree-level mass coefficient. Coincident masses require the continuous limit.','specified');
INSERT INTO "theory_parameters" VALUES(151,'weinberg-t1i-first-row',1,NULL,'α','Integer hypercharge label of the first T1-i row',NULL,'α is an integer; no value selected. It labels representation alternatives, not a continuously variable coupling in one fixed gauge representation.','specified');
INSERT INTO "theory_parameters" VALUES(152,'weinberg-t41ii-first-row',1,NULL,'α','Integer hypercharge label of the first T4-1-ii row',NULL,'No value selected; distinct values specify electroweak representation alternatives.','specified');
INSERT INTO "theory_parameters" VALUES(153,'weinberg-t41i-doublet-fermions',1,NULL,'α','Integer hypercharge label of the singlet-Psi T4-1-i row',NULL,'No value selected. This representation-family parameter is distinct from flavor indices used elsewhere in the paper.','specified');
INSERT INTO "theory_parameters" VALUES(154,'su4-hypercolor-partial-compositeness',1,NULL,'f; v; xi','SU(5)/SO(5) decay constant, electroweak scale and misalignment ratio','mW=(g/2)f sin(<h>/f); v=f sin(<h>/f)=246 GeV; xi=v^2/f^2','The approximate relation xi approximately [1-(alpha/2beta)^2]/4 applies at small misalignment; it is not an exact branch-independent identity.','specified');
INSERT INTO "theory_parameters" VALUES(155,'su4-hypercolor-partial-compositeness',1,301,'M','Mass of the retained composite Dirac multiplet',NULL,'M < Lambda is assumed. The illustrative f < M < Lambda, f approximately 800 GeV and Lambda approximately 5 TeV do not fix the spectrum.','specified');
INSERT INTO "theory_parameters" VALUES(156,'su4-hypercolor-partial-compositeness',1,304,'alpha; beta','Dimensionless coefficients summarizing strong-resonance integrals in the leading Higgs-background potential',NULL,'Undetermined by the microscopic calculation. A suitable electroweak-breaking minimum requires the stated coefficient choice, not guaranteed dynamics.','unspecified_in_scope');
INSERT INTO "theory_parameters" VALUES(157,'littlest-higgs-minimal',1,NULL,'g1,g2,g1'',g2'',lambda1,lambda2,f,c,c''','Nine parameters used by the source to describe the minimal one-loop Higgs potential and couplings.',NULL,'No numerical benchmark or equality of independent gauge couplings is imposed. c and c'' encode unknown ultraviolet information and have natural size of order one. This count does not specify the unresolved individual fermion charge assignments.','specified');
INSERT INTO "theory_parameters" VALUES(158,'littlest-higgs-minimal',1,NULL,'f; Lambda','Goldstone decay constant and nonlinear EFT cutoff.',NULL,'f of order a TeV; Lambda can be as high as approximately 4pi f, of order 10 TeV. These are scale assumptions, not a fixed point or a completed ultraviolet matching.','specified');
INSERT INTO "theory_parameters" VALUES(159,'littlest-higgs-minimal',1,NULL,'lambda_t; m-prime','Source-stated light top Yukawa and heavy-quark mass.','lambda_t=lambda1 lambda2/sqrt(lambda1^2+lambda2^2); m-prime=f sqrt(lambda1^2+lambda2^2).','Use the expansion convention of Eqs. (3.12)–(3.13) and Section 8. The normalization map from the unexpanded Eq. (3.11) remains unresolved; no general complex-phase extension of these printed formulas is inferred.','specified');
INSERT INTO "theory_parameters" VALUES(160,'twin-higgs-linear-scalar-sector',1,NULL,'f','Scalar norm in the symmetry-breaking vacuum','<|H|>=m/sqrt(2lambda)=f',NULL,'specified');
INSERT INTO "theory_parameters" VALUES(161,'twin-higgs-unextended',1,NULL,'Lambda; f','Nonlinear cutoff and symmetry-breaking scale',NULL,'Lambda approximately 4pi f assumes strong coupling at the cutoff; no fixed benchmark values are imposed.','specified');
INSERT INTO "theory_parameters" VALUES(162,'twin-higgs-extended-top',1,321,'M','Common mass coefficient pairing the added exotic quarks and their partners',NULL,'Soft SU(4) breaking confined to the top sector; preserves twin interchange. No numerical mass is selected.','specified');
INSERT INTO "theory_parameters" VALUES(163,'twin-higgs-unextended',1,NULL,'M_B','Optional twin hypercharge gauge-boson mass parameter',NULL,'Optional soft twin-symmetry breaking. It is not automatically the exact physical twin-photon eigenmass. The source leaves the generating dynamics unspecified and allows them above Lambda.','specified');
INSERT INTO "theory_parameters" VALUES(164,'fraternal-twin-higgs',1,NULL,'yhat_t; ghat_2; ghat_3','Twin top Yukawa, weak coupling and color coupling at the cutoff',NULL,'Approximately match visible counterparts. Source estimates percent-level top, ten-percent weak and fifteen-percent color agreement near a 5 TeV cutoff. These are approximate naturalness criteria; signed displayed inequalities are not converted into exact two-sided bounds.','specified');
INSERT INTO "theory_parameters" VALUES(165,'fraternal-twin-higgs',1,NULL,'yhat_b; yhat_tau','Twin bottom and tau Yukawa coefficients',NULL,'Need not equal the visible values; much smaller than the top Yukawa in the source''s naturalness domain. Their masses remain free within the stated hierarchy below the twin top.','specified');
INSERT INTO "theory_parameters" VALUES(166,'fraternal-twin-higgs',1,NULL,'f; v_A; v_B','Scalar symmetry-breaking and visible/twin vacuum scales','Dominant potential uses f²/2; source alignment writes f²=v_A²+v_B² and v_A=v=246 GeV.','Use within the approximate SU(4)-dominated treatment. No exact finite-kappa, finite-sigma radial-minimum identity is inferred. f a few times v is a selected analysis hierarchy.','specified');
INSERT INTO "theory_parameters" VALUES(167,'large-extra-dimensions-framework',1,NULL,'M_Pl; M_Pl(4+n); R','Effective and fundamental gravitational scales and characteristic compactification size','M_Pl² ∼ M_Pl(4+n)^(2+n) R^n','Order-of-magnitude relation with compact volume of order R^n; exact geometric prefactors are not fixed.','specified');
INSERT INTO "theory_parameters" VALUES(168,'large-extra-dimensions-framework',1,NULL,'R','Compactification size as a parameter characterizing a solution',NULL,'Its dynamical magnitude is not calculated. Source claims of radiative stability do not supply a stabilization potential.','unspecified_in_scope');
INSERT INTO "theory_parameters" VALUES(169,'six-dimensional-pati-salam-vortex',1,NULL,'χ′; χ; Λ; H','Source notation for core scalar scales and cutoff','χ′ ∼ χ ∼ Λ ∼ 10H ∼ m_EW','Assumed soft hierarchy. No canonical six-dimensional scalar normalization or exact VEV equality is inferred.','specified');
INSERT INTO "theory_parameters" VALUES(170,'rs-two-brane-warped',1,335,'M; Lambda; k','Five-dimensional gravitational scale, bulk vacuum energy and warp curvature scale','Curvature coefficient 2M^3; Lambda=-24M^3 k^2 in the flat solution.','Lambda<0; k<M assumed for classical validity. No fixed numerical scale imposed.','specified');
INSERT INTO "theory_parameters" VALUES(171,'rs-two-brane-warped',1,NULL,'V_hid; V_vis','Brane vacuum energies','V_hid=-V_vis=24M^3 k','Flat-background tuning. Hidden positive and visible negative for k>0; no independent stabilization follows.','specified');
INSERT INTO "theory_parameters" VALUES(172,'rs-two-brane-warped',1,NULL,'r_c; mu_c','Compactification radius and inverse-radius scale','G_phi_phi=r_c^2; interval length pi r_c; mu_c=1/r_c; <T>=r_c.','Classically arbitrary integration constant. Effective discussion takes r_c>1/k and the extra dimension unresolved in gravity experiments.','specified');
INSERT INTO "theory_parameters" VALUES(173,'rs-two-brane-warped',1,339,'M_Pl','Source-defined four-dimensional gravitational scale','M_Pl^2=(M^3/k)[1-exp(-2k r_c pi)]','Derived at fixed radius using Eqs. (15)-(16); not an independent gravitational coefficient.','specified');
INSERT INTO "theory_parameters" VALUES(174,'rs-two-brane-warped',1,NULL,'v; v_0; m; m_0','Physical visible-brane scales and their input parameters','v=exp(-k r_c pi)v_0; m=exp(-k r_c pi)m_0','Measured with the effective Einstein metric after canonical field normalization. For the Higgs, the rescaled potential is lambda(|H|^2-exp(-2k r_c pi)v_0^2)^2; this reuses the same Higgs degrees of freedom.','specified');
INSERT INTO "theory_parameters" VALUES(175,'rs-two-brane-warped',1,NULL,'Massive KK coupling scale','Qualitative strength of individual massive gravitational excitations coupled to matter',NULL,'Source states dimensionless strength of order Energy/TeV in the hierarchy-generating regime. No normalized vertex, full interaction action or exact eigenfunction is supplied.','specified');
INSERT INTO "theory_parameters" VALUES(176,'ued-orbifold-framework',1,NULL,'R; Ms; delta; Mh','Common compactification radius, EFT cutoff, discrete number of universal dimensions and Higgs mass',NULL,'1/R < Ms. Delta labels alternative dimensional theories in this framework. The source''s Mh approximately at most 250 GeV is a historical perturbativity-analysis choice, not a present-day exclusion or a defining mass value.','specified');
INSERT INTO "theory_parameters" VALUES(177,'ued-orbifold-framework',1,NULL,'Mj; Dj','Compact-momentum masses and mode degeneracies','Mj=pj/R; sum_a ja^2=pj^2; pj+1>pj; j>=1','Dj counts allowed integer representatives, not new microscopic species. At delta=1, Dj=1 and Mj=j/R. Include levels only within Ms; electroweak mass shifts are additional.','specified');
INSERT INTO "theory_parameters" VALUES(178,'ued-orbifold-framework',1,NULL,'M_top^(j); alpha_j','Derived top KK masses and mixing in regime 150','Weak-basis matrix in (U3^j,Qt^j): [[-Mj,mt],[mt,Mj]]; both eigenstate masses sqrt(Mj^2+mt^2); tan(2 alpha_j)=mt/Mj','Source convention uses gamma5 factors in the weak-to-mass-basis transformation. No independent top partners or inter-level mixing are introduced.','specified');
INSERT INTO "theory_parameters" VALUES(179,'holographic-su3-brane-scalar-mediator',1,344,'MQ, MD; cQ, cD','Bulk fermion masses and localization parameters.','ci=Mi/k.','Realistic Yukawa discussion selects |MQ| and |MD| approximately no larger than k/2; these are phenomenological parameter choices.','specified');
INSERT INTO "theory_parameters" VALUES(180,'holographic-su3-brane-scalar-mediator',1,348,'M_Phi²','Bulk scalar mediator squared mass.',NULL,'Approximately -4k²; small deviations are permitted. Appropriate boundary masses are required for scalar stability.','specified');
INSERT INTO "theory_parameters" VALUES(181,'holographic-su3-brane-scalar-mediator',1,348,'m0,S; m0,D; m0,T; m1','Ultraviolet component masses and common infrared mediator mass parameter.',NULL,'The selected tree-level cancellation uses m0,D=m0,S; a desirable pattern is m0,T approximately greater than or equal to m0,S approximately equal to m0,D. This equality is not guaranteed by specified ultraviolet dynamics and is not radiatively exact.','specified');
INSERT INTO "theory_parameters" VALUES(182,'holographic-su3-brane-scalar-mediator',1,NULL,'mH²; lambda_H','Derived coefficients after integrating out Phi.','V_tree=mH²|H|²+(lambda_H/2)|H|⁴; mH²=2lambda_Phi² v²(Ghat_S-Ghat_D); lambda_H=(2/3)lambda_Phi²(8Ghat_D-5Ghat_S-3Ghat_T).','Equation (21)-(23) convention; zero-momentum infrared propagators. These are derived quantities, not extra independent ultraviolet operators. No general complex-coupling extension of the printed formula is inferred.','specified');
INSERT INTO "theory_parameters" VALUES(183,'holographic-boundary-pgb-framework',1,NULL,'g_rho; m_rho; g; f_pi; Lambda_IR','Boundary-limit resonance, gauge and Goldstone scales.','g_rho=sqrt(g5² k); m_rho=pi/L1; g²=g_rho²/ln(L1/L0); f_pi=sqrt(2)m_rho/(pi g_rho); Lambda_IR approximately 24pi² m_rho/g_rho².','Section 5 conventions. mW²=g² f_pi² refers to the (+,-) vectors made massive by strong dynamics. Coupling matching is modified by brane kinetics and large logarithmic corrections; the cutoff uses NDA.','specified');
INSERT INTO "theory_parameters" VALUES(184,'hidden-valley-chi-two-flavor',1,NULL,'q+,q−','Hidden-quark χ charges in Table I',NULL,'q++q−=−2; q+ otherwise arbitrary. The source omits q+=q−=−1. These charge choices are not fixed by its q+=−2 numerical example.','specified');
INSERT INTO "theory_parameters" VALUES(185,'hidden-valley-chi-two-flavor',1,355,'k; Qχ','Abelian mixing and the source''s redefined effective charges','Qχ=Qχ0−(k g1/g′)Y; subsequent source formulas use redefined g′ and charges.','k is free. Special B−L-like choices do not remove hidden matter or turn this model into the existing pure minimal B−L construction.','specified');
INSERT INTO "theory_parameters" VALUES(186,'hidden-valley-chi-two-flavor',1,NULL,'nv; Λv; g′; gv','Hidden gauge rank, confinement scale and additional gauge couplings',NULL,'Source omits nv=2 and discusses 1 GeV<Λv<1 TeV. Numerical nv=3 is illustrative, not a fixed inventory. No equality of g′ and gv is imposed.','specified');
INSERT INTO "theory_parameters" VALUES(187,'hidden-valley-colored-x-framework',1,NULL,'mX','Heavy colored mediator mass scale',NULL,'Source discusses approximately 0.5–3 TeV. Its 1 TeV lifetime example does not select a fixed mass or complete mediator spectrum.','specified');
INSERT INTO "theory_parameters" VALUES(188,'secluded-dirac-u1-higgsed',1,359,'κ; β','Kinetic mixing; β=(κe''/(e cosθW))²',NULL,'Small β defines the secluded analysis, not the entire structural parameter space. κ=0 is a conditional limit.','specified');
INSERT INTO "theory_parameters" VALUES(189,'secluded-fermion-scalar-portal',1,364,'λ2','Quadratic Higgs portal coefficient',NULL,'Take λ2→0 for the illustrative Higgs-mixing analysis; no symmetry prohibition or exact all-scale absence is established.','specified');
INSERT INTO "theory_parameters" VALUES(190,'simp-sp-pions',1,NULL,'fpi; mpi; mQ; mu','Pion decay constant, degenerate pion mass, quark mass coefficient and condensate scale','Tr(Ta Tb)=2 delta_ab; Sigma=exp(2i pi/fpi)J; mpi^2=8mQ mu^3/fpi^2.','Leading flavor-preserving matching. No numerical mass or relic-density benchmark is imposed.','specified');
INSERT INTO "theory_parameters" VALUES(191,'simp-sp-pions',1,NULL,'Nc=Nf=2','Scoped minimal member',NULL,'Sp(2) is isomorphic to SU(2); four fundamental Weyl fermions give five pions in the Sp(4) 5-plet. SU(4)/Sp(4) is topologically S^5. This is a member selection, not a restriction on the entire class.','specified');
INSERT INTO "theory_parameters" VALUES(192,'simp-su-pions',1,NULL,'fpi; mpi','Pion decay constant and degenerate pion mass','Source uses Eq. (12) with J replaced by the identity in its matching prescription.','The source changes the sign in Eq. (11); no universal positive-mQ convention or exact microscopic mass matrix is inferred.','specified');
INSERT INTO "theory_parameters" VALUES(193,'simp-o-pions',1,NULL,'fpi; mpi','Pion decay constant and degenerate pion mass','Source uses Eq. (12) with J replaced by the identity in its matching prescription.','The source changes the sign in Eq. (11); spinor conventions and a positive-mass microscopic prescription remain unresolved.','specified');
INSERT INTO "theory_parameters" VALUES(194,'vector-higgs-portal-z2-eft',1,NULL,'m_X; m; lambda_hv; v','Physical vector mass and its electroweak contribution','m_X²=m²+lambda_hv v²/2; H^0=v+h/sqrt(2); v=174 GeV','The portal contribution may have either sign in the stated Stückelberg examples. No benchmark mass is imposed.','specified');
INSERT INTO "theory_parameters" VALUES(195,'vector-portal-stueckelberg-higgs',1,381,'mu; M; zeta; lambda_hv','Direct mass-function parameters and derived portal coefficient','m²(H)=mu²(1+zeta H†H/M²); lambda_hv=2zeta mu²/M²','mu and M need not be related to each other or the electroweak scale.','specified');
INSERT INTO "theory_parameters" VALUES(196,'vector-portal-stueckelberg-scalar',1,NULL,'lambda_hv','Tree-level vector portal after heavy-S elimination','lambda_hv=2lambda_hs mu²<S>²/(M²m_S²)','Requires m_h²,m_X² much smaller than m_S². The source also writes 2lambda_hs m_X²/m_S²; its treatment of the electroweak mass shift is left qualified. Loop contributions make the low-energy coupling cutoff dependent.','specified');
INSERT INTO "theory_parameters" VALUES(197,'vector-portal-stueckelberg-scalar',1,NULL,'c_X4','Induced coefficient of (X_mu X^mu)² in the reduced Lagrangian','c_X4=mu⁴<S>²/(2M⁴m_S²)','Tree-level heavy-S matching. This coefficient is not set to zero by the distinct origin-independent phenomenological scan.','specified');
INSERT INTO "theory_parameters" VALUES(198,'vector-portal-abelian-higgs',1,NULL,'g; lambda_S','Hidden gauge coupling and singlet self-interaction used in the hierarchy discussion',NULL,'The source selects g² much smaller than lambda_S to keep the vector light relative to the hidden Higgs. No complete potential normalization or numerical values are supplied.','specified');
INSERT INTO "theory_parameters" VALUES(199,'silh-hww-operator-sector',1,NULL,'cH, cW, cHW','Free coefficients of the three displayed dimension-six operators','Use exactly the prefactors of Eq. (5.1), including gρ² and 16π².','No benchmark values or additional reality restrictions imposed.','specified');
INSERT INTO "theory_parameters" VALUES(200,'silh-hww-operator-sector',1,NULL,'f, g, gρ, v, ξ','Operator suppression scale, weak coupling, new strong coupling, neutral Higgs vacuum parameter and expansion parameter','ξ=v²/f²; v is the source''s neutral Higgs-doublet vacuum parameter.','No numerical scale or vacuum solution imposed. The strong coupling does not introduce an explicitly retained new gauge field. No independent conversion between g and the gw notation of Eq. (5.2) is asserted.','specified');
INSERT INTO "theory_parameters" VALUES(201,'smeft-d6-b-conserving',1,NULL,'C_k^(5), C_k^(6); Lambda','Dimensionless Wilson coefficients and the effective expansion scale','Each dimension-n operator multiplies C_k^(n)/Lambda^(n-4). Canonical dimensions count fields and derivatives without dimensionful couplings.','No numerical matching or common-coefficient hierarchy is selected. Coefficients require an underlying theory for UV matching; independent basis types do not each identify a unique UV model.','specified');
INSERT INTO "theory_parameters" VALUES(202,'general-heavy-field-tree-matching',1,NULL,'C_j^(n)','Heavy-field contributions multiplying local operators O_j^(n)','L_eff=L0+sum_n,j C_j^(n) O_j^(n); C_j^(n) has mass dimension 4-n','These contributions are not necessarily the complete coefficients when L0 already contains the same operators.','specified');
INSERT INTO "theory_parameters" VALUES(203,'general-heavy-field-tree-matching',1,NULL,'Zphi','Low-energy Higgs kinetic normalization','phi -> Zphi^(-1/2) phi; an operator with n_phi Higgs fields receives Zphi^(-n_phi/2)','Nontrivial only when gamma_L1 is nonzero. The selected isolated S, renormalizable N and single-W examples do not acquire this effect without L1.','specified');
INSERT INTO "theory_regime_relations" VALUES(1,'real-singlet-z2',1,1,2,'finite_temperature_application','Same underlying scalar operators; the singlet quartic becomes relevant to the thermal phase structure. No complete thermal effective potential or phase sequence is reconstructed.','provisional');
INSERT INTO "theory_regime_relations" VALUES(2,'mchm-spinorial',1,11,10,'holographic_effective_action_matching','Integrating out the bulk at fixed UV values yields the quadratic boundary action of Eq. (9) and low-energy description (11). This matches effective descriptions, not an identified microscopic strong theory.','provisional');
INSERT INTO "theory_regime_relations" VALUES(3,'mchm-spinorial',1,11,12,'alternative_holographic_source_choice','Fix the left-handed ξu component instead of the principal right-handed source. The alternative organization is used to explain the light custodial partner.','provisional');
INSERT INTO "theory_regime_relations" VALUES(4,'mchm-spinorial-scalar14',1,14,13,'holographic_scalar_deformation_realization','The bulk scalar with an IR singlet tadpole realizes the scalar-source potential. UV Neumann and Dirichlet choices correspond to dynamical and auxiliary sources respectively.','provisional');
INSERT INTO "theory_regime_relations" VALUES(5,'georgi-machacek-general',1,15,16,'parameter_decoupling_limit','The same potential yields increasingly heavy and degenerate extra scalars and SM limits for the light-Higgs couplings. No additional model identity or complete low-energy EFT matching is implied.','provisional');
INSERT INTO "theory_regime_relations" VALUES(6,'sm-octet-doublet-mfv',1,19,20,'heavy_field_integration','One-loop heavy-octet expansion for Higgs observables; the calculation''s CP assumption is scoped to this regime.','provisional');
INSERT INTO "theory_regime_relations" VALUES(7,'su5-gg-extra5-two10',1,36,37,'assumed_light_component_spectrum','The two doublets and two Rtilde2 multiplets are components of the unified scalars under the desert assumption. No full threshold matching or complete low-energy action is asserted.','provisional');
INSERT INTO "theory_regime_relations" VALUES(8,'ql421-dirac',1,55,56,'subgroup_component_decomposition','χ breaking exposes the SM representations of Φ and Aμ. Components are not additional independent unified multiplets; no threshold matching is supplied.','provisional');
INSERT INTO "theory_regime_relations" VALUES(9,'ql421-inverse-seesaw',1,57,58,'hierarchical_mass_and_phenomenological_regime','Same field and interaction specification evaluated in the source''s inverse-seesaw hierarchy and conditional scale examples.','provisional');
INSERT INTO "theory_regime_relations" VALUES(10,'su5-adjoint-renormalizable',1,59,60,'threshold_parameter_application','The component masses used in descriptions 95–97 belong to the unified multiplets of regime 59. No independent low-energy field addition or fully matched EFT is asserted.','provisional');
INSERT INTO "theory_regime_relations" VALUES(11,'so10-45-126-sector',1,61,62,'threshold_parameter_application','Tune one existing 126H component light and select the associated hierarchical VEV region. No additional unified multiplet or fully matched low-energy EFT is specified.','provisional');
INSERT INTO "theory_regime_relations" VALUES(12,'so10-45-126-sector',1,61,63,'threshold_parameter_application','Lower one existing octet-doublet eigenstate through the same potential parameters; this is not an independent octet-scalar extension.','provisional');
INSERT INTO "theory_regime_relations" VALUES(13,'mssm-minimal-gauge-messengers',1,72,73,'leading_messenger_threshold_matching','Messenger loops generate the MSSM gaugino and scalar soft coefficients near M_mess. Leading expressions require small splitting; subsequent RG running changes the input relations. No complete higher-order EFT matching is supplied.','provisional');
INSERT INTO "theory_regime_relations" VALUES(14,'mssm-rpc-conventional-soft',1,67,68,'conditional_soft_parameter_restriction','Weak universality is an optional high-scale restriction on the same conventional soft coefficients, not a different field inventory.','provisional');
INSERT INTO "theory_regime_relations" VALUES(15,'mssm-rpc-conventional-soft',1,67,69,'conditional_universal_boundary_restriction','The source''s MSUGRA/CMSSM description specifies relations among existing soft coefficients. It does not select a complete supergravity model.','provisional');
INSERT INTO "theory_regime_relations" VALUES(16,'mssm-rpc-conventional-soft',1,67,70,'conditional_rg_trajectory','Pure AMSB selects scale-dependent values of existing soft coefficients. No 5D geometry or boundary conditions are intrinsic to this trajectory record.','provisional');
INSERT INTO "theory_regime_relations" VALUES(17,'mssm-rpc-conventional-soft',1,70,71,'phenomenological_scalar_mass_modification','An added common m0² repairs the pure trajectory phenomenologically at an unspecified input scale; it is an additional assumption and need not preserve pure-AMSB RG invariance.','provisional');
INSERT INTO "theory_regime_relations" VALUES(18,'mssm-rpv-general',1,74,78,'conditional_classical_parameter_restriction','The trilinear-only input ansatz generally leaves its zero-bilinear locus under quantum corrections. It is not a separate all-scale quantum specification.','provisional');
INSERT INTO "theory_regime_relations" VALUES(19,'split-susy',1,83,82,'heavy_scalar_decoupling_and_matching','Integrate out sfermions and the heavy Higgs direction at mtilde. Project the parent Higgs fields and impose Eqs. (22)–(25); the equalities are threshold conditions, not identities at every lower scale.','provisional');
INSERT INTO "theory_regime_relations" VALUES(20,'split-susy',1,82,84,'conditional_mass_boundary_application','Unified gaugino masses and the plotted threshold choices restrict parameters without altering the defining EFT.','provisional');
INSERT INTO "theory_regime_relations" VALUES(21,'split-susy',1,82,85,'conditional_mass_boundary_application','Equation (33) supplies a gaugino boundary at mtilde, not an all-scale nonsupersymmetric AMSB trajectory.','provisional');
INSERT INTO "theory_regime_relations" VALUES(22,'split-susy',1,82,86,'conditional_zero_mu_boundary_application','The zero input mu condition can accompany either mass-boundary scenario; its radiative result does not define an additional model.','provisional');
INSERT INTO "theory_regime_relations" VALUES(23,'gem-supersoft',1,87,88,'conditional_minimal_Dirac_limit','Zero adjoint-bilinear and superpotential-mass coefficients select the minimal limit without removing independent adjoint multiplets.','provisional');
INSERT INTO "theory_regime_relations" VALUES(24,'gem-supersoft',1,87,89,'heavy_adjoint_integration','A large supersymmetric ESP mass produces a low-energy Majorana-gaugino description. The additional R breaking is not attributed to the D source alone.','provisional');
INSERT INTO "theory_regime_relations" VALUES(25,'gem-supersoft-messengers',1,90,93,'messenger_threshold_matching','The displayed messenger threshold generates both supersoft operators; exact matching and complete messenger charges are unspecified.','provisional');
INSERT INTO "theory_regime_relations" VALUES(26,'ksvz-neutral-triplet',1,97,98,'heavy_quark_anomaly_matching','The axial Q redefinition and integration below m_Q yield Eq. (82); the radial scalar is neglected. This is an effective description of the same construction.','provisional');
INSERT INTO "theory_regime_relations" VALUES(27,'smash-down',1,102,103,'heavy_particle_integration','Heavy singlet neutrinos generate seesaw masses; heavy colored fermions generate anomalous axion couplings. The angular mode survives radial-scalar removal. No complete higher-order EFT operator basis is reconstructed.','provisional');
INSERT INTO "theory_regime_relations" VALUES(28,'smash-down',1,102,104,'conditional_inflation_and_cosmology_application','Negative-portal mixed valley of the same scalar theory. Reheating, PQ restoration, axion abundance and leptogenesis impose correlated additional conditions.','provisional');
INSERT INTO "theory_regime_relations" VALUES(29,'smash-down',1,102,105,'conditional_inflationary_trajectory','Positive-portal pure-singlet inflation is a parameter and trajectory choice, not a new field inventory.','provisional');
INSERT INTO "theory_regime_relations" VALUES(30,'smash-down',1,102,106,'conditional_cosmological_branch','Changes fA and the post-inflationary PQ history within the same construction; source exclusion is conditional on axion dark-matter saturation.','provisional');
INSERT INTO "theory_regime_relations" VALUES(31,'smash-down',1,102,107,'scoped_scan_restriction','The vanishing quark mixing and neutrino ansatz are numerical simplifications only. They do not remove the corresponding operators from the general specification.','provisional');
INSERT INTO "theory_regime_relations" VALUES(32,'lns-two-singlet-quarks',1,109,108,'heavy_quark_integration','The source states that integrating out the heavy fields in the 6×6 and 8×8 matrices (7.7)–(7.8) yields (7.3). This records leading texture matching, not exact Wilson coefficients. Basis-choice mass zeros are distinguished from holomorphic zeros.','provisional');
INSERT INTO "theory_regime_relations" VALUES(33,'lns-reduced-quarks',1,111,112,'reduced_heavy_quark_integration','The selected U1,D3,D4 pairs generate the reduced textures summarized in (9.3), following the removals and charge changes on page 20. No exact coefficient matching or unrestricted all-orders texture claim.','provisional');
INSERT INTO "theory_regime_relations" VALUES(34,'grv-quark-flavor-u3',1,116,117,'heavy_exotic_fermion_integration','Equation (2.5) gives leading effective Yukawas proportional to inverse flavon VEVs. This approximation does not replace exact third-family diagonalization or specify a complete matched EFT.','provisional');
INSERT INTO "theory_regime_relations" VALUES(35,'numsm',1,120,121,'conditional_seesaw_and_dark_matter_application','Retains the same fields and operators while selecting M_I much larger than Dirac masses and the adopted N1 dark-matter abundance scenario.','provisional');
INSERT INTO "theory_regime_relations" VALUES(36,'numsm',1,121,122,'conditional_perturbative_cosmological_application','Adds cosmological initial conditions, kinetic approximations and illustrative normal-hierarchy choices within the dark-matter-compatible domain. The source presents an existence calculation, not a separate model.','provisional');
INSERT INTO "theory_regime_relations" VALUES(37,'ma-radiative-seesaw-z2',1,123,124,'conditional_mass_ordering_application','Fermionic dark matter selects an odd-sector hierarchy without removing any fields or operators.','provisional');
INSERT INTO "theory_regime_relations" VALUES(38,'ma-radiative-seesaw-z2',1,123,125,'conditional_mass_ordering_application','Bosonic dark matter selects a neutral-scalar ordering while retaining the singlets and their radiative neutrino-mass interactions.','provisional');
INSERT INTO "theory_regime_relations" VALUES(39,'su4-hypercolor-partial-compositeness',1,129,130,'conditional_strong_dynamics_infrared_realization','The proposed flavor breaking supplies the pNGB manifold. Table 3 organizes four Dirac partner channels, of which one is assumed light. This is a source-motivated realization, not a calculated nonperturbative matching or a proof of its spectrum.','provisional');
INSERT INTO "theory_regime_relations" VALUES(40,'littlest-higgs-minimal',1,131,132,'heavy_particle_integration','Triplet elimination produces the leading Higgs quartic; heavy-quark elimination leaves the top Yukawa. Heavy scalar and vector exchange also produces higher-dimensional effects, so the SM spectrum does not imply an exactly pure renormalizable SM action.','provisional');
INSERT INTO "theory_regime_relations" VALUES(41,'fraternal-twin-higgs',1,137,138,'heavy_threshold_effective_matching','Eliminate the radial scalar using Eq. (18); twin-bottom Yukawa produces Eq. (36), and twin-top loops generate Eqs. (37)–(38). These are derived portals of the same model.','provisional');
INSERT INTO "theory_regime_relations" VALUES(42,'fraternal-twin-higgs',1,137,139,'conditional_confining_infrared_description','For heavy twin colored fermions the infrared twin-color theory is pure SU(3), producing glueballs. This does not add an independent pure-glue model.','provisional');
INSERT INTO "theory_regime_relations" VALUES(43,'fraternal-twin-higgs',1,137,140,'conditional_quarkonium_infrared_description','The microscopic twin bottom forms bottomonium. Absence of light twin flavors removes ordinary open-bottom meson channels; masses and available decays select phenomenological regimes.','provisional');
INSERT INTO "theory_regime_relations" VALUES(44,'large-extra-dimensions-framework',1,141,142,'compactification_KK_description','The KK tower describes the same bulk gravitational degrees of freedom in four-dimensional language, not an additional independent gravitational sector.','provisional');
INSERT INTO "theory_regime_relations" VALUES(45,'rs-two-brane-warped',1,144,145,'compactification_and_fixed_radius_effective_description','Zero modes reorganize the same bulk metric. Integrating over phi at T=r_c gives the effective gravitational coefficient and visible-brane rescaling. Massive-mode matching is only qualitatively stated.','provisional');
INSERT INTO "theory_regime_relations" VALUES(46,'ued-orbifold-framework',1,146,147,'discrete_dimension_specialization','Set delta=1 and use the unpaired S1/Z2 factor. Specialize the same bulk species and operator assignments; this is not a continuous parameter limit of a fixed six-dimensional theory.','provisional');
INSERT INTO "theory_regime_relations" VALUES(47,'ued-orbifold-framework',1,146,148,'discrete_dimension_specialization','Set delta=2 and retain the displayed six-dimensional chiral choice and paired-coordinate projection. No anomaly-completing sector is inherited from another model.','provisional');
INSERT INTO "theory_regime_relations" VALUES(48,'ued-orbifold-framework',1,146,149,'iterative_dimensional_extension','Apply only the source''s odd/even-dimensional spinor and iterative compactification prescription; full component interactions remain unspecified.','provisional');
INSERT INTO "theory_regime_relations" VALUES(49,'ued-orbifold-framework',1,146,150,'compactification_KK_description','For a selected dimensional member, integrate the bulk action over its compact space and expand into zero modes and repeated nonzero modes. No new microscopic generations are added.','provisional');
INSERT INTO "theory_regime_relations" VALUES(50,'holographic-boundary-pgb-framework',1,152,153,'holographic_correspondence','Bulk boundary breaking corresponds to global G breaking to H1 in the CFT with elementary H0 gauging. Uneaten Goldstones correspond to the A5 zero modes.','provisional');
INSERT INTO "theory_regime_relations" VALUES(51,'holographic-boundary-pgb-framework',1,152,154,'scoped_equal_boundary_fermion_example','Select H0=H1=H and add the section 4.1 fermion with its stated boundary assignments. This example is not mandatory matter content for every framework member.','provisional');
INSERT INTO "theory_regime_relations" VALUES(52,'hidden-valley-chi-two-flavor',1,156,157,'conditional_confining_description','Select two light hidden flavors. Hidden hadrons reorganize the existing constituents; no added elementary fields.','provisional');
INSERT INTO "theory_regime_relations" VALUES(53,'hidden-valley-chi-two-flavor',1,156,158,'conditional_confining_description','Select one light and one heavy hidden flavor. Source spectrum expectations are not a demonstrated nonperturbative matching.','provisional');
INSERT INTO "theory_regime_relations" VALUES(54,'hidden-valley-chi-two-flavor',1,156,159,'heavy_quark_confining_limit','Both hidden quarks are heavy relative to confinement. This retains the same microscopic portal theory.','provisional');
INSERT INTO "theory_regime_relations" VALUES(55,'hidden-valley-colored-x-framework',1,160,161,'heavy_mediator_loop_matching','Integrating out heavy jointly charged X induces dimension-eight gluonic operators; exact matching coefficients are unspecified.','provisional');
INSERT INTO "theory_regime_relations" VALUES(56,'hidden-valley-colored-x-framework',1,161,162,'confining_infrared_description','Hidden gluons form metastable glueballs that decay through the induced operator set. No complete hadronic matrix-element matching is reconstructed.','provisional');
INSERT INTO "theory_regime_relations" VALUES(57,'secluded-dirac-u1-higgsed',1,166,167,'conditional_coupling_and_vacuum_limit','Change κ and the symmetry-breaking background without inferring removal of φ.','provisional');
INSERT INTO "theory_regime_relations" VALUES(58,'secluded-neutrino-portal-z2',1,169,170,'conditional_mass_hierarchy_application','Select N'' as the lighter odd state.','provisional');
INSERT INTO "theory_regime_relations" VALUES(59,'secluded-neutrino-portal-z2',1,169,171,'conditional_mass_hierarchy_application','Select S as the lighter odd state; no Yukawa replacement.','provisional');
INSERT INTO "theory_regime_relations" VALUES(60,'simp-sp-pions',1,172,173,'conditional_confining_chiral_description','Assumed condensate supplies the pion coset; the flavor-preserving mass gives pseudo-Goldstone masses. Pions reorganize microscopic degrees of freedom.','provisional');
INSERT INTO "theory_regime_relations" VALUES(61,'simp-su-pions',1,174,175,'conditional_confining_chiral_description','Apply the source''s q qbar and J-to-identity matching prescription. Heavy baryons and resonances are omitted conditionally; no complete nonperturbative matching is established.','provisional');
INSERT INTO "theory_regime_relations" VALUES(62,'simp-o-pions',1,176,177,'conditional_confining_chiral_description','Apply the source''s assumed coset and J-to-identity prescription, preserving the unresolved microscopic spinor convention.','provisional');
INSERT INTO "theory_regime_relations" VALUES(63,'vector-higgs-portal-z2-eft',1,178,182,'conditional_phenomenological_application','The quartic-zero choice and thermal relic assumptions restrict the analysis, without removing the symmetry-allowed quartic from the general EFT.','provisional');
INSERT INTO "theory_regime_relations" VALUES(64,'general-heavy-field-tree-matching',1,186,187,'classical_heavy_field_matching','Eliminate heavy fields using classical equations of motion and expand covariant propagators in D/M through local operators of dimension six. This does not identify all UV inventories yielding the same infrared operators.','provisional');
INSERT INTO "theory_regime_relations" VALUES(65,'sm-singlet-neutrino-framework',1,119,189,'heavy_mass_matching_application','Apply the P50 renormalizable N restriction to the existing variable-N Yukawa and Majorana sector. Four-component Majorana notation is a field organization; the heavy hierarchy selects a matching application rather than a new inventory.','provisional');
INSERT INTO "theory_regimes" VALUES(1,'real-singlet-z2',1,NULL,'Renormalizable electroweak-scale description, including its expansion about the chosen vacuum','Retain renormalizable operators; neglect nonrenormalizable couplings','S is the only new electroweak-scale degree of freedom. Broken-phase expressions refer to the chosen S = 0 vacuum.',NULL);
INSERT INTO "theory_regimes" VALUES(2,'real-singlet-z2',1,NULL,'Finite-temperature electroweak-transition application',NULL,'P02 Section 6.1 applies the same scalar construction with a relevant singlet quartic and temporary Z2 breaking. The detailed finite-temperature procedure and numerical scan domain remain unresolved.',NULL);
INSERT INTO "theory_regimes" VALUES(3,'complex-singlet-portal',1,NULL,'Minimal complex-singlet generalization in P02 Section 6.4',NULL,'Restricted to the stated case with no additional interactions and the displayed mass and portal terms; Eq. (26) is not treated as a complete potential.',NULL);
INSERT INTO "theory_regimes" VALUES(4,'thdm-type-i-real-z2',1,NULL,'Chapter 2 symmetry-basis description with the restricted scalar potential','Scalar potential through quartic order and defining Yukawa assignments','Early-chapter real-potential and neutral CP-conserving-vacuum scope. No UV completion or numerical validity scale is specified.',NULL);
INSERT INTO "theory_regimes" VALUES(5,'thdm-type-ii-real-z2',1,NULL,'Chapter 2 symmetry-basis description with the restricted scalar potential','Scalar potential through quartic order and defining Yukawa assignments','Early-chapter real-potential and neutral CP-conserving-vacuum scope. No UV completion or numerical validity scale is specified.',NULL);
INSERT INTO "theory_regimes" VALUES(6,'lr-triplet-parity',1,NULL,'Minimal LR gauge-basis description and its stated symmetry-breaking vacuum',NULL,'Section 2 P implementation. Only displayed structural sectors are enumerated; no complete potential or effective matching calculation is inferred.',NULL);
INSERT INTO "theory_regimes" VALUES(7,'lr-triplet-charge-conjugation',1,NULL,'Minimal LR gauge-basis description and its stated symmetry-breaking vacuum',NULL,'Section 2 C implementation. Only displayed structural sectors are enumerated; no SO(10) completion or complete potential is inferred.',NULL);
INSERT INTO "theory_regimes" VALUES(8,'nmssm-general-rpc-cpc',1,NULL,'Section 2.1 superfield description with component soft terms and tree-level neutral-vacuum expansion','Renormalisable superpotential and displayed soft supersymmetry breaking','R-parity and CP conserved in the scoped discussion; no numerical validity cutoff specified.',NULL);
INSERT INTO "theory_regimes" VALUES(9,'nmssm-z3-rpc-cpc',1,NULL,'Section 2.1 cubic-superpotential restriction with component soft terms','Renormalisable cubic superpotential and surviving soft supersymmetry breaking','Same R-parity and CP scope as the general construction; six defining zero coefficients.',NULL);
INSERT INTO "theory_regimes" VALUES(10,'mchm-spinorial',1,'4','Symmetry-based strong-sector and external-source description','Quadratic external-field form-factor action and its low-energy expansion','Large N; high-energy conformality and an infrared mass gap. Form factors are not perturbatively calculable from this 4D account. Nondynamical completion sources do not add physical elementary particles.',NULL);
INSERT INTO "theory_regimes" VALUES(11,'mchm-spinorial',1,'5','Weakly coupled AdS interval realization',NULL,'5D perturbative description with a strong cutoff; not a microscopic 4D completion.','ds²=(kz)⁻²(ημν dxμ dxν−dz²), L0≤z≤L1; L0=1/k∼1/MPl; L1∼1/TeV. The source''s intervening L1–μIR equality is not adopted.');
INSERT INTO "theory_regimes" VALUES(12,'mchm-spinorial',1,'4','Alternative left-handed ξu holographic source description',NULL,'Section 4 light-b′ discussion: before external mixing, composite massless tR and b′R form an SU(2)R doublet. External bcL′ pairs with b′R. Its coupling becomes marginal at cu=1/2 and irrelevant above it. These assignments describe the same 5D fields through a different source choice.',NULL);
INSERT INTO "theory_regimes" VALUES(13,'mchm-spinorial-scalar14',1,'4','Scalar-source deformation of the inherited strong-sector description','Dimension-two operators coupled to scalar sources; induced marginal double-trace deformation','SO(4)-invariant source masses are chosen for simplicity. Sources can be dynamical or auxiliary; no universal choice is imposed.',NULL);
INSERT INTO "theory_regimes" VALUES(14,'mchm-spinorial-scalar14',1,'5','Bulk scalar realization of the source deformation',NULL,'Additional bulk SO(5) 14 scalar with MΦ²=−4k² and an IR SO(4)-singlet tadpole; the complete scalar boundary action is unspecified.','Inherited AdS interval with UV and IR boundaries.');
INSERT INTO "theory_regimes" VALUES(15,'georgi-machacek-general',1,NULL,'Electroweak scalar description and expansion about a custodial-aligned vacuum','General gauge- and custodial-invariant tree-level scalar potential through quartic order','Custodial symmetry organizes the tree-level scalar potential and aligned spectrum. Hypercharge interactions violate it; no exact custodial symmetry of the full quantum theory or numerical ultraviolet cutoff is asserted.',NULL);
INSERT INTO "theory_regimes" VALUES(16,'georgi-machacek-general',1,NULL,'Large-positive-μ3² decoupling expansion of the same scalar construction','Asymptotic expansions in inverse powers of μ3=√μ3²; no matched effective-operator basis is specified','Fixed weak scale, μ3²≫λiv², perturbative quartics and M1,M2 of order μ3 or smaller, subject to an acceptable aligned minimum. Case A holds M1,M2 fixed; case B scales both with μ3.',NULL);
INSERT INTO "theory_regimes" VALUES(17,'threedm-d6',1,NULL,'Scalar symmetry-basis description before selecting a vacuum','Renormalizable quadratic and quartic scalar potential','Kinetic-term-preserving Higgs-family transformations are counted modulo gauge-trivial overall phases in PSU(3). Generalized CP enlarges the classification domain to PSU(3) ⋊ Z2*. Exact finite-group claims require generic coefficients avoiding larger-symmetry loci.',NULL);
INSERT INTO "theory_regimes" VALUES(18,'threedm-d8',1,NULL,'Scalar symmetry-basis description before selecting a vacuum','Renormalizable quadratic and quartic scalar potential','The same potential is examined in PSU(3) and PSU(3) ⋊ Z2*. Its generic unitary group is D8 and its generic full group is D8 × Z2*. Enhanced finite or continuous parameter loci are outside the exact-group claim.',NULL);
INSERT INTO "theory_regimes" VALUES(19,'sm-octet-doublet-mfv',1,NULL,'Section III gauge-basis construction and electroweak vacuum expansion','Renormalizable scalar potential and quark Yukawa interactions','One added octet doublet with proportional quark Yukawa matrices. No general CP-conservation or custodial restriction.',NULL);
INSERT INTO "theory_regimes" VALUES(20,'sm-octet-doublet-mfv',1,NULL,'Heavy-octet Higgs effective-operator calculation','One-loop integration of the octet; displayed Higgs corrections through dimension six','v²/m_S² significantly below unity. CP conservation is assumed for the displayed operator corrections, without restricting the general Section III construction.',NULL);
INSERT INTO "theory_regimes" VALUES(21,'sm-octet-doublet-mfv-triplets',1,NULL,'Section VIII additional-triplet description','Displayed renormalizable triplet operators supplement the inherited octet-doublet construction','Three real weak triplets with approximate sign symmetry. Eq. (42) is retained as a displayed operator set, without declaring unlisted operators absent.',NULL);
INSERT INTO "theory_regimes" VALUES(22,'vlq-t-singlet',1,NULL,'Weak-eigenstate description with electroweak VEV inserted','Renormalisable mixing; scalar sector contains only SU(2)L doublets','One extra multiplet, with third-family-only mixing approximation. No additional new-physics contribution is assumed for the electroweak fits. Eq. (4) uses v=246 GeV; this is not an unbroken-phase operator inventory.',NULL);
INSERT INTO "theory_regimes" VALUES(23,'vlq-b-singlet',1,NULL,'Weak-eigenstate description with electroweak VEV inserted','Renormalisable mixing; scalar sector contains only SU(2)L doublets','One extra multiplet, with third-family-only mixing approximation. No additional new-physics contribution is assumed for the electroweak fits. Eq. (4) uses v=246 GeV.',NULL);
INSERT INTO "theory_regimes" VALUES(24,'vlq-xt-doublet',1,NULL,'Weak-eigenstate description with electroweak VEV inserted','Renormalisable mixing; scalar sector contains only SU(2)L doublets','One extra multiplet, with third-family-only mixing approximation. No additional new-physics contribution is assumed for the electroweak fits. Eq. (4) uses v=246 GeV.',NULL);
INSERT INTO "theory_regimes" VALUES(25,'vlq-tb-doublet',1,NULL,'Weak-eigenstate description with electroweak VEV inserted','Renormalisable mixing; scalar sector contains only SU(2)L doublets','One extra multiplet, with third-family-only mixing approximation. No additional new-physics contribution is assumed for the electroweak fits. Eq. (4) uses v=246 GeV.',NULL);
INSERT INTO "theory_regimes" VALUES(26,'vlq-by-doublet',1,NULL,'Weak-eigenstate description with electroweak VEV inserted','Renormalisable mixing; scalar sector contains only SU(2)L doublets','One extra multiplet, with third-family-only mixing approximation. No additional new-physics contribution is assumed for the electroweak fits. Eq. (4) uses v=246 GeV.',NULL);
INSERT INTO "theory_regimes" VALUES(27,'vlq-xtb-triplet',1,NULL,'Weak-eigenstate spherical-basis triplet description with electroweak VEV inserted','Renormalisable mixing; scalar sector contains only SU(2)L doublets','One extra multiplet, with third-family-only mixing approximation. No additional new-physics contribution is assumed for the electroweak fits. Eq. (4) uses v=246 GeV.',NULL);
INSERT INTO "theory_regimes" VALUES(28,'vlq-tby-triplet',1,NULL,'Weak-eigenstate spherical-basis triplet description with electroweak VEV inserted','Renormalisable mixing; scalar sector contains only SU(2)L doublets','One extra multiplet, with third-family-only mixing approximation. No additional new-physics contribution is assumed for the electroweak fits. Eq. (4) uses v=246 GeV.',NULL);
INSERT INTO "theory_regimes" VALUES(29,'lq-r2-general',1,NULL,'Single scalar LQ in the SM gauge basis','Renormalizable fermion interactions and displayed bosonic operators','No selected flavor texture, vacuum or ultraviolet completion.',NULL);
INSERT INTO "theory_regimes" VALUES(30,'lq-rtilde2-nur',1,NULL,'Eq. (5) scalar-LQ description with three nuR fields','Renormalizable displayed interactions','Both Yukawa matrices retained. No neutrino mass mechanism or complete scalar potential is fixed.',NULL);
INSERT INTO "theory_regimes" VALUES(31,'lq-u3-effective',1,NULL,'Single massive-vector effective description','Displayed dimension-four currents and bosonic terms','Explicit-mass formulation is not a renormalizable ultraviolet theory; loop predictions require completion information.',NULL);
INSERT INTO "theory_regimes" VALUES(32,'lq-utilde1-effective',1,NULL,'Single massive-vector effective description','Displayed dimension-four currents and bosonic terms','No ultraviolet cutoff or gauge completion is specified.',NULL);
INSERT INTO "theory_regimes" VALUES(33,'lq-u1-effective',1,NULL,'Section 1.12 SM-fermion branch','Displayed vector currents and bosonic terms','No added right-chiral neutrinos in this branch; no Pati–Salam coupling restrictions imposed.',NULL);
INSERT INTO "theory_regimes" VALUES(34,'lq-ubar1-nur-effective',1,NULL,'Neutrino-dependent massive-vector effective description','Displayed RR current and bosonic terms','At least one nuR field is required; its mass sector and ultraviolet completion are unspecified.',NULL);
INSERT INTO "theory_regimes" VALUES(35,'su5-georgi-glashow-review',1,NULL,'Unified gauge description and stated breaking pattern',NULL,'Review-level inventory; no reconstructed full action or minimum calculation.',NULL);
INSERT INTO "theory_regimes" VALUES(36,'su5-gg-extra5-two10',1,NULL,'Unified additional-scalar description',NULL,'Inherited GG content plus one scalar 5 and two scalar 10s. Exact scalar contractions remain unresolved.',NULL);
INSERT INTO "theory_regimes" VALUES(37,'su5-gg-extra5-two10',1,NULL,'Assumed light spectrum below the unified scale',NULL,'Desert hypothesis: two Higgs doublets and two Rtilde2 multiplets are light; remaining non-SM components are superheavy. This is not a complete matched EFT.',NULL);
INSERT INTO "theory_regimes" VALUES(38,'su5-gg-scalar15',1,NULL,'Unified scalar-15 extension and stated neutral-component vacuum',NULL,'Review-level scalar addition. Type-II seesaw and higher-dimensional charged-fermion mass contributions are stated without a full potential or operator inventory.',NULL);
INSERT INTO "theory_regimes" VALUES(39,'mdm-majorana-quintuplet',1,NULL,'Single-multiplet gauge-basis description','Equation (1) renormalizable gauge kinetic and mass terms; higher-dimensional decay effects assessed separately','Minimal non-chiral quintuplet added to the inherited SM. Mass is free; thermal saturation and perturbative coannihilation approximations do not define the Lagrangian.',NULL);
INSERT INTO "theory_regimes" VALUES(40,'mdm-real-septuplet-displayed',1,NULL,'Single scalar septuplet with the source''s displayed scalar additions','Equation (1) plus recorded terms from equation (4); complete independent scalar potential and higher-dimensional basis unresolved','Assume zero septuplet VEV. Small portal effects specify the numerical limit, without declaring allowed scalar interactions forbidden or identically zero.',NULL);
INSERT INTO "theory_regimes" VALUES(41,'u1-ybl-charge-family',1,NULL,'Family-universal left-chiral fermion charge basis',NULL,'QYBL=b(zY+TBL), b nonzero; unspecified breaking sector. A charge parametrization is not a complete Lagrangian.',NULL);
INSERT INTO "theory_regimes" VALUES(42,'e6-full27-charge-template',1,NULL,'Left-handed fermion charge template for one relevant additional Abelian current',NULL,'Retain three full 27 inventories. Supersymmetric partners, scalar completion and optional incomplete 27+27* additions are not selected.',NULL);
INSERT INTO "theory_regimes" VALUES(43,'u1-chi-minimal16-charge',1,NULL,'Minimal left-chiral χ fermion inventory',NULL,'Unshifted χ charges; omit the optional non-chiral 10+1. Scalar content remains unspecified.',NULL);
INSERT INTO "theory_regimes" VALUES(44,'umssm-single-s-higgs-sector',1,NULL,'Superfield Higgs sector with neutral scalar component potential','Displayed renormalizable superpotential and tree-level neutral potential with soft terms','Squark and slepton expectation values vanish. Neutral component expressions do not enumerate the complete charged-scalar or matter action.',NULL);
INSERT INTO "theory_regimes" VALUES(45,'u1-two-singlet-flat-sector',1,NULL,'Two-singlet supersymmetric toy sector','Displayed renormalizable potential; higher-dimensional lifting discussed conditionally','QS1 QS2<0. No SiSj or SiSjSk terms in W; other sectors are not reconstructed.',NULL);
INSERT INTO "theory_regimes" VALUES(46,'abelian-stueckelberg-sector',1,NULL,'Isolated gauge-invariant Abelian vector mass description',NULL,'Equation (53), before optional gauge fixing. No Higgs VEV or physical Higgs boson is needed for this mass mechanism.',NULL);
INSERT INTO "theory_regimes" VALUES(47,'minimal-bl-pure',1,NULL,'Classical gauge-basis construction and its stated symmetry-breaking expansion','Displayed renormalizable gauge, scalar and Yukawa Lagrangian','Pure B−L convention with diagonal Abelian kinetic terms and no mixed Abelian coupling. No scale-dependent boundary condition or all-orders preservation of this restriction is specified.',NULL);
INSERT INTO "theory_regimes" VALUES(48,'u1-leptonic-opposite-nur',1,NULL,'Gauge-basis fermion charge template',NULL,'Three RH neutrinos retained; rational charge classification represented by integers. No complete Lagrangian or vacuum selected.',NULL);
INSERT INTO "theory_regimes" VALUES(49,'u1-sm-left23-charge',1,NULL,'Physical weak-family charge basis',NULL,'SM chiral fermion inventory. The suggested broken-phase flavour currents require additional mixing and breaking assumptions.',NULL);
INSERT INTO "theory_regimes" VALUES(50,'u1-sm-top-only-charge',1,NULL,'Physical weak-family charge basis with FH=2','Renormalizable Yukawa permission specified; higher-dimensional mass operators unconstructed','The selected Higgs is H∼(1,2,−1/2). No vacuum or ultraviolet completion is supplied.',NULL);
INSERT INTO "theory_regimes" VALUES(51,'u1-smnur-table5-14',1,NULL,'Ordered anomaly-classification representative',NULL,'Three RH neutrinos. Charges are sorted independently within each species; these indices are not physical mass-family labels.',NULL);
INSERT INTO "theory_regimes" VALUES(52,'u1-smnur-all-sm-yukawas',1,NULL,'Gauge-basis Yukawa-compatible charge family','All entries of the renormalizable charged-fermion Yukawa matrices permitted','Single Higgs doublet and three RH neutrinos; neutrino mass generation and the symmetry-breaking realization remain unspecified.',NULL);
INSERT INTO "theory_regimes" VALUES(53,'pp331-displayed',1,NULL,'Gauge-basis construction with a stated neutral-vacuum expansion','Displayed Yukawa interactions and scalar potential through quartic order','Eq. (10) sets mixed quark terms aside for presentation. Scalar spectrum uses Eq. (36) and the tree-level phase-free vacuum; neutral-vector approximations additionally require vchi much larger than veta and vrho.',NULL);
INSERT INTO "theory_regimes" VALUES(54,'pp331-sigma-omega',1,NULL,'Additional-triplet scalar extension of the inherited gauge-basis construction','Locally stated scalar additions only','The source proposes charged-scalar mixing but supplies no extended vacuum or complete operator inventory; detailed calculations are delegated to reference [10].',NULL);
INSERT INTO "theory_regimes" VALUES(55,'ql421-dirac',1,NULL,'Unified gauge-basis core and its neutral vacuum','Displayed renormalizable interactions','Left-handed fermion convention; no singlet N extension in this specification. A complete independent scalar invariant basis is not certified.',NULL);
INSERT INTO "theory_regimes" VALUES(56,'ql421-dirac',1,NULL,'Standard Model subgroup decomposition after χ breaking',NULL,'Component representation inventory of the same unified fields, not a separately matched low-energy EFT or an additional particle inventory.',NULL);
INSERT INTO "theory_regimes" VALUES(57,'ql421-inverse-seesaw',1,NULL,'Singlet-extended unified gauge-basis description','Inherited renormalizable core plus Eq. (17)','Three N fields are added. The later one-generation calculation does not reduce the defining singlet multiplicity.',NULL);
INSERT INTO "theory_regimes" VALUES(58,'ql421-inverse-seesaw',1,NULL,'Hierarchical inverse-seesaw and low-scale phenomenological application',NULL,'One-generation approximation µ ≪ Mν^D ≪ Mχ^D. Illustrative Mν^D ~ 10^2 GeV and Mχ^D ~ 10^6 GeV give mν ~ 10^-8 µ; the source quotes µ < 0.1 GeV. With no flavor suppression it quotes MX ≥ 10^3 TeV, while small scalar Yukawas can permit TeV scalar leptoquarks. These are conditional paper-era statements, not defining universal bounds or an equation for vχ.',NULL);
INSERT INTO "theory_regimes" VALUES(59,'su5-adjoint-renormalizable',1,NULL,'Unified gauge-basis description with the stated VEV-dependent fermion mass relations','Renormalizable nonsupersymmetric construction; displayed Yukawa and adjoint mass operators','No higher-dimensional fermion-mass operators are required in the stated construction. The full scalar potential is not supplied. Tree-level seesaw results and assumed breaking are distinguished from a completed vacuum analysis.',NULL);
INSERT INTO "theory_regimes" VALUES(60,'su5-adjoint-renormalizable',1,NULL,'One-loop unification and proton-decay threshold applications','One-loop threshold running using the source''s central electroweak inputs','Both Higgs doublets are at MZ. Descriptions 95–97 select different component masses within the same unified inventory. Remaining thresholds are placed at MGUT in the first two scenarios. Reported scales and proton-decay estimates are conditional source results, not defining masses or independently validated predictions.',NULL);
INSERT INTO "theory_regimes" VALUES(61,'so10-45-126-sector',1,NULL,'Unified scalar description and SM-preserving vacuum analysis','General renormalizable scalar potential, Eqs. (1)-(4)','Nonsupersymmetric breaking-sector scope. Tree-level stationarity and masses are distinguished from the minimally regularized numerical spectrum; no full quantum effective potential or global-minimum certification.',NULL);
INSERT INTO "theory_regimes" VALUES(62,'so10-45-126-sector',1,NULL,'Single accidental (6,3,+1/3) threshold application','Qualitative one-loop gauge running with minimally regularized scalar spectrum','The threshold is a 126H component, not an added unified multiplet. Reported solutions have |ωR| much smaller than ωBL, a short SU(3)c × SU(2)L × SU(2)R × U(1)BL stage and threshold mass around 10^11 GeV. The source reports |σ| reaching almost 10^15 GeV under its current Super-K limit and a few times 10^14 GeV under its strongest assumed Hyper-K sensitivity. These are conditional source-era results.',NULL);
INSERT INTO "theory_regimes" VALUES(63,'so10-45-126-sector',1,NULL,'Single accidental (8,2,+1/2) threshold application','Qualitative one-loop gauge running with minimally regularized scalar spectrum','Only one eigenstate in the 126H octet-doublet sector is lowered. Reported solutions have |ωBL| much smaller than |ωR| and a short SU(4)C × SU(2)L × U(1)R stage. The threshold lies below 10^10 GeV and can approach the electroweak scale; |σ| reaches about 10^14 GeV in this approximation. No MFV coupling restriction is imposed.',NULL);
INSERT INTO "theory_regimes" VALUES(64,'so10-45-126-complex10',1,NULL,'Unified fermion-mass extension with a complex 10H','Displayed renormalizable Yukawa interactions and schematic scalar mixing interaction','General complex symmetric Yukawa matrices retained. The full extended scalar potential and its doublet mass matrix are unspecified. The one-light-doublet VEV restriction in assertion 685 is deferred pending a consistent conjugate-doublet projection analysis.',NULL);
INSERT INTO "theory_regimes" VALUES(65,'trinification-n3-adjoint-l',1,NULL,'Trinification gauge-basis construction with assumed scalar breaking','Displayed renormalizable Yukawas and general quartic-sector scope; full dimensionful scalar potential unspecified','Three scalar bi-triplets and one extra 8L. One-loop TAF existence and the illustrative vacuum are separate conditional source claims; no full weak-scale running or potential minimization is supplied.',NULL);
INSERT INTO "theory_regimes" VALUES(66,'trinification-singlet-neutrino-sector',1,NULL,'Displayed singlet-neutrino extension sector before integrating out N','Renormalizable Eq. (2.18) mass and Yukawa terms','Three added singlets. Hn denotes the common scalar collection without choosing n=2 or n=3. Other common-sector fields and interactions remain inherited context rather than a reconstructed complete inventory.',NULL);
INSERT INTO "theory_regimes" VALUES(67,'mssm-rpc-conventional-soft',1,NULL,'Superfield gauge-basis definition with component soft operators','Renormalizable MSSM superpotential and conventional soft operator class of Eq. (5.1)','Exact matter parity. Gauge and superpotential interactions obey supersymmetry; conventional soft terms explicitly break it in this effective description. No full matter-representation table is reconstructed.',NULL);
INSERT INTO "theory_regimes" VALUES(68,'mssm-rpc-conventional-soft',1,NULL,'Conditional weak-universality boundary scenario',NULL,'At a high input scale Q0 each of the five sfermion matrices is a separate real coefficient times the family identity; a_u=A_u0 y_u, a_d=A_d0 y_d, a_e=A_e0 y_e. In the source''s μ,b-real convention, M1,M2,M3,A_u0,A_d0,A_e0 are real. These relations are additional assumptions, generally modified by running. Neither a common scalar mass nor gaugino unification is required.',NULL);
INSERT INTO "theory_regimes" VALUES(69,'mssm-rpc-conventional-soft',1,NULL,'Conditional source-labeled MSUGRA/CMSSM soft-boundary scenario',NULL,'At Q approximately MP: M1=M2=M3=m_1/2; all five sfermion matrices=m0² times the identity; m_Hu²=m_Hd²=m0²; a_f=A0 y_f; b=B0 μ. Common phases of m_1/2,A0,B0 give the source''s CP restriction. Starting instead at MU approximately 1.5×10^16 GeV is a practical approximation with potentially important omitted corrections. Universality is not guaranteed by supergravity; no extra B0 relation or gravitino-mass relation is imposed.',NULL);
INSERT INTO "theory_regimes" VALUES(70,'mssm-rpc-conventional-soft',1,NULL,'Conditional pure-AMSB soft trajectory',NULL,'M_a=F_phi beta_g_a/g_a; (m²)_i^j=|F_phi|²(d gamma_i^j/dt)/2; a^ijk=−F_phi beta_y^ijk, using the source anomalous-dimension convention. These are RG trajectories at every renormalization scale, not input-scale-only conditions. F_phi is a nondynamical compensator auxiliary VEV of mass dimension one. The simplest MSSM realization has negative slepton squared masses and is nonviable as presented. No complete extra-dimensional or conformal completion is selected.',NULL);
INSERT INTO "theory_regimes" VALUES(71,'mssm-rpc-conventional-soft',1,NULL,'Conditional AMSB plus common scalar squared-mass scenario',NULL,'Add a common m0² to all scalar squared masses at an unspecified scale, chosen sufficiently large to cure the slepton problem. Inputs are F_phi,m0²,tanβ,arg(μ), with |μ| and b determined by electroweak breaking. Leading gaugino masses remain those of AMSB. This modified prescription is not asserted to retain the exact pure-AMSB RG trajectory.',NULL);
INSERT INTO "theory_regimes" VALUES(72,'mssm-minimal-gauge-messengers',1,NULL,'Messenger superfield construction','Displayed renormalizable messenger superpotential with unspecified W_breaking','MSSM visible fields are inherited. S and its auxiliary component have assumed nonzero VEVs. Four additional messenger multiplets are independent of MSSM quark and lepton multiplets; their components are not extra independent superfields.',NULL);
INSERT INTO "theory_regimes" VALUES(73,'mssm-minimal-gauge-messengers',1,NULL,'MSSM effective soft matching near the messenger threshold','Leading one-loop gaugino and two-loop scalar soft contributions','At Q0 approximately M_mess, M_a=(α_a/4π)Λ and m_phi_i²=2Λ² sum_a C_a(i)(α_a/4π)² in the source''s displayed convention; α1 is GUT normalized. Require small messenger splitting |<F_S>/(y_I<S>²)|. The printed Λ² formula is not generalized here to arbitrary complex Λ. a_u=a_d=a_e approximately zero at matching, with nonzero values generated by running. b=0 is optional and model dependent; no such zero is imposed.',NULL);
INSERT INTO "theory_regimes" VALUES(74,'mssm-rpv-general',1,NULL,'Superfield gauge basis with component soft terms','Renormalizable superpotential and displayed soft operators','No preferred Higgs-lepton basis; no complete component-potential audit or ultraviolet completion.',NULL);
INSERT INTO "theory_regimes" VALUES(75,'mssm-rpv-bilinear',1,NULL,'Defining bilinear-only basis and its rotated descriptions','Inherited renormalizable MSSM with bilinear RPV','Existence of a bilinear-only basis is defining. Rotations induce dependent lambda and lambda-prime interactions but no lambda-double-prime.',NULL);
INSERT INTO "theory_regimes" VALUES(76,'mssm-rpv-dim23',1,NULL,'Dimension-two and dimension-three breaking pattern','RPV superpotential bilinears plus all displayed RPV soft terms','Restriction specified in the source basis; no general all-basis vanishing claim.',NULL);
INSERT INTO "theory_regimes" VALUES(77,'mssm-rpv-soft-bilinear',1,NULL,'Dimension-two-only breaking pattern','RPV confined to soft scalar bilinears','Six source soft parameters in the defining basis; no selected vacuum or mediation mechanism.',NULL);
INSERT INTO "theory_regimes" VALUES(78,'mssm-rpv-general',1,NULL,'Conditional tree-level trilinear-only ansatz',NULL,'Set mu_i, B_i and mtilde_di^2 to zero in the classical Lagrangian and retain lambda, lambda-prime, lambda-double-prime and associated A-terms. Generic lepton-number-violating trilinears regenerate bilinears under quantum corrections. Imposed lepton-number conservation prevents its violating terms from being generated; this exception is not imposed on the generic ansatz.',NULL);
INSERT INTO "theory_regimes" VALUES(79,'mssm-rpc-conventional-soft',1,NULL,'Alternative minimal spontaneous sneutrino-breaking vacuum application',NULL,'The Lagrangian conserves R-parity and global lepton number, while a sneutrino VEV breaks them. This application replaces the earlier zero-sfermion-VEV assumption. P22 reports exclusion from the additional invisible Z decay; no current numerical constraint or completed minimum calculation is asserted.',NULL);
INSERT INTO "theory_regimes" VALUES(80,'rpv-singlet-spontaneous-sector',1,NULL,'Singlet-extended superfield sector and illustrative broken vacuum','Displayed cubic superpotential additions, Eq. (2.49)','Ordinary quark and charged-lepton Yukawas remain inherited. Full soft interactions and vacuum stability are unspecified. Effective bilinears do not remove the additional Majoron and singlet degrees of freedom.',NULL);
INSERT INTO "theory_regimes" VALUES(81,'su5-rpv-trilinear-sector',1,NULL,'Unified superfield operator description','Renormalizable bar5-bar5-10 operator with field-independent coefficients','Relations apply at the unified description, not automatically after running or for coefficients induced by GUT-breaking VEVs.',NULL);
INSERT INTO "theory_regimes" VALUES(82,'split-susy',1,NULL,'Component effective theory below the heavy-scalar threshold','Matter-parity-preserving renormalizable Lagrangian of Eq. (20), plus gauge-invariant kinetic terms','Applies below mtilde and above the relevant retained-particle thresholds. The four Higgs–higgsino–gaugino couplings run independently of gauge couplings below matching. Higher-dimensional gluino-decay operators are not enumerated.',NULL);
INSERT INTO "theory_regimes" VALUES(83,'split-susy',1,NULL,'Supersymmetric parent description at and above the scalar threshold','Displayed supersymmetric Higgs interactions and threshold projection, Eqs. (21)–(25)','Two parent Higgs scalar doublets and the heavy sfermions are present. Parent inventory is inherited supersymmetric-SM context, not an independently reconstructed full soft Lagrangian. Supersymmetric running above mtilde neglects mass effects; no exact unbroken supersymmetry of the massive spectrum is asserted.',NULL);
INSERT INTO "theory_regimes" VALUES(84,'split-susy',1,NULL,'Optional unified-gaugino mass scenario',NULL,'Gaugino mass unification is an additional boundary choice. Figures 2–3 use mu=M2, M2=300 GeV or 1 TeV, and tan(beta)=1.5 or 50, with two-loop gauge running and one-loop thresholds. Unknown GUT and scalar-threshold corrections prevent firm parameter bounds. These benchmarks do not constrain the general EFT.',NULL);
INSERT INTO "theory_regimes" VALUES(85,'split-susy',1,NULL,'Optional anomaly-mediated gaugino boundary scenario',NULL,'At mtilde impose Mi=(beta_gi/gi)m3/2, where m3/2 denotes the compensator auxiliary VEV in this paper. Below mtilde nonsupersymmetric evolution changes these relations. Wino is the lightest gaugino in the analysis, but need not be lighter than higgsinos. No full AMSB scalar or trilinear prescription is imposed.',NULL);
INSERT INTO "theory_regimes" VALUES(86,'split-susy',1,NULL,'Optional radiatively generated higgsino mass',NULL,'Set mu(mtilde)=0 with either unified or anomaly-mediated gaugino boundaries. Electroweak gaugino masses generate mu below the threshold. Figures 7 and 9 use tan(beta)=1.5 and yield a higgsino lightest neutralino; thermal dark-matter saturation selects the source''s approximately 1.0–1.2 TeV higgsino range with heavier gauginos. The mass operator is not absent at all scales.',NULL);
INSERT INTO "theory_regimes" VALUES(87,'gem-supersoft',1,'4','N=1 superfield description of the extended gauge sector','Displayed cutoff-suppressed supersoft operators and their component consequences','Below mediation scale M. Hidden field strength is treated as a D spurion; optional adjoint superpotential masses are retained as parameter freedom. No complete UV theory is implied.',NULL);
INSERT INTO "theory_regimes" VALUES(88,'gem-supersoft',1,'4','Minimal Dirac limit and real-adjoint elimination',NULL,'Set the second supersoft operator and supersymmetric ESP masses to zero for this limit. Eq. (2.4) masses the real adjoint but not its pseudoscalar at tree level. Eliminating the massive real adjoint gives D_j=0 and vanishing low-energy tree D-term quartics; loop quartics remain.',NULL);
INSERT INTO "theory_regimes" VALUES(89,'gem-supersoft',1,'4','Heavy-ESP effective Majorana-gaugino limit',NULL,'ESP masses, and bachelor masses when bachelors are present, lie well above the weak scale. For the Eq. (2.9) scale no greater than the Eq. (2.4) scale, integrating out ESPs gives Mi=[alpha_i(M_ESP)/alpha(M_GUT)] D^2/(M^2 M_ESP). Gaugino mediation below M_ESP and competing anomaly mediation are conditional; this is not a new MSSM identity or a full matching calculation.',NULL);
INSERT INTO "theory_regimes" VALUES(90,'gem-supersoft-messengers',1,'4','Displayed messenger superpotential above its threshold','Renormalizable messenger mass and adjoint coupling','Messenger inventory is schematic and the hidden D source is parameterized. No exact messenger charges or number of messenger copies is supplied.',NULL);
INSERT INTO "theory_regimes" VALUES(91,'gem-supersoft-su5-bachelors',1,'4','SM-level SU(5)-adjoint completion',NULL,'Inherited octet, triplet and singlet ESPs plus the two bachelor representations of Eq. (3.8). Light versus heavy bachelor thresholds are parameter choices. Full unified breaking is unspecified.',NULL);
INSERT INTO "theory_regimes" VALUES(92,'gem-supersoft-su3cubed-bachelors',1,'4','SM-level SU(3)^3-inspired adjoint completion',NULL,'Inherited ESPs plus the stated vectorlike doublet pair, two charged-singlet pairs and four additional SM singlets. Numerical spectra and unification running remain outside the prepared detailed scope.',NULL);
INSERT INTO "theory_regimes" VALUES(93,'gem-supersoft-messengers',1,'4','Messenger-induced supersoft effective operators',NULL,'Integrating out T and bar T generates both Eqs. (2.4) and (2.9). The large-ESP-mass variant of Eq. (3.22) retains M_A A^2 and schematic coefficients 1/(16 pi^2 M) and 1/(16 pi^2 M^2). These express the source''s loop hierarchy, not a complete charge-dependent matching coefficient.',NULL);
INSERT INTO "theory_regimes" VALUES(94,'general-gauge-mediation',1,'4','Hidden-current description with weak visible gauging','Leading visible gauge contributions using hidden one- and two-point functions with full momentum dependence','Hidden coupling need not be perturbative. Soft formulas are boundary contributions at characteristic scale M. A generic strongly coupled hidden sector is not calculationally reconstructed.',NULL);
INSERT INTO "theory_regimes" VALUES(95,'u1-minimal-gauge-messenger-toy',1,'4','Appendix A messenger superfield sector with a fixed spurion','Displayed canonical kinetic terms and renormalizable messenger superpotential','Real M,F and lambda=1 convention. Messenger correlators use free-field contractions at leading gauge order; the calculation retains the displayed splitting rather than imposing a small-F expansion.',NULL);
INSERT INTO "theory_regimes" VALUES(96,'general-gauge-mediation-higgs-operators',1,'4','Direct Higgs coupling extension of the hidden-correlator framework','Leading expansion in lambda_u,d in addition to visible gauge couplings','Full chiral-superfield two-point functions parameterize Higgs masses, mu and Bmu. Higher-point dimension-five and dimension-six operators are mentioned without a supplied operator basis.',NULL);
INSERT INTO "theory_regimes" VALUES(97,'ksvz-neutral-triplet',1,NULL,'Gauge-basis benchmark and its PQ-breaking scalar expansion','Displayed renormalizable new-sector Lagrangian','Bare Q mass absent; Phi has the potential and nonzero vacuum parameter of Eqs. (78)-(79).',NULL);
INSERT INTO "theory_regimes" VALUES(98,'ksvz-neutral-triplet',1,NULL,'Axion effective description below the heavy-quark threshold','Displayed anomalous gluon operator','Q integrated out and the heavy radial scalar neglected. Zero ultraviolet photon and SM-fermion coefficients do not remove gluon-induced low-energy couplings.',NULL);
INSERT INTO "theory_regimes" VALUES(99,'ksvz-representation-framework',1,NULL,'Representation and PQ-charge framework','Singlet Yukawa assignments and associated anomaly matching','Variable reducible collection of heavy representations. Anomaly sums count left-handed irreducible fields, including conjugated right-handed fields. Nontrivial color alone does not exclude cancellations in total N; the f_a formulation requires N nonzero.',NULL);
INSERT INTO "theory_regimes" VALUES(100,'dfsz-i-quartic',1,NULL,'Generation-universal gauge-basis construction and neutral-vacuum expansion','Renormalizable scalar potential and Yukawas; derived ultraviolet axion couplings','Quartic H_u H_d Phi-dagger-squared interaction. Assume v_Phi much larger than the doublet VEVs for the invisible-axion approximation.',NULL);
INSERT INTO "theory_regimes" VALUES(101,'dfsz-ii-quartic',1,NULL,'DFSZ-II replacement within the inherited common quartic construction','Renormalizable charged-lepton Yukawa replacement','Same scalar potential, quark Yukawas, generation universality and neutral VEV assumptions as DFSZ-I. H_tilde_u is constructed from H_u and is not an additional independent doublet.',NULL);
INSERT INTO "theory_regimes" VALUES(102,'smash-down',1,'4','Gauge-basis matter theory with Jordan-frame gravitational couplings','Renormalizable matter interactions of Eqs. (1),(4), supplemented by Eq. (22) gravitational EFT','Main down-type choice. Source left-handed Weyl convention. Positive ξH and ξσ assumed for the gravitational analysis; no flavor texture, fixed mass spectrum or compulsory portal sign imposed on the matter construction.',NULL);
INSERT INTO "theory_regimes" VALUES(103,'smash-down',1,'4','Low-energy axion/majoron and seesaw description','Displayed leading axion interactions after heavy-particle removal; QCD vacuum potential and quoted hadronic matching','Requires sufficiently heavy Ni,Q and radial scalar. Eq. (8) applies above ΛQCD and below electroweak breaking. Below ΛQCD use the QCD potential and matched photon/nucleon coefficients. Angular and neutrino mass eigenstates reorganize the ultraviolet fields.',NULL);
INSERT INTO "theory_regimes" VALUES(104,'smash-down',1,'4','Preferred HHSI and restored-PQ cosmological application','Tree-level inflationary valley reduction, stability analysis and approximate reheating/leptogenesis treatment','κH=λHσξH−λHξσ<0 and κσ=λHσξσ−λσξH<0; negative portal and ξH≪ξσ give h/ρ≈sqrt(|λHσ|/λH)≪1. Adequate CP violation and decay-enabling quark mixing are required for the combined account; no complete common numerical benchmark is fixed.',NULL);
INSERT INTO "theory_regimes" VALUES(105,'smash-down',1,'4','HSI trajectory and typical positive-portal reheating comparison','Pure-singlet valley reduction and approximate reheating calculation','h=0 is a valley for κσ>0; inflaton quartic is λσ. Typical analyzed reheating assumes |λHσ|≫λσ and kinematic blocking. Its dark-radiation result is not an unconditional exclusion of every positive-portal parameter point.',NULL);
INSERT INTO "theory_regimes" VALUES(106,'smash-down',1,'4','Large-fA branch without post-inflationary PQ restoration',NULL,'For fA roughly above 4×10^16 GeV, consider PQ remaining broken after inflation. With axions making all dark matter and the source''s HSI/HHSI fluctuation treatment, its isocurvature bound fA<1.4×10^14 GeV excludes this branch. This is a conditional pinned-version result.',NULL);
INSERT INTO "theory_regimes" VALUES(107,'smash-down',1,'4','Restricted numerical stability scans','One-loop threshold matching and two-loop running; Appendix B uses MS and Landau gauge','For simplicity set yQd_i=0, choose diagonal Y with Y22=Y33=3Y11, lightest active neutrino mass zero and O=identity in the neutrino ansatz. Initial four-parameter scans take y=Y11 and positive portal; negative-portal scans are also considered. These restrictions do not define a decay-enabled, CP-asymmetric joint cosmological benchmark.',NULL);
INSERT INTO "theory_regimes" VALUES(108,'lns-two-singlet-quarks',1,NULL,'Light supersymmetric quark effective description below M','Holomorphic singlet-insertion Yukawa operators and their leading mass textures','Continuous horizontal selection rules; no S-dagger insertions. Higher-order effects of the intended discrete completion and soft breaking are not established.',NULL);
INSERT INTO "theory_regimes" VALUES(109,'lns-two-singlet-quarks',1,NULL,'Explicit heavy-quark realization at the scale M','Displayed supersymmetric heavy mass and Yukawa structure of (7.7)–(7.8)','Three U pairs and five D pairs supplement the light multiplets of regime 108, with the same light charges. Scalar VEV entries stand for Yukawa insertions. Some explicit mass zeros are basis choices among equal-charge fields.',NULL);
INSERT INTO "theory_regimes" VALUES(110,'lns-single-singlet-quarks',1,NULL,'Single-charge light effective alternative','Holomorphic Yukawa operators with powers of S/M fixed by H-charge sums','Common light gauge and Higgs sector inherited with the stated replacements. No dedicated messenger inventory or matching coefficients are specified.',NULL);
INSERT INTO "theory_regimes" VALUES(111,'lns-reduced-quarks',1,NULL,'Reduced supersymmetric heavy-quark realization','One U pair and two D pairs with modified light down charges','Retain U1,D3,D4 and their independent conjugate partners. Other light fields and their charges are inherited from the two-singlet construction. The full scalar dynamics and discrete completion remain unspecified.',NULL);
INSERT INTO "theory_regimes" VALUES(112,'lns-reduced-quarks',1,NULL,'Light effective texture after reduced heavy-field removal','Leading quark mass textures of (9.3)','Use inherited Q, up-singlet, Higgs and singlet fields and the replaced down charges. mu=0 and <phi_d> approximately epsilon1 <phi_u>; nonzero entries carry generic coefficients. This is not the unrestricted charge-allowed effective operator set.',NULL);
INSERT INTO "theory_regimes" VALUES(113,'af-a4-susy-effective',1,'4','Supersymmetric lepton and alignment effective description','Leading charged-lepton operators at 1/Lambda, neutrino operators at 1/Lambda² and renormalizable w_d; selected next-order operators recorded separately','Flavon VEVs below the cutoff. Leading alignment is obtained in the supersymmetric limit with subsequent assumed soft selection and stabilization. The recorded higher-order operators do not certify the disputed complete Appendix B basis.',NULL);
INSERT INTO "theory_regimes" VALUES(114,'af-a4-susy-seesaw',1,'4','Supersymmetric seesaw realization before heavy-neutrino removal','Leading Dirac and Majorana neutrino superpotential plus the inherited charged-lepton effective operators and leading w_d','Section 6 replacements apply. Higher-order Dirac and Majorana terms receive phiT/Lambda insertions; a full corrected seesaw basis is not supplied. Local light-neutrino operators scale as VEV²/Lambda³, while the seesaw contribution scales as 1/VEV with common electroweak factors suppressed.',NULL);
INSERT INTO "theory_regimes" VALUES(115,'modular-a4-flavonfree-seesaw',1,'4','Global N=1 supersymmetric modular lepton construction before heavy-neutrino removal','Displayed lepton superpotential of equations (50)–(51), with exact modular functions rather than truncated q expansions','The source''s complete-superpotential claim is confined to the stated lepton construction in exact supersymmetry. Predictions use the assumed Kähler structure; supersymmetry breaking and Kähler modifications can alter them. No local-supergravity completion is selected.',NULL);
INSERT INTO "theory_regimes" VALUES(116,'grv-quark-flavor-u3',1,'4','Gauge-basis quark-flavor construction and assumed broken vacuum','Renormalizable displayed fermion interactions and covariant kinetics; scalar potential unspecified','Exact mixing relations are needed outside the heavy-exotic expansion, especially in the top sector. No fixed mass scale or fully renormalizable realistic scalar completion is asserted.',NULL);
INSERT INTO "theory_regimes" VALUES(117,'grv-quark-flavor-u3',1,'4','Leading inverse-flavon effective Yukawa description','Leading heavy-exotic elimination; schematic vector-induced four-quark effects','The source states Yu,d much larger than Mu,d. Third-family corrections can invalidate the leading formula. The effective quarks and Higgs descend from regime 116, without adding multiplets. Schematic 1/Y² flavor suppression is not an exact universal matrix identity.',NULL);
INSERT INTO "theory_regimes" VALUES(118,'grv-quark-flavor-su3',1,'4','Nonabelian-only flavor gauging with the common two-flavon matter sector','Inherited displayed renormalizable fermion sector; scalar completion unspecified','Section 5.1 selects a numerical point in this construction. Gauge generators are restricted to the three SU(3) factors. The full scalar spectrum and realistic potential are not fixed.',NULL);
INSERT INTO "theory_regimes" VALUES(119,'sm-singlet-neutrino-framework',1,NULL,'General-N gauge-basis neutrino extension','Renormalizable Eq. (1) and inherited Standard Model action','Variable N. Charged-lepton and sterile mass matrices are real and diagonal in the displayed coordinates; F remains a general flavor matrix.',NULL);
INSERT INTO "theory_regimes" VALUES(120,'numsm',1,NULL,'Three-singlet renormalizable gauge-basis construction','Inherited Eq. (1), with I=1,2,3 and alpha=e,mu,tau','Majorana masses of order the electroweak scale or below in the introduction; described as smaller than that scale in the conclusions. No numerical dark-matter or baryogenesis benchmark is imposed here.',NULL);
INSERT INTO "theory_regimes" VALUES(121,'numsm',1,NULL,'Seesaw and adopted sterile warm-dark-matter application','Same renormalizable theory in the small-mixing seesaw regime','M_I greatly exceed Dirac masses; Yukawa couplings are very small. N1 is selected as the sole sterile dark-matter species. The adopted abundance relation and historical constraints are conditional on production assumptions imported from reference [12], not universal consequences of the Lagrangian.',NULL);
INSERT INTO "theory_regimes" VALUES(122,'numsm',1,NULL,'Perturbative simultaneous dark-matter and oscillation-baryogenesis application','Leading iterative solution of Eqs. (16)–(17); coherent sterile helicity sectors and diagonal active populations','Standard Big Bang evolution, initially absent sterile neutrinos and initially vanishing active-flavor asymmetries. Use Boltzmann statistics and sin(phi) approximately 0.02. Neglect helicity-flip and lepton-number-changing sectors for small Yukawas and M_I/T. All sterile states remain out of equilibrium at sphaleron freeze-out: source estimates f_i²<2e-14 and M2,3<12 GeV. The illustrative normal hierarchy neglects s_R12 and s_R13 and uses f2²=m_sol M2/v², f3²=m_atm M3/v². The successful approximately 10 GeV example requires strong heavier-state degeneracy and suitable CP phases; this is an existence calculation, not a complete parameter-space analysis.',NULL);
INSERT INTO "theory_regimes" VALUES(123,'ma-radiative-seesaw-z2',1,NULL,'Gauge-basis construction and expansion about the parity-preserving electroweak vacuum','Displayed renormalizable Yukawa, Majorana and scalar operators','Exact Z2; assumed zero η expectation value. Loop masses are derived results, not independent tree-level inputs. No fixed cutoff or mass hierarchy is imposed.',NULL);
INSERT INTO "theory_regimes" VALUES(124,'ma-radiative-seesaw-z2',1,NULL,'Conditional fermionic dark-matter and decay application',NULL,'N1 is lightest in the entire odd sector, with M1<M2<M3. The explicit decay example additionally places all η masses above all M_k. Common fields and interactions remain those of regime 123.',NULL);
INSERT INTO "theory_regimes" VALUES(125,'ma-radiative-seesaw-z2',1,NULL,'Conditional neutral-scalar dark-matter and decay application',NULL,'sqrt(2)Reη0 is the lightest odd particle; sqrt(2)Imη0 is slightly heavier in the coannihilation discussion. The explicit decay example additionally places all M_k above the η masses. No numerical splitting or relic-density calculation is supplied; common fields and interactions are retained.',NULL);
INSERT INTO "theory_regimes" VALUES(126,'weinberg-t1i-first-row',1,NULL,'Electroweak representation template for an irreducible one-loop completion','Necessary mediator assignments for the d=5 Weinberg operator at one loop','Scalar and fermion mediators only; self-energy diagrams excluded. The first T1-i row is retained without a selected alpha or complete Lagrangian.',NULL);
INSERT INTO "theory_regimes" VALUES(127,'weinberg-t41ii-first-row',1,NULL,'Finite scalar-loop correction to a type-II scalar vertex','Bounded first T4-1-ii field-assignment row','The loop is finite but does not by itself establish leading radiative neutrino mass. No scalar potential or vacuum is supplied.',NULL);
INSERT INTO "theory_regimes" VALUES(128,'weinberg-t41i-doublet-fermions',1,NULL,'Displayed electroweak interaction sector and one-loop vertex renormalization','Eqs. (3)-(4), supplemented by the required tree-level type-II scalar vertex','The logarithmically divergent loop renormalizes mu_Delta. Displayed component terms are not a complete allowed Lagrangian; no vacuum is selected.',NULL);
INSERT INTO "theory_regimes" VALUES(129,'su4-hypercolor-partial-compositeness',1,'4','Microscopic fermionic SU(4) hypercolor description','Specified hypercolor matter and flavor structure; higher-scale elementary–hypercolor interactions unresolved','Assumed valid when coupled to the SM up to LambdaUV much greater than Lambda. The source quotes LambdaUV > 10^7 GeV from FCNC considerations without specifying its mediators.',NULL);
INSERT INTO "theory_regimes" VALUES(130,'su4-hypercolor-partial-compositeness',1,'4','Conditional pNGB and one-light-Dirac-partner effective description','Product coset SU(5)/SO(5) × [SU(3) × SU(3)''/SU(3)c] × U(1)''; displayed nonlinear kinetics and mass-generating interactions','Below the generic resonance scale Lambda; assumes the proposed condensates and M < Lambda. Eta and eta-prime are identified but omitted from the subsequent explicit treatment. Detailed heavy channels and the full derivative operator series are outside the retained scope.',NULL);
INSERT INTO "theory_regimes" VALUES(131,'littlest-higgs-minimal',1,NULL,'Nonlinear sigma EFT with the TeV-scale states retained','Leading two-derivative sigma action, displayed fermion interactions, and leading gauge and fermion radiative counterterms','f is of order a TeV and the cutoff can approach 4pi f, of order 10 TeV. The symmetry-breaking origin is unselected. One-loop logarithmic and two-loop quadratic sensitivity remain; small light-fermion Yukawa corrections are neglected separately.',NULL);
INSERT INTO "theory_regimes" VALUES(132,'littlest-higgs-minimal',1,NULL,'Low-energy description after heavy-state elimination','Minimal Standard Model spectrum with the matched Higgs quartic and higher-dimensional heavy-exchange effects','Applies below the heavy triplet, vector and quark thresholds in the intended hierarchy. A full dimension-six operator basis and exact threshold matching are not supplied.',NULL);
INSERT INTO "theory_regimes" VALUES(133,'twin-higgs-linear-scalar-sector',1,NULL,'Linear illustrative scalar and gauge description','Displayed renormalizable scalar potential and leading gauge-induced quartic','Initial SU(2)_A × SU(2)_B example; no full matter completion is assumed.',NULL);
INSERT INTO "theory_regimes" VALUES(134,'twin-higgs-unextended',1,NULL,'Nonlinear doubled-SM construction with ordinary twin matter','Radial mode removed; nonlinear Higgs interactions, gauge-allowed portals and displayed soft scalar term','Assumed nonlinear O(8) symmetry restricts higher-dimensional custodial violation. Strong coupling at the cutoff gives the estimate Lambda approximately 4pi f. The full higher-dimensional operator basis is not enumerated.',NULL);
INSERT INTO "theory_regimes" VALUES(135,'twin-higgs-extended-top',1,NULL,'Extended top matter coupled to the inherited nonlinear Higgs','Displayed invariant top Yukawa and soft exotic masses, with inherited nonlinear gauge and scalar structure','Retains the exotic quarks explicitly. The source states finiteness of the one-loop top contribution; no full loop-formula reconstruction or ultraviolet completion is asserted.',NULL);
INSERT INTO "theory_regimes" VALUES(136,'mirror-higgs-unextended',1,NULL,'Mirror-interchange alternative and conditional massless-photon application','Shared pseudo-Goldstone Higgs mechanism and renormalizable portal scope','Mirror action is explicitly defined by the source. The common phenomenological discussion does not establish equality of every twin and mirror operator or soft-breaking coefficient.',NULL);
INSERT INTO "theory_regimes" VALUES(137,'fraternal-twin-higgs',1,NULL,'Perturbative linear microscopic construction below the ultraviolet cutoff','Displayed renormalizable tree scalar potential and twin Yukawa assignments; approximate radiative Higgs analysis','Retain the radial Higgs. Approximate matching of the largest visible and twin couplings supports the source''s naturalness estimates; no exact exchange symmetry of the full particle inventory is imposed.',NULL);
INSERT INTO "theory_regimes" VALUES(138,'fraternal-twin-higgs',1,NULL,'Low-energy portal description after heavy-scalar and twin-top matching','Leading radial constraint and displayed dimension-five fermionic and gluonic Higgs portals','Below the relevant heavy thresholds. Use |B|²=f²/2−|A|² and a leading v/f expansion. The gluon operator additionally integrates out the twin top. This is not a complete higher-dimensional operator basis.',NULL);
INSERT INTO "theory_regimes" VALUES(139,'fraternal-twin-higgs',1,NULL,'Conditional pure-glue confined twin-color regime','Glueball spectrum and leading scalar Higgs-portal decay mechanism','Twin colored fermions much heavier than confinement. Stability against other glueball decays does not imply absolute stability against portal-mediated decays. Lattice inputs are reported by this paper.',NULL);
INSERT INTO "theory_regimes" VALUES(140,'fraternal-twin-higgs',1,NULL,'Conditional twin-bottomonium regime','Selected quarkonium states and qualitative competing decay channels','Bottom–antibottom bound states of the same twin quark. Nonrelativistic estimates require twin-bottom mass much greater than confinement. Glueball coexistence and mixing depend on thresholds; overlapping spectra and hadronization are not reliably calculated.',NULL);
INSERT INTO "theory_regimes" VALUES(141,'large-extra-dimensions-framework',1,'4+n, n≥2','Higher-dimensional gravitational framework with localized SM matter','Low-energy SM and bulk gravity below m_EW; ultraviolet action unspecified','Common characteristic compactification radius R; gravitational expressions retain order-of-magnitude accuracy.','R^4×M_n with compact volume of order R^n. SM support has transverse thickness of order m_EW^−1. No particular topology or boundary conditions are selected.');
INSERT INTO "theory_regimes" VALUES(142,'large-extra-dimensions-framework',1,'4','Four-dimensional graviton KK description','SM plus graviton and accessible KK excitations below the cutoff','Source scaling: spacing of order 1/R per extra dimension, coupling of each mode of order 1/M_Pl and accessible multiplicity of order (ER)^n. These are not exact spectral formulas for every compact manifold.',NULL);
INSERT INTO "theory_regimes" VALUES(143,'six-dimensional-pati-salam-vortex',1,'6','Bulk field description with a four-dimensional vortex core','Displayed localization interactions and particle assignments below a weak-scale cutoff Λ','Gauge localization and the light bulk spectrum depend on the postulated mass gap. A complete six-dimensional action is not supplied.','Signature (−1,1,1,1,1,1); compact transverse x5,x6 have R of order 1 mm. Alternatives are S² with a vortex–antivortex pair and the source-described zero-inner-radius torus with one vortex. Core thickness is of order Λ^−1; no interval boundaries are introduced.');
INSERT INTO "theory_regimes" VALUES(144,'rs-two-brane-warped',1,'5','Classical bulk and boundary description','Displayed Einstein cosmological action and brane actions; illustrative brane Higgs sector','Classical curvature treatment with k < M; four-dimensional Poincare-invariant background selected.','S^1/Z2: periodic covering coordinate -pi <= phi <= pi with (x,phi) identified with (x,-phi). Independent interval 0 <= phi <= pi, proper length pi r_c; boundary branes at both fixed points.');
INSERT INTO "theory_regimes" VALUES(145,'rs-two-brane-warped',1,'4','Gravitational zero modes and qualitative massive KK description','Explicit zero-mode metric and fixed-radius Einstein reduction; massive tower specified only qualitatively','The compact dimension is unresolved in gravitational experiments, with r_c > 1/k. T is retained as a modulus in the zero-mode identification and subsequently fixed by assumption. No vector zero modes are retained. Massive spin-2 states are separate excited modes, not part of the massless truncation.','Effective Einstein metric gbar_mu_nu; fixed-radius induced metrics g_hid=gbar and g_vis=exp(-2 k r_c pi) gbar.');
INSERT INTO "theory_regimes" VALUES(146,'ued-orbifold-framework',1,'4+delta','Shared dimension-indexed bulk action','Equation (2.1): gauge and matter kinetics, Higgs kinetic and potential sector, quark and analogous lepton Yukawas','All Standard Model fields propagate throughout the universal dimensions; delta is a discrete framework index. Additional anomaly-cancelling sectors are unspecified.','Common radius R. For delta=2k use [(S1 x S1)/Z2]^k; for delta=2k+1 append S1/Z2. Each Z2 reverses its paired coordinates, or the final unpaired coordinate.');
INSERT INTO "theory_regimes" VALUES(147,'ued-orbifold-framework',1,'5','One-universal-dimension specialization','Shared bulk action at delta=1; no added localized operators','Five-dimensional fermions are four-component vector-like spinors. The source''s one-loop electroweak KK sums converge; higher-order and ultraviolet estimates remain conditional.','S1/Z2 with 0 <= y <= pi R. Obtain the displayed expansions by setting j2=y2=0. Boundary conditions below apply at both endpoints.');
INSERT INTO "theory_regimes" VALUES(148,'ued-orbifold-framework',1,'6','Two-universal-dimension specialization','Shared bulk action at delta=2 and the explicit expansions (2.2)–(2.3)','The displayed chiral choice uses four-component six-dimensional spinors with opposite doublet/singlet chiralities. Anomaly-cancelling completion is unspecified. Electroweak sums are logarithmically cutoff sensitive.','(S1 x S1)/Z2 with simultaneous inversion (y1,y2)->(-y1,-y2), common R. Nonzero representatives satisfy j1+j2>=1 or j1=-j2>=1. Gauge A_mu is cosine-even and A_b sine-odd; Q3 has even left and odd right 4D components, while U3 has even right and odd left components.');
INSERT INTO "theory_regimes" VALUES(149,'ued-orbifold-framework',1,'4+delta, delta>=3','Iterative higher-dimensional framework branch','Shared action and iterative KK prescription only','Odd delta=2k+1 uses vector-like 2^(k+2)-component fermions; even delta=2k permits chiral 2^(k+1)-component fermions. Complete component expansions, higher-dimensional interaction signs and anomaly completion are not supplied. Precision predictions have strong cutoff dependence.','Iterate the paired-coordinate construction k times; for odd delta first compactify the unpaired dimension. No alternative orbifold or unequal-radius prescription is selected.');
INSERT INTO "theory_regimes" VALUES(150,'ued-orbifold-framework',1,'4','KK description of a selected dimensional member','Standard Model zero modes and KK levels below Ms; selected zero-mode/nonzero-mode interactions','This reorganizes the bulk fields rather than adding microscopic generations. Component scalar counts are retained before independently resolving gauge fixing. The source assumes only the Higgs zero mode has a VEV.','Mode domain and degeneracies depend on the chosen dimensional member. The displayed one-loop vertices contain one or two zero modes and two nonzero modes.');
INSERT INTO "theory_regimes" VALUES(151,'holographic-su3-brane-scalar-mediator',1,'5','Bulk and brane construction with the quartic mediator retained','Displayed bulk masses and infrared interactions; ultraviolet dynamics parameterized by breaking and boundary masses.',NULL,'ds²=(kz)^(-2)(eta_mu_nu dx^mu dx^nu-dz²); L0<=z<=L1; L0=1/k, ultraviolet boundary; L1, infrared boundary.');
INSERT INTO "theory_regimes" VALUES(152,'holographic-boundary-pgb-framework',1,'5','General gauge theory with boundary-condition breaking',NULL,'Finite interval and weakly coupled five-dimensional description. The extra quartic-generating structures are not included.','AdS5 metric of equation (1), with ultraviolet z=L0=1/k and infrared z=L1 boundaries.');
INSERT INTO "theory_regimes" VALUES(153,'holographic-boundary-pgb-framework',1,'4','Holographic CFT and elementary gauge-source description','Equation (28) current coupling and spontaneous symmetry-breaking pattern; microscopic CFT action unspecified.','Global G spontaneously breaks to H1; elementary fields weakly gauge H0. This is a corresponding description, not an additional microscopic sector in five dimensions.',NULL);
INSERT INTO "theory_regimes" VALUES(154,'holographic-boundary-pgb-framework',1,'5','Equal-boundary bulk-fermion loop example',NULL,'H0=H1=H; one bulk fermion in unselected representation r with constant mass M_Psi and the complementary chiral assignments of equation (36).','Same finite AdS interval as regime 152; local boundary records below apply to this specialization.');
INSERT INTO "theory_regimes" VALUES(155,'hidden-valley-framework',1,NULL,'General confining hidden-sector framework','SM–hidden interactions induced by heavy mediators; no fixed operator basis','SM particles are hidden-neutral; light hidden constituents are SM-neutral and assemble into hidden-neutral hadrons.',NULL);
INSERT INTO "theory_regimes" VALUES(156,'hidden-valley-chi-two-flavor',1,NULL,'Microscopic gauge and matter construction','Source-stated mass-generating couplings, Abelian kinetic mixing and scalar portal; full scalar potential unspecified','nv=2 and q+=q−=−1 are omitted by the source. Table I charges refer to the basis before kinetic-mixing removal.',NULL);
INSERT INTO "theory_regimes" VALUES(157,'hidden-valley-chi-two-flavor',1,NULL,'Two-light-flavor confined regime',NULL,'mU ∼ mC ≪ Λv. Approximate hidden isospin gives a QCD-like spectrum. In the flavor-conserving baseline, terminal hidden pions and nucleons are stable and invisible except πv0; superscript ± is not electric charge.',NULL);
INSERT INTO "theory_regimes" VALUES(158,'hidden-valley-chi-two-flavor',1,NULL,'One-light-flavor confined regime',NULL,'mC ≫ Λv ≫ mU. Spectrum and decay modes are uncertain; stability against hidden strong decay is distinct from absolute stability. ηv′ is assumed lightest for the illustrated analysis; vector strong stability is conditional on the source''s Cp conservation.',NULL);
INSERT INTO "theory_regimes" VALUES(159,'hidden-valley-chi-two-flavor',1,NULL,'Heavy-hidden-quark glueball regime',NULL,'mU,mC ≫ Λv. Source describes longer-lived glueballs and decays inside or outside detectors; its word stable does not establish absolute stability. No detailed spectrum or decay operator matching is supplied.',NULL);
INSERT INTO "theory_regimes" VALUES(160,'hidden-valley-colored-x-framework',1,NULL,'Heavy jointly charged mediator description','Gauge-charge and mass inventory only; full microscopic action unspecified','X and Xbar carry ordinary color and hidden SU(nv) charge; no unique representation or spin selected.',NULL);
INSERT INTO "theory_regimes" VALUES(161,'hidden-valley-colored-x-framework',1,NULL,'Gluonic effective portal below the heavy-X threshold','Induced dimension-eight operator set, with tr G² tr Gv² displayed as one example','Local effective-operator treatment applies below the mediator threshold. Other tensor structures and matching coefficients are not enumerated.',NULL);
INSERT INTO "theory_regimes" VALUES(162,'hidden-valley-colored-x-framework',1,NULL,'Confined hidden-glueball description',NULL,'Several metastable glueballs of various spins with masses of order Λv. Their decay channels depend on the induced operator set; no complete spin spectrum or numerical lifetime is fixed.',NULL);
INSERT INTO "theory_regimes" VALUES(163,'hidden-valley-x-adjoint-prompt',1,NULL,'Hidden-adjoint prompt-decay branch',NULL,'Inherit the common heavy-X loop portal; assume additional interactions allowing prompt X decay. Their microscopic form is unresolved.',NULL);
INSERT INTO "theory_regimes" VALUES(164,'hidden-valley-x-adjoint-stable',1,NULL,'Stable hidden-adjoint branch',NULL,'Select either color triplet or octet X. Hidden-gluon screening produces Xgv, accompanied by hidden glueballs. Spin and stability mechanism remain unselected.',NULL);
INSERT INTO "theory_regimes" VALUES(165,'hidden-valley-x-fundamental-stable',1,NULL,'Stable hidden-fundamental branch',NULL,'Stable constituents form a flux-tube-connected pair and eventually annihilate. The visible representation and microscopic stability mechanism are unspecified.',NULL);
INSERT INTO "theory_regimes" VALUES(166,'secluded-dirac-u1-higgsed',1,'4','Displayed gauge-basis construction and Higgsed expansion','Renormalizable terms of Eqs. (2)-(3); unspecified U retained','Conventional and secluded annihilation are mass regimes of this theory. Vector-pair annihilation requires mψ>mV. No extra ultraviolet thermalizing operator is included in this truncation.',NULL);
INSERT INTO "theory_regimes" VALUES(167,'secluded-dirac-u1-higgsed',1,'4','Conditional decoupled dark-radiation limit',NULL,'Set κ=0 and choose an unbroken or very-low-scale U(1)'' background. Massless-vector radiation pertains to the unbroken limit. Early decoupling can lower its temperature; no new inventory or quantitative breaking potential is specified.',NULL);
INSERT INTO "theory_regimes" VALUES(168,'secluded-fermion-scalar-portal',1,'4','Displayed singlet and Higgs portal construction','Eq. (16) operator inventory, with unspecified V(φ)','Use a shifted origin with <φ>=0. The illustrative λ2→0 limit is not symmetry enforced. Both mediator mass hierarchies and the minimal scalar-coupled MeV application use this inventory.',NULL);
INSERT INTO "theory_regimes" VALUES(169,'secluded-neutrino-portal-z2',1,'4','Baseline neutrino-portal construction','Displayed Eq. (19) masses, Yukawa assignments and scalar portal','Unbroken joint Z2 protects the lighter odd state. Neither an NR flavor count nor a complete scalar potential is supplied.',NULL);
INSERT INTO "theory_regimes" VALUES(170,'secluded-neutrino-portal-z2',1,'4','Conditional fermionic dark-matter application',NULL,'mS>mN''>mNR; N'' annihilates into NR pairs through S exchange. Same fields and couplings as regime 169; unbroken Z2 assumed.',NULL);
INSERT INTO "theory_regimes" VALUES(171,'secluded-neutrino-portal-z2',1,'4','Conditional scalar dark-matter application',NULL,'mN''>mS>mNR; S annihilates into NR states through N'' exchange. Same fields and couplings as regime 169; unbroken Z2 assumed.',NULL);
INSERT INTO "theory_regimes" VALUES(172,'simp-sp-pions',1,'4','Microscopic confining gauge description','Gauge theory with 2Nf fundamental Weyl fermions and the displayed flavor-preserving mass term','Nc is even and denotes fundamental dimension. Condensation is expected for moderately small Nf in the asymptotically free range; no numerical upper bound is specified.',NULL);
INSERT INTO "theory_regimes" VALUES(173,'simp-sp-pions',1,'4','Confined SU(2Nf)/Sp(2Nf) pion EFT','Displayed quadratic and four-pion mass/kinetic terms plus the leading five-pion WZW term','Assumed chiral breaking; Nf>=2 for the source''s WZW mechanism. Pions are the lightest states. Higher-derivative corrections can be order one near Lambda=2pi fpi.','The auxiliary five-dimensional WZW construction does not introduce a physical extra dimension or a bulk field inventory.');
INSERT INTO "theory_regimes" VALUES(174,'simp-su-pions',1,'4','Microscopic generalized QCD-like gauge description','SU(Nc) with Nf fundamental Dirac fermions and flavor-preserving masses','Conditional on the source''s SU(Nf)×SU(Nf) to SU(Nf) chiral pattern; no universal statement for exceptional color representations is inferred.',NULL);
INSERT INTO "theory_regimes" VALUES(175,'simp-su-pions',1,'4','Confined chiral SU(Nf) pion EFT','Leading terms of Eq. (12), with the source''s generalization prescription','Nf>=3 for the stated WZW mechanism. Baryons and other resonances are omitted only when much heavier than pions. Leading chiral predictions near Lambda=2pi fpi have potentially order-one corrections.',NULL);
INSERT INTO "theory_regimes" VALUES(176,'simp-o-pions',1,'4','Microscopic orthogonal gauge description at stated source detail','O(Nc) with Nf vector fermions and flavor-preserving masses','Spinor counting is unspecified. Assume the stated SU(Nf) to SO(Nf) chiral pattern; no complete microscopic action or disconnected-group prescription is reconstructed.',NULL);
INSERT INTO "theory_regimes" VALUES(177,'simp-o-pions',1,'4','Confined SU(Nf)/SO(Nf) pion EFT','Leading terms of Eq. (12), with the source''s generalization prescription','Nf>=3 is the source-stated WZW threshold. Omit baryons and other resonances only when much heavier than pions. Leading chiral predictions near Lambda=2pi fpi have potentially order-one corrections.',NULL);
INSERT INTO "theory_regimes" VALUES(178,'vector-higgs-portal-z2-eft',1,NULL,'Origin-independent massive-vector effective description','Displayed parity-even mass, dimension-four Higgs portal and vector quartic','Use below its longitudinal-scattering unitarity cutoff and any eliminated-particle thresholds. The reduced vector theory is ultraviolet-incomplete.',NULL);
INSERT INTO "theory_regimes" VALUES(179,'vector-portal-stueckelberg-higgs',1,NULL,'Gauge-invariant direct Higgs-dependent Stückelberg description','Eqs. (3)–(7), including the field-dependent Stückelberg kinetic interactions','An effective construction with higher-dimensional interactions; no complete ultraviolet theory or relation between mu, M and the electroweak scale is selected.',NULL);
INSERT INTO "theory_regimes" VALUES(180,'vector-portal-stueckelberg-scalar',1,NULL,'Scalar-mediated Stückelberg description with S retained','Stückelberg mass function mu² S²/M², scalar portal and symbolic V(S)','Higher-dimensional effective construction. Heavy-S matching requires m_h²,m_X² much smaller than m_S²; loop coefficients require a cutoff expected near M.',NULL);
INSERT INTO "theory_regimes" VALUES(181,'vector-portal-abelian-higgs',1,NULL,'Minimal hidden Abelian Higgs description with charged S retained','Displayed Eq. (14); V(S) remains symbolic','Assume a broken phase with a physical hidden Higgs excitation. Vector-only reduction requires eliminating that excitation; no full potential or exact vacuum is supplied.',NULL);
INSERT INTO "theory_regimes" VALUES(182,'vector-higgs-portal-z2-eft',1,NULL,'Conditional thermal dark-matter and invisible-Higgs scan','Same EFT with lambda=0 for simplicity','Scan lambda_hv and m_X without selecting their microscopic origin. Require validity approximately up to v for light X and 2m_X for heavy X. WMAP, XENON100 and ATLAS/CMS comparisons are historical results of this paper.',NULL);
INSERT INTO "theory_regimes" VALUES(183,'silh-hww-operator-sector',1,NULL,'Displayed SILH Higgs and weak-gauge operator sector','Selected dimension-six terms of Eq. (5.1), through O(1/f²)=O(ξ)','Only SM particle content is retained. The Goldstone-Higgs strong-sector interpretation does not specify microscopic dynamics. Amplitudes of order ξ² and higher generally require missing higher-order Lagrangian terms; two dimension-six insertions do not complete that expansion.',NULL);
INSERT INTO "theory_regimes" VALUES(184,'smeft-d6-b-conserving',1,'4','Gauge-invariant SM operator description before selecting a broken vacuum','L=L_SM^(4)+sum C^(5)Q^(5)/Lambda+sum C^(6)Q^(6)/Lambda^2+O(Lambda^-3); baryon-conserving dimension-six sector','Low energies below Lambda with only SM fields retained. Basis equivalence is modulo total derivatives and EOM-vanishing combinations. Dimension-six reductions use the renormalizable EOM; corrections from dimension five enter those reductions beyond the retained order. SSB is not analyzed.',NULL);
INSERT INTO "theory_regimes" VALUES(185,'smeft-d6-b-violating',1,'4','Common gauge-invariant EFT with baryon-violating four-fermion operators admitted','Inherited expansion through Lambda^-2, supplemented by Qduq, Qqqu, Qqqq and Qduu and their Hermitian conjugates','Same SM field content and general generation labels. Four denotes operator types before flavor assignments and Hermitian conjugates, as stated in the pinned version. No selected UV origin or baryon-violating benchmark.',NULL);
INSERT INTO "theory_regimes" VALUES(186,'general-heavy-field-tree-matching',1,'4','High-energy effective matching framework','Relevant single-spin heavy interactions through dimension five; mixed-spin interactions through dimension four; pure-SM L0 through dimension six','Only representations admitting linear heavy–SM interactions of dimension at most four contribute at the stated classical matching order. The criterion does not remove relevant interactions involving several heavy fields.',NULL);
INSERT INTO "theory_regimes" VALUES(187,'general-heavy-field-tree-matching',1,'4','Classically matched low-energy description','Local Warsaw-basis SMEFT operators through canonical dimension six','Energies much smaller than every integrated-out mass. Heavy-field contributions supplement L0 and need not equal the complete low-energy coefficients. This regime is a matching prescription with unselected coefficients.',NULL);
INSERT INTO "theory_regimes" VALUES(188,'real-singlet-linear-portal-gluon-sector',1,'4','Displayed heavy-singlet sector in the electroweak-symmetric matching basis','Selected renormalizable scalar terms plus S G G/f','Canonical real scalars with diagonal gauge-invariant masses; heavy replica indices retained. Matching formulas select individual contributions and do not assert all unlisted terms vanish.',NULL);
INSERT INTO "theory_regimes" VALUES(189,'sm-singlet-neutrino-framework',1,'4','Heavy-neutrino classical matching application','Renormalizable N-sector contributions to dimension-five and dimension-six SMEFT','Integrate out all retained singlets at energies well below their masses. The selected N-only formulas exclude dimension-five heavy interactions and additional heavy sectors, giving Zphi=1. This does not impose a new neutrino count or flavor texture.',NULL);
INSERT INTO "theory_regimes" VALUES(190,'scalar-zeta-ql-qq-sector',1,'4','Single-ζ gauge-basis matching example','Displayed renormalizable leptoquark and diquark interactions; selected dimension-six matching','One heavy multiplet in the Section 5 example. Matching is classical and isolates its contributions. Scalar potential and full ultraviolet completion are not specified.',NULL);
INSERT INTO "theory_regimes" VALUES(191,'heavy-weak-triplet-proca-current-sector',1,'4','Single-W covariant Proca matching example','Proca quadratic action and displayed dimension-four currents; selected dimension-six matching','One heavy multiplet with couplings to L1 omitted in Section 5. No gauge-origin completion or universal fermion-current coupling is assumed.',NULL);
INSERT INTO "theory_relations" VALUES(1,'complex-singlet-portal',1,'real-singlet-z2',1,'complex_field_generalization','P02 describes complex S as two canonical real components with identical displayed mass and portal coefficients. The extra real degree of freedom prevents identity with the one-real-singlet construction. This relation does not establish equivalence of unspecified self-interaction sectors.','provisional');
INSERT INTO "theory_relations" VALUES(2,'thdm-type-i-real-z2',1,'thdm-type-ii-real-z2',1,'distinct_Yukawa_realizations_of_shared_scalar_structure','Both specifications use the same scalar representations and real restricted potential. Type I assigns all charged-fermion sectors to one doublet; Type II separates up quarks from down quarks and charged leptons, with different fermion Z2 actions. This is not an identity or historical-priority relation.','provisional');
INSERT INTO "theory_relations" VALUES(3,'lr-triplet-parity',1,'lr-triplet-charge-conjugation',1,'distinct_discrete_realizations_of_shared_LR_structure','Shared gauge and multiplet content supports different discrete actions and different Yukawa restrictions. General P and C are not identified. The footnote-level real-symmetric-Yukawa special case does not establish equivalence of their unresolved complete sectors.','provisional');
INSERT INTO "theory_relations" VALUES(4,'nmssm-z3-rpc-cpc',1,'nmssm-general-rpc-cpc',1,'operator_restriction','Same inherited gauge and multiplet content. Set μ = μ′ = ξF = m3² = mS′² = ξS = 0 in the displayed coordinates; all other displayed sectors remain. The accidental Z3 action distinguishes this restriction from choosing μ = 0 by shifting the singlet origin.','provisional');
INSERT INTO "theory_relations" VALUES(5,'mchm-spinorial-scalar14',1,'mchm-spinorial',1,'additional_scalar_source_extension','Adds dimension-two scalar operators and 14_0 sources, with the stated bulk 14 realization. Pure sin⁴ and sin⁴−sin² potentials are source limits of this extension, not new minimal-model parameter points.','provisional');
INSERT INTO "theory_relations" VALUES(6,'sm-octet-doublet-mfv-triplets',1,'sm-octet-doublet-mfv',1,'additional_real_triplet_extension','Adds three real (1,3)0 fields and the displayed Eq. (42) interactions. This is additional field content, not a mass benchmark of the minimal octet model. Representation-label conflicts and potential completeness remain qualified.','provisional');
INSERT INTO "theory_relations" VALUES(7,'su5-gg-extra5-two10',1,'su5-georgi-glashow-review',1,'additional_scalar_extension','Adds one scalar 5 and two scalar 10s. The desert spectrum is a regime of the extension; this is not a parameter point of minimal GG.','provisional');
INSERT INTO "theory_relations" VALUES(8,'su5-gg-scalar15',1,'su5-georgi-glashow-review',1,'additional_scalar_extension','Adds a scalar 15, with type-II-seesaw and unified flavor information. The reviewed realization also invokes higher-dimensional charged-fermion contributions, whose operators are not reconstructed.','provisional');
INSERT INTO "theory_relations" VALUES(9,'u1-chi-minimal16-charge',1,'e6-full27-charge-template',1,'charge_specialization_and_optional_fermion_removal','Set θE6=0 and ε=0, then omit the non-chiral 10+1 fermion collections. This relation concerns charge inventories only; unspecified scalar and interaction completions are not identified.','provisional');
INSERT INTO "theory_relations" VALUES(10,'u1-chi-minimal16-charge',1,'u1-ybl-charge-family',1,'fermion_charge_specialization','The review identifies χ as a T3R–TBL special case. Matching the retained Table II charges gives b=−5/sqrt(10), z=−4/5, an algebraic conversion of Eqs. (45) and Table II. This is not a claim of complete-model equivalence.','provisional');
INSERT INTO "theory_relations" VALUES(11,'minimal-bl-pure',1,'u1-ybl-charge-family',1,'fermion_charge_specialization_with_selected_scalar_and_mass_sectors','Compare the existing template Q2=b[zY+(B−L)/2] at z=0, b=2. Conjugating ucL, dcL, e+L and νcL gives P14''s right-handed charges. More generally, at z=0 current normalization matches when g1′=b g2/2 in corresponding unmixed bases. This algebraic correspondence concerns fermion currents only. P14 additionally selects H, χ of B−L charge +2, its potential and neutrino Yukawas, and vanishing mixing; P13 left these completion choices open.','provisional');
INSERT INTO "theory_relations" VALUES(12,'pp331-sigma-omega',1,'pp331-displayed',1,'additional_scalar_triplet_extension','Adds independent sigma and omega with eta''s quantum numbers and an epsilon eta sigma omega contraction. Only the locally stated extension is reconstructed; neither its vacuum nor its complete potential is identified with the baseline.','provisional');
INSERT INTO "theory_relations" VALUES(13,'ql421-inverse-seesaw',1,'ql421-dirac',1,'additional_singlet_fermion_extension','Adds three N fields and Eq. (17), retaining the gauge and scalar construction and four core Yukawas. µ→0 restores matter symmetry but does not remove N or identify the extension with the core.','provisional');
INSERT INTO "theory_relations" VALUES(14,'so10-45-126-complex10',1,'so10-45-126-sector',1,'additional_scalar_and_matter_sector_completion','Adds a complex 10H and explicitly describes the matter Yukawa sector. The 45-126 scalar subpotential is inherited, but new interactions alter the doublet mixing and potentially the vacuum and spectrum. A fitted realistic completion is proposed, not established.','provisional');
INSERT INTO "theory_relations" VALUES(15,'mssm-minimal-gauge-messengers',1,'mssm-rpc-conventional-soft',1,'messenger_extension_and_soft_matching','Adds S and four messenger chiral multiplets with W_mess. Below the messenger threshold the visible conventional soft operators receive the specified gauge-mediated contributions. This is not identity of the high-energy inventories, nor a complete hidden-sector or gravitational completion.','provisional');
INSERT INTO "theory_relations" VALUES(16,'mssm-rpv-general',1,'mssm-rpc-conventional-soft',1,'parity_restriction_relaxation','Same minimal gauge and superfield content, with parity-odd superpotential and displayed soft operators added. Setting all independent RPV sources to zero recovers the RPC operator sector. Neither the existing vacuum nor an unaudited component-sign conversion is inherited.','provisional');
INSERT INTO "theory_relations" VALUES(17,'mssm-rpv-bilinear',1,'mssm-rpv-general',1,'operator_restriction','There exists a basis with only mu_i, B_i and mtilde_di^2 providing RPV. This is stronger than removing mu_i by an SU(4) rotation; induced trilinears are dependent and baryon-violating lambda-double-prime is absent.','provisional');
INSERT INTO "theory_relations" VALUES(18,'mssm-rpv-dim23',1,'mssm-rpv-general',1,'operator_restriction','Remove trilinear RPV superpotential terms while keeping all displayed RPV soft terms and mu_i. Independent triscalar soft terms distinguish this from bilinear-only breaking.','provisional');
INSERT INTO "theory_relations" VALUES(19,'mssm-rpv-soft-bilinear',1,'mssm-rpv-general',1,'operator_restriction','Retain only B_i and mtilde_di^2 as independent RPV sources in the defining basis; remove RPV superpotential and soft triscalars.','provisional');
INSERT INTO "theory_relations" VALUES(20,'rpv-singlet-spontaneous-sector',1,'mssm-rpv-bilinear',1,'effective_bilinear_mechanism_correspondence','The assumed v_R gives mu_i=h^nu_i3 v_R/sqrt(2) and induced lambda/lambda-prime flavour structure. This is not complete-model equivalence or a supplied decoupling matching: the Majoron and singlet fields remain additional physical content.','provisional');
INSERT INTO "theory_relations" VALUES(21,'su5-rpv-trilinear-sector',1,'mssm-rpv-general',1,'unified_operator_embedding','The unified trilinear correlates the three MSSM trilinear RPV classes as in Eq. (2.67). This relates operator sectors only and does not supply a complete GUT breaking or threshold matching.','provisional');
INSERT INTO "theory_relations" VALUES(22,'split-susy',1,'mssm-rpc-conventional-soft',1,'heavy_scalar_effective_description','P23 explicitly obtains its EFT by removing sfermions and the heavy Higgs sector from the supersymmetric SM while tuning one light Higgs direction. This supports a decoupling correspondence to the existing matter-parity-conserving MSSM operator framework, not identity of retained inventories or inheritance of every general parent soft coefficient, vacuum, or convention.','provisional');
INSERT INTO "theory_relations" VALUES(23,'gem-supersoft-messengers',1,'gem-supersoft',1,'partial_messenger_origin','Adds T and bar T with Eq. (3.1); their threshold generates both supersoft operators. This is a possible mediation origin, not a unique UV completion or an identity with the EFT inventory.','provisional');
INSERT INTO "theory_relations" VALUES(24,'gem-supersoft-su5-bachelors',1,'gem-supersoft',1,'additional_bachelor_field_completion','Adds the (3,2,-5/6) and (bar3,2,+5/6) chiral multiplets to complete the visible ESP inventory into a proposed SU(5) adjoint; Section 3.2 coupling restrictions apply.','provisional');
INSERT INTO "theory_relations" VALUES(25,'gem-supersoft-su3cubed-bachelors',1,'gem-supersoft',1,'additional_bachelor_field_completion','Adds the Section 3.2.1 bachelor inventory with its coupling restrictions. These additional multiplets cannot be represented solely as a core mass choice.','provisional');
INSERT INTO "theory_relations" VALUES(26,'u1-minimal-gauge-messenger-toy',1,'general-gauge-mediation',1,'illustrative_Abelian_messenger_realization','Appendix A realizes the Abelian current-correlator calculation with explicit messengers. This relates the toy mechanism to the framework, without claiming that the toy alone supplies an MSSM visible sector or a dynamical hidden completion.','provisional');
INSERT INTO "theory_relations" VALUES(27,'general-gauge-mediation-higgs-operators',1,'general-gauge-mediation',1,'direct_Higgs_operator_extension','Adds O_u H_u and O_d H_d couplings. At nonzero lambda_u,d, setting gauge couplings to zero alone does not decouple the sectors. No particular microscopic hidden theory or successful mu/Bmu solution is selected.','provisional');
INSERT INTO "theory_relations" VALUES(28,'ksvz-neutral-triplet',1,'ksvz-representation-framework',1,'specified_spectrum_specialization','Select one (3,1,0) vector-like pair coupled to Phi with X_QL=1/2 and X_QR=-1/2. The benchmark separately supplies its singlet potential; the framework does not identify every generalized spectrum with this model.','provisional');
INSERT INTO "theory_relations" VALUES(29,'dfsz-ii-quartic',1,'dfsz-i-quartic',1,'charged_lepton_Yukawa_replacement','Shared quartic scalar and quark sectors, but replace the H_d lepton assignment by i sigma_2 H_u*. The associated lepton charge difference and electromagnetic anomaly change; this is not complete-model identity or a scalar vacuum choice.','provisional');
INSERT INTO "theory_relations" VALUES(30,'smash-down',1,'ksvz-representation-framework',1,'KSVZ_sector_realization_with_additional_seesaw_and_portal_structure','The target explicitly identifies its colored-pair axion mechanism as KSVZ-type. Its selected pair has down-type hypercharge, and its PQ-breaking scalar also couples to three singlet neutrinos and the Higgs. This is a sector correspondence, not full-model equivalence, baseline inheritance or an asserted detailed charge-coordinate map.','provisional');
INSERT INTO "theory_relations" VALUES(31,'lns-single-singlet-quarks',1,'lns-two-singlet-quarks',1,'singlet_and_horizontal_symmetry_replacement','Replace S1,S2 by S and the two generators by H=2H1+3H2. Relating epsilon1,epsilon2 to powers of epsilon reproduces the old nonzero-entry orders but permits the former Mu12 and Mu32 zeros. This is not full-model equivalence and does not transfer the heavy realization.','provisional');
INSERT INTO "theory_relations" VALUES(32,'lns-reduced-quarks',1,'lns-two-singlet-quarks',1,'heavy_field_removal_and_down_charge_replacement','Remove U2,U3,D1,D2,D5 with conjugate partners; change dbar charges to ((-1,1),(0,0),(0,0)). Combine the resulting massless-up realization with a small down-Higgs VEV. This changes structural inventory and generated operators, not only masses within the original inventory.','provisional');
INSERT INTO "theory_relations" VALUES(33,'af-a4-susy-seesaw',1,'af-a4-susy-effective',1,'neutrino_sector_and_auxiliary_charge_replacement','Add nu^c as an A4 triplet; replace the five neutrino-sector flavon/driving Z3 phases and the leading neutrino interactions. Retain the charged-lepton sector and leading w_d and alignment. The different charge assignments and inverse-heavy-mass structure do not establish that integrating out nu^c reproduces the full effective specification with its original charges and independent coefficients.','provisional');
INSERT INTO "theory_relations" VALUES(34,'grv-quark-flavor-su3',1,'grv-quark-flavor-u3',1,'flavor_gauge_sector_restriction','Delete the two gauged right-handed flavor-number U(1) factors and their vector fields, retaining the common fermion and two-bifundamental inventory and six displayed fermion operators. This changes gauge content, not just a mass benchmark. Scalar spectra and potential operator bases are not identified.','provisional');
INSERT INTO "theory_relations" VALUES(35,'numsm',1,'sm-singlet-neutrino-framework',1,'fixed_multiplicity_specialization','Set N=3 in the parent field collection, Yukawa columns and Majorana masses. Retain the inherited SM and all Eq. (1) operator classes. The νMSM name additionally selects the source''s electroweak-scale-or-lighter mass domain; later cosmological benchmarks are applications.','provisional');
INSERT INTO "theory_relations" VALUES(36,'twin-higgs-linear-scalar-sector',1,'twin-higgs-unextended',1,'possible_linear_origin_of_nonlinear_Higgs_sector','Integrating out the radial H mode supplies the nonlinear scalar coordinates. The recorded linear example only gauges the illustrative weak subgroup; this relation does not identify its incomplete matter inventory with the full doubled-SM theory or assert a unique ultraviolet completion.','provisional');
INSERT INTO "theory_relations" VALUES(37,'twin-higgs-extended-top',1,'twin-higgs-unextended',1,'top_sector_extension_and_Yukawa_replacement','Adds the cross-sector Q_L components and their opposite-charge partners, replacing the ordinary top assignment by yHQ_LT_R and the common exotic mass M. The absence of jointly charged matter and its kinetic-mixing conclusions do not transfer to this extension.','provisional');
INSERT INTO "theory_relations" VALUES(38,'mirror-higgs-unextended',1,'twin-higgs-unextended',1,'distinct_discrete_actions_with_source_stated_similar_phenomenology','Mirror symmetry combines spatial inversion and CP-conjugate interchange, whereas twin symmetry directly exchanges corresponding particles. The source assigns the mirror model the phenomenology of the unextended twin branch; this is not an equivalence of their discrete actions.','provisional');
INSERT INTO "theory_relations" VALUES(39,'fraternal-twin-higgs',1,'twin-higgs-unextended',1,'shared_protection_mechanism_with_reduced_twin_inventory','Shares twin cancellation but removes the first two twin generations and low-energy twin hypercharge and retains a perturbative radial scalar. This is not parameter-only specialization or automatic baseline inheritance. Existing records already permit unmatched small Yukawas and soft misalignment, so those are not claimed as new distinctions. P38''s broad mirror terminology does not identify the earlier distinct twin and mirror actions.','provisional');
INSERT INTO "theory_relations" VALUES(40,'six-dimensional-pati-salam-vortex',1,'large-extra-dimensions-framework',1,'illustrative_localization_realization','Specializes to two compact dimensions and supplies a Pati–Salam vortex sector. Its gauge localization is conditional on a postulated bulk gap. The general framework does not require this gauge group, topology or field inventory.','provisional');
INSERT INTO "theory_relations" VALUES(41,'holographic-su3-brane-scalar-mediator',1,'holographic-boundary-pgb-framework',1,'source_stated_large_vev_boundary_limit','The section 3 brane-breaking gauge/Higgs sector approaches a corresponding SU(3)L boundary-condition realization as v tends to infinity. This does not identify a finite-VEV theory with every G,H0,H1 member, or supply a matching of the retained six mediator and its quartic mechanism to the separate section 4.2 tadpole proposal.','provisional');
INSERT INTO "theory_relations" VALUES(42,'hidden-valley-chi-two-flavor',1,'hidden-valley-framework',1,'illustrative_portal_realization','The source''s simple theory selects hidden SU(nv), two quark flavors and an additional massive Abelian mediator within the broader framework.','provisional');
INSERT INTO "theory_relations" VALUES(43,'hidden-valley-colored-x-framework',1,'hidden-valley-framework',1,'heavy_loop_portal_realization','Realizes the heavy jointly charged mediator option with hidden glueball phenomenology. The mediators themselves are heavy and need not be SM-neutral.','provisional');
INSERT INTO "theory_relations" VALUES(44,'hidden-valley-x-adjoint-prompt',1,'hidden-valley-colored-x-framework',1,'representation_and_decay_specialization','Select hidden adjoint and prompt decay; microscopic decay completion remains open.','provisional');
INSERT INTO "theory_relations" VALUES(45,'hidden-valley-x-adjoint-stable',1,'hidden-valley-colored-x-framework',1,'representation_and_stability_specialization','Select hidden adjoint, stable X and alternative color 3 or 8. No equivalence between the two fixed color choices is asserted.','provisional');
INSERT INTO "theory_relations" VALUES(46,'hidden-valley-x-fundamental-stable',1,'hidden-valley-colored-x-framework',1,'representation_and_stability_specialization','Select stable fundamental X with a confining pair flux tube. This is not adjoint screening at a different mass point.','provisional');
INSERT INTO "theory_relations" VALUES(47,'vector-portal-stueckelberg-higgs',1,'vector-higgs-portal-z2-eft',1,'gauge_invariant_realization_of_displayed_portal','The direct field-dependent mass supplies lambda_hv=2zeta mu²/M² and vector parity. This is a realization of the displayed EFT terms, not a unique ultraviolet completion or inheritance of arbitrary EFT coefficients.','provisional');
INSERT INTO "theory_relations" VALUES(48,'vector-portal-stueckelberg-scalar',1,'vector-higgs-portal-z2-eft',1,'conditional_heavy_scalar_matching','Eliminating heavy S produces both the Higgs-vector portal and the Eq. (10) vector quartic. Matching requires the stated hierarchy; the later lambda=0 scan is not the generic matched prediction. Higher-order operators are not fully enumerated.','provisional');
INSERT INTO "theory_relations" VALUES(49,'vector-portal-abelian-higgs',1,'vector-higgs-portal-z2-eft',1,'conditional_hidden_Higgs_elimination','Eliminating the physical hidden Higgs in unitary gauge gives vector-even interactions and xi1=xi2=0. The source identifies a generated H†H X² portal but does not supply a complete normalized matching action.','provisional');
INSERT INTO "theory_relations" VALUES(50,'smeft-d6-b-violating',1,'smeft-d6-b-conserving',1,'baryon_conservation_restriction_relaxation','Same SM field inventory and common operators, with four additional baryon-violating dimension-six types. Setting their coefficient tensors to zero recovers the baryon-conserving operator space. This is not a UV-completion or historical-priority relation.','provisional');
INSERT INTO "theory_specifications" VALUES('real-singlet-z2',1,'Standard Model plus a Z2-symmetric real singlet scalar',NULL,'defined_for_stated_scope','Renormalizable singlet sector, Higgs interaction and chosen vacuum; inherited Standard Model','Provisional identity pending P02 comparison. Vacuum choices and phenomenological mass preferences do not define separate constructions. Conflicting Higgs normalization and competing-minimum restrictions are deferred.','Standard Model Lagrangian L_SM; component inventory not independently specified','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('complex-singlet-portal',1,'Standard Model with a complex scalar singlet Higgs portal',NULL,'partial_structural_specification','Complex singlet field, canonical real-component decomposition, displayed mass and Higgs portal','P02 Section 6.4 minimal generalization with no additional interactions. Self-interaction completion, exact stabilizing symmetry and vacuum classification remain unspecified. The proposed additional X field is outside this specification.','Standard Model, referenced through its Higgs field; component inventory not enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('thdm-type-i-real-z2',1,'Type-I 2HDM with a real Z2-restricted scalar potential',NULL,'partial_structural_specification','Two scalar doublets, conventional quark and charged-lepton Yukawa assignments, Z2 realization, real scalar potential and scoped neutral vacuum','Provisional parameterized construction matching the prepared early-chapter scope. Real soft m12² is permitted, including zero. Scalar CP conservation and the selected vacuum are recorded as assumptions. Signed mass-eigenstate couplings are deferred.','Standard Model gauge and fermion sectors; scalar sector replaced by two doublets. Baseline inventory is not fully enumerated.','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('thdm-type-ii-real-z2',1,'Type-II 2HDM with a real Z2-restricted scalar potential',NULL,'partial_structural_specification','Two scalar doublets, conventional quark and charged-lepton Yukawa assignments, Z2 realization, real scalar potential and scoped neutral vacuum','Provisional parameterized construction matching the prepared early-chapter scope. Real soft m12² is permitted, including zero. Scalar CP conservation and the selected vacuum are recorded as assumptions. No MSSM scalar relations are imposed. Signed mass-eigenstate couplings are deferred.','Standard Model gauge and fermion sectors; scalar sector replaced by two doublets. Baseline inventory is not fully enumerated.','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lr-triplet-parity',1,'Minimal triplet left-right theory with generalized parity',NULL,'partial_structural_specification','Displayed LR gauge sector, quark and lepton doublets, scalar bidoublet and triplets, quark Yukawa operators, parity actions and breaking pattern','Provisional identity. Complete scalar potential, lepton Yukawa operators and explicit lepton/triplet parity actions remain unresolved. Real-VEV and collider choices are scoped applications.','Color sector suppressed by the source; no independently enumerated baseline Lagrangian','unresolved',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lr-triplet-charge-conjugation',1,'Minimal triplet left-right theory with generalized charge conjugation',NULL,'partial_structural_specification','Displayed LR gauge sector, quark and lepton doublets, scalar bidoublet and triplets, quark Yukawa operators, charge-conjugation actions and breaking pattern','Provisional identity. Complete scalar potential, lepton Yukawa operators and explicit lepton/triplet C actions remain unresolved. No SO(10) completion or compulsory CP-conserving phase choice is imposed.','Color sector suppressed by the source; no independently enumerated baseline Lagrangian','unresolved',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('nmssm-general-rpc-cpc',1,'General NMSSM with conserved R-parity and CP',NULL,'defined_for_stated_scope','Singlet extension, Higgs and matter superpotentials, displayed scalar and gaugino soft terms, neutral vacuum conventions','Provisional Section 2.1 specification. MSSM baseline is inherited, not fully enumerated. General dimensionful terms are retained before the optional singlet-origin convention. No mediation mechanism or high-scale universality is imposed.','MSSM','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('nmssm-z3-rpc-cpc',1,'Z3-invariant NMSSM with conserved R-parity and CP',NULL,'defined_for_stated_scope','Cubic Higgs and matter superpotentials, surviving soft terms, accidental Z3 action and neutral vacuum conventions','Provisional Section 2.1 restriction with μ = μ′ = ξF = m3² = mS′² = ξS = 0. Scale invariance describes the superpotential; dimensionful soft masses and trilinear coefficients remain. MSSM baseline is inherited, not fully enumerated.','MSSM field and gauge content supplemented by one singlet chiral superfield','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('mchm-spinorial',1,'Minimal composite Higgs with spinorial fermion embedding',NULL,'partial_structural_specification','SO(5)/SO(4) composite Higgs; elementary sources; AdS gauge and quark sectors; boundary conditions; IR mixing; vacuum misalignment','Provisional shared identity for the effective and AdS descriptions. The 5D realization fixes form factors not determined by the general symmetry-based 4D account. Microscopic strong dynamics and detailed lepton realization remain unspecified.','Elementary Standard Model gauge and fermion fields coupled to a strong sector; Higgs supplied by the Goldstone sector','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('mchm-spinorial-scalar14',1,'Minimal composite Higgs with a scalar 14 source deformation',NULL,'partial_structural_specification','Additional dimension-two operators and scalar sources; SO(4)-dependent source masses; bulk scalar and IR tadpole','Parameterized Appendix B extension. Source propagation and decoupling limits are conditional choices. The full scalar bulk and boundary action is not enumerated.','Minimal spinorial composite-Higgs construction','explicit','mchm-spinorial',1);
INSERT INTO "theory_specifications" VALUES('georgi-machacek-general',1,'Georgi–Machacek model with the general custodial scalar potential',NULL,'defined_for_stated_scope','Electroweak scalar representations, gauge kinetics, custodial organization, general tree-level potential, fermion mass assignment, aligned vacuum and decoupling','Provisional identity. Both cubic operators are retained; their coefficients may vanish at parameter points. Custodial invariance refers to the scalar potential, not the full hypercharge-gauged theory. Matrix multiplets and mass eigenstates reorganize the same scalar degrees of freedom.','Standard Model gauge and fermion sectors; usual Higgs doublet supplemented by real and complex triplets. Baseline inventory is not fully enumerated.','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('threedm-d6',1,'Three-Higgs-doublet scalar potential with unitary D6 symmetry',NULL,'defined_for_stated_scope','Three complex Higgs doublets; renormalizable scalar potential; unitary generators and conditional generalized CP','Provisional parameterized scalar construction. Generic coefficients have exact unitary D6; special loci can enhance symmetry. Both explicitly CP-violating and CP-conserving coefficient choices are retained. Fermion completion and vacuum are unspecified.','Electroweak gauge framework of NHDM; no independently specified full Standard Model or fermion-sector completion','unresolved',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('threedm-d8',1,'Three-Higgs-doublet scalar potential with unitary D8 and automatic generalized CP',NULL,'defined_for_stated_scope','Three complex Higgs doublets; Z4-based renormalizable scalar potential; unitary D8 and commuting generalized CP','Provisional identity shared by descriptions 21 and 22. Generic full symmetry is D8 × Z2* when antiunitary transformations are counted. This is distinct from Z4 ⋊ Z2* with unitary subgroup Z4. Fermion completion and vacuum are unspecified.','Electroweak gauge framework of NHDM; no independently specified full Standard Model or fermion-sector completion','unresolved',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('sm-octet-doublet-mfv',1,'Standard Model with an MFV color-octet scalar doublet',NULL,'defined_for_stated_scope','Added scalar representation; aligned quark Yukawa interactions; displayed scalar potential; electroweak spectrum','Provisional parameterized construction. CP conservation and custodial restrictions are not imposed on the general potential. Heavy-octet calculations are a scoped regime. Neutrino-sector completion is not supplied.','Standard Model; Higgs and quark participants identified, remaining baseline inventory inherited','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('sm-octet-doublet-mfv-triplets',1,'MFV octet-doublet model with three real weak triplets',NULL,'partial_structural_specification','Three additional real triplets; displayed triplet potential; approximate triplet sign symmetry','Provisional Section VIII extension interpreted using the introduction and Eq. (42). Conflicting representation labels are retained through source qualifications. Unlisted interactions are not declared forbidden or zero; no grand-unified completion is specified.','Section III MFV octet-doublet construction','explicit','sm-octet-doublet-mfv',1);
INSERT INTO "theory_specifications" VALUES('vlq-t-singlet',1,'Standard Model with a vector-like T singlet',NULL,'defined_for_stated_scope','One added quark multiplet; gauge representation; weak-basis masses and third-family mixing','Provisional parameterized identity. SM sectors are inherited, not fully enumerated. Weak-basis and mass-eigenstate fields are distinguished.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vlq-b-singlet',1,'Standard Model with a vector-like B singlet',NULL,'defined_for_stated_scope','One added quark multiplet; gauge representation; weak-basis masses and third-family mixing','Provisional parameterized identity. SM sectors are inherited, not fully enumerated.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vlq-xt-doublet',1,'Standard Model with a vector-like (X T) doublet',NULL,'defined_for_stated_scope','One added quark doublet; gauge representation; weak-basis masses and third-family mixing','Provisional parameterized identity. X and T are components of one multiplet. No composite or extra-dimensional completion is imposed.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vlq-tb-doublet',1,'Standard Model with a vector-like (T B) doublet',NULL,'defined_for_stated_scope','One added quark doublet; two mixing Yukawas; shared bare mass','Provisional parameterized identity. Independent up/down mixing angles are retained; decay benchmarks are optional parameter choices.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vlq-by-doublet',1,'Standard Model with a vector-like (B Y) doublet',NULL,'defined_for_stated_scope','One added quark doublet; gauge representation; weak-basis masses and bottom mixing','Provisional parameterized identity. Bottom-asymmetry fits are applications. The Table 3 right-handed bottom coupling is not adopted.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vlq-xtb-triplet',1,'Standard Model with a vector-like (X T B) triplet',NULL,'defined_for_stated_scope','One added quark triplet; correlated mixing Yukawas; shared bare mass','Provisional parameterized identity. Triplet components use the source''s spherical basis; no additional scalar multiplet is introduced.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vlq-tby-triplet',1,'Standard Model with a vector-like (T B Y) triplet',NULL,'defined_for_stated_scope','One added quark triplet; correlated mixing Yukawas; shared bare mass','Provisional parameterized identity. Triplet components use the source''s spherical basis; no additional scalar multiplet is introduced.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lq-r2-general',1,'SM with a general scalar R2 leptoquark',NULL,'partial_structural_specification','Scalar representation; two Yukawa assignments; gauge kinetic and displayed Higgs operators','Provisional single-multiplet description. Self-interaction potential and vacuum are not reconstructed. No flavor texture or unified completion is imposed.','Standard Model; relevant participants enumerated only','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lq-rtilde2-nur',1,'SM with scalar Rtilde2 and three right-chiral neutrinos',NULL,'partial_structural_specification','Scalar and neutrino fields; two Yukawa assignments; displayed kinetic and Higgs operators','Provisional Eq. (5) branch with three nuR fields. Their masses and other interactions are unspecified. The alleged single-multiplet H Rtilde2 cubed operator is deferred, not assigned an implemented forbidding symmetry.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lq-u3-effective',1,'Effective vector U3 leptoquark description',NULL,'partial_structural_specification','Vector representation; LL current; displayed kinetic, mass and Higgs operators','Provisional effective description; no extended gauge group or Higgs breaking sector supplied.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lq-utilde1-effective',1,'Effective vector Utilde1 leptoquark description',NULL,'partial_structural_specification','Vector representation; RR current; displayed kinetic, mass and Higgs operators','Provisional effective description with unspecified ultraviolet completion.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lq-u1-effective',1,'Effective vector U1 with SM-fermion currents',NULL,'partial_structural_specification','Section 1.12 representation; LL and charged-lepton RR currents; displayed bosonic operators','Provisional SM-fermion branch. Additional nuR fields and their current are outside this specification. Local hypercharge 2/3 is retained with the conflicting completion passage explicitly qualified.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lq-ubar1-nur-effective',1,'Effective vector Ubar1 with right-chiral neutrinos',NULL,'partial_structural_specification','Vector representation; required nuR fields; RR current; displayed bosonic operators','Provisional neutrino-dependent description. Neutrino multiplicity, masses and ultraviolet completion remain unspecified.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('su5-georgi-glashow-review',1,'Georgi–Glashow SU(5), reviewed baseline',NULL,'partial_structural_specification','SU(5) gauge sector; dimensional matter inventory; scalar 24 and 5; breaking sequence','Provisional review-level identity. Matter-five conjugation, complete Yukawas and scalar potential are unresolved. Heavy mediator statements are scoped to this minimal setting.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('su5-gg-extra5-two10',1,'GG SU(5) with an additional scalar 5 and two scalar 10s',NULL,'partial_structural_specification','Added unified scalars; assumed desert light spectrum','Provisional Ref. [71] construction as reviewed. Full potential and any implemented proton-protection symmetry are unspecified. The review states that the model is no longer phenomenologically viable.','Reviewed Georgi–Glashow baseline','explicit','su5-georgi-glashow-review',1);
INSERT INTO "theory_specifications" VALUES('su5-gg-scalar15',1,'GG SU(5) with a scalar 15 and type-II seesaw',NULL,'partial_structural_specification','Added scalar 15; type-II-seesaw vacuum; stated unified flavor relation','Provisional Ref. [74] realization as reviewed. Higher-dimensional charged-fermion mass contributions are acknowledged but not reconstructed. Full scalar potential and tensor-level Yukawas remain unresolved.','Reviewed Georgi–Glashow baseline','explicit','su5-georgi-glashow-review',1);
INSERT INTO "theory_specifications" VALUES('mdm-majorana-quintuplet',1,'Minimal dark matter Majorana electroweak quintuplet',NULL,'defined_for_stated_scope','One colorless Y=0 fermion quintuplet; gauge kinetics and common mass; qualified accidental stability','Provisional identity. Majorana realization follows the minimal non-chiral interpretation in assertion 426. Thermal abundance and mass predictions are applications. Higher-dimensional operators require the stated suppression; no ultraviolet completion is specified.','Standard Model Lagrangian inherited from equation (1); baseline inventory not independently enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('mdm-real-septuplet-displayed',1,'Minimal dark matter real scalar septuplet, displayed operator specification',NULL,'partial_structural_specification','One colorless Y=0 scalar septuplet; gauge kinetics and mass; displayed scalar portal and self-interaction; assumed zero septuplet VEV','Provisional source-scoped identity. Real realization follows assertion 426. The displayed scalar terms are not certified as a complete independent operator basis. Automatic stability is retained only as a qualified source claim; no exact imposed stabilizing symmetry is inferred.','Standard Model Lagrangian inherited from equation (1); baseline inventory not independently enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('u1-ybl-charge-family',1,'Family-universal QYBL fermion-charge template',NULL,'framework_or_template','Additional Abelian charges of SM fermions and three conjugate right-handed neutrinos','Provisional parameterized charge template. Breaking scalars, supersymmetric completion and neutrino masses are not selected.','Standard Model fermion and gauge framework','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('e6-full27-charge-template',1,'E6-inspired full-27 fermion-charge template',NULL,'framework_or_template','Three full 27 fermion inventories and their χ–ψ charge parametrization','Provisional charge template, without a full E6 GUT or a selected supersymmetric realization. Grouped fields below are charge-equivalent collections, not new gauged SU(5) multiplets.','Standard Model fermion and gauge framework','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('u1-chi-minimal16-charge',1,'χ fermion-charge template with the optional 10+1 omitted',NULL,'framework_or_template','Three ordinary-family 16 inventories, including conjugate right-handed neutrinos, with unshifted χ charges','Provisional minimal fermion branch explicitly permitted by the review. No scalar 10, full SO(10) gauge theory or complete breaking sector is selected.','Standard Model fermion and gauge framework','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('umssm-single-s-higgs-sector',1,'Single-S supersymmetric U(1)′ Higgs sector',NULL,'partial_structural_specification','S, Hu, Hd superpotential, neutral component potential and conditional singlet-breaking vacuum','Provisional sector specification. S is a Standard Model singlet charged under U(1)′. Full matter charges and anomaly cancellation are unresolved; existing NMSSM CP and R-parity assumptions are not inherited.','MSSM context with an additional U(1)′ gauge sector','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('u1-two-singlet-flat-sector',1,'Two-singlet supersymmetric U(1)′ flat-direction toy sector',NULL,'partial_structural_specification','Opposite-sign singlet charges, superpotential exclusions and soft-plus-D-term potential','Provisional illustrative sector; no full matter or anomaly completion. Stabilization by running or higher-dimensional operators is conditional.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('abelian-stueckelberg-sector',1,'Isolated Abelian Stückelberg mass sector',NULL,'defined_for_stated_scope','Abelian gauge field, shifting scalar, kinetic term and gauge-invariant mass','Provisional Eq. (53) sector only. No matter current, SM coupling, supersymmetric extension or Green–Schwarz completion is assumed.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('minimal-bl-pure',1,'Pure minimal gauged B−L extension of the Standard Model',NULL,'defined_for_stated_scope','Gauge factors and charges; three right-handed neutrinos; complex singlet and Higgs doublet; scalar potential; Dirac and Majorana Yukawas; assumed broken vacuum','Provisional specification in the source''s zero-Abelian-mixing basis. General generation matrices are retained; flavor degeneracy and collider benchmarks are applications. Scalar minimization, exact mass-basis conventions and a quantum mixing prescription remain unresolved.','Standard Model gauge and matter sectors, supplemented by U(1)B−L, three right-handed neutrinos and one complex scalar χ','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('u1-leptonic-opposite-nur',1,'Opposite-family leptonic U(1) charges with three RH neutrinos',NULL,'partial_structural_specification','SM fermions, three RH neutrinos and their additional Abelian charges','Provisional three-neutrino branch of Section 3.2. Scalar content, Yukawas, neutrino masses and breaking are unspecified. Neutral neutrinos are retained when b=0.','Standard Model gauge and fermion framework','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('u1-sm-left23-charge',1,'SM U(1) charge assignment on second- and third-family left doublets',NULL,'partial_structural_specification','SM chiral fermion charges with physical weak-family identification','Provisional Table 1 solution 5 realization. No RH neutrinos added. Higgs charge, breaking sector and mass completion unspecified.','Standard Model gauge and fermion framework','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('u1-sm-top-only-charge',1,'Eq. (4.2) U(1) charge assignment with a top-only renormalizable Yukawa',NULL,'partial_structural_specification','SM fermion charges, Higgs charge and renormalizable Yukawa selection','Provisional FH=2 branch. No RH neutrinos added. Full scalar potential, additional breaking fields and higher-dimensional mass operators are unspecified.','Standard Model gauge and fermion framework with its Higgs doublet','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('u1-smnur-table5-14',1,'SM plus three RH neutrinos: Table 5 charge solution 14',NULL,'partial_structural_specification','Ordered fermion charge inventory','Provisional charge representative with all RH quarks neutral under U(1)F. Physical family assignments, scalar content, Yukawas and breaking are unspecified.','Standard Model gauge and fermion framework','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('u1-smnur-all-sm-yukawas',1,'Anomaly-free U(1) charges permitting all SM Yukawas with three RH neutrinos',NULL,'partial_structural_specification','Fermion and Higgs charges, charged-fermion Yukawa permission and anomaly restrictions','Provisional three-neutrino branch. RH-neutrino charges may be nonuniversal. No neutrino mass mechanism, breaking sector, scalar potential or Abelian mixing prescription selected.','Standard Model gauge and fermion framework with one Higgs doublet','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('pp331-displayed',1,'Pisano–Pleitez three-triplet SU(3)L × U(1)N construction, displayed v1 specification',NULL,'partial_structural_specification','Gauge factors, chiral multiplets, scalar triplets, displayed Yukawa assignments and potential, lepton-number convention and neutral vacuum','Provisional source-scoped identity. The appendix prescription and charged-lepton mass claim are not independently certified. Eq. (36) is recorded as displayed, without treating it as an exhaustive gauge-invariant operator basis. Color is acknowledged but its complete action is not reconstructed.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('pp331-sigma-omega',1,'Pisano–Pleitez construction with additional sigma and omega triplets',NULL,'partial_structural_specification','Two added eta-like scalar triplets and the displayed epsilon mixing operator','Provisional extension sketch. Baseline gauge and fermion content is inherited; the extended potential, vacuum, Yukawas and spectrum are not fully specified. No baseline vacuum or scalar spectrum is automatically carried into this extension.','Displayed three-triplet construction in the same paper','explicit','pp331-displayed',1);
INSERT INTO "theory_specifications" VALUES('ql421-dirac',1,'SU(4)C × SU(2)L × U(1)R quark–lepton theory with Dirac neutrinos',NULL,'partial_structural_specification','Unified gauge and matter assignments; χ, H and Φ scalars; four Yukawa matrices; matter symmetry; scalar and vector decomposition; assumed breaking vacuum','Provisional core before adding N. Scalar potential is recorded only at the reliably extracted level. No MFV, supersymmetry, Pati–Salam completion or fixed mass scale is imposed.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('ql421-inverse-seesaw',1,'SU(4)C × SU(2)L × U(1)R quark–lepton theory with inverse seesaw',NULL,'defined_for_stated_scope','Inherited unified core plus three singlet fermions, singlet Yukawa and Majorana terms, approximate matter symmetry and hierarchical neutrino regime','Provisional extension. The core gauge, scalar and four-Yukawa sectors are inherited, including their unresolved scalar-potential details. Explicit neutrino eigenstate formulas are only one-generation results.','P17 core before the singlet addition','explicit','ql421-dirac',1);
INSERT INTO "theory_specifications" VALUES('su5-adjoint-renormalizable',1,'Renormalizable nonsupersymmetric adjoint SU(5)',NULL,'partial_structural_specification','Unified matter and scalar multiplets; charged-fermion and neutrino Yukawas; adjoint mass operators; assumed adjoint breaking and derived fermion masses','Provisional identity. Full stated unified matter and Higgs inventory is recorded independently. The scalar potential, detailed component representation transcription and vacuum stability are incomplete. Threshold benchmarks do not define separate specifications.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('so10-45-126-sector',1,'Nonsupersymmetric SO(10) 45H plus 126H breaking sector',NULL,'defined_for_stated_scope','Unified scalar representations, general renormalizable breaking potential, SM-preserving vacuum directions and conditional spectrum analysis','Provisional scalar-sector identity. Matter Yukawas are discussed as motivation and a limitation, not included as a complete matter inventory. The sector alone cannot provide realistic renormalizable flavor. Component mass matrices and branching tables are not fully reconstructed.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('so10-45-126-complex10',1,'Nonsupersymmetric SO(10) with 45H, 126H and complex 10H',NULL,'partial_structural_specification','Inherited 45-126 scalar subpotential, additional complex 10H, matter 16F, three symmetric Yukawa structures and stated doublet-mixing operator','Provisional potentially realistic extension. The full extended scalar potential, its vacuum, correlated VEV projections and a successful flavor fit are not supplied. Inheritance of the scalar subpotential does not inherit its computed spectrum or establish the extended vacuum. No PQ symmetry or type-I dominance is imposed.','45H plus 126H breaking sector in the same paper','explicit','so10-45-126-sector',1);
INSERT INTO "theory_specifications" VALUES('trinification-n3-adjoint-l',1,'Three-bi-triplet trinification with one Majorana SU(3)L adjoint',NULL,'partial_structural_specification','Trinification gauge group, three chiral families, three scalar bi-triplets, one Majorana adjoint, displayed Yukawas, quartic-sector scope and assumed breaking','Provisional selected first Table 4 construction. Full dimensionful scalar potential, mixed-quartic transcription, numerical fixed flows and a minimized vacuum are unresolved. TAF is a conditional source-reported existence result, not a property of arbitrary couplings.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('trinification-singlet-neutrino-sector',1,'Trinification singlet-neutrino Majorana mechanism',NULL,'partial_structural_specification','Three additional gauge-singlet fermions, Majorana mass matrix and Yukawa coupling to the common trinification lepton and scalar multiplets','Provisional Eq. (2.18) sector. The total Higgs multiplicity and other extra fermions are not selected. This is not a complete TAF construction, and does not inherit the 8L addition.','Common trinification gauge and chiral-family sector; scalar multiplicity and complete extension inventory unselected','unresolved',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('mssm-rpc-conventional-soft',1,'MSSM with exact matter parity and general conventional soft terms',NULL,'partial_structural_specification','Chiral-superfield inventory; gauge framework; Yukawa and μ superpotential; matter parity; conventional soft terms; conditional neutral vacuum','Provisional identity. Full introductory component and matter-representation tables were not inspected. General flavor and complex soft parameters are retained. No mediation mechanism, universality, gaugino unification or full-theory CP conservation is imposed. Nonholomorphic soft cubics are conventionally omitted.','Standard Model gauge and ordinary-matter context, supersymmetrized with two Higgs chiral multiplets; not an additional independent SM Higgs sector','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('mssm-minimal-gauge-messengers',1,'Minimal gauge-messenger extension of the MSSM',NULL,'partial_structural_specification','Four messenger chiral multiplets, singlet S, messenger superpotential, assumed scalar and auxiliary VEVs, leading MSSM soft matching','Provisional extension with parameterized W_breaking. No complete hidden sector, singlet potential, μ-generation mechanism or messenger-parity assignment is reconstructed. Leading threshold relations restrict the inherited soft parameters in the effective regime.','MSSM visible sector with conventional soft operators','explicit','mssm-rpc-conventional-soft',1);
INSERT INTO "theory_specifications" VALUES('mssm-rpv-general',1,'MSSM field content with general displayed explicit R-parity violation',NULL,'partial_structural_specification','MSSM superfields, gauge framework, renormalizable superpotential, displayed conventional soft terms and Higgs-lepton basis freedom','Provisional. No CP, flavour universality or mediation assumption. Full representations and component scalar transcription remain incomplete. Generality refers to the displayed conventional operator class.','MSSM gauge and particle content; parity restriction relaxed and vacuum unselected','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('mssm-rpv-bilinear',1,'MSSM with explicit bilinear R-parity violation',NULL,'defined_for_stated_scope','Inherited MSSM field and gauge content with bilinear-only RPV in an appropriate basis','Provisional restriction of the parent operator space. Trilinear RPV superpotential and soft coefficients vanish in a defining basis, not in every rotated basis. No parent vacuum is inherited.','General displayed RPV MSSM, with the explicit restrictions below overriding its operator inclusion','explicit','mssm-rpv-general',1);
INSERT INTO "theory_specifications" VALUES('mssm-rpv-dim23',1,'MSSM with dimension-two and dimension-three RPV operators',NULL,'defined_for_stated_scope','Bilinear RPV superpotential and all displayed RPV soft operator classes','Provisional. Removes parent trilinear RPV superpotential terms while retaining independent triscalar soft terms. Dimensions refer to Lagrangian operators. Inherited representation limitations remain.','General displayed RPV MSSM with specified operator restrictions','explicit','mssm-rpv-general',1);
INSERT INTO "theory_specifications" VALUES('mssm-rpv-soft-bilinear',1,'MSSM with dimension-two soft R-parity violation only',NULL,'defined_for_stated_scope','Two RPV soft bilinear operator classes with inherited RPC interactions','Provisional. No independent RPV superpotential or triscalar soft terms in the defining basis. This is not the general theory written in mu_i=0 coordinates.','General displayed RPV MSSM with specified operator restrictions','explicit','mssm-rpv-general',1);
INSERT INTO "theory_specifications" VALUES('rpv-singlet-spontaneous-sector',1,'Displayed singlet extension for spontaneous R-parity breaking',NULL,'partial_structural_specification','Three N_i^c, three S_i, Phi, four cubic superpotential terms and an illustrative singlet-breaking vacuum','Provisional local reconstruction of Section 2.4. Complete soft potential and minimum conditions are unspecified. Not identified with a full external construction or the existing NMSSM. Three-family inventory is retained despite the one-family VEV illustration.','MSSM gauge and matter context and ordinary quark and charged-lepton Yukawas; the Higgs mass is generated through Phi','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('su5-rpv-trilinear-sector',1,'Renormalizable supersymmetric SU(5) RPV trilinear operator sector',NULL,'partial_structural_specification','Matter bar5 and 10 superfields, unified RPV trilinear and its stated coefficient relations','Provisional sector identity, not a complete GUT. Requires field-independent renormalizable coefficients. Higgs breaking, full Yukawa completion and the separate bilinear alternative are not reconstructed.','Supersymmetric SU(5) context; complete baseline inventory unselected','unresolved',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('split-susy',1,'Split Supersymmetry with supersymmetric scalar-threshold matching',NULL,'defined_for_stated_scope','Retained component spectrum; matter parity; renormalizable Higgs, Yukawa and electroweakino interactions; supersymmetric threshold matching; conditional mass boundaries','Provisional effective construction. The microscopic origin of the scalar–fermion hierarchy, complete parent soft sector and unified completion are unspecified. Numerical masses and relic requirements are application choices.','Standard Model gauge and fermion sectors with one tuned light scalar Higgs doublet; supersymmetric parent treated through threshold matching','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('gem-supersoft',1,'Gauge Extended Model with supersoft D-term breaking',NULL,'framework_or_template','Visible gauge adjoints, hidden D spurion, supersoft operators and adjoint mass deformations','Provisional parameterized framework. Minimal Dirac limit is a regime; optional superpotential interactions are not universally zero. Hidden dynamics, full Higgs sector and matter interactions are not reconstructed.','MSSM gauge and chiral-matter context; conventional MSSM soft coefficients and vacuum are not inherited','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('gem-supersoft-messengers',1,'Supersoft GEM with the displayed heavy-messenger sector',NULL,'partial_structural_specification','Messenger mass, adjoint–messenger coupling and qualitative supersoft matching','Provisional Eq. (3.1) extension. Complete messenger quantum numbers, hidden dynamics and matching coefficients remain unspecified. Supersoft EFT operators below the threshold are generated contributions, not automatically independent tree-level UV terms.','Supersoft GEM visible sector and D-source context','explicit','gem-supersoft',1);
INSERT INTO "theory_specifications" VALUES('gem-supersoft-su5-bachelors',1,'Supersoft GEM with SU(5)-adjoint bachelor completion',NULL,'partial_structural_specification','Inherited supersoft core and additional SM bachelor supermultiplets','Provisional SM-level completion into a proposed SU(5) adjoint. Full unified matter, breaking sector and GUT action are not supplied. Benchmark interaction omissions are explicit assumptions.','Supersoft GEM core, with the Section 3.2 restrictions below','explicit','gem-supersoft',1);
INSERT INTO "theory_specifications" VALUES('gem-supersoft-su3cubed-bachelors',1,'Supersoft GEM with SU(3)^3-inspired bachelor completion',NULL,'partial_structural_specification','Inherited supersoft core and additional doublet, charged-singlet and neutral-singlet bachelors','Provisional SM-level field completion. A full supersymmetric trinification theory, unified breaking and complete interactions are not reconstructed. Distinct from the existing nonsupersymmetric three-bi-triplet construction.','Supersoft GEM core, with the Section 3.2 restrictions below','explicit','gem-supersoft',1);
INSERT INTO "theory_specifications" VALUES('general-gauge-mediation',1,'General gauge mediation through hidden current correlators',NULL,'framework_or_template','Gauge-decoupling definition, conserved hidden currents, weak gauging and leading visible soft coefficients','Provisional class-level framework; no generic hidden Lagrangian or vacuum is reconstructed. Zero and nonzero hypercharge one-point functions belong to the same framework.','MSSM visible sector; its gauge-mediated soft contributions are determined here rather than inherited as arbitrary independent inputs','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('general-gauge-mediation-higgs-operators',1,'General gauge mediation with direct composite-operator Higgs couplings',NULL,'framework_or_template','Inherited current framework plus O_u H_u and O_d H_d couplings and their leading correlator treatment','Provisional operator framework, not an elementary hidden-field inventory or demonstrated phenomenological solution. The additional couplings override the parent''s gauge-only decoupling condition.','General gauge-mediation current framework with the Section 5 coupling extension','explicit','general-gauge-mediation',1);
INSERT INTO "theory_specifications" VALUES('u1-minimal-gauge-messenger-toy',1,'U(1) minimal gauge-mediation messenger toy sector',NULL,'defined_for_stated_scope','Oppositely charged chiral messengers, canonical gauge kinetics, spurion coupling and split messenger spectrum','Provisional Appendix A construction. The prescribed X background does not specify dynamical supersymmetry breaking. No full MSSM inventory or identification with P21''s messenger sector is implied.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('ksvz-neutral-triplet',1,'KSVZ axion with one hypercharge-neutral color-triplet pair',NULL,'defined_for_stated_scope','Added fermion and scalar, PQ action, displayed Yukawa and potential, broken vacuum and gluon matching','Provisional benchmark identity. Unlisted gauge-invariant operators are not all declared absent. No PQ-quality completion or optional discrete gauge symmetry is imposed.','Standard Model; ordinary fields and interactions inherited rather than exhaustively enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('ksvz-representation-framework',1,'Generalized KSVZ heavy-representation framework',NULL,'framework_or_template','Variable heavy fermion representations, singlet Yukawa alternatives and anomaly sums','Provisional class-level record. No particular spectrum, multiplicity, mixing matrix, complete potential or ultraviolet protection mechanism is selected. An axion realization requires nonzero total QCD anomaly.','Standard Model gauge and matter context','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('dfsz-i-quartic',1,'Generation-universal DFSZ-I with quartic singlet interaction',NULL,'defined_for_stated_scope','Scalar representations and potential, generation-universal Yukawa assignments, PQ charges, vacuum and axion normalization','Provisional nonsupersymmetric construction. Individual moduli coefficients and absolute chiral SM PQ charges remain unspecified. No PQ-quality protection or extra neutrino sector is reconstructed.','Standard Model gauge and fermion sectors; Higgs sector replaced by H_u, H_d and Phi','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('dfsz-ii-quartic',1,'Generation-universal DFSZ-II with quartic singlet interaction',NULL,'defined_for_stated_scope','Common DFSZ scalar, gauge and quark sectors; replacement charged-lepton Yukawa and derived anomaly coefficients','Provisional. Inherit only the common scalar potential, scalar PQ action, gauge and quark sectors and common vacuum definitions. Replace the DFSZ-I charged-lepton Yukawa, lepton charge difference, electromagnetic anomaly and lepton coupling by the rows below. No DFSZ-I lepton interaction is retained as an additional term.','Common quartic DFSZ structure, with charged-lepton and electromagnetic quantities explicitly replaced','explicit','dfsz-i-quartic',1);
INSERT INTO "theory_specifications" VALUES('smash-down',1,'SMASH with a down-type colored fermion',NULL,'defined_for_stated_scope','New Weyl and scalar multiplets; PQ/lepton charges; renormalizable Yukawas and scalar potential; gravitational EFT; broken vacuum; low-energy axion and seesaw; scoped cosmological regimes','Provisional identity. General flavor couplings and either portal sign are retained. Stability scans and cosmological selections do not define separate models. No discrete-symmetry UV completion, current observational validation or quantitative joint five-problem benchmark is established.','Standard Model gauge and matter sectors with one Higgs doublet; baseline kinetics and gauge interactions inherited rather than exhaustively enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lns-two-singlet-quarks',1,'Leurer–Nir–Seiberg two-singlet horizontal quark construction',NULL,'defined_for_stated_scope','Supersymmetric light quark sector, horizontal charges, effective Yukawas, explicit vectorlike-quark realization and matching','Provisional selected realization. Continuous charges organize the Yukawa sector; a fully consistent discrete completion, scalar potential and soft-breaking sector are unspecified. Leptons are outside the reconstructed inventory.','Standard Model gauge and quark context, supersymmetrized with two Higgs multiplets; no complete MSSM action or matter-parity restriction imported','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('lns-single-singlet-quarks',1,'Leurer–Nir–Seiberg single-singlet horizontal quark alternative',NULL,'partial_structural_specification','Single horizontal generator, one breaking singlet and modified effective selection rules','Provisional alternative. Inherit only the common light gauge representations, two Higgs fields, supersymmetric holomorphic framework and U(1)X Yukawa assignment. Replace S1,S2 and both horizontal generators by S and H. Do not inherit the eight-pair heavy inventory, its matching, or its scale bound.','Common light effective quark sector of the two-singlet construction, with the stated field and charge replacements','explicit','lns-two-singlet-quarks',1);
INSERT INTO "theory_specifications" VALUES('lns-reduced-quarks',1,'Leurer–Nir–Seiberg reduced one-U-pair, two-D-pair quark construction',NULL,'defined_for_stated_scope','Modified down charges, reduced heavy inventory, rank-restricted effective textures and assumed Higgs-VEV hierarchy','Provisional variant. Retain the common light inventory, scalar charges, Q and up-singlet charges and U(1)X Yukawa assignment. Replace down charges; delete U2,U3,D1,D2,D5 and their partners. Replace the baseline effective textures and comparable-Higgs-VEV assumption. No complete discrete or scalar-dynamical completion is inherited.','Two-singlet construction with explicit charge, heavy-field and effective-texture replacements','explicit','lns-two-singlet-quarks',1);
INSERT INTO "theory_specifications" VALUES('af-a4-susy-effective',1,'Four-dimensional supersymmetric A4 lepton model with effective neutrino operators',NULL,'partial_structural_specification','Lepton and Higgs superfields, flavons and driving fields; flavour and auxiliary actions; leading superpotentials; selected higher-dimensional operators and alignment','Provisional source-scoped identity. Charged-singlet A4 assignments and parts of the higher-order driving basis remain unresolved. Soft breaking, radiative stabilization and electroweak breaking are only partially specified. No complete quark sector or modular ultraviolet completion is imported.','Supersymmetric electroweak lepton and two-Higgs context; no complete MSSM action or conventional soft prescription is inherited','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('af-a4-susy-seesaw',1,'Four-dimensional supersymmetric A4 lepton model with a triplet seesaw sector',NULL,'partial_structural_specification','Common charged-lepton and leading driving sectors; added conjugate-neutrino triplet; replaced Z3 actions and neutrino superpotential','Provisional. Inherit the common gauge and superfield inventory, A4 and R assignments, charged-lepton operators, U(1)F hierarchy sector, and leading driving superpotential and alignment assumptions. Replace the neutrino operators and the Z3 actions of phiS, xi, xi_tilde, phiS0 and xi0. Do not inherit the effective realization''s higher-dimensional neutrino operators or a verified Dirac matrix. The charged-singlet assignment conflict persists.','Common construction of sections 3–4 with the explicit section 6 replacements','explicit','af-a4-susy-effective',1);
INSERT INTO "theory_specifications" VALUES('modular-a4-flavonfree-seesaw',1,'Flavon-free level-3 modular A4 supersymmetric seesaw, Example 3',NULL,'defined_for_stated_scope','Lepton and Higgs chiral multiplets, modulus, modular actions, constrained holomorphic couplings, assumed Kähler potential and scanned modulus background','Provisional equation (50) weight choice only. No complete quark, gauge-kinetic, soft-breaking or modulus-stabilization sector is reconstructed. The benchmark does not define the specification.','Supersymmetric electroweak lepton and two-Higgs context; no full MSSM action or AF flavon sector inherited','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('grv-quark-flavor-u3',1,'Minimal two-flavon gauged quark flavor with two Abelian factors',NULL,'partial_structural_specification','Quark flavor gauging, exotic chiral multiplets, two complex bifundamentals, universal mass-generating interactions and assumed flavor vacuum','Provisional SU(3)QL × U(3)UR × U(3)DR construction. Scalar potential and explicit normalized Abelian charge table remain incomplete. No lepton-flavor gauging, B−L completion, unification or supersymmetry is imported. Numerical examples do not define the parameters.','Standard Model gauge and matter context; ordinary quark Yukawas arise through the exotic sector rather than being independently inherited','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('grv-quark-flavor-su3',1,'Minimal two-flavon SU(3)^3 gauged quark flavor',NULL,'partial_structural_specification','Shared quark and two-flavon sectors with nonabelian-only flavor gauging','Provisional. Inherit the SM gauge context, ten listed matter/scalar fields, their SM and SU(3)^3 representations, six fermion mass-generating operators and universal coefficients. Remove both flavor U(1) gauge fields and their hypercharge kinetic mixing. Restrict the flavor-vector mass expression to traceless generators. Do not inherit the 26-Goldstone/10-radial count or a scalar potential, spectrum or benchmark vacuum.','Common construction of section 2 with the section 5.1 gauge-sector replacement','explicit','grv-quark-flavor-u3',1);
INSERT INTO "theory_specifications" VALUES('sm-singlet-neutrino-framework',1,'Standard Model with N right-handed singlet neutrinos',NULL,'framework_or_template','Inherited Standard Model; variable-N chiral neutrino inventory; sterile kinetics, neutrino Yukawas and bare Majorana masses','Provisional class-level framework of Eq. (1). N is unselected. No extra gauge factor, mass-generating singlet scalar, flavor symmetry or ultraviolet completion is specified. Phenomenology for general N is not reconstructed.','Standard Model gauge, matter and Higgs sectors; only participants in the added interactions are enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('numsm',1,'νMSM: three low-mass right-handed neutrinos',NULL,'defined_for_stated_scope','Three-singlet specialization of the inherited renormalizable neutrino framework; low-mass domain; scoped seesaw, dark-matter and baryogenesis applications','Provisional. Inherit the SM baseline and all three Eq. (1) operator classes, replacing the parent''s variable N by exactly three everywhere, including Yukawa and Majorana indices. Local N_I replaces the parent collection rather than adding three further fields. General complex Yukawas remain. Warm-dark-matter and perturbative baryogenesis selections do not define the full parameter space.','Eq. (1) singlet-neutrino framework with N=3 and the source-defined low-mass domain','explicit','sm-singlet-neutrino-framework',1);
INSERT INTO "theory_specifications" VALUES('ma-radiative-seesaw-z2',1,'Ma radiative seesaw with an exact Z2 and three singlet fermions',NULL,'defined_for_stated_scope','Additional singlet fermions and scalar doublet; electroweak assignments; exact parity; displayed Yukawas, Majorana masses and scalar potential; assumed vacuum and dark-matter regimes','Provisional identity. Quark and gauge kinetics remain inherited SM content. Exact flavor-index transcription of the h interaction is deferred. No A4 completion, numerical spectrum or global-minimum certification is imposed.','Standard Model with its ordinary Higgs doublet and matter; only displayed lepton and Higgs participants are enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('weinberg-t1i-first-row',1,'T1-i first-row electroweak mediator template',NULL,'framework_or_template','Four mediator labels and their integer-hypercharge electroweak assignments; irreducible one-loop scope','Provisional bounded first row of Table 2 only. Color, generation counts, field identifications at special alpha, exact Yukawa contractions, parity actions and scalar potential are unselected. Other T1 and T3 realizations are not included.','Standard Model external lepton and Higgs doublets; remaining baseline action not enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('weinberg-t41ii-first-row',1,'T4-1-ii first-row scalar-loop type-II extension template',NULL,'framework_or_template','Scalar mediator assignments and finite correction to the type-II scalar vertex','Provisional first representation row of Table 5 only. Necessary diagrammatic content does not specify the full potential, vacuum or interaction inventory. Generic tree-level type-II contribution is not removed.','Standard Model external lepton and Higgs doublets and type-II seesaw context','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('weinberg-t41i-doublet-fermions',1,'T4-1-i doublet-fermion correction to the type-II seesaw',NULL,'partial_structural_specification','Electroweak mediator assignments, displayed component Yukawas and masses, required type-II scalar counterterm','Provisional Eqs. (3)-(4) example with the singlet-Psi row of Table 4. Component vertices belong to the listed multiplets. Color, flavor multiplicities, full scalar potential and vacuum remain unspecified. No identification with every divergent completion is implied.','Standard Model; only lepton and Higgs participants of the displayed sector are enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('su4-hypercolor-partial-compositeness',1,'SU(4) fermionic hypercolor with SU(5)/SO(5) partial compositeness',NULL,'defined_for_stated_scope','Microscopic hyperfermions and flavor action; proposed condensates; conditional pNGB and single-partner IR theory; elementary mixing and quadratic mass assignments; conditional electroweak vacuum','Provisional shared UV/IR identity. The IR spectrum and condensation are assumed, not nonperturbatively established. No higher-scale mediator theory, full heavy-resonance inventory or complete derivative effective action is reconstructed.','Elementary Standard Model gauge and fermion sectors; the Higgs arises from the composite pNGB sector and fermion masses use the specified mechanisms','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('littlest-higgs-minimal',1,'Minimal SU(5)/SO(5) Littlest Higgs',NULL,'defined_for_stated_scope','Nonlinear sigma sector; doubled electroweak gauging; Goldstone and heavy-vector content; minimal top sector; light Yukawa assignments; leading radiative potential and conditional low-energy matching','Provisional effective construction. Exact normalization of the nonlinear top operator and the dimensionful prefactor of the fermion counterterm are deferred. No complete ultraviolet theory, individual broken-subgroup fermion charge table, anomaly-cancelling spectrum, fixed benchmark or historical-priority claim is included.','Standard Model color and ordinary fermion context; electroweak gauge and Higgs sectors replaced by the specified collective construction, and Yukawas supplied as described here','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('twin-higgs-linear-scalar-sector',1,'Linear twin-Higgs scalar mechanism',NULL,'defined_for_stated_scope','Complex scalar fundamental, illustrative doubled weak gauging, interchange, potential and global breaking','Provisional sector specification. Retains the radial mode. Twin parity is the recorded implementation; mirror parity is a source-stated alternative. No complete doubled-SM fermion sector or unique ultraviolet completion is included.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('twin-higgs-unextended',1,'Nonlinear twin Higgs without extended top matter',NULL,'defined_for_stated_scope','Doubled SM gauge and ordinary matter sectors, nonlinear O(8) Higgs, twin interchange, portals and soft misalignment','Provisional unextended branch combining descriptions 176 and 178. Ordinary SM sectors are inherited, not exhaustively enumerated. No cross-sector exotic quarks are present. Optional twin hypercharge mass and kinetic-mixing boundary choices do not select a microscopic completion. Detailed loop coefficients and cosmology are outside this record.','Two Standard Model gauge and ordinary matter sectors; Higgs sector replaced by the shared nonlinear construction','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('twin-higgs-extended-top',1,'Nonlinear twin Higgs with SU(6) × SU(4) extended top sector',NULL,'partial_structural_specification','Inherited nonlinear Higgs and doubled gauge structure; enlarged top matter, invariant Yukawa and soft exotic masses','Provisional extension. Inherit the nonlinear Higgs, doubled gauge sectors, direct interchange, small-Yukawa relaxation and soft mu term. Replace the ordinary top Yukawa by yHQ_LT_R and add the cross-sector exotics and their independent partners. Do not inherit the absence of jointly charged matter, preliminary mixing suppression or massless-photon viability condition. Hypercharges and the heavy twin-photon mass origin remain unspecified.','Common nonlinear twin construction with an explicit top-sector replacement','explicit','twin-higgs-unextended',1);
INSERT INTO "theory_specifications" VALUES('mirror-higgs-unextended',1,'Mirror-symmetric pseudo-Goldstone Higgs without extended top matter',NULL,'partial_structural_specification','Common Higgs protection and doubled gauge sectors; parity-plus-CP-conjugate sector interchange; unextended matter and portal phenomenology','Provisional alternative. Inherit the common Higgs mechanism, doubled SM gauge context, unextended matter inventory and gauge-allowed portals. Replace direct twin interchange and partner correspondence by the stated mirror transformation. Do not automatically inherit a twin-specific soft-breaking prescription or a microscopic mass-generation completion. The massless mirror-photon discussion is conditional.','Common unextended Higgs and doubled-SM structure, with the discrete action replaced','explicit','twin-higgs-unextended',1);
INSERT INTO "theory_specifications" VALUES('fraternal-twin-higgs',1,'Minimal Fraternal Twin Higgs',NULL,'defined_for_stated_scope','Linear Higgs sector; twin weak and color gauging; third-generation twin fermions; displayed scalar potential and Yukawa assignments; misaligned vacuum; leading portals and conditional confined regimes','Provisional. No first- or second-generation twin fermions and no low-energy twin hypercharge. The radial Higgs is retained microscopically. Neutrino mass generation and protection above the cutoff remain unspecified. Infrared fields describe the same degrees of freedom after matching or confinement.','Standard Model gauge and ordinary matter sectors; its Higgs doublet A participates in the enlarged scalar potential. Baseline inventory and ordinary Yukawas are inherited, not exhaustively enumerated.','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('large-extra-dimensions-framework',1,'Large compact extra dimensions with weak-scale fundamental gravity',NULL,'framework_or_template','Compact geometry, gravitational scaling, localized Standard Model and bulk graviton, four-dimensional KK description','Provisional framework. Number of dimensions is variable with n≥2; geometry, localization mechanism and ultraviolet gravity are unselected. No particular unified gauge group or supersymmetric completion is intrinsic.','Standard Model below the weak cutoff; its inventory and ordinary interactions are inherited rather than enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('six-dimensional-pati-salam-vortex',1,'Six-dimensional Pati–Salam vortex localization construction',NULL,'partial_structural_specification','Vortex scalar, Pati–Salam gauge and matter assignments, trapping and Higgs Yukawas, core condensates and assumed gauge localization','Provisional illustrative realization. Sphere and source-described zero-inner-radius torus are alternative compactifications. Complete scalar action, U(1)V charge inventory and higher-dimensional confinement dynamics are unspecified. No claim of a demonstrated ultraviolet completion.','Large compact extra dimension framework specialized to n=2 with an explicit localization sector','explicit','large-extra-dimensions-framework',1);
INSERT INTO "theory_specifications" VALUES('rs-two-brane-warped',1,'Two-brane warped five-dimensional hierarchy construction',NULL,'defined_for_stated_scope','Bulk Einstein gravity; orbifold boundaries and brane actions; tuned AdS background; gravitational zero modes; visible-brane mass rescaling; qualitative massive KK properties','Provisional. Radius stabilization, detailed massive-mode reduction and ultraviolet completion are not supplied. No supersymmetric extension, bulk Standard Model or composite Higgs is imported.','Standard Model localized on the visible brane; ordinary inventory and interactions inherited rather than independently enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('ued-orbifold-framework',1,'Universal Standard Model dimensions with the paired-orbifold prescription',NULL,'framework_or_template','Bulk Standard Model inventory and action; dimension-dependent spinors and orbifolds; five-dimensional component boundary conditions; KK reduction and assumed Higgs vacuum','Provisional framework with delta unselected. Its different-dimensional members are alternatives, not simultaneous sectors or equivalent fixed-dimensional models. Localized operators and exterior thick-brane fields are excluded from this recorded truncation. Even-dimensional anomaly completion and quantum boundary terms remain unresolved.','Standard Model gauge, matter and single-Higgs assignments promoted to bulk fields; KK modes are repeated modes of these fields','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('holographic-su3-brane-scalar-mediator',1,'Holographic SU(3)L brane-scalar Higgs with a bulk quartic mediator',NULL,'partial_structural_specification','AdS electroweak gauge sector; third-generation quarks; infrared triplet Higgs; bulk six mediator; boundary breaking and quartic mechanism','Provisional section 3 and 3.2 specification. Retains the added mediator as independent field content. Full Standard Model matter, ultraviolet breaking dynamics and a stable complete scalar potential are not reconstructed. The optional ultraviolet S realization is not selected.','Color sector acknowledged through the stated quark triplets; only the explicitly constructed third-generation sector is enumerated.','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('holographic-boundary-pgb-framework',1,'Holographic boundary-condition pseudo-Goldstone framework',NULL,'framework_or_template','AdS gauge boundary breaking; A5 zero modes; holographic symmetry description; scoped bulk-fermion loop example','Provisional class-level record. G, H0, H1 and fermion representation r are unselected. Their different choices are alternative constructions, not simultaneous sectors. No complete Standard Model or supersymmetric realization is implied.',NULL,'not_applicable',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('hidden-valley-framework',1,'Confining Hidden Valley framework',NULL,'framework_or_template','Hidden confinement, SM-neutral light constituents and heavy mediator portals','Provisional family-level record. Gauge group, matter inventory, mediator and operator coefficients are unselected; no single microscopic Lagrangian is implied.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('hidden-valley-chi-two-flavor',1,'Two-flavor Hidden Valley with a U(1)χ portal',NULL,'partial_structural_specification','Added gauge sector, hidden quarks, neutrinos, breaking scalar, χ charges, mass-generating assignments, portals and confined regimes','Provisional. Hidden fundamental versus antifundamental assignments remain unresolved from supplied text. Full scalar potential, flavor matrices and exact Z2 actions are not reconstructed. Numerical examples do not define the parameters.','Standard Model gauge and matter sectors with its Higgs doublet; ordinary inventory inherited and only relevant charge collections enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('hidden-valley-colored-x-framework',1,'Hidden SU(nv) with heavy colored-X mediators',NULL,'framework_or_template','Heavy jointly charged matter, induced gluonic operators and confined glueballs','Provisional. X spin, electroweak assignments, multiplicity and general color/hidden representations are unselected. The displayed dimension-eight operator is not the complete decay operator set.','Standard Model','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('hidden-valley-x-adjoint-prompt',1,'Colored-X Hidden Valley with a promptly decaying hidden adjoint',NULL,'framework_or_template','Inherited gluonic portal with hidden-adjoint mediator and assumed prompt decay','Provisional. Replace the parent''s unselected hidden representation by adjoint and select prompt decay. The local X collection replaces the parent''s X collection. Exact color representation, spin, electroweak charges and decay interaction remain unspecified.','Common colored-X portal framework with the first possibility selected','explicit','hidden-valley-colored-x-framework',1);
INSERT INTO "theory_specifications" VALUES('hidden-valley-x-adjoint-stable',1,'Colored-X Hidden Valley with a stable hidden adjoint',NULL,'framework_or_template','Inherited gluonic portal, stable hidden-adjoint mediator and screened composite','Provisional. Color 3 and color 8 are alternative members, not two simultaneous fields. Local X replaces the parent collection. No spin, electroweak completion or protecting symmetry is supplied.','Common colored-X portal framework with the second possibility selected','explicit','hidden-valley-colored-x-framework',1);
INSERT INTO "theory_specifications" VALUES('hidden-valley-x-fundamental-stable',1,'Colored-X Hidden Valley with a stable hidden fundamental',NULL,'framework_or_template','Inherited gluonic portal, stable fundamental constituent and confining flux-tube system','Provisional. Local X replaces the parent collection. Spin and exact visible representations remain unspecified. Stable constituents can annihilate after their bound system loses energy.','Common colored-X portal framework with the third possibility selected','explicit','hidden-valley-colored-x-framework',1);
INSERT INTO "theory_specifications" VALUES('secluded-dirac-u1-higgsed',1,'Dirac WIMP with a Higgsed U(1)'' kinetic portal',NULL,'partial_structural_specification','Dark Dirac fermion, Abelian vector, charged breaking scalar, kinetic mixing and conditional cosmological regimes','Provisional Eqs. (2)-(3) construction. Scalar potential is unspecified. Unlisted scalar portals are not declared forbidden. No ultraviolet stability completion is supplied. Broken and unbroken backgrounds are alternatives within the same inventory.','Standard Model; ordinary inventory inherited, with hypercharge field identified as a portal participant','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('secluded-fermion-scalar-portal',1,'Singlet fermion WIMP with a Higgs-mixed scalar mediator',NULL,'partial_structural_specification','Singlet fermion and scalar; scalar Yukawa; linear and quadratic Higgs portals; chosen field origin and mass regimes','Provisional Eq. (16) sector. Retain quadratic portal freedom; its small-coupling limit is an application. Fermion Dirac/Majorana designation, complete scalar potential and ultraviolet stability protection remain unspecified. Conflicting scalar kinetic signs are not canonicalized.','Standard Model with its Higgs doublet; remaining ordinary fields and interactions inherited','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('secluded-neutrino-portal-z2',1,'Z2 neutrino portal with an additional fermion and real scalar',NULL,'partial_structural_specification','Majorana-type neutrino and dark-fermion masses; real scalar; neutrino and dark Yukawas; scalar portal; shared parity and two dark-matter hierarchies','Provisional baseline Eq. (19). NR multiplicity, exact spinor contractions and full scalar potential remain unspecified. S and N'' are jointly odd; each need not occur an even number of times separately. The complexified global-charge alternative is excluded from this record.','Standard Model; lepton and Higgs Yukawa participants identified without enumerating the complete baseline','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('simp-sp-pions',1,'Flavor-preserving Sp(Nc) dark-pion SIMP class',NULL,'framework_or_template','Fundamental Weyl matter; assumed chiral condensate; flavor-preserving mass; leading pion EFT and WZW interaction','Provisional rank- and flavor-indexed class. Fixed Nc,Nf choices are members, not identical fixed-inventory theories. SM mediation is unspecified; no mediator or SM representation assignment is imported.','Standard Model thermal bath; its ordinary action is not independently enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('simp-su-pions',1,'Flavor-preserving SU(Nc) dark-pion SIMP class',NULL,'framework_or_template','Fundamental Dirac matter; assumed chiral breaking; flavor-preserving masses; leading pion EFT and WZW interaction','Provisional class conditional on the stated chiral pattern. No complete portal, heavy-hadron spectrum or flavor-breaking extension is reconstructed. Nc,Nf label alternative members.','Standard Model thermal bath; its ordinary action is not independently enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('simp-o-pions',1,'Flavor-preserving O(Nc) dark-pion SIMP class',NULL,'framework_or_template','Vector fermion inventory; assumed SU(Nf)/SO(Nf) breaking; flavor-preserving pion EFT and WZW interaction','Provisional source-scoped class. Preserve the printed O(Nc) gauge notation. Fermion Weyl/Dirac counting and disconnected-group data are unresolved. No portal completion is supplied.','Standard Model thermal bath; its ordinary action is not independently enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vector-higgs-portal-z2-eft',1,'Z2-symmetric massive-vector Higgs portal EFT',NULL,'defined_for_stated_scope','Massive hidden vector, parity, displayed portal and self-interaction, electroweak mass relation and conditional phenomenology','Provisional origin-independent EFT. No unique microscopic mass sector or ultraviolet completion is selected. The quartic-zero scan does not define the general operator inventory.','Standard Model with its Higgs field; remaining ordinary inventory and interactions inherited','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vector-portal-stueckelberg-higgs',1,'Stückelberg vector portal with a directly Higgs-dependent mass',NULL,'defined_for_stated_scope','Hidden Abelian gauge field, shifting scalar, direct Higgs-dependent mass and natural vector parity','Provisional example (i). Gauge-invariant field-dependent mass contains higher-dimensional derivative interactions. No Green–Schwarz or string completion is inherited.','Standard Model; ordinary inventory inherited and Higgs participant identified','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vector-portal-stueckelberg-scalar',1,'Scalar-mediated Stückelberg vector Higgs portal',NULL,'partial_structural_specification','Stückelberg sector, mass-controlling hidden scalar, scalar portal and heavy-scalar matching','Provisional example (ii). V(S) and its minimum are unspecified. The induced vector quartic is retained in matching; it is not universally set to zero by the later phenomenological scan.','Standard Model; ordinary inventory inherited and Higgs participant identified','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('vector-portal-abelian-higgs',1,'Minimal hidden Abelian Higgs vector portal with charge conjugation',NULL,'partial_structural_specification','Hidden U(1), charged complex scalar, covariant kinetics, scalar Higgs portal, charge conjugation and broken-phase reduction','Provisional example (iii). Numerical hidden charge, explicit scalar potential and quantitative vacuum solution are unspecified. No extra charged matter or full ultraviolet completion is imported.','Standard Model; ordinary inventory inherited and Higgs participant identified','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('silh-hww-operator-sector',1,'Displayed SILH dimension-six HWW operator sector',NULL,'partial_structural_specification','Three displayed Higgs and weak-field operators; source coefficient conventions; EFT truncation','Provisional Section 5 sector only. Other SILH operators are unspecified, not zero. No complete SILH action, ultraviolet strong sector, coset, fermion embedding or full exported implementation is reconstructed.','Standard Model particle content and ordinary interactions; baseline inventory inherited rather than enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('smeft-d6-b-conserving',1,'SM effective theory through dimension six with baryon conservation',NULL,'framework_or_template','SM matter inventory; gauge symmetry; dimension-five neutrino operator; 59 baryon-conserving dimension-six operator types','Provisional EFT operator-space identity. General flavor and CP phases are retained. Collective inventory rows name basis elements without supplying unextracted individual expressions. No UV completion, numerical matching, generation-expanded coefficient count or vacuum is specified.','Renormalizable Standard Model action of Eq. (2.1), including the implicitly present non-Abelian topological terms; ordinary kinetics and Yukawas inherited rather than independently transcribed','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('smeft-d6-b-violating',1,'SM effective theory through dimension six allowing baryon violation',NULL,'framework_or_template','Inherited SM and dimension-five action; all 59 common dimension-six types; four additional baryon-violating four-fermion types','Provisional extension. Inherit the field inventory, gauge assignments, conventions, general flavor scope and common interactions. Override the parent''s baryon-conservation selection and permit the four additional coefficient tensors. Do not inherit baryon conservation as a symmetry of the full extended action. No flavor-diagonal vanishing constraint is imposed on Qqqq.','Common effective construction with baryon-conservation restriction relaxed','explicit','smeft-d6-b-conserving',1);
INSERT INTO "theory_specifications" VALUES('general-heavy-field-tree-matching',1,'General heavy-field framework for classical matching to dimension-six SMEFT',NULL,'framework_or_template','Theory domain, relevant representation criterion, heavy-field operator truncation and matching conventions','Provisional class-level record. Heavy representations and replica counts are alternatives or selectable collections, not a fixed simultaneous inventory. Only the prepared framework and representative sectors are curated.','Standard Model fields and renormalizable action within L0; L0 may additionally contain pure-SM higher-dimensional operators','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('real-singlet-linear-portal-gluon-sector',1,'Real singlet scalar with displayed Higgs portals and dimension-five gluonic coupling',NULL,'partial_structural_specification','Real singlet replicas, selected renormalizable scalar terms and S G G interaction','Provisional selected sector. Unlisted self-interactions, dimension-five terms and other heavy sectors are unspecified, not forbidden. No stabilizing Z2, complete scalar potential or vacuum minimum is imposed.','Standard Model; Higgs and gluon participants identified without enumerating the complete baseline','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('scalar-zeta-ql-qq-sector',1,'Scalar ζ weak-triplet leptoquark with leptoquark and diquark couplings',NULL,'partial_structural_specification','One scalar representation and two renormalizable fermion assignments','Provisional Section 5 single-multiplet restriction. Both coupling tensors are retained. No proton-protection symmetry, flavor texture, scalar-potential completion or unified embedding is imposed.','Standard Model; only the displayed left-handed fermion participants are enumerated','explicit',NULL,NULL);
INSERT INTO "theory_specifications" VALUES('heavy-weak-triplet-proca-current-sector',1,'Heavy weak-triplet Proca vector with lepton, quark and Higgs currents',NULL,'partial_structural_specification','One heavy vector, covariant Proca quadratic action and displayed current interactions','Provisional Section 5 single-W sector. No extended gauge group or mass-generating scalar sector is specified. L1 couplings are excluded from this example. Unlisted interactions are not universally forbidden.','Standard Model; W denotes an additional heavy multiplet, not the SM weak gauge connection','explicit',NULL,NULL);
INSERT INTO "theory_symmetries" VALUES(1,'real-singlet-z2',1,1,'Z2 singlet sign symmetry','internal','unspecified_in_scope','imposed','Preserved in the chosen vacuum with <S> = 0',NULL);
INSERT INTO "theory_symmetries" VALUES(2,'thdm-type-i-real-z2',1,4,'Z2 enforcing Type-I natural flavour conservation','internal','unspecified_in_scope','imposed','Dimension-four interactions respect Z2; nonzero real m12² softly breaks it. The exact scalar limit has m12² = 0. Vacuum preservation is not imposed.',NULL);
INSERT INTO "theory_symmetries" VALUES(3,'thdm-type-ii-real-z2',1,5,'Z2 enforcing Type-II natural flavour conservation','internal','unspecified_in_scope','imposed','Dimension-four interactions respect Z2; nonzero real m12² softly breaks it. The exact scalar limit has m12² = 0. Vacuum preservation is not imposed.',NULL);
INSERT INTO "theory_symmetries" VALUES(4,'lr-triplet-parity',1,6,'Generalized parity P','spacetime parity supplemented by SU(2)L/R exchange','unspecified_in_scope','imposed','Imposed in the high-energy symmetric phase.',NULL);
INSERT INTO "theory_symmetries" VALUES(5,'lr-triplet-charge-conjugation',1,7,'Generalized charge conjugation C','internal charge conjugation supplemented by SU(2)L/R exchange','unspecified_in_scope','imposed','Imposed in the high-energy symmetric phase; a gauged embedding is motivated but not specified here.',NULL);
INSERT INTO "theory_symmetries" VALUES(6,'nmssm-general-rpc-cpc',1,8,'R-parity',NULL,NULL,'imposed','Conserved in the Section 2.1 scope; explicit component actions are not reconstructed from the name.',NULL);
INSERT INTO "theory_symmetries" VALUES(7,'nmssm-general-rpc-cpc',1,8,'CP',NULL,NULL,'imposed','Conserved in the scoped construction and its assumed real neutral vacuum.',NULL);
INSERT INTO "theory_symmetries" VALUES(8,'nmssm-z3-rpc-cpc',1,9,'R-parity',NULL,NULL,'imposed','Conserved under the same Section 2.1 assumption.',NULL);
INSERT INTO "theory_symmetries" VALUES(9,'nmssm-z3-rpc-cpc',1,9,'CP',NULL,NULL,'imposed','Conserved in the scoped construction and its assumed real neutral vacuum.',NULL);
INSERT INTO "theory_symmetries" VALUES(10,'nmssm-z3-rpc-cpc',1,9,'Z3 common chiral-component phase','internal','unspecified_in_scope','accidental','Exact symmetry of the specified Lagrangian, including surviving soft terms; this does not assert preservation by nonzero vacuum expectation values.',NULL);
INSERT INTO "theory_symmetries" VALUES(11,'mchm-spinorial',1,10,'Strong-sector SU(3)c×SO(5)×U(1)B−L','internal','global','assumed','Spontaneously broken to SU(3)c×SO(4)×U(1)B−L. Couplings to elementary fields explicitly break SO(5).',NULL);
INSERT INTO "theory_symmetries" VALUES(12,'georgi-machacek-general',1,15,'Scalar-sector SU(2)L × SU(2)R','internal','global scalar-sector organization; electroweak subgroup gauged separately','imposed_on_scalar_potential','Aligned identity-proportional vevs preserve diagonal custodial SU(2). Hypercharge interactions explicitly violate custodial symmetry, so this is not an exact symmetry of the full gauged theory.',NULL);
INSERT INTO "theory_symmetries" VALUES(13,'threedm-d6',1,17,'Unitary Higgs-family D6 ≃ S3, order 6','internal','global','imposed_on_scalar_potential','Exact unitary symmetry for generic constrained coefficients. Vacuum preservation is unspecified. The full group remains D6 on the generic explicitly CP-violating branch.',NULL);
INSERT INTO "theory_symmetries" VALUES(14,'threedm-d6',1,17,'Conditional commuting generalized CP, Z2*','generalized CP','not a new gauge symmetry','conditional_coefficient_restriction','Present on the CP-conserving coefficient locus, giving generic D6 × Z2*. Absent on the generic branch violating equation (30). No spontaneous-CP conclusion is established.',NULL);
INSERT INTO "theory_symmetries" VALUES(15,'threedm-d8',1,18,'Unitary Higgs-family D8 = Z4 ⋊ Z2, order 8','internal','global','imposed_on_scalar_potential','Generic exact symmetry within the unitary domain. Vacuum preservation is unspecified.',NULL);
INSERT INTO "theory_symmetries" VALUES(16,'threedm-d8',1,18,'Automatic commuting generalized CP, Z2*','generalized CP','not a new gauge symmetry','automatic_consequence_of_scalar_constraints','The D8 potential automatically conserves generalized CP explicitly. Generic full symmetry is D8 × Z2*. Vacuum CP preservation remains unspecified.',NULL);
INSERT INTO "theory_symmetries" VALUES(17,'sm-octet-doublet-mfv',1,19,'SU(3)_U×SU(3)_D×SU(3)_Q flavor symmetry','internal','global','assumed','Broken by fixed G^U and G^D matrices, transforming as (3_U,3bar_Q) and (3_D,3bar_Q). The source imposes proportional Yukawa matrices; this is not an exact unbroken flavor symmetry.',NULL);
INSERT INTO "theory_symmetries" VALUES(18,'sm-octet-doublet-mfv-triplets',1,21,'Approximate triplet sign symmetry','internal','unspecified_in_scope','assumed','Explicitly broken by small dimensionful μ1, μ2 and ξ; not imposed as an exact stabilizing symmetry.',NULL);
INSERT INTO "theory_symmetries" VALUES(19,'mdm-majorana-quintuplet',1,39,'Accidental dark-matter protection in the source''s operator classification','internal',NULL,'accidental','Source states absence of renormalizable and dangerous dimension-5 decays for the quintuplet. Higher-dimensional decay effects are conditional on cutoff suppression. No explicit group label or field action is reconstructed.',NULL);
INSERT INTO "theory_symmetries" VALUES(20,'mdm-real-septuplet-displayed',1,40,'Source-claimed accidental protection of the scalar septuplet','internal',NULL,'accidental_source_claim','Qualified claim under the displayed operator assumptions and zero X VEV. Completeness of the scalar and higher-dimensional operator basis remains unresolved; this record does not certify exact stability.',NULL);
INSERT INTO "theory_symmetries" VALUES(21,'abelian-stueckelberg-sector',1,46,'Abelian Stückelberg gauge invariance','internal','gauged',NULL,'The displayed mass is gauge invariant through the scalar shift, without an assumed Higgs VEV.',NULL);
INSERT INTO "theory_symmetries" VALUES(22,'pp331-displayed',1,53,'Lepton number in the authors'' convention','internal','global quantum number','not imposed as a conserved symmetry','The authors describe explicit violation through the eta2+ coupling and V,U charged currents and explicitly decline to assign lepton number to gauge bosons. No numerical scalar or exotic-quark charge table is inferred.',NULL);
INSERT INTO "theory_symmetries" VALUES(23,'ql421-dirac',1,55,'U(1)F fermion matter symmetry','internal','global','accidental','Symmetry of the stated renormalizable core couplings; scalars are neutral. No quantum anomaly-freedom claim is made.',NULL);
INSERT INTO "theory_symmetries" VALUES(24,'ql421-inverse-seesaw',1,57,'Approximate U(1)F fermion matter symmetry','internal','global','inherited_accidental_symmetry_with_explicit_breaking','Inherited core charges and FN=1 make µNN the sole stated renormalizable breaking term. The symmetry is restored at µ=0 at the level of the displayed couplings; anomaly properties are unspecified.',NULL);
INSERT INTO "theory_symmetries" VALUES(25,'so10-45-126-sector',1,61,'Conditional O(45) × O(252) symmetry of the scalar potential','internal','global symmetry of the restricted potential','accidental_at_parameter_locus','Only when a2=λ2=λ4=λ′4=η2=τ=β4=β′4=γ2=0. Nonzero VEVs reduce this potential symmetry to O(44) × O(251). The source counts 295 Goldstones, with 33 eaten under generic SO(10) to SM breaking and 262 pseudo-Goldstone modes upon restoring explicit potential breaking. This is not an imposed symmetry of the general gauged theory.',NULL);
INSERT INTO "theory_symmetries" VALUES(26,'trinification-n3-adjoint-l',1,65,'Accidental quark-phase U(1) of the common Yukawa sector','internal','global','accidental','Source statement applies to Eq. (2.10). No quantum anomaly-freedom or nonperturbative proton-stability theorem is inferred.',NULL);
INSERT INTO "theory_symmetries" VALUES(27,'mssm-rpc-conventional-soft',1,67,'Z2 matter parity P_M=(-1)^{3(B-L)}','internal','unspecified_in_scope','imposed','Exactly conserved in the defined MSSM. Equivalent conservation law to component R-parity P_R=P_M(-1)^{2s}; no continuous U(1)R or particular gauged B-L completion is imposed.',NULL);
INSERT INTO "theory_symmetries" VALUES(28,'mssm-rpv-general',1,74,'R_p=(-1)^(2S+3B+L), equivalently (-1)^(2S+3(B-L))',NULL,NULL,'not imposed as a conserved symmetry','Explicitly broken by the RPV operators. Ordinary particles and Higgs bosons have parity +1 and their superpartners -1; this component grading is not a uniform charge on a chiral superfield.',NULL);
INSERT INTO "theory_symmetries" VALUES(29,'mssm-rpc-conventional-soft',1,79,'Lepton number in the minimal spontaneous-breaking application',NULL,'global',NULL,'Spontaneously broken by the sneutrino VEV, producing a Majoron in the source treatment. Gauged lepton number and explicit breaking are separate remedies.',NULL);
INSERT INTO "theory_symmetries" VALUES(30,'rpv-singlet-spontaneous-sector',1,80,'R-parity',NULL,NULL,NULL,'Preserved by the displayed superpotential; spontaneously broken by the assumed singlet lepton scalar VEVs. Full soft-sector invariance is a requirement of this mechanism, not an independently enumerated potential.',NULL);
INSERT INTO "theory_symmetries" VALUES(31,'rpv-singlet-spontaneous-sector',1,80,'Total lepton number',NULL,'global',NULL,'Preserved by Eq. (2.49), spontaneously broken in the displayed singlet vacuum; the Majoron remains a physical distinction from explicit bilinear RPV.',NULL);
INSERT INTO "theory_symmetries" VALUES(32,'split-susy',1,82,'Matter parity; associated component R-parity conservation',NULL,NULL,'imposed','Eq. (20) assumes conserved matter parity; R-parity protects an appropriate lightest neutral state. The source assertion does not tabulate individual parity actions, and no component charge table is imported from P21.',NULL);
INSERT INTO "theory_symmetries" VALUES(33,'split-susy',1,82,'Conditional U(1) combining parent R and PQ transformations','internal action on EFT components','global','restored_in_joint_massless_limit','For generic beta the displayed symmetry is restored when Mi=mu=0 together; it is explicitly broken by the mass coefficients and spontaneously broken by the Higgs VEV. Appropriate quark and lepton charges are not enumerated. The separate massless limits behave differently at tan(beta) tending to infinity.',NULL);
INSERT INTO "theory_symmetries" VALUES(34,'gem-supersoft',1,87,'R symmetry preserved by the D-breaking source',NULL,NULL,'conditional_source_property','D breaking itself preserves R symmetry and does not supply Majorana gaugino masses. No full charge assignment or exact R symmetry of every optional interaction is established.',NULL);
INSERT INTO "theory_symmetries" VALUES(35,'gem-supersoft-su5-bachelors',1,91,'Conditional bachelor sign parity','internal',NULL,'consequence_of_restricted_interactions','Present when ESP/bachelor couplings preserve N=2 and Higgs fields are outside the N=2 sector. Not an unconditional symmetry of every completion or higher-dimensional operator.',NULL);
INSERT INTO "theory_symmetries" VALUES(36,'gem-supersoft-su3cubed-bachelors',1,92,'Conditional bachelor sign parity','internal',NULL,'consequence_of_restricted_interactions','Present under N=2-preserving ESP/bachelor couplings and an N=1 Higgs assignment. Additional independent parities may exist; their full group is unspecified.',NULL);
INSERT INTO "theory_symmetries" VALUES(37,'ksvz-neutral-triplet',1,97,'U(1)_PQ','internal','global','assumed through the displayed operator restrictions','Spontaneously broken by the Phi VEV; not protected by SM gauge invariance alone.','QCD anomalous; N=1/2 in the displayed X_Phi=1 normalization.');
INSERT INTO "theory_symmetries" VALUES(38,'ksvz-representation-framework',1,99,'U(1)_PQ','internal','global','assumed',NULL,'N and E are spectrum-dependent sums over left-handed irreducible fields. QCD-axion applications require nonzero N.');
INSERT INTO "theory_symmetries" VALUES(39,'dfsz-i-quartic',1,100,'U(1)_PQ','internal','global','assumed through PQ-invariant operator selection','Survives the explicit reduction of three scalar rephasings to U(1)_Y × U(1)_PQ; subsequently spontaneously broken by the scalar VEVs.','N=3 and E=8 for DFSZ-I with X_Phi=1. The inherited scalar symmetry in DFSZ-II has a different electromagnetic anomaly.');
INSERT INTO "theory_symmetries" VALUES(40,'smash-down',1,102,'Shared U(1) PQ and lepton symmetry','internal','global','assumed through invariant operator selection','Spontaneously broken by σ. An accidental discrete-symmetry origin is optional and unconstructed.','Color anomalous through the one extra colored pair; the axion/majoron has domain-wall number one in the stated construction.');
INSERT INTO "theory_symmetries" VALUES(41,'lns-two-singlet-quarks',1,108,'U(1)H1 × U(1)H2 continuous horizontal presentation','internal','Continuous charge presentation; gauging not established','imposed_on_Yukawa_operators','Singlet VEVs provide horizontal breaking. Full scalar theory is intended to retain only a discrete subgroup.','No continuous anomaly-free gauge completion is asserted; discrete completion remains incomplete.');
INSERT INTO "theory_symmetries" VALUES(42,'lns-two-singlet-quarks',1,108,'U(1)X of the Yukawa sector','internal','global Yukawa-sector action','imposed_on_Yukawa_operators','Not required to be an exact symmetry of the full scalar Lagrangian. No additional continuous gauge boson is implied.',NULL);
INSERT INTO "theory_symmetries" VALUES(43,'lns-two-singlet-quarks',1,109,'U(1)H1 × U(1)H2 heavy-sector charge presentation','internal','Continuous charge presentation; gauging not established','imposed_on_displayed_heavy_couplings','Same scalar and light-field action as regime 108; heavy conjugate partners carry opposite charges. A full discrete realization is unresolved.',NULL);
INSERT INTO "theory_symmetries" VALUES(44,'lns-single-singlet-quarks',1,110,'U(1)H with H=2H1+3H2','internal','Continuous charge presentation; gauging not established','replacement_horizontal_action','S supplies breaking; this replaces both independent horizontal generators. Higgs charges are zero and the common U(1)X Yukawa assignment is retained.',NULL);
INSERT INTO "theory_symmetries" VALUES(45,'lns-reduced-quarks',1,111,'U(1)H1 × U(1)H2 in the reduced realization','internal','Continuous charge presentation; gauging not established','imposed_on_displayed_couplings','Q, up-singlet and scalar actions are retained; down charges are replaced and heavy multiplets removed. Full discrete completion remains unresolved.',NULL);
INSERT INTO "theory_symmetries" VALUES(46,'af-a4-susy-effective',1,113,'A4 flavour symmetry','internal','unspecified_in_scope','imposed','Flavon VEVs break the flavour symmetry. The separate leading charged-lepton and neutrino sectors preserve subgroups generated by T and S, respectively; neither is asserted to remain a symmetry of the full combined vacuum.',NULL);
INSERT INTO "theory_symmetries" VALUES(47,'af-a4-susy-effective',1,113,'Auxiliary Z3','internal','unspecified_in_scope','imposed','Separates leading charged-lepton and neutrino flavon operators. The selected nonzero neutrino-sector flavon VEVs carry nontrivial Z3 phases.',NULL);
INSERT INTO "theory_symmetries" VALUES(48,'af-a4-susy-effective',1,113,'Continuous U(1)R','R symmetry acting on superspace and superfields','unspecified_in_scope','imposed','Organizes the leading superpotential with driving fields of charge two. The source identifies an ordinary R-parity subgroup; a complete soft-sector R-breaking prescription is unspecified.',NULL);
INSERT INTO "theory_symmetries" VALUES(49,'af-a4-susy-effective',1,113,'U(1)F charged-lepton hierarchy symmetry','internal','unspecified_in_scope','imposed','Broken by the theta VEV. No gauged anomaly-free completion or numerical q is specified.',NULL);
INSERT INTO "theory_symmetries" VALUES(50,'af-a4-susy-seesaw',1,114,'Auxiliary Z3 with seesaw assignments','internal','unspecified_in_scope','imposed','Replaces the five neutrino-sector flavon/driving phases by omega² and assigns omega² to nu^c. Other phases remain inherited.',NULL);
INSERT INTO "theory_symmetries" VALUES(51,'af-a4-susy-seesaw',1,114,'Inherited A4 flavour symmetry extended to nu^c','internal','unspecified_in_scope','imposed','Same leading flavon alignment; nu^c is an added triplet. No new modular dynamics is introduced.',NULL);
INSERT INTO "theory_symmetries" VALUES(52,'af-a4-susy-seesaw',1,114,'Inherited continuous U(1)R extended to nu^c','R symmetry acting on superspace and superfields','unspecified_in_scope','imposed','Inherited R assignments are unchanged; nu^c has superfield R charge one.',NULL);
INSERT INTO "theory_symmetries" VALUES(53,'modular-a4-flavonfree-seesaw',1,115,'Modular invariance with level-3 finite representation group Γ3 ≅ A4','internal modular action on field space','unspecified_in_scope','imposed','The full transformation includes the fractional-linear action on τ and matter automorphy factors. A4 representation matrices alone do not specify this symmetry. Flavour breaking is supplied by the modulus background.',NULL);
INSERT INTO "theory_symmetries" VALUES(54,'modular-a4-flavonfree-seesaw',1,115,'Lepton number with Majorana spurion','internal','global quantum number','not imposed as an exact symmetry at fixed nonzero Λ','The Λ(N^c N^c Y)1 term breaks lepton number. τ and Yi carry no lepton number; no extra lepton-number-breaking flavon is introduced.',NULL);
INSERT INTO "theory_symmetries" VALUES(55,'ma-radiative-seesaw-z2',1,123,'Exact Z2','internal','unspecified_in_scope','imposed','Exact in the displayed theory and preserved by the assumed zero η VEV. No soft Φ†η breaking is permitted. The lightest odd particle is stable.',NULL);
INSERT INTO "theory_symmetries" VALUES(56,'su4-hypercolor-partial-compositeness',1,129,'GF = SU(5) × SU(3) × SU(3)'' × U(1)X × U(1)''','internal','global flavor symmetry before coupling to elementary SM fields',NULL,'Proposed condensates break GF to SO(5) × SU(3)c × U(1)X. SM gauging selects a subgroup.','Source states absence of mixed GF–hypercolor-squared ABJ anomalies. This is not a claim that every cubic flavor anomaly vanishes.');
INSERT INTO "theory_symmetries" VALUES(57,'su4-hypercolor-partial-compositeness',1,130,'Nonlinear GF/HF realization with HF = SO(5) × SU(3)c × U(1)X','internal','strong-sector global symmetry with SM subgroup gauged',NULL,'Conditional spontaneous flavor breaking. SU(3)c is diagonal in SU(3) × SU(3)''; custodial SU(2)L × SU(2)R lies in SO(5). Elementary couplings are represented by spurions.',NULL);
INSERT INTO "theory_symmetries" VALUES(58,'littlest-higgs-minimal',1,131,'SU(5) nonlinear sigma symmetry','internal','global before explicit gauge and Yukawa breaking',NULL,'Spontaneously broken to SO(5), producing fourteen Goldstones. Gauge and Yukawa interactions explicitly break the global symmetry.',NULL);
INSERT INTO "theory_symmetries" VALUES(59,'littlest-higgs-minimal',1,131,'Conditional protecting SU(3) subgroups','internal','global','restored_in_single_spurion_limits','Each gauge copy alone preserves a protecting SU(3); both together break the Higgs protection. Section 3 and Section 4 conflict on the numeric SU(3) labels. No unique gauge-copy-to-numeric-label assignment is canonicalized.',NULL);
INSERT INTO "theory_symmetries" VALUES(60,'twin-higgs-linear-scalar-sector',1,133,'SU(4)',NULL,'global scalar-sector symmetry',NULL,'Spontaneously broken to SU(3) by the scalar vacuum; explicitly broken by doubled weak gauging.',NULL);
INSERT INTO "theory_symmetries" VALUES(61,'twin-higgs-linear-scalar-sector',1,133,'O(8) of the displayed scalar potential',NULL,'global','enlarged_symmetry_of_displayed_potential','The same seven angular modes can be organized through O(8) to O(7); explicit interactions need not preserve O(8).',NULL);
INSERT INTO "theory_symmetries" VALUES(62,'twin-higgs-linear-scalar-sector',1,133,'Twin parity Z2','internal sector interchange',NULL,'imposed','Exact in the illustrative gauge calculation; exchanges both doublets and the two sets of weak gauge bosons, enforcing g_A=g_B.',NULL);
INSERT INTO "theory_symmetries" VALUES(63,'twin-higgs-unextended',1,134,'Nonlinearly realized O(8)',NULL,'global Higgs-sector symmetry','assumed','Seven Goldstone coordinates; explicit gauge and Yukawa interactions generate the pseudo-Goldstone potential.',NULL);
INSERT INTO "theory_symmetries" VALUES(64,'twin-higgs-unextended',1,134,'Direct twin interchange Z2','internal sector interchange',NULL,'imposed_on_dominant_interactions','Relates corresponding gauge and Yukawa interactions. The mu² H_A-dagger H_A term softly breaks it; smaller Yukawa equalities are relaxed separately.',NULL);
INSERT INTO "theory_symmetries" VALUES(65,'twin-higgs-extended-top',1,135,'SU(6) × SU(4) × U(1) approximate top-sector symmetry',NULL,'global, with doubled-SM subgroups gauged',NULL,'The displayed Yukawa preserves SU(6) × SU(4). M is the sole soft SU(4)-breaking source within this top sector, not within the entire theory.',NULL);
INSERT INTO "theory_symmetries" VALUES(66,'mirror-higgs-unextended',1,136,'Mirror symmetry','Spatial inversion combined with CP-conjugate sector interchange',NULL,'imposed_on_dominant_interactions','Relates the sector gauge and Yukawa interactions. Common small-Yukawa departures are permitted; no exact all-sector mirror invariance is inferred for every phenomenological choice.',NULL);
INSERT INTO "theory_symmetries" VALUES(67,'fraternal-twin-higgs',1,137,'Approximate scalar-sector SU(4)',NULL,'global',NULL,'Spontaneously broken to SU(3) in the dominant scalar potential; gauge, Yukawa and smaller scalar interactions explicitly break it.',NULL);
INSERT INTO "theory_symmetries" VALUES(68,'fraternal-twin-higgs',1,137,'Approximate twin exchange Z2','internal sector interchange','global','imposed_on_dominant_couplings','A↔B organizes the scalar and dominant-coupling relations. It is not an exact symmetry of the full unequal inventories. Rho and sigma break scalar exchange; hypercharge and small Yukawas also depart from it.',NULL);
INSERT INTO "theory_symmetries" VALUES(69,'six-dimensional-pati-salam-vortex',1,143,'U(1)V','internal','unspecified_in_scope','imposed_vortex_symmetry','Broken by Φ away from its core zeros. Section 3 discusses gauging conditionally; section 3.4 introduces a factor without a complete gauge or charge prescription.',NULL);
INSERT INTO "theory_symmetries" VALUES(70,'rs-two-brane-warped',1,144,'Four-dimensional Poincare invariance of the selected background','spacetime',NULL,'assumed_background_isometry','Preserved by the tuned flat-slice solution. This is not an internal gauge breaking chain.',NULL);
INSERT INTO "theory_symmetries" VALUES(71,'ued-orbifold-framework',1,150,'Source-stated KK-number selection rule','compact-momentum selection rule in the reduced theory',NULL,'source_claim_for_bulk_truncation','The paper excludes inter-level fermion mixing and vertices with exactly one nonzero KK mode. This row records its working claim, not an independently established exact quantum symmetry or a replacement by KK parity.',NULL);
INSERT INTO "theory_symmetries" VALUES(72,'holographic-boundary-pgb-framework',1,153,'CFT global G','internal','global',NULL,'Spontaneously broken to H1. Elementary H0 gauging explicitly breaks G; dim(G/H1)-dim(H0/(H0 intersection H1)) Goldstones remain uneaten.',NULL);
INSERT INTO "theory_symmetries" VALUES(73,'hidden-valley-chi-two-flavor',1,156,'Z2 forbidding Dirac neutrino masses','internal',NULL,'imposed','Baseline assumption makes Ni stable; the source explicitly considers relaxing it. Individual parity transformations are not tabulated.',NULL);
INSERT INTO "theory_symmetries" VALUES(74,'secluded-dirac-u1-higgsed',1,166,'ψ fermion number of the displayed action','internal','global','accidental_in_displayed_terms','Inferred invariance of the mass and gauge bilinears only; no protection against arbitrary higher-dimensional operators is established.',NULL);
INSERT INTO "theory_symmetries" VALUES(75,'secluded-neutrino-portal-z2',1,169,'Joint Z2 of N'' and S','internal','unspecified_in_scope','source_stated_symmetry_of_displayed_action','Assumed unbroken for either dark-matter application. A scalar potential proving this vacuum is not supplied.',NULL);
INSERT INTO "theory_symmetries" VALUES(76,'simp-sp-pions',1,172,'SU(2Nf) massless flavor symmetry','internal','global',NULL,'Assumed condensate preserves Sp(2Nf); the selected explicit mass also preserves that subgroup.',NULL);
INSERT INTO "theory_symmetries" VALUES(77,'simp-sp-pions',1,173,'Preserved Sp(2Nf) flavor symmetry','internal','global',NULL,'Preserved in the canonical degenerate-pion treatment; flavor-breaking alternatives are not included.',NULL);
INSERT INTO "theory_symmetries" VALUES(78,'simp-su-pions',1,174,'SU(Nf)×SU(Nf) chiral flavor symmetry','internal','global',NULL,'Assumed chiral breaking preserves diagonal SU(Nf); the canonical mass restriction retains this subgroup.',NULL);
