INSERT INTO "theory_symmetry_actions" VALUES(30,'threedm-d6',1,17,13,63,'a: φ → diag(ω,ω²,1)φ, ω=exp(2πi/3); b: (φ1,φ2,φ3) → (exp(iδ)φ2,exp(−iδ)φ1,−φ3). a³=b²=1; ab=ba².',NULL,'SU(3) matrices represent PSU(3) cosets. Choose 3δ=π−ψ1+ψ2 in the source convention; shifts δ→δ+2πk/3 select the three order-two elements. ψi=arg λi when defined.');
INSERT INTO "theory_symmetry_actions" VALUES(31,'threedm-d6',1,17,14,63,'J''=cJ; c=[[0,exp(iγ),0],[exp(iγ),0,0],[0,0,−exp(−2iγ)]]. J is CP conjugation in the source notation. J'' commutes with a and b and has square one.',NULL,'For nonzero λ1,λ2,λ3: 6γ=−2(ψ1+ψ2)=2ψ3 and 2(ψ1+ψ2+ψ3)=0 in the source phase convention. For λ3=0, use 6γ=−2(ψ1+ψ2) without an additional phase condition.');
INSERT INTO "theory_symmetry_actions" VALUES(32,'threedm-d8',1,18,15,64,'a: φ → diag(i,−i,1)φ; b: (φ1,φ2,φ3) → (exp(iδ)φ2,exp(−iδ)φ1,−φ3). b²=1; b⁻¹ab=a³.',NULL,'The chosen a fixes the mixed pair. For λ2 nonzero, δ=ψ2/2 with ψ2=arg λ2. Matrices represent Higgs-family transformations modulo gauge-trivial center phases.');
INSERT INTO "theory_symmetry_actions" VALUES(33,'threedm-d8',1,18,16,64,'J''=cJ; c=[[0,exp(iγ),0],[exp(iγ),0,0],[0,0,−exp(−2iγ)]]. This generalized CP commutes with the unitary D8 generators.',NULL,'6γ=2ψ1 with ψ1=arg λ1 for nonzero λ1. The D8 coefficient constraints already suffice; no further quartic-magnitude or phase restriction is imposed.');
