INSERT INTO "theory_vacua" VALUES(1,'real-singlet-z2',1,1,'Electroweak-breaking, singlet-sign-preserving vacuum','<S> = 0; unshifted h_ext² = v_EW²; electroweak symmetry is spontaneously broken and S → −S remains unbroken.','v_EW² > 0 and m_0² + lambda v_EW² > 0 within an acceptable Higgs sector. Full boundedness at quartic-flat boundaries and the conflicting competing-minimum restrictions remain deferred.','source_assumed');
INSERT INTO "theory_vacua" VALUES(2,'real-singlet-z2',1,2,'Temporary singlet-breaking phase at the critical temperature','P02 states that a singlet VEV Sc temporarily breaks S → −S at the critical temperature. The full phase sequence and simultaneous Higgs order parameter in this phase are not specified here.','Scoped parametrization: lambda_S(P02) = (lambda_h/4)(vc/Sc)^4, with lambda_h = 0.13. No numerical scan interval is adopted because the printed intervals conflict.','source_stated_scoped_application');
INSERT INTO "theory_vacua" VALUES(3,'thdm-type-i-real-z2',1,4,'Chapter 2 neutral CP-conserving vacuum','⟨Φj⟩ = (0, vj/√2)^T with real non-negative v1 and v2; no spontaneous scalar CP breaking is assumed.','Parameters must admit the chosen vacuum; no benchmark or universal global-minimum condition is asserted.','source_assumed');
INSERT INTO "theory_vacua" VALUES(4,'thdm-type-ii-real-z2',1,5,'Chapter 2 neutral CP-conserving vacuum','⟨Φj⟩ = (0, vj/√2)^T with real non-negative v1 and v2; no spontaneous scalar CP breaking is assumed.','Parameters must admit the chosen vacuum; no benchmark or universal global-minimum condition is asserted.','source_assumed');
INSERT INTO "theory_vacua" VALUES(5,'lr-triplet-parity',1,6,'Staged triplet and bidoublet breaking','After right-triplet breaking, ⟨Φ⟩ = diag(v1,v2 exp(iα)); electroweak breaking induces a small ⟨ΔL⟩ proportional to v²/vR. The first-stage zero ⟨ΔL⟩ is not imposed at all stages.','v1 and v2 real and positive; α is not fixed to a real-VEV limit. Full potential and minimum conditions unresolved.','source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(6,'lr-triplet-charge-conjugation',1,7,'Staged triplet and bidoublet breaking','After right-triplet breaking, ⟨Φ⟩ = diag(v1,v2 exp(iα)); electroweak breaking induces a small ⟨ΔL⟩ proportional to v²/vR. The first-stage zero ⟨ΔL⟩ is not imposed at all stages.','v1 and v2 real and positive; complex bidoublet VEVs are permitted. Full potential and minimum conditions unresolved.','source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(7,'nmssm-general-rpc-cpc',1,8,'Real neutral Higgs vacuum','Hu⁰ = vu + (HuR + iHuI)/√2; Hd⁰ = vd + (HdR + iHdI)/√2; S = s + (SR + iSI)/√2, with real vu, vd, s.','Values follow from minimisation; the assumed expansion does not certify a global minimum for arbitrary parameters.','source_assumed');
INSERT INTO "theory_vacua" VALUES(8,'nmssm-z3-rpc-cpc',1,9,'Real neutral Higgs vacuum in the cubic specification','Same real vu, vd, s expansion of Hu⁰, Hd⁰ and S as Eq. (2.10); scalar fluctuations have 1/√2 normalization.','Apply the six-zero restriction to the general potential and its minimisation conditions. No benchmark or universal global-minimum inequality is imposed.','source_assumed');
INSERT INTO "theory_vacua" VALUES(9,'mchm-spinorial',1,10,'Strong-sector breaking and electroweak misalignment','⟨Σ⟩=(0,0,ϵ,0,√(1−ϵ²)); a nonzero Higgs VEV breaks SO(4) to custodial SO(3). ϵ=0 is the electroweak-preserving endpoint.','The radiative potential selects ϵ. The approximate stationary solution cos(h/fπ)=−α/(2β) applies only for suitable coefficients and within its approximation.','source_stated_conditional_vacuum');
INSERT INTO "theory_vacua" VALUES(10,'georgi-machacek-general',1,15,'Custodial-aligned electroweak vacuum','⟨Φ⟩=(vφ/√2)I2 and ⟨X⟩=vχI3, with equal neutral χ and ξ vevs. Neutral expansions: φ0=vφ/√2+(φ0,r+iφ0,i)/√2; χ0=vχ+(χ0,r+iχ0,i)/√2; ξ0=vχ+ξ0, reusing ξ0 for the real fluctuation.','vφ²+8vχ²=v². Stationarity: 0=vφ[μ2²+4λ1vφ²+3(2λ2−λ5)vχ²−3M1vχ/2]; 0=3μ3²vχ+3(2λ2−λ5)vφ²vχ+12(λ3+3λ4)vχ³−3M1vφ²/4−18M2vχ². An acceptable minimum additionally requires stability and comparison with competing extrema; alignment alone does not certify global minimality.','source_selected_conditional_vacuum');
INSERT INTO "theory_vacua" VALUES(11,'sm-octet-doublet-mfv',1,19,'Electroweak Higgs vacuum used for the spectrum','Neutral Higgs expectation value v/√2; the corresponding Higgs matrix has expectation value diag(v/√2,v/√2).','No general global-minimum or boundedness conditions are established by the prepared assertions.','source_stated_vacuum');
INSERT INTO "theory_vacua" VALUES(12,'sm-octet-doublet-mfv-triplets',1,21,'Negligible-triplet-VEV approximation','Neutral triplet expectation values are neglected; this is an approximation and not an exact zero enforced by an unbroken sign symmetry.','Very small μ1, μ2 and ξ in the source''s example; no general minimum conditions supplied.','source_assumed');
INSERT INTO "theory_vacua" VALUES(13,'su5-georgi-glashow-review',1,35,'Adjoint then electroweak breaking','Scalar-adjoint expectation value breaks SU(5); the scalar 5 subsequently supplies electroweak breaking. No potential or global-minimum proof is reconstructed.',NULL,'source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(14,'su5-gg-scalar15',1,38,'Neutral scalar-15 expectation value','An electrically neutral component of 15_H acquires an expectation value and generates type-II-seesaw neutrino masses.','Full potential and expectation-value solution are not provided.','source_stated_mechanism');
INSERT INTO "theory_vacua" VALUES(15,'mdm-real-septuplet-displayed',1,40,'Zero septuplet expectation value','<X>=0 as assumed in the discussion following equation (4).','No complete scalar-potential minimum or boundedness analysis is supplied. The assumption is not a global-minimum certification.','source_assumed');
INSERT INTO "theory_vacua" VALUES(16,'umssm-single-s-higgs-sector',1,44,'Neutral singlet-dominated breaking example','Nonzero singlet scalar VEV and neutral Higgs VEVs; squark and slepton VEVs vanish. Source phases chosen real and positive in this sector.','For TeV-scale soft parameters, mS²<0 and νu,d≪s, s²≈−2mS²/(g2²QS²) and MZ′²≈−2mS². The hierarchy uses cancellations and is not a fixed spectrum or global-minimum theorem.','source_stated_conditional_vacuum');
INSERT INTO "theory_vacua" VALUES(17,'u1-two-singlet-flat-sector',1,45,'Conditional F- and D-flat breaking direction','The quartic vanishes for |S2|²/|S1|²=−QS1/QS2. For QS1=−QS2 choose S1=S2≡S.','If m²=mS1²+mS2²<0, V(S)=m²S² requires stabilization. Running m²(S) or higher-dimensional W=(S1S2)^k/M^(2k−3) can lift the direction; no specific stabilized minimum or scale is selected.','source_stated_direction_not_completed_minimum');
INSERT INTO "theory_vacua" VALUES(18,'minimal-bl-pure',1,47,'B−L and electroweak broken vacuum used for the seesaw','χ has a nonzero vacuum parameter x and the Higgs has a neutral electroweak vacuum parameter v. The one-generation neutrino matrix is [[0,mD],[mD,M]], giving light and heavy Majorana states in the source''s seesaw regime; three of each occur for three generations.','No scalar minimum or boundedness conditions are supplied. Light/heavy seesaw hierarchy is a selected regime of the Yukawa and vacuum parameters; no fixed mass, flavor degeneracy or transition ordering is imposed.','source_assumed_with_inferred_continuous_breaking');
INSERT INTO "theory_vacua" VALUES(19,'pp331-displayed',1,53,'Aligned neutral three-triplet vacuum','<eta>=(veta,0,0)/sqrt(2); <rho>=(0,vrho,0)/sqrt(2); <chi>=(0,0,vchi)/sqrt(2). Relative phases neglected in the scalar analysis.','v1=veta/sqrt(2), v2=vrho/sqrt(2), v3=vchi/sqrt(2). For nonzero vi, Eq. (38) requires mu1²+2lambda1 v1²+lambda4 v2²+lambda5 v3²+Re(f)v2v3/v1=0; mu2²+2lambda2 v2²+lambda4 v1²+lambda6 v3²+Re(f)v1v3/v2=0; mu3²+2lambda3 v3²+lambda5 v1²+lambda6 v2²+Re(f)v1v2/v3=0; Im(f)=0. These stationarity conditions do not certify a stable global minimum. Large vchi is an additional approximation for the neutral-vector spectrum.','source_assumed_with_tree_stationarity');
INSERT INTO "theory_vacua" VALUES(20,'ql421-dirac',1,55,'Color- and charge-preserving neutral vacuum','Only χ_R^0, H0 and H2^0 acquire VEVs. ⟨χ_R^0⟩=vχ/√2, ⟨H0⟩=v1/√2 and ⟨H2^0⟩=v2/√2.','The authors assume potential parameters admitting this vacuum; no minimization, boundedness or global-minimum proof is supplied.','source_assumed');
INSERT INTO "theory_vacua" VALUES(21,'su5-adjoint-renormalizable',1,59,'Adjoint unified-symmetry-breaking alignment','⟨24H⟩=v diag(2,2,2,−3,−3)/√30.','Used for the displayed adjoint-fermion and superheavy gauge-boson masses. The scalar potential and minimum conditions are not supplied; no stable global minimum is certified.','source_assumed');
INSERT INTO "theory_vacua" VALUES(22,'so10-45-126-sector',1,61,'General SM-preserving stationary directions','VEVs only in the three directions ωBL, ωR and σ of Eq. (5); adjoint VEVs real and σ may be made real by rephasing.','Away from ωBL=ωR, require 0=−μ²+a0(6ωBL²+4ωR²)+a2(ωRωBL+ωBL²+ωR²)+2α|σ|²+2β′4|σ|²; 0=a2ωRωBL(ωBL+ωR)−τ|σ|²+2β′4(3ωBL+2ωR)|σ|²; 0=2σ*[−ν²+4λ0|σ|²+τ(3ωBL+2ωR)+α(3ωBL²+2ωR²)−2β′4(6ωRωBL+3ωBL²+ωR²)]. The σ=0 branch is retained. Stationarity does not certify a minimum.','source_stated_stationarity');
INSERT INTO "theory_vacua" VALUES(23,'so10-45-126-sector',1,61,'Left-right adjoint alignment','First take σ=0, ωR=0 and ωBL≠0; then consider nonzero σ.','A symmetry-alignment branch, not a demonstrated tree-level stable minimum.','source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(24,'so10-45-126-sector',1,61,'SU(4) adjoint alignment','First take σ=0, ωBL=0 and ωR≠0; then consider nonzero σ.','A symmetry-alignment branch, not a demonstrated tree-level stable minimum.','source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(25,'so10-45-126-sector',1,61,'Generic two-Abelian-factor adjoint alignment','First take σ=0, ωRωBL≠0 and ωR≠±ωBL; then consider nonzero σ.','Enhanced equal and opposite adjoint alignments excluded from this generic branch.','source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(26,'so10-45-126-sector',1,61,'Flipped SU(5) adjoint alignment','First take σ=0 and ωR=−ωBL≠0; then consider nonzero σ.','Flipped embedding Y′=−TR^3+TBL, Z′=4TR^3+6TBL. No complete flipped-SU(5) phenomenological construction is inferred.','source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(27,'so10-45-126-sector',1,61,'Standard SU(5) adjoint alignment','First take σ=0 and ωR=ωBL≠0; nonzero σ retains standard SU(5).','Standard embedding Y=TR^3+TBL, Z=−4TR^3+6TBL. Eqs. (B2)-(B3) divide by ωBL−ωR and cannot be used on this branch. Its phenomenology is not developed.','source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(28,'trinification-n3-adjoint-l',1,65,'Desired trinification and electroweak breaking','⟨Hn⟩=[[vun,0,0],[0,vdn,vLn],[0,VRn,Vn]], n=1,2,3. A field redefinition permits VR1=vL1=0.','Capital-V entries exceed the electroweak lowercase-v entries. The full scalar potential and minimization are not supplied; this is an assumed breaking pattern, not a certified minimum.','source_assumed');
INSERT INTO "theory_vacua" VALUES(29,'trinification-n3-adjoint-l',1,65,'Illustrative separation of exotic and ordinary fermion masses','V1≠0 and vd1=vu1=vL1=0; H1 preserves GSM while breaking part of G333. Other bi-triplets provide the remaining breaking and ordinary fermion masses.','yQ1 and yL1 generate exotic masses through V1; H2,H3 can have small Yukawas. The quoted 700 and 200 GeV bounds are paper-era conditions, not defining masses. H1 alone is not asserted to leave exactly GSM.','source_assumed_example');
INSERT INTO "theory_vacua" VALUES(30,'mssm-rpc-conventional-soft',1,67,'Conditional neutral electroweak vacuum','Squark and slepton VEVs vanish; charged Higgs VEVs vanish. Choose b,v_u,v_d real and positive. The classical Higgs potential does not spontaneously violate CP; this does not remove complex phases elsewhere.','Assume large positive sfermion squared masses for this analysis. Neutral tree-level conditions: 2b<2|μ|²+m_Hu²+m_Hd² and b²>(|μ|²+m_Hu²)(|μ|²+m_Hd²). Stationarity: m_Hu²+|μ|²−b cotβ−m_Z² cos(2β)/2=0 and m_Hd²+|μ|²−b tanβ+m_Z² cos(2β)/2=0. These are not a global-minimum test over all MSSM scalar directions. Numerically stable minimization requires radiative corrections; at the effective-potential level replace each Higgs soft mass by m_Hi²+(1/2v_i)∂ΔV/∂v_i.','source_assumed_with_tree_level_conditions');
INSERT INTO "theory_vacua" VALUES(31,'mssm-minimal-gauge-messengers',1,72,'Parameterized singlet scalar and F-term background','<S>≠0 and <F_S>≠0; no complete phase convention or hidden-sector field inventory is fixed.','<∂W_breaking/∂S>=−<F_S*>≠0 and <∂W_mess/∂S>=0. The dynamics producing this background are unspecified; no stable global minimum is certified.','source_assumed');
INSERT INTO "theory_vacua" VALUES(32,'mssm-rpv-general',1,74,'Conditional induced sneutrino VEVs','<sneutrino_i>=v_i/sqrt(2), <h_d^0>=v_d/sqrt(2), <h_u^0>=v_u/sqrt(2). A weak basis with v_i=0 can be chosen.','Bilinear soft terms generally induce v_i unless special relations hold. These VEVs depend on couplings and are not independent RPV inputs. No global-minimum certification.','source_stated_conditional_vacuum');
INSERT INTO "theory_vacua" VALUES(33,'mssm-rpc-conventional-soft',1,79,'Minimal spontaneous sneutrino-breaking branch','An MSSM sneutrino has a nonzero VEV and breaks R-parity and global lepton number.','Alternative to the existing neutral vacuum with vanishing slepton VEVs. Source-reported Majoron and scalar-partner Z decay excludes this minimal application; the complete scalar minimum is not reconstructed.','source_stated_alternative_vacuum');
INSERT INTO "theory_vacua" VALUES(34,'rpv-singlet-spontaneous-sector',1,80,'One-family singlet-breaking illustration','Singlet lepton scalar VEVs v_R/sqrt(2) and v_S/sqrt(2), neutral Higgs VEVs v_u/sqrt(2), v_d/sqrt(2), and a small left-handed tau-sneutrino VEV v_L/sqrt(2).','One-family VEV choice does not reduce the three-family singlet inventory. Full soft potential, minimization and stability conditions remain unspecified.','source_assumed');
INSERT INTO "theory_vacua" VALUES(35,'gem-supersoft',1,87,'Assumed hidden D background','Nonzero auxiliary D'' expectation value in hidden U(1)''.','Hidden charged fields, potential and vacuum dynamics are unspecified. No hidden gauge-symmetry breaking pattern or visible electroweak minimum follows solely from D'' being nonzero.','source_assumed');
INSERT INTO "theory_vacua" VALUES(36,'u1-minimal-gauge-messenger-toy',1,95,'Prescribed chiral spurion background','<X>=M+theta²F, with real M and F.','Background assumed for messenger calculations. No X potential, completed hidden minimum or messenger-condensed phase is reconstructed.','source_assumed');
INSERT INTO "theory_vacua" VALUES(37,'ksvz-neutral-triplet',1,97,'PQ-broken singlet vacuum','Phi=(v_a+rho_a) exp(i a/v_a)/sqrt(2), with nonzero radial vacuum parameter v_a.','Use the symmetry-breaking potential of Eq. (78); no complete coupled SM-scalar minimum analysis is supplied.','source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(38,'dfsz-i-quartic',1,100,'Common neutral DFSZ vacuum','H_u contains v_u exp(i a_u/v_u)(1,0)^T/sqrt(2); H_d contains v_d exp(i a_d/v_d)(0,1)^T/sqrt(2); Phi contains v_Phi exp(i a_Phi/v_Phi)/sqrt(2).','Assume potential parameters admitting all three nonzero VEVs with v_Phi much larger than v_u,v_d. Charged and radial modes omitted from these expressions. This common vacuum assumption also applies to DFSZ-II; no global-minimum proof is inferred.','source_assumed');
INSERT INTO "theory_vacua" VALUES(39,'smash-down',1,102,'Electroweak and PQ/lepton broken vacuum','<H†H>=v²/2; <|σ|²>=vσ²/2; v=246 GeV and vσ≫v. σ=(vσ+ρ)exp(iA/vσ)/sqrt(2).','λH,λσ>0 and λHσ²<λHλσ near the vacuum. These near-vacuum conditions are not imposed unchanged at every scale in the positive-portal analysis.','source_stated_conditional_minimum');
INSERT INTO "theory_vacua" VALUES(40,'smash-down',1,103,'QCD-selected axion vacuum','θ=A/fA relaxes to the QCD vacuum minimum θ=0.','Heavy fields removed; QCD supplies the axion potential. This is the stated strong-CP mechanism, conditional on the assumed PQ structure.','source_stated_mechanism');
INSERT INTO "theory_vacua" VALUES(41,'smash-down',1,104,'Thermal PQ restoration and subsequent breaking','HHSI reheating exceeds the PQ critical temperature in the analyzed region; subsequent cooling gives the source''s second-order PQ transition.','For stabilized hierarchical Yukawas Tc/fA≳2λσ^(1/4); for approximately degenerate Yukawas Tc/fA≳λσ^(1/4). These are conditional finite-temperature estimates; no general exact Tc formula is transcribed.','source_calculated_conditional_thermal_phase');
INSERT INTO "theory_vacua" VALUES(42,'lns-two-singlet-quarks',1,108,'Assumed horizontal-breaking and comparable-Higgs-VEV configuration','Nonzero scalar singlet VEVs define epsilon1,epsilon2; <phi_u> and <phi_d> are of comparable magnitude. No CP phase restriction is supplied.','Illustrative epsilon1 approximately 0.04 and epsilon2 approximately 0.008. No scalar potential, stationary solution or minimum certification.','source_assumed');
INSERT INTO "theory_vacua" VALUES(43,'lns-reduced-quarks',1,112,'Assumed small down-Higgs VEV','<phi_d> approximately epsilon1 <phi_u>, with the two inherited singlet breaking parameters.','Supplies the bottom/top hierarchy in the reduced example. Dynamics generating the Higgs-VEV ratio are not specified; no minimum certification.','source_assumed');
INSERT INTO "theory_vacua" VALUES(44,'af-a4-susy-effective',1,113,'Selected leading flavon alignment','<phiT>=(vT,0,0); <phiS>=(vS,vS,vS); <xi>=u; <xi_tilde>=0. Driving-field scalar VEVs vanish under the stated positive soft-mass choices.','vT=-3M/(2g); vS²=-g4 u²/(3g3); u remains undetermined at supersymmetric leading order. A finite parameter region and subsequent soft selection are assumed; radiative stabilization is not calculated. No full global-minimum certification or universal real-VEV restriction.','source_stated_branch_with_assumed_selection');
INSERT INTO "theory_vacua" VALUES(45,'af-a4-susy-effective',1,113,'Source-stated first-order alignment shifts','<phiT>=(vT_prime+delta_vT,delta_vT,delta_vT); <phiS>=(vS+delta_v1,vS+delta_v2,vS+delta_v3); <xi>=u; <xi_tilde>=delta_u_prime.','Shifts have one additional inverse-cutoff suppression relative to leading VEVs; u remains undetermined. Retain equation (33) as a source-stated perturbative result. Detailed coefficients and consistency with the disputed Appendix B invariants are deferred.','source_stated_with_operator_basis_qualification');
INSERT INTO "theory_vacua" VALUES(46,'af-a4-susy-seesaw',1,114,'Inherited leading alignment for the seesaw realization','<phiT>=(vT,0,0); <phiS>=(vS,vS,vS); <xi>=u; <xi_tilde>=0, with vanishing driving VEVs under the inherited assumptions.','Section 6 explicitly retains w_d and the section 4 alignment mechanism: vT=-3M/(2g), vS²=-g4 u²/(3g3). Flat-direction stabilization and electroweak breaking remain assumed; no seesaw-specific global-minimum proof is supplied.','source_stated_inherited_branch');
INSERT INTO "theory_vacua" VALUES(47,'modular-a4-flavonfree-seesaw',1,115,'Example 3 scanned modulus background','⟨τ⟩=0.008+0.98i; sole flavour-breaking background in the flavon-free construction. Higgs VEVs enter the lepton masses separately.','α/γ=15.3; β/γ=0.054; g2/g1=0.029i. No stabilization or minimum proof. The source reports inverted ordering and mixing angles excluded by its contemporary data; no current fit or whole-parameter-space exclusion is inferred.','source_assumed_scan_point');
INSERT INTO "theory_vacua" VALUES(48,'grv-quark-flavor-u3',1,116,'Assumed generic flavon vacuum','Choose Yd=Ŷd diagonal and Yu=Ŷu V with V unitary. No universal CP-conserving restriction is imposed.','VEVs are assumed to reproduce quark masses and mixing; no explicit potential or minimum proof is supplied. For the main gauging the source counts 26 eaten Goldstones and 10 radial coordinates, six associated with masses and four with CKM parameters.','source_assumed');
INSERT INTO "theory_vacua" VALUES(49,'grv-quark-flavor-u3',1,116,'Section 5.2 numerical example','Yu≈diag(1e5,2e2,3e-1)V TeV; Yd≈diag(6e3,4e2,7) TeV.','Mu=350 GeV; Md=100 GeV; λu=1.1; λ′u=0.5; λd=0.25; λ′d=0.25; gQ=0.3; gU=1; gD=0.3. Hypercharge mixing values remain unselected; the authors allow at most 5% for this example. Running above the TeV scale and a scalar minimum are not established.','source_assumed_benchmark');
INSERT INTO "theory_vacua" VALUES(50,'grv-quark-flavor-su3',1,118,'Section 5.1 numerical example','Yu≈diag(1e5,2e2,8e-2)V TeV; Yd≈diag(5e3,3e2,6) TeV, with V the unitary experimental CKM matrix used by the source.','Mu=400 GeV; Md=100 GeV; λu=1; λ′u=0.5; λd=0.25; λ′d=0.3; gQ=0.4; gU=0.3; gD=0.5. Yukawa running is included only to the TeV scale; the largest VEVs are order-of-magnitude estimates. No scalar minimum or complete scalar spectrum is computed.','source_assumed_benchmark');
INSERT INTO "theory_vacua" VALUES(51,'ma-radiative-seesaw-z2',1,123,'Parity-preserving neutral electroweak vacuum','Only φ0 has a nonzero expectation value v; <η0>=0 and exact Z2 is preserved.','The author takes m_1²<0 and m_2²>0. These signs alone are not certified as sufficient global-minimum or stability conditions for the coupled scalar potential.','source_assumed');
INSERT INTO "theory_vacua" VALUES(52,'su4-hypercolor-partial-compositeness',1,129,'Proposed hypercolor-invariant condensates','<epsilon_mnpq psi^I_mn psi^J_pq> proportional to delta^IJ; <chi_tilde_ma'' chi^ma> proportional to delta_aa''. Hypercolor remains unbroken.','Condensation is motivated by anomaly and NJL arguments, explicitly not proved. The MAC estimate of separated scales is non-rigorous and does not establish a thermal sequence.','source_assumed');
INSERT INTO "theory_vacua" VALUES(53,'su4-hypercolor-partial-compositeness',1,130,'Conditional neutral-Higgs electroweak misalignment','H0=h/sqrt(2); other physical pNGB backgrounds vanish in the singlet-omitted treatment. Charged Higgs directions are eaten in unitary gauge; color is preserved.','For suitable coefficients the source states beta approximately greater than or equal to |alpha|/2 and sin^2(2<h>/f)=1-(alpha/2beta)^2. Gauge alignment and a Higgs-selective top instability motivate this choice; a complete nonperturbative or global-minimum calculation is absent.','source_assumed_conditional_vacuum');
INSERT INTO "theory_vacua" VALUES(54,'littlest-higgs-minimal',1,131,'Electroweak-preserving sigma alignment','Sigma0 has 2+1+2 blocks [[0,0,I2],[0,1,0],[I2,0,0]], equivalent to an identity-proportional symmetric-tensor direction.','The source assumes c>0 for gauge alignment. Including the leading fermion contribution, a positive triplet mass requires c(g1^2+g1''^2+g2^2+g2''^2)-c''lambda1^2>0. This is not a full global-minimum proof. Block-zero transcription retains the supplied text''s layout limitation.','source_assumed_with_leading_mass_condition');
INSERT INTO "theory_vacua" VALUES(55,'littlest-higgs-minimal',1,132,'Conditional radiative electroweak-breaking vacuum',NULL,'The negative top contribution -3 lambda_t^2 m-prime^2 log(Lambda^2/m-prime^2)/(8pi^2) can dominate the positive gauge and scalar logarithmic terms. Electroweak breaking is parameter dependent; no fixed Higgs VEV, complete triplet background solution or global-minimum certification is reconstructed.','source_stated_conditional_vacuum');
INSERT INTO "theory_vacua" VALUES(56,'twin-higgs-linear-scalar-sector',1,133,'Linear scalar symmetry-breaking norm','<|H|>=f','Negative quadratic term and the displayed quartic give f=m/sqrt(2lambda). Global Goldstone counting refers to the potential before explicit gauging.','source_stated');
INSERT INTO "theory_vacua" VALUES(57,'twin-higgs-unextended',1,134,'Nonlinear reference alignment','H reference direction is (0,0,0,f)^T; the h=(h1,h2) doublet remains uneaten.','Reference alignment before visible electroweak misalignment and before an optional explicit twin hypercharge mass. No complete global-minimum analysis is reconstructed.','source_stated_reference_alignment');
INSERT INTO "theory_vacua" VALUES(58,'fraternal-twin-higgs',1,137,'SU(4)-dominated vacuum with visible misalignment','The dominant scalar norm breaks SU(4) to SU(3). In the realistic branch v_A² is much smaller than v_B², making the uneaten Higgs primarily visible.','Small exchange breaking selects the hierarchy; lambda dominates and rho is neglected in the working analysis. The source''s f²=v_A²+v_B² relation is retained at its approximation order, not as a certified exact minimum of the full potential.','source_assumed_with_approximate_potential_analysis');
INSERT INTO "theory_vacua" VALUES(59,'six-dimensional-pati-salam-vortex',1,143,'Sphere vortex–antivortex background','Opposite sphere poles carry the two core zeros. Locally Φ=f(r)exp(iθ), f(0)=0 and f(r≫Λ^−1)→φ_bulk; the antivortex reverses winding.','Core thickness of order Λ^−1 and separation of order 1 mm. The source argues practical longevity from roughly 10^16 core-width separation; no topological stability or global-minimum proof is asserted.','source_stated_background');
INSERT INTO "theory_vacua" VALUES(60,'six-dimensional-pati-salam-vortex',1,143,'Alternative source-described torus vortex background','The source identifies and removes the sphere poles, describes the result as a zero-inner-radius torus, and assigns it a single topologically stable vortex.','Retain as a source-stated alternative, not an independently verified smooth compactification or globally constructed gauge bundle.','source_stated_alternative_with_geometry_question');
INSERT INTO "theory_vacua" VALUES(61,'six-dimensional-pati-salam-vortex',1,143,'Core-localized Pati–Salam breaking','χ, χ′ and H have nonzero VEVs only in the vortex core and vanish in the bulk.','Interactions with Φ are assumed to admit this localization. Full coupled scalar potential and global-minimum conditions are not supplied.','source_assumed');
INSERT INTO "theory_vacua" VALUES(62,'rs-two-brane-warped',1,144,'Flat four-dimensional slices of a finite AdS5 interval','ds^2=exp(-2k r_c |phi|) eta_mu_nu dx^mu dx^nu+r_c^2 dphi^2, periodically continued on the covering circle.','Lambda=-24M^3 k^2; V_hid=-V_vis=24M^3 k. The radius remains arbitrary; no stabilized global minimum is established.','source_derived_classical_solution_with_assumed_flat_slices');
INSERT INTO "theory_vacua" VALUES(63,'ued-orbifold-framework',1,150,'Higgs-zero-mode electroweak vacuum','Only the even Higgs zero mode acquires the electroweak-breaking VEV v/sqrt(2), approximately 174 GeV.','Used in the source''s KK spectrum calculation. No full higher-dimensional potential minimization or global-minimum certification is supplied.','source_assumed');
INSERT INTO "theory_vacua" VALUES(64,'holographic-su3-brane-scalar-mediator',1,151,'Aligned infrared triplet background','Sigma has its reference VEV in the third component, (0,0,v_tilde)^T; the unbroken group is aligned with ultraviolet SU(2)L × U(1)Y.','v=v_tilde L0/L1 is of order the local infrared cutoff. Alignment is attributed to possible radiative effects; no complete coupled scalar minimum is certified.','source_assumed');
INSERT INTO "theory_vacua" VALUES(65,'hidden-valley-chi-two-flavor',1,156,'Additional Abelian symmetry-breaking vacuum','Nonzero ⟨φ⟩ gives the additional massive Z′.','Source discusses mZ′ approximately 1–6 TeV. No full potential, scalar minimum, thermal ordering or residual discrete-group determination is supplied.','source_stated_breaking_pattern');
INSERT INTO "theory_vacua" VALUES(66,'secluded-dirac-u1-higgsed',1,166,'Assumed U(1)'' Higgs vacuum','Nonzero φ expectation value generates mV.','Assume U(φφ*) has a minimum away from zero near the weak scale. No normalized VEV–mass relation or complete scalar minimum is supplied.','source_assumed');
INSERT INTO "theory_vacua" VALUES(67,'secluded-fermion-scalar-portal',1,168,'Shifted singlet origin and electroweak expansion','<φ>=0 by a field redefinition; H has the SM electroweak expectation value.','Coordinate choice does not impose a singlet sign symmetry. λ2→0 is the illustrative limit. A full scalar minimum is not established.','source_stated_basis_and_assumed_vacuum');
INSERT INTO "theory_vacua" VALUES(68,'secluded-neutrino-portal-z2',1,169,'Parity-preserving dark-matter background','Joint Z2 remains unbroken; S has no parity-breaking expectation value.','Condition needed for stability in both mass-ordering applications, inferred in assertion 1569. No full potential or minimum proof is supplied.','conditional_inferred_requirement');
INSERT INTO "theory_vacua" VALUES(69,'simp-sp-pions',1,172,'Assumed symplectic chiral condensate','<qi qj>=mu^3 Jij, J=i sigma2 tensor 1_Nf.','Expected for moderately small Nf in the asymptotically free range; no nonperturbative proof or complete phase diagram.','source_assumed');
INSERT INTO "theory_vacua" VALUES(70,'simp-su-pions',1,174,'Assumed QCD-like chiral condensate','Flavor-identity-aligned q qbar condensate preserving diagonal SU(Nf).','Use the source''s J-to-identity and bilinear-replacement prescription; no independently demonstrated strong-dynamics vacuum.','source_assumed');
INSERT INTO "theory_vacua" VALUES(71,'simp-o-pions',1,176,'Assumed orthogonal chiral condensate','Flavor-identity-aligned fermion bilinear preserving SO(Nf).','Source''s J-to-identity prescription; no unprinted Weyl/Dirac convention or nonperturbative vacuum proof.','source_assumed');
INSERT INTO "theory_vacua" VALUES(72,'vector-portal-stueckelberg-scalar',1,180,'Assumed nonzero mass-controlling scalar background','Nonzero <S> enters the vector mass and heavy-S matching.','V(S) is unspecified. The physical Higgs mixes with S by an angle of order v/<S>; no exact mixing formula or minimum proof is supplied.','source_assumed');
INSERT INTO "theory_vacua" VALUES(73,'vector-portal-abelian-higgs',1,181,'Hidden Higgs broken phase preserving vector parity','The charged scalar provides the longitudinal mode; charge conjugation survives as reversal of the massive vector.','No explicit V(S), normalized scalar VEV or quantitative vacuum solution is supplied.','source_stated_breaking_pattern');
